function isThesisCourse(c){
  return Boolean(c?.thesis) || /examensarbete|kandidatuppsats|självständigt arbete|degree project|thesis/i.test(String(c?.name||''));
}
function courseSubject(c){
  return String(c?.subject||guessSubject(c?.name||'')||'').trim();
}
function issuedBachelorSubject(){
  const issued=issuedBachelorInfo?.();
  return String(issued?.subject||'').trim();
}
function thesisReuseStatus(c,targetSubject){
  if(!isThesisCourse(c))return {locked:false,reason:''};
  const cSubject=courseSubject(c);
  const target=String(targetSubject||'').trim();
  const issuedSubject=issuedBachelorSubject();

  // A thesis can only satisfy the thesis requirement in its own main field.
  if(cSubject && target && cSubject.toLowerCase()!==target.toLowerCase()){
    // If the thesis belongs to an already issued bachelor, be conservative and
    // do not count it again in another bachelor at the same level.
    if(issuedSubject && cSubject.toLowerCase()===issuedSubject.toLowerCase()){
      return {locked:true,reason:`Redan knuten till kandidatexamen i ${cSubject}`};
    }
    return {locked:false,reason:`Examensarbete i ${cSubject} – uppfyller inte uppsatskravet i ${target}`};
  }
  return {locked:false,reason:''};
}


function isAdvancedCourse(c){
 return /Avancerad nivå/i.test(String(c?.level||'')) ||
   /^(A1N|A1F|A1E|A2E|AX)$/i.test(String(c?.level||'').trim()) ||
   /^(A1N|A1F|A1E|A2E|AX)$/i.test(String(c?.progression||'').trim());
}
function isBasicCourse(c){
 return /Grundnivå/i.test(String(c?.level||'')) ||
   /^(G1N|G1F|G1E|G2F|G2E|GX)$/i.test(String(c?.level||'').trim()) ||
   /^(G1N|G1F|G1E|G2F|G2E|GX)$/i.test(String(c?.progression||'').trim());
}

function courseDegreeHistory(c){
 const raw=c?.degreeHistory ?? c?.usedInDegrees ?? c?.degrees ?? c?.previousDegrees ?? [];
 if(Array.isArray(raw)) return raw;
 if(typeof raw==='string') return raw.split(/[;,|]/).map(x=>x.trim()).filter(Boolean);
 return [];
}
function courseUsedInPriorDegree(c){
 return courseDegreeHistory(c).length>0 || c?.usedInDegree===true || c?.includedInPreviousDegree===true;
}
function degreeLevelFromText(v){
 const s=String(v||'').toLowerCase();
 if(/master/.test(s)) return 'master';
 if(/magister/.test(s)) return 'magister';
 if(/kandidat|bachelor/.test(s)) return 'candidate';
 return '';
}
function targetDegreeLevel(){
 const explicit=String(window.__lotsenTargetDegreeLevel||'').toLowerCase();
 if(explicit) return explicit;
 const txt=[
   document.querySelector('[data-degree-level]')?.getAttribute('data-degree-level'),
   document.querySelector('[data-degree-type]')?.getAttribute('data-degree-type'),
   document.body?.dataset?.degreeLevel
 ].filter(Boolean).join(' ');
 return degreeLevelFromText(txt);
}
function priorDegreeReuseDecision(c,targetSubject){
 if(!courseUsedInPriorDegree(c)) return null;
 const targetLevel=targetDegreeLevel();
 const history=courseDegreeHistory(c);
 const historyText=history.join(', ') || 'tidigare examen';

 // Courses in the qualifying bachelor's degree must not silently be counted again
 // toward a magister/master. If provenance is incomplete, keep them out of the
 // automatic total until the institution-specific rule is known.
 if(targetLevel==='magister' || targetLevel==='master'){
   return {
     status:'review',
     hp:0,
     reason:`Ingår i ${historyText} – räknas inte automatiskt mot ${targetLevel}`
   };
 }

 // For a new bachelor's degree, prior use alone is not an automatic exclusion.
 // Keep it countable, but surface the provenance only in details.
 return {
   status:'count',
   hp:Number(c?.hp||0),
   reason:`Ingår även i ${historyText} – återanvändning kontrolleras mot lärosätets regler`,
   reused:true
 };
}
function candidateCourseDecision(c,targetSubject){
 const hp=Number(c?.hp||0);
 const subject=courseSubject(c);
 const target=String(targetSubject||'').trim();
 const reuse=thesisReuseStatus(c,target);
 const priorDegree=priorDegreeReuseDecision(c,target);

 if(reuse.locked){
   return {status:'excluded',hp:0,reason:reuse.reason||'Kan inte räknas igen'};
 }
 if(priorDegree && (targetDegreeLevel()==='magister' || targetDegreeLevel()==='master')){
   return priorDegree;
 }
 if(isAdvancedCourse(c)){
   return {status:'review',hp:0,reason:'Avancerad nivå – kontrollera med lärosätet'};
 }
 if(isThesisCourse(c) && subject && target && subject.toLowerCase()!==target.toLowerCase()){
   return {status:'review',hp:0,reason:`Examensarbete i ${subject} – kontroll krävs som valfri kurs`};
 }
 if(!isBasicCourse(c)){
   return {status:'review',hp:0,reason:'Kursnivån är inte verifierad'};
 }
 if(priorDegree && priorDegree.status==='count'){
   return priorDegree;
 }
 return {
   status:'count',
   hp,
   reason: subject && target && subject.toLowerCase()===target.toLowerCase()
     ? `Kan räknas i huvudområdet ${target}`
     : 'Kan preliminärt räknas som valfri kurs'
 };
}
function candidateCourseAudit(targetSubject){
 const rows=courses.filter(c=>c.selected!==false).map(c=>({...c,_decision:candidateCourseDecision(c,targetSubject)}));
 return {
   count:rows.filter(c=>c._decision.status==='count'),
   reused:rows.filter(c=>c._decision.status==='count' && c._decision.reused),
   review:rows.filter(c=>c._decision.status==='review'),
   excluded:rows.filter(c=>c._decision.status==='excluded')
 };
}

function calc(d){
  const raw=courses.filter(c=>c.selected!==false);
  const norm=s=>String(s||'').trim().toLowerCase();
  const audit=candidateCourseAudit(d.subject);
  const active=audit.count;

  const total=active.reduce((s,c)=>s+Number(c.hp||0),0);
  const subjectCourses=active.filter(c=>norm(courseSubject(c))===norm(d.subject));
  const subjectTotal=subjectCourses.reduce((s,c)=>s+Number(c.hp||0),0);
  const thesisHp=subjectCourses.filter(isThesisCourse).reduce((s,c)=>s+Number(c.hp||0),0);

  const totalReq=Number(d.total||180);
  const subjectReq=Number(d.subjectReq||90);
  const thesisReq=Number(d.thesisReq||15);

  const totalMissing=Math.max(0,totalReq-total);
  const subjectMissing=Math.max(0,subjectReq-subjectTotal);
  const thesisMissing=Math.max(0,thesisReq-thesisHp);
  const remaining=Math.max(totalMissing,subjectMissing,thesisMissing);
  const pct=Math.max(0,Math.min(100,Math.round(100*(totalReq-remaining)/Math.max(1,totalReq))));

  return {
    pct,remaining,total,totalReq,
    profileSubjectHp:subjectTotal,subjectReq,subjectMissing,
    thesisHp,thesisReq,thesisMissing,
    totalMissing,
    reviewHp:audit.review.reduce((s,c)=>s+Number(c.hp||0),0),
    excludedHp:audit.excluded.reduce((s,c)=>s+Number(c.hp||0),0),
    reviewCourses:audit.review,
    excludedCourses:audit.excluded
  };
}

