function showImport(){importBox.style.display=importBox.style.display==='none'?'block':'none'}
let importedCandidates=[];
let pdfJsPromise=null;
async function loadPdfJs(){
  if(window.pdfjsLib)return window.pdfjsLib;
  if(!pdfJsPromise){
    pdfJsPromise=import('https://cdnjs.cloudflare.com/ajax/libs/pdf.js/4.10.38/pdf.min.mjs')
      .then(pdfjsLib=>{
        pdfjsLib.GlobalWorkerOptions.workerSrc='https://cdnjs.cloudflare.com/ajax/libs/pdf.js/4.10.38/pdf.worker.min.mjs';
        window.pdfjsLib=pdfjsLib;
        return pdfjsLib;
      })
      .catch(error=>{pdfJsPromise=null;throw error});
  }
  return pdfJsPromise;
}
async function readPdfLines(file){
  const pdfjsLib=await loadPdfJs().catch(()=>null);
  if(!pdfjsLib) throw new Error('PDF-läsaren kunde inte laddas. Kontrollera internetanslutningen.');
  const data=new Uint8Array(await file.arrayBuffer());
  const pdf=await pdfjsLib.getDocument({data}).promise;
  let lines=[];
  for(let p=1;p<=pdf.numPages;p++){
    const page=await pdf.getPage(p), content=await page.getTextContent();
    const rows=new Map();
    for(const it of content.items){
      const y=Math.round((it.transform?.[5]||0)*2)/2, x=it.transform?.[4]||0;
      if(!rows.has(y)) rows.set(y,[]);
      rows.get(y).push({x,s:it.str});
    }
    [...rows.entries()].sort((a,b)=>b[0]-a[0]).forEach(([,items])=>{
      const line=items.sort((a,b)=>a.x-b.x).map(z=>z.s).join(' ').replace(/\s+/g,' ').trim();
      if(line) lines.push(line);
    });
  }
  return lines;
}
function detectPdfSource(lines){
  const text=lines.join(' ');
  if((/Nationellt resultatintyg/i.test(text) && /Avslutade kurser/i.test(text)) || (/Resultatintyg/i.test(text) && (/student\.ladok\.se\/verifiera/i.test(text) || /utdrag ur registret för studiedokumentation/i.test(text)))) return 'ladok';
  if(/Antagning\.se/i.test(text) && /Universitet och högskola/i.test(text)) return 'antagning';
  return 'unknown';
}



function ladokDateToTerm(date){
  const m=String(date||'').match(/^(\d{4})-(\d{2})-\d{2}$/);
  if(!m)return '';
  const month=Number(m[2]);
  return `${month>=7?'HT':'VT'}${m[1]}`;
}

function detectCourseLevel(text){
  const s=String(text||'').replace(/\u00ad/g,'').toLowerCase();
  if(/avancerad\s*nivå|advanced\s*level|second\s*cycle|\b(a1n|a1f|a1e|a2e|ax)\b/i.test(s)) return 'Avancerad nivå';
  if(/grund\s*nivå|grundnivå|first\s*cycle|\b(g1n|g1f|g1e|g2f|g2e|gx)\b/i.test(s)) return 'Grundnivå';
  return '';
}

function cleanLadokCourseName(name){
  let s=String(name||'').replace(/\s+/g,' ').trim();

  // Stop at known Ladok header/footer markers if PDF extraction has merged them
  // into the same line as the course name.
  const markers=[
    'Nationellt resultatintyg',
    'Utskriftsdatum',
    'Personnummer',
    'Kontrollkod',
    'Kontrollera intyget',
    'Verifierbart'
  ];
  for(const marker of markers){
    const i=s.toLowerCase().indexOf(marker.toLowerCase());
    if(i>0) s=s.slice(0,i).trim();
  }

  // Remove Swedish personal identity number and nearby name text if it leaked in.
  s=s.replace(/\s+[A-ZÅÄÖ][A-Za-zÅÄÖåäö\- ]{2,50}\s+\d{8}-\d{4}.*$/,'').trim();
  s=s.replace(/\s+\d{8}-\d{4}.*$/,'').trim();

  // Remove isolated print-date fragments that sometimes follow the header.
  s=s.replace(/\s+\d{4}-\d{2}-\d{2}\s*$/,'').trim();

  return s;
}


function detectIssuedDegreeLine(line){
 const s=String(line||'').replace(/\s+/g,' ').trim();
 const tests=[
   {type:'master',re:/\bmasterexamen\b/i,hp:120},
   {type:'magister',re:/\bmagisterexamen\b/i,hp:60},
   {type:'candidate',re:/\bkandidatexamen\b/i,hp:180}
 ];
 for(const t of tests){
   if(t.re.test(s)){
     const hpMatch=s.match(/(\d+(?:[,.]\d+)?)\s*hp\b/i);
     const hp=hpMatch?parseFloat(hpMatch[1].replace(',','.')):t.hp;
     return {type:t.type,hp,title:s};
   }
 }
 return null;
}
function extractDegreeSubject(lines,index){
 for(let j=index+1;j<Math.min(index+8,lines.length);j++){
   const line=String(lines[j]||'').trim();
   const m=line.match(/^Huvudområde:\s*(.+)$/i);
   if(m)return m[1].trim();
   if(/^(Avslutade kurser|Summering|Utfärdade bevis|Kod Benämning)/i.test(line))break;
 }
 return '';
}
function extractDegreeDates(lines,index){
 for(let j=index+1;j<Math.min(index+10,lines.length);j++){
   const line=String(lines[j]||'').trim();
   const dates=line.match(/\b\d{4}-\d{2}-\d{2}\b/g)||[];
   if(dates.length>=2)return {completedDate:dates[0],issuedDate:dates[1]};
   if(dates.length===1){
     // Ladok can split the two dates over visual lines.
     for(let k=j+1;k<Math.min(j+3,lines.length);k++){
       const next=(String(lines[k]||'').match(/\b\d{4}-\d{2}-\d{2}\b/g)||[]);
       if(next.length)return {completedDate:dates[0],issuedDate:next[0]};
     }
   }
   if(/^Avslutade kurser$/i.test(line))break;
 }
 return {completedDate:'',issuedDate:''};
}
function parseLadokLines(rawLines){
  const lines=rawLines.map(x=>String(x).replace(/\s+/g,' ').trim()).filter(Boolean);
  const text=lines.join(' ');
  const isLadok=(/Nationellt resultatintyg/i.test(text)&&/Avslutade kurser/i.test(text)) || (/Resultatintyg/i.test(text) && (/student\.ladok\.se\/verifiera/i.test(text) || /utdrag ur registret för studiedokumentation/i.test(text)));
  let institution='Okänt lärosäte', inCourses=false, inPartialCourses=false, partialParent='', out=[], issuedDegrees=[];
  const instLine=l=>{
    if(/Resultatintyg över högre utbildning|svenska universitet|Ladok/i.test(l)) return false;
    return l.length<100 && /(universitet|högskol)/i.test(l);
  };
  // Footer/header institution can appear after the actual course rows in Ladok PDFs.
  const institutionCandidates=lines.filter(instLine);
  if(institutionCandidates.length) institution=institutionCandidates[institutionCandidates.length-1];
  const rowRe=/^([A-ZÅÄÖ0-9][A-ZÅÄÖ0-9.\-]{2,15})\s+(.+?)\s+(\d+(?:[,.]\d+)?)\s*hp\s+([A-ZÅÄÖ0-9+\-]+)\s+(\d{4}-\d{2}-\d{2})(?:\s+\d+)?$/i;
  const partialRowRe=/^(.+?)\s+(\d+(?:[,.]\d+)?)\s*hp\s+([A-ZÅÄÖ0-9+\-]+)\s+(\d{4}-\d{2}-\d{2})(?:\s+\d+)?$/i;
  const partialParentRe=/^(.+?)\s*\((\d+(?:[,.]\d+)?)\s*hp\)\s*$/i;
  const ignoreContinuation=l=>{
    const s=String(l||'').trim();
    if(/^(Summering|Totalt|varav tillgodoräknat|Övrig tillgodoräknad|Noter och information|Kontrollera intyget|Verifierbart tom|Kontrollkod|Sida \d|Kod Benämning|Kod$|Benämning$|Omfattning$|Betyg$|Datum$|Not$|Utfärdade bevis|Titel|Huvudområde:)/i.test(s)) return true;
    // Sidhuvud/sidfot från Ladok kan hamna mitt i en kursrad när PDF-texten bryts.
    if(/Nationellt resultatintyg|Utskriftsdatum|Personnummer/i.test(s)) return true;
    if(/\b\d{8}-\d{4}\b/.test(s)) return true;
    return false;
  };

  for(let i=0;i<lines.length;i++){
    const l=lines[i];
    if(instLine(l)) institution=l;
    const degreeLine=detectIssuedDegreeLine(l);
    if(degreeLine){
      const subject=extractDegreeSubject(lines,i);
      const dates=extractDegreeDates(lines,i);
      const key=[degreeLine.type,subject,institution,degreeLine.title,dates.completedDate].join('|').toLowerCase();
      if(!issuedDegrees.some(x=>x._key===key)){
        issuedDegrees.push({...degreeLine,...dates,subject,institution,_key:key,verified:true,source:'Ladok'});
      }
    }
    if(/^Avslutade kurser$/i.test(l)){inCourses=true;inPartialCourses=false;partialParent='';continue}
    if(/^Delar i ej avslutade kurser$/i.test(l)){inPartialCourses=true;inCourses=false;partialParent='';continue}
    if(/^Summering$/i.test(l)){inCourses=false;inPartialCourses=false;partialParent='';continue}
    if(!inCourses && !inPartialCourses) continue;
    if(/^Kod Benämning/i.test(l) || /^Benämning\s+Omfattning/i.test(l)) continue;

    if(inPartialCourses){
      const parent=l.match(partialParentRe);
      if(parent && !/\b(?:G|VG|U|A|B|C|D|E|F)\b/i.test(l)){
        partialParent=cleanLadokCourseName(parent[1]);
        continue;
      }
      const pm=l.match(partialRowRe);
      if(pm){
        const name=cleanLadokCourseName(pm[1]), hp=parseFloat(pm[2].replace(',','.')), grade=pm[3], date=pm[4];
        // Only completed credit-bearing components count as earned hp.
        if(hp>0 && !/^(U|F)$/i.test(grade)){
          const parentSubject=partialParent ? guessSubject(partialParent,'',institution) : '';
          out.push({
            name,code:'',hp,grade,date,term:ladokDateToTerm(date),institution,
            parentCourse:partialParent,partialCourse:true,
            level:detectCourseLevel(l)||detectCourseLevel(partialParent),
            levelSource:(detectCourseLevel(l)||detectCourseLevel(partialParent))?'Intyg':'',
            levelVerified:Boolean(detectCourseLevel(l)||detectCourseLevel(partialParent)),
            subject:parentSubject||guessSubject(name,'',institution),
            thesis:/examensarbete|självständigt arbete|kandidatuppsats|kandidatprojekt|degree project|thesis/i.test(name),
            selected:true
          });
        }
        continue;
      }
    }

    const m=l.match(rowRe);
    if(m){
      const code=m[1], name=cleanLadokCourseName(m[2]), hp=parseFloat(m[3].replace(',','.')), grade=m[4], date=m[5];
      out.push({
        name,code,hp,grade,date,term:ladokDateToTerm(date),institution,
        level:detectCourseLevel(l)||detectCourseLevel(name),
        levelSource:(detectCourseLevel(l)||detectCourseLevel(name))?'Intyg':'',
        levelVerified:Boolean(detectCourseLevel(l)||detectCourseLevel(name)),
        subject:guessSubject(name,code,institution),
        thesis:/examensarbete|självständigt arbete|kandidatuppsats|kandidatprojekt|degree project|thesis/i.test(name),
        selected:true
      });
      continue;
    }

    // Ladok may wrap a long course title onto the next visual line.
    if(out.length && !ignoreContinuation(l) && !/\d+(?:[,.]\d+)?\s*hp/i.test(l) && !/^\d{4}-\d{2}-\d{2}$/.test(l)){
      const prev=out[out.length-1];
      if(prev.institution===institution && l.length<100) {
        prev.name=cleanLadokCourseName(prev.name+' '+l);
        if(!prev.level) prev.level=detectCourseLevel(l);
        prev.subject=guessSubject(prev.name,prev.code,prev.institution);
      }
    }
  }
  out=out.map(c=>({...c,name:cleanLadokCourseName(c.name)})).filter(c=>c.name); const total=out.reduce((s,c)=>s+Number(c.hp||0),0);
  return {isLadok,courses:out,expectedTotal:total,issuedDegrees:issuedDegrees.map(({_key,...d})=>d)};
}
async function importPdf(inp, chosenSource='auto'){
  const files=[...(inp.files||[])]; if(!files.length)return;
  importedCandidates=[]; importPreview.innerHTML='';
  try{
    let detectedSources=[], expectedTotals=[], issued=[];
    for(const file of files){
      const lines=await readPdfLines(file);
      const detected=detectPdfSource(lines);
      const source=chosenSource==='auto'?detected:chosenSource;
      detectedSources.push(detected);

      let parsed;
      if(source==='ladok' || detected==='ladok') parsed=parseLadokLines(lines);
      else if(source==='antagning' || detected==='antagning') parsed=parseAntagningLines(lines);
      else throw new Error('StudieLots känner inte igen dokumentet som ett Ladok-resultatintyg eller Antagning.se-meriter.');

      if(source==='ladok' && !parsed.isLadok) throw new Error('Det här ser inte ut som ett resultatintyg från Ladok.');
      if(source==='antagning' && !parsed.isAntagning) throw new Error('Fel Antagning.se-PDF. Spara sidan Mina meriter → Universitet och högskola.');

      importedCandidates.push(...parsed.courses.map(c=>{
        const safe=(window.__studielotsPrivacy?.sanitizeCourse||((x)=>x))(c);
        return {...safe,sourceFile:file.name};
      }));
      if(Number.isFinite(parsed.expectedTotal)) expectedTotals.push(parsed.expectedTotal);
      if(parsed.issuedDegrees) issued.push(...parsed.issuedDegrees);
    }
    markDuplicates();

    if(!importedCandidates.length){
      importStatus.textContent='PDF:en kunde läsas, men Lotsen hittade inga avslutade kurser.';
      return;
    }
    const importedHp=importedCandidates.reduce((s,c)=>s+Number(c.hp||0),0);
    const expected=expectedTotals.reduce((s,n)=>s+n,0);
    const sourceLabel=detectedSources.includes('ladok')?'Ladok':'Antagning.se';
    const check=expectedTotals.length && Math.abs(importedHp-expected)<0.01
      ? `✓ ${fmtHp(importedHp)} hp hittades.`
      : `${fmtHp(importedHp)} hp hittades.`;
    importStatus.innerHTML=`<span class="import-ok">✓ ${sourceLabel} identifierat</span> · ${importedCandidates.length} kurser · ${check}${issued.length?` · ${issued.length} examen${issued.length===1?'':'ina'} hittad${issued.length===1?'':'e'}`:''}`;
    if(issued.length){
      try{sessionStorage.setItem('lotsen_issued_degrees',JSON.stringify(issued));}catch(e){}
    }
    renderImportPreview();
  }catch(e){
    importStatus.innerHTML='<span class="import-error">Kunde inte importera dokumentet.</span> '+escapeHtml(e.message);
  }
}
function fmtHp(n){return Number(n).toLocaleString('sv-SE',{maximumFractionDigits:1})}
function normCourse(s){return String(s).toLowerCase().replace(/[^a-zåäö0-9]/g,'')}
function markDuplicates(){const existing=new Set(courses.map(c=>(c.code||normCourse(c.name))+'|'+Number(c.hp)));const seen=new Set();for(const c of importedCandidates){const k=(c.code||normCourse(c.name))+'|'+Number(c.hp);c.duplicate=existing.has(k)||seen.has(k);if(c.duplicate)c.selected=false;seen.add(k)}}
function parseAntagningLines(rawLines){
 const lines=rawLines.map(x=>String(x).replace(/\s+/g,' ').trim()).filter(Boolean);
 const joined=lines.join(' ');
 const isAntagning=/Antagning\.se/i.test(joined)&&/Universitet och högskola/i.test(joined);
 const tm=joined.match(/Högskolepoäng totalt:\s*([0-9]+(?:[,.][0-9]+)?)/i);
 const expectedTotal=tm?parseFloat(tm[1].replace(',','.')):NaN;
 let institution='Okänt lärosäte', out=[];
 const isInstitution=l=>l.length<90 && !/^(Universitet\/Högskola|Ger högskolepoäng|Högskolepoäng|Tillbaka)/i.test(l) && /(universitet|högskol|University)/i.test(l);
 const val=(l,key)=>l.toLowerCase().startsWith(key.toLowerCase()+' ')?l.slice(key.length).trim():null;
 for(let i=0;i<lines.length;i++){
   const l=lines[i]; if(isInstitution(l)) institution=l;
   if(!/^Kurs\s+/i.test(l)||/^Kurskod/i.test(l)) continue;
   let name=l.replace(/^Kurs\s+/i,'').trim(), j=i+1;
   while(j<lines.length&&!/^Kurskod\s+/i.test(lines[j])&&j<i+6){if(!/antagning\.se|^Sida \d+/i.test(lines[j])) name+=' '+lines[j];j++}
   if(j>=lines.length||!/^Kurskod\s+/i.test(lines[j])) continue;
   const code=lines[j].replace(/^Kurskod\s+/i,'').trim(); let hp=null,grade='',date='',gives=''; let k=j+1;
   for(;k<Math.min(lines.length,j+10);k++){
     let v;if((v=val(lines[k],'Poäng'))!==null&&hp===null)hp=parseFloat(v.replace(',','.'));
     else if((v=val(lines[k],'Betyg'))!==null&&!grade)grade=v;
     else if((v=val(lines[k],'Datum'))!==null&&!date)date=v;
     else if((v=val(lines[k],'Ger högskolepoäng'))!==null){gives=v;k++;break}
   }
   if(!hp||gives!=='Ja') continue;
   let componentHp=0, componentCompleted=false, q=k;
   while(q<lines.length&&!/^Kurs\s+/i.test(lines[q])&&!/^Totalt lärosäte/i.test(lines[q])){
     if(/^Ingående del\s+/i.test(lines[q])){
       let chp=null,cgrade='',cdate='';
       for(let z=q+1;z<Math.min(lines.length,q+9)&&!/^Ingående del\s+/i.test(lines[z])&&!/^Kurs\s+/i.test(lines[z]);z++){
         let v;if((v=val(lines[z],'Poäng'))!==null&&chp===null)chp=parseFloat(v.replace(',','.'));
         else if((v=val(lines[z],'Betyg'))!==null&&!cgrade)cgrade=v;
         else if((v=val(lines[z],'Datum'))!==null&&!cdate)cdate=v;
       }
       if(chp&&cgrade&&cgrade!=='-'&&cdate&&cdate!=='-'){componentHp+=chp;componentCompleted=true}
     }
     q++;
   }
   const completed=(grade&&grade!=='-'&&date&&date!=='-') || (componentCompleted&&componentHp+0.001>=hp);
   if(!completed) continue;
   const nearby=lines.slice(Math.max(0,i),Math.min(lines.length,q+2)).join(' ');
   out.push({
     name:name.replace(/\s+/g,' ').trim(),code,hp,grade,date,
     term:ladokDateToTerm(date),
     institution,
     level:detectCourseLevel(nearby),
     levelSource:detectCourseLevel(nearby)?'Intyg':'',
     levelVerified:Boolean(detectCourseLevel(nearby)),
     subject:guessSubject(name,code,institution),
     thesis:/examensarbete|självständigt arbete|kandidatuppsats|kandidatprojekt|degree project|thesis/i.test(name),
     selected:true
   });
   i=j;
 }
 return {isAntagning,expectedTotal,courses:out};
}
function guessSubject(name,code='',institution=''){
 const n=String(name||'').toLowerCase();
 const c=String(code||'').toUpperCase().replace(/\s+/g,'');
 if(/folkhälso|epidemiologi|public health/.test(n)) return 'Folkhälsovetenskap';
 if(/psykolog|psycholog/.test(n)) return 'Psykologi';
 if(/sociolog|sociology/.test(n)) return 'Sociologi';
 if(/nationalekonomi|mikroekonomi|makroekonomi|economics/.test(n)) return 'Nationalekonomi';
 if(/statistik|statistics/.test(n)) return 'Statistik';
 if(/arbetsvetenskap|work science|arbetsliv/.test(n)) return 'Arbetsvetenskap';
 if(/pedagog|didaktik|education/.test(n)) return 'Pedagogik';
 if(/ledarskap|leadership|organisation och ledarskap/.test(n)) return 'Ledarskap';
 if(/företagsekonomi|business|marketing|marknadsför|redovis|accounting|management|finance|finansiering/.test(n) || /^FÖ/.test(c)) return 'Företagsekonomi';
 if(/^(IIG|IKG|IKA|IDG)/.test(c)) return 'Idrottsvetenskap';
 if(/idrott|sport|träningslära|fysisk aktivitet|idrottsmedicin|hälsopromotion|hälsokommunikation|coaching|rörelse|fysisk kapacitet/.test(n)) return 'Idrottsvetenskap';
 if(/juridik|law/.test(n)) return 'Juridik';
 if(/informatik|computer|programmer|data science/.test(n)) return 'Informatik';
 return 'Behöver granskas';
}
function renderImportPreview(){
 const selected=importedCandidates.filter(c=>c.selected&&!c.duplicate);
 const totalHp=importedCandidates.reduce((s,c)=>s+Number(c.hp||0),0);
 const institutions=[...new Set(importedCandidates.map(c=>c.institution).filter(Boolean))];

 importPreview.innerHTML=`
   <details class="import-results">
     <summary class="import-results-summary">
       <div>
         <strong>${importedCandidates.length} kurser hittades</strong>
         <div class="small muted">${fmtHp(totalHp)} hp · ${institutions.length} ${institutions.length===1?'lärosäte':'lärosäten'}${importedCandidates.some(c=>!c.level)?' · nivåkontroll pågår i bakgrunden':''}</div>
       </div>
       <span class="detail-arrow">›</span>
     </summary>
     <div class="import-results-list">
       ${importedCandidates.map((c,i)=>`<div class="course import-compact">
         <div class="import-main">
           <strong>${escapeHtml(c.name)}</strong>
           <div class="small muted">${escapeHtml(c.institution||'Okänt lärosäte')} · ${escapeHtml(c.code||'')} · ${escapeHtml(c.level||'Nivå ej verifierad')} · ${fmtHp(c.hp)} hp${c.duplicate?' · Möjlig dubblett':''}</div>
         </div>
         <label class="import-check"><input type="checkbox" ${c.selected?'checked':''} onchange="importedCandidates[${i}].selected=this.checked"> Importera</label>
       </div>`).join('')}
     </div>
   </details>
   <div class="import-confirm"><button class="primary" id="confirmImportBtn" type="button">Importera valda kurser</button></div>`;
}
function confirmImport(){
  const chosen=importedCandidates
    .filter(c=>c.selected&&!c.duplicate)
    .map(({selected,duplicate,sourceFile,...c})=>c);

  if(!chosen.length){
    importStatus.textContent='Välj minst en kurs att importera.';
    return;
  }

  courses.push(...chosen);
  try{sessionStorage.setItem('examensmatch_courses',JSON.stringify(courses))}catch(e){}

  importStatus.textContent=`${chosen.length} kurser importerades.`;
  importPreview.innerHTML='';

  // Efter import stannar användaren på Hem.
  document.querySelectorAll('.screen').forEach(s=>s.classList.remove('active'));
  document.getElementById('start')?.classList.add('active');
  document.querySelectorAll('.nav button[data-screen]').forEach(b=>b.classList.toggle('active',b.dataset.screen==='start'));
  document.querySelectorAll('.lotsen-bottomnav button[data-screen]').forEach(b=>b.classList.toggle('active',b.dataset.screen==='start'));
  window.scrollTo(0,0);

  // Uppdatera alla vyer i bakgrunden, men lämna användaren på Hem.
  try{renderCourses()}catch(e){console.error(e)}
  try{refreshAll()}catch(e){
    console.error(e);
    try{renderDegrees()}catch(_){}
  }

  // Kör en extra renderpass när DOM och sessionsdata hunnit uppdateras.
  requestAnimationFrame(()=>{
    try{refreshAll()}catch(e){console.error('Hem refresh efter import',e)}
  });
  setTimeout(()=>{
    try{refreshAll()}catch(e){console.error('Hem refresh efter import 2',e)}
  },60);

  // Kurskod + lärosäte + termin används i bakgrunden för att verifiera nivå.
  setTimeout(async()=>{
    try{
      await resolveMissingCourseLevelsInBackground();
    }catch(e){}
    try{refreshAll()}catch(e){console.error('Hem refresh efter nivåanalys',e)}
  },100);
}
function escapeHtml(s){return String(s).replace(/[&<>"']/g,m=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#039;'}[m]))}





function issuedBachelorInfo(){
 let issued=[];
 try{issued=JSON.parse(sessionStorage.getItem('lotsen_issued_degrees')||'[]')}catch(e){}
 const hit=issued.find(x=>x.type==='candidate');
 return hit||null;
}
function detectedBachelor(){
 if(issuedBachelorInfo())return true;
 return degrees.some(d=>d.kind==='candidate'&&calc(d).pct===100);
}
function candidateReadiness(){
 const issued=issuedBachelorInfo();
 const rows=degrees
   .filter(d=>d.kind==='candidate')
   .map(d=>{
     const r=calc(d);
     return {
       subject:d.subject||'',
       name:d.name,
       score:Number(r.pct||0),
       remaining:Number(r.remaining||0),
       subjectMissing:Number(r.subjectMissing??r.missingSubject??0),
       ready:Number(r.pct||0)>=100,
       near:Number(r.remaining||0)<=30 && Number(r.pct||0)>=80
     };
   })
   .filter(x=>x.subject);

 if(issued){
   const subject=String(issued.subject||'').trim();
   if(subject){
     const existing=rows.find(x=>x.subject.toLowerCase()===subject.toLowerCase());
     if(existing){existing.ready=true;existing.near=true;existing.score=100;existing.remaining=0}
     else rows.unshift({subject,name:`Kandidatexamen i ${subject}`,score:100,remaining:0,subjectMissing:0,ready:true,near:true});
   }else{
     // Candidate is verified, but Ladok did not expose the subject reliably.
     // Use strongest known subject as a cautious fallback.
     const best=bestKnownMajor();
     if(best){
       const existing=rows.find(x=>x.subject.toLowerCase()===best.toLowerCase());
       if(existing){existing.ready=true;existing.near=true}
       else rows.unshift({subject:best,name:`Kandidatexamen i ${best}`,score:100,remaining:0,subjectMissing:0,ready:true,near:true});
     }
   }
 }
 return rows.sort((a,b)=>(b.ready-a.ready)||(b.score-a.score)||(a.remaining-b.remaining));
}
function bestKnownMajor(){
 const sums={};
 courses.filter(c=>c.selected!==false).forEach(c=>{
   const s=c.subject||guessSubject(c.name||'');
   if(!s||s==='Behöver granskas'||s==='Övrigt')return;
   sums[s]=(sums[s]||0)+Number(c.hp||0);
 });
 return Object.entries(sums).sort((a,b)=>b[1]-a[1])[0]?.[0]||'';
}

function advancedRuleBreakdown(rule,subject){
 if(!rule)return null;
 const norm=s=>String(s||'').trim().toLowerCase();
 const selected=courses.filter(c=>c.selected!==false);

 // Courses already used in the qualifying degree are not auto-counted in an advanced degree.
 const fresh=selected.filter(c=>!courseUsedInPriorDegree(c));
 const advanced=fresh.filter(isAdvancedCourse);
 const basic=fresh.filter(c=>!isAdvancedCourse(c)&&isBasicCourse(c));

 const maxBasic=Math.max(0,Number(rule.maxBasicHp||0));
 const allowedBasic=maxBasic?basic.slice():[];
 let basicUsed=0, basicCourses=[];
 for(const c of allowedBasic){
   if(basicUsed>=maxBasic)break;
   const hp=Math.min(Number(c.hp||0),maxBasic-basicUsed);
   if(hp>0){basicUsed+=hp;basicCourses.push({...c,_countedHp:hp})}
 }

 const mainAdvanced=advanced.filter(c=>norm(courseSubject(c))===norm(subject));
 const mainHp=Math.min(Number(rule.mainSubject||0),mainAdvanced.reduce((s,c)=>s+Number(c.hp||0),0));
 const thesisCourses=mainAdvanced.filter(isThesisCourse);
 const thesisHp=Math.min(Number(rule.thesis||0),thesisCourses.reduce((s,c)=>s+Number(c.hp||0),0));

 const advancedHpTotal=advanced.reduce((s,c)=>s+Number(c.hp||0),0);
 const totalCounted=Math.min(Number(rule.total||0),advancedHpTotal+basicUsed);

 const mainMissing=Math.max(0,Number(rule.mainSubject||0)-mainHp);
 const thesisMissing=Math.max(0,Number(rule.thesis||0)-thesisHp);
 const advancedMinimum=Number(rule.minAdvancedHp!=null?rule.minAdvancedHp:(rule.allAdvanced?rule.total:Math.max(0,Number(rule.total||0)-maxBasic)));
 const advancedMissing=Math.max(0,advancedMinimum-advancedHpTotal);
 const totalMissing=Math.max(0,Number(rule.total||0)-totalCounted);

 const req=(rule.requiredOther||[]).map(r=>{
   const subjects=(r.subjects||[]).map(norm);
   const matches=advanced.filter(c=>subjects.includes(norm(courseSubject(c))));
   const have=Math.min(Number(r.hp||0),matches.reduce((s,c)=>s+Number(c.hp||0),0));
   return {...r,have,courses:matches,missing:Math.max(0,Number(r.hp||0)-have)};
 });
 const reqMissing=req.reduce((s,r)=>s+r.missing,0);

 // Requirements overlap, so "remaining" is the strongest outstanding requirement,
 // not the sum of all labels.
 const institutionNeed=Number(rule.institutionMinHp||0);
 const institutionKeys=(rule.institutionMatch||[]).map(norm);
 const institutionHp=institutionNeed?fresh.filter(c=>{
   const inst=norm(c.institution||'');
   return institutionKeys.some(k=>inst.includes(k));
 }).reduce((s,c)=>s+Number(c.hp||0),0):0;
 const institutionMissing=Math.max(0,institutionNeed-institutionHp);

 const remaining=Math.max(totalMissing,mainMissing,thesisMissing,advancedMissing,reqMissing,institutionMissing);

 const missing=[];
 if(mainMissing>0)missing.push({type:'main',hp:mainMissing,label:`${fmtHp(mainMissing)} hp ${subject} på avancerad nivå`,subject});
 if(thesisMissing>0)missing.push({type:'thesis',hp:thesisMissing,label:`${fmtHp(thesisMissing)} hp examensarbete i ${subject}`,subject});
 req.filter(r=>r.missing>0).forEach(r=>missing.push({type:'required',hp:r.missing,label:`${fmtHp(r.missing)} hp ${r.label}`}));
 if(advancedMissing>0 && advancedMissing>mainMissing)missing.push({type:'advanced',hp:advancedMissing,label:`${fmtHp(advancedMissing)} hp på avancerad nivå`});
 if(institutionMissing>0)missing.push({type:'institution',hp:institutionMissing,label:`${fmtHp(institutionMissing)} hp behöver examineras vid Chalmers`});
 if(totalMissing>0 && !missing.length)missing.push({type:'total',hp:totalMissing,label:`${fmtHp(totalMissing)} hp återstår`});

 return {
   total:Number(rule.total||0),totalCounted,remaining,
   advancedHp:advancedHpTotal,basicHp:basicUsed,
   mainHp,thesisHp,mainMissing,thesisMissing,advancedMissing,totalMissing,
   institutionHp,institutionNeed,institutionMissing,
   req,reqMissing,missing,
   countedCourses:[...advanced,...basicCourses],
   excludedPrior:selected.filter(courseUsedInPriorDegree)
 };
}

function advancedUniversityOptions(subject,degreeType){
 const kind=String(degreeType||'').toLowerCase()==='magister'?'magister':'master';
 return flexibleDegreeCatalog.map(d=>{
   const rule=localDegreeRule(d.id,subject,kind);
   if(!rule)return null;
   const breakdown=advancedRuleBreakdown(rule,subject);
   if(!breakdown)return null;
   return {d,rule,breakdown,remaining:breakdown.remaining,verified:Boolean(rule.verified),major:subject,advanced:true,degreeTitle:{title:rule.label||`${degreeType}examen i ${subject}`}};
 }).filter(Boolean).sort((a,b)=>(Number(b.verified)-Number(a.verified))||a.remaining-b.remaining||String(a.d.university||'').localeCompare(String(b.d.university||''),'sv'));
}
function advancedOpportunitySummary(o){
 const opts=advancedUniversityOptions(o.subject,o.degreeType);
 let preferred='';
 try{preferred=sessionStorage.getItem('lotsen_preferred_profile')||''}catch(e){}
 const best=(preferred&&opts.find(x=>x.d?.id===preferred))||opts[0]||null;
 if(!best)return {remaining:Number(o.remaining||0),missing:[],university:'',profileId:''};
 return {remaining:Number(best.remaining||0),missing:best.breakdown.missing||[],university:best.d.university||'',profileId:best.d.id||''};
}

function advancedDegreeOpportunities(){
 const readiness=candidateReadiness().filter(x=>x.ready||x.near);
 if(!readiness.length)return [];

 const rows=[];
 readiness.slice(0,4).forEach(c=>{
   const eligibilityLabel=c.ready?'Kandidat klar':'Nära kandidat';
   const eligibilityScore=c.ready?100:Math.max(0,Math.min(99,c.score));

   ['Magister','Master'].forEach(degreeType=>{
     const total=degreeType==='Magister'?60:120;
     const opts=advancedUniversityOptions(c.subject,degreeType);
     if(!opts.length)return;
     const best=opts[0];
     const remaining=Number(best.remaining||total);
     rows.push({
       key:`${degreeType.toLowerCase()}:${c.subject}`,
       name:`${degreeType}examen i ${c.subject.toLowerCase()}`,
       subject:c.subject,
       score:Math.max(0,Math.min(100,Math.round(100*(total-remaining)/total))),
       remaining,
       source:'advanced',
       degreeType,total,
       candidateReady:c.ready,
       candidateNear:c.near&&!c.ready,
       candidateRemaining:c.remaining,
       candidateScore:eligibilityScore,
       eligibilityLabel,
       advancedMissing:best.breakdown.missing||[],
       canonicalUniversity:best.d.university||'',
       canonicalProfileId:best.d.id||''
     });
   });
 });
 return rows;
}


function bestCandidateUniversityResult(subject){
 try{
   const rows=flexibleDegreeCandidates()
     .filter(x=>String(x.major||'').toLowerCase()===String(subject||'').toLowerCase())
     .sort((a,b)=>{
       const av=Number(Boolean(a.d?.verified));
       const bv=Number(Boolean(b.d?.verified));
       return (bv-av)||Number(a.remaining||999)-Number(b.remaining||999);
     });
   return rows[0]||null;
 }catch(e){
   return null;
 }
}
function canonicalCandidateProgress(subject,fallback){
 const best=bestCandidateUniversityResult(subject);
 if(best){
   const remaining=Number(best.remaining||0);
   return {
     remaining,
     score:Math.max(0,Math.min(100,Math.round(100*(180-remaining)/180))),
     university:best.d?.university||'',
     profileId:best.d?.id||''
   };
 }
 return {
   remaining:Number(fallback?.remaining||0),
   score:Number(fallback?.score||0),
   university:'',
   profileId:''
 };
}

function safeDegreeOpportunities(){
  const rows=[];

  // Core catalogue must always be available.
  try{
    degrees.forEach(d=>{
      const r=calc(d);
      const canonical=canonicalCandidateProgress(d.subject||'',{score:Number(r.pct||0),remaining:Number(r.remaining||0)});
      rows.push({
        key:(d.subject||d.name).toLowerCase(),
        name:d.name,
        subject:d.subject||'',
        score:canonical.score,
        remaining:canonical.remaining,
        source:'specific',
        routeId:d.id,
        canonicalUniversity:canonical.university,
        canonicalProfileId:canonical.profileId
      });
    });
  }catch(e){console.error('Lotsen core opportunities',e)}

  // Flexible university rules are additive only; they can never blank the core list.
  try{
    if(typeof flexibleDegreeCandidates==='function'){
      flexibleDegreeCandidates().forEach(x=>{
        rows.push({
          key:String(x.major||x.degreeTitle?.title||x.d?.name||'').toLowerCase(),
          name:`Kandidatexamen i ${x.major}`,
          subject:x.major||'',
          score:Math.max(0,Math.min(100,Math.round(100*(180-Number(x.remaining||0))/180))),
          remaining:Number(x.remaining||0),
          source:'flex',
          canonicalUniversity:x.d?.university||'',
          canonicalProfileId:x.d?.id||''
        });
      });
    }
  }catch(e){console.error('Lotsen flexible opportunities',e)}

  // Advanced paths are additive too.
  try{rows.push(...advancedDegreeOpportunities())}catch(e){console.error('Lotsen advanced opportunities',e)}

  const best=new Map();
  for(const r of rows){
    const subject=(r.subject||r.name).toLowerCase();
    const key=r.source==='advanced'
      ? `advanced:${String(r.degreeType||'').toLowerCase()}:${subject}`
      : `candidate:${subject}`;
    const prev=best.get(key);
    if(!prev){
      best.set(key,r);
    }else if(r.source==='flex' && prev.source!=='flex'){
      best.set(key,r);
    }else if(r.source===prev.source && (r.remaining<prev.remaining || (r.remaining===prev.remaining&&r.score>prev.score))){
      best.set(key,r);
    }
  }
  const finalRows=[...best.values()].map(r=>{
    if(r.source==='advanced')return r;
    const opts=universityOptionsForOpportunity(r);
    if(!opts.length)return r;
    const min=Number(opts[0].remaining||0);
    return {...r,remaining:min,score:Math.max(0,Math.min(100,Math.round(100*(180-min)/180))),canonicalUniversity:opts[0].d?.university||'',canonicalProfileId:opts[0].d?.id||''};
  });
  return finalRows.sort((a,b)=>{
    if(a.source==='advanced'&&b.source==='advanced'){
      return Number(b.candidateReady||0)-Number(a.candidateReady||0)
        || Number(b.candidateScore||0)-Number(a.candidateScore||0)
        || a.remaining-b.remaining;
    }
    return b.score-a.score||a.remaining-b.remaining;
  });
}

function opportunityByKey(key){
 return safeDegreeOpportunities().find(x=>x.key===key);
}

