function hpForSubjects(subjects){
 const set=(subjects||[]).map(x=>String(x).toLowerCase());
 return courses.filter(c=>c.selected!==false && set.includes(String(c.subject||guessSubject(c.name||'')).toLowerCase()))
   .reduce((s,c)=>s+Number(c.hp||0),0);
}
function localRuleBreakdown(rule,major){
 if(!rule)return null;
 const audit=candidateCourseAudit(major);
 const selected=audit.count;
 const norm=s=>String(s||'').trim().toLowerCase();

 const main=selected.filter(c=>norm(c.subject||guessSubject(c.name||''))===norm(major));
 const mainHp=Math.min(rule.mainSubject,main.reduce((s,c)=>s+Number(c.hp||0),0));

 const req=(rule.requiredOther||[]).map(r=>{
   const set=(r.subjects||[]).map(x=>norm(x));
   const matching=selected.filter(c=>set.includes(norm(c.subject||guessSubject(c.name||''))));
   return {...r,have:Math.min(r.hp,matching.reduce((s,c)=>s+Number(c.hp||0),0)),courses:matching};
 });

 const used=new Set(main);
 req.forEach(r=>(r.courses||[]).forEach(c=>used.add(c)));

 const electiveCourses=selected.filter(c=>!used.has(c));
 const electiveAvailable=electiveCourses.reduce((s,c)=>s+Number(c.hp||0),0);
 const electiveUsed=Math.min(rule.electiveHp,electiveAvailable);

 const missingMain=Math.max(0,rule.mainSubject-mainHp);
 const missingReq=req.reduce((s,r)=>s+Math.max(0,r.hp-r.have),0);
 const missingElective=Math.max(0,rule.electiveHp-electiveUsed);
 const institutionNeed=Number(rule.institutionMinHp||0);
 const institutionKeys=(rule.institutionMatch||[]).map(norm);
 const institutionHp=institutionNeed?selected.filter(c=>{
   const inst=norm(c.institution||'');
   return institutionKeys.some(k=>inst.includes(k));
 }).reduce((s,c)=>s+Number(c.hp||0),0):0;
 const missingInstitution=Math.max(0,institutionNeed-institutionHp);

 return {
   main,mainHp,req,electiveCourses,electiveUsed,
   missingMain,missingReq,missingElective,
   institutionHp,institutionNeed,missingInstitution,
   reviewCourses:audit.review,
   excludedCourses:audit.excluded
 };
}

function coursesForDegree(o){
 const selected=courses.filter(c=>c.selected!==false);
 const subject=selected.filter(c=>courseSubject(c)===o.subject);
 const lockedThesis=selected.filter(c=>thesisReuseStatus(c,o.subject).locked);
 const others=selected.filter(c=>!subject.includes(c)&&!lockedThesis.includes(c));
 if(o.source==='advanced'){
   return {
     subject:selected.filter(c=>(/Avancerad nivå/i.test(String(c.level||''))||/^A[12]/i.test(String(c.progression||'')))&&courseSubject(c)===o.subject),
     others:[],
     lockedThesis
   };
 }
 return {subject,others,lockedThesis};
}
function missingForOpportunity(o){
 if(!o)return [];
 if(o.source==='advanced'){
   const s=advancedOpportunitySummary(o);
   return (s.missing||[]).map(x=>({label:x.label,hp:Number(x.hp||0),type:x.type,subject:x.subject}));
 }

 // Candidate paths: use the same university rule as the canonical "hp kvar" value.
 const path=canonicalPathResult(o);
 const opts=universityOptionsForOpportunity(o);
 const chosen=(path.profileId&&opts.find(x=>x.d?.id===path.profileId))||opts[0];
 if(chosen?.breakdown){
   const b=chosen.breakdown;
   const rows=[];
   if(Number(b.missingMain||0)>0){
     rows.push({label:`${o.subject} – huvudområde`,hp:Number(b.missingMain||0),type:'main',subject:o.subject});
   }
   (b.req||[]).forEach(r=>{
     const missing=Math.max(0,Number(r.hp||0)-Number(r.have||0));
     if(missing>0)rows.push({label:r.label,hp:missing,type:'required',subject:(r.subjects||[])[0]||''});
   });
   if(Number(b.missingElective||0)>0){
     rows.push({label:'Övriga/valfria kurser',hp:Number(b.missingElective||0),type:'elective'});
   }
   if(Number(b.missingInstitution||0)>0){
     rows.push({label:'Behöver examineras vid Chalmers',hp:Number(b.missingInstitution||0),type:'institution'});
   }

   // Enforce the same total remaining value everywhere.
   const target=Number(path.remaining||0);
   const sum=rows.reduce((s,x)=>s+Number(x.hp||0),0);
   if(target>sum){
     rows.push({label:'Övriga poäng till examen',hp:target-sum,type:'elective'});
   }else if(target<sum && rows.length){
     // Defensive normalization: trim only the generic/elective tail if duplicated constraints overlap.
     let over=sum-target;
     for(let i=rows.length-1;i>=0&&over>0;i--){
       if(rows[i].type==='elective'){
         const take=Math.min(over,rows[i].hp);
         rows[i].hp-=take; over-=take;
       }
     }
     return rows.filter(x=>x.hp>0);
   }
   return rows;
 }

 const remaining=Number(path.remaining||0);
 return remaining>0?[{label:'Återstår till examen',hp:remaining,generic:true}]:[];
}

function chalmersSuggestionReason(row,major,missing){
 const bits=[];
 if(String(row.subject||'').toLowerCase()===String(major||'').toLowerCase())bits.push(`matchar ${major}`);
 if(row.required)bits.push('obligatorisk i Chalmersprogram');
 else if(row.elective)bits.push('valbar i Chalmersprogram');
 const miss=String(missing||'').toLowerCase();
 const hay=[row.name,row.subject,...(row.keywords||[])].join(' ').toLowerCase();
 if(miss&&normalizedWords(miss).some(w=>w.length>4&&hay.includes(w)))bits.push('matchar det som saknas i din väg');
 return bits.length?bits.join(' · '):'relevant utifrån ämne och kursinnehåll';
}
function chalmersCourseSuggestions(major,o,limit=12){
 let ps=[];try{ps=normalizedProgramCatalog().filter(p=>p.university==='Chalmers tekniska högskola'&&p.academicYear==='2026/2027'&&!p.catalogOnly)}catch(e){return []}
 const completed=new Set((courses||[]).map(c=>String(c.code||'').trim().toUpperCase()).filter(Boolean));
 const advanced=!!(o?.source==='advanced'||String(o?.degreeType||'').match(/master|magister/i));
 let missing=[];try{missing=missingForOpportunity(o)||[]}catch(e){}
 const missingText=missing.map(x=>x.label||'').join(' ');
 const majorWords=normalizedWords(major||'').filter(w=>w.length>3);
 const aliases={
  'informationsteknik':['datateknik','programmering','software','mjukvara'],
  'automation och mekatronik':['automation','mekatronik','reglerteknik'],
  'samhällsbyggnadsteknik':['samhällsbyggnad','bygg','construction'],
  'teknisk fysik':['fysik','matematik'],
  'teknikvetenskap':['teknik','ingenjör'],
  'företagsekonomi':['industriell ekonomi','ekonomi','organisation','marknadsföring'],
  'psykologi':['kognitiv','ergonomi','beteende','human factors'],
  'idrottsvetenskap':['biomekanik','fysiologi','hälsa','rörelse']
 };
 const extra=aliases[String(major||'').toLowerCase()]||[];
 const seen=new Map();
 ps.forEach(program=>(program.courses||[]).forEach(c=>{
   const code=String(c.code||'').trim().toUpperCase(); if(!code||completed.has(code))return;
   const level=String(c.level||'').toLowerCase();
   if(advanced&&level&&level.includes('grund'))return;
   const hay=[c.name,c.subject,program.name,...(c.keywords||[])].join(' ').toLowerCase();
   let score=0;
   if(String(c.subject||'').toLowerCase()===String(major||'').toLowerCase())score+=45;
   majorWords.forEach(w=>{if(hay.includes(w))score+=12});
   extra.forEach(w=>{if(hay.includes(String(w).toLowerCase()))score+=9});
   normalizedWords(missingText).filter(w=>w.length>4).forEach(w=>{if(hay.includes(w))score+=4});
   if(c.required)score+=5;
   if(advanced&&level.includes('avancer'))score+=7;
   if(!advanced&&level.includes('grund'))score+=4;
   const row={...c,code,programCode:program.code,programName:program.name,programUrl:program.sourceUrl||'',verified:program.verified===true,score};
   const prev=seen.get(code); if(!prev||score>prev.score)seen.set(code,row);
 }));
 const ranked=[...seen.values()].filter(x=>x.score>=9).sort((a,b)=>b.score-a.score||Number(b.required)-Number(a.required)||String(a.name).localeCompare(String(b.name),'sv'));
 return ranked.slice(0,limit).map(x=>({...x,reason:chalmersSuggestionReason(x,major,missingText)}));
}
function chalmersCourseProviderOption(o){
 return {d:{id:'course-chalmers',name:'Kurser vid Chalmers',university:'Chalmers tekniska högskola',verified:true,hp:degreeTotalHp(o)},major:o.subject||'',remaining:Number(o.remaining||0),verified:true,courseProviderOnly:true,rule:null,degreeTitle:{title:`Komplettera med kurser vid Chalmers`}};
}
function chalmersSuggestionHtml(rows){
 if(!rows.length)return '<div class="card empty">Inga tillräckligt starka Chalmersmatchningar hittades för den här vägen ännu.</div>';
 return `<div class="chalmers-suggestion-list">${rows.map(c=>{const antagningUrl=antagningCourseUrl(c);return `<article class="chalmers-suggestion compact"><div class="chalmers-suggestion-top"><div><div class="eyebrow">${escapeHtml(c.code)}</div><h3>${escapeHtml(c.name)}</h3></div><b>${fmtHp(c.hp)} hp</b></div><div class="chalmers-suggestion-reason">${c.required?'Obligatorisk kurs som saknas':c.elective?'Valbar kurs som kan passa':'Föreslagen kurs i din väg'}</div><div class="chalmers-application">${courseApplicationBadge(c)}<a href="${escapeHtml(antagningUrl)}" target="_blank" rel="noopener">Visa på Antagning.se ↗</a></div><details class="course-more"><summary>Detaljer</summary><div class="course-more-body"><div>${escapeHtml(c.programName)} · ${escapeHtml(c.programCode)}</div><div>${escapeHtml(c.level||'Nivå ej angiven')} · verifierad 2026/27</div>${c.programUrl?`<a href="${escapeHtml(c.programUrl)}" target="_blank" rel="noopener">Programplan ↗</a>`:''}</div></details></article>`}).join('')}</div>`;
}

