function universityOptionsForOpportunity(o){
 let opts=[];
 if(o.source==='advanced'){
   opts=advancedUniversityOptions(o.subject,o.degreeType).slice(0,8);
 }else{
   opts=flexibleDegreeCatalog.map(d=>{
     const rule=localDegreeRule(d.id,o.subject,'candidate');
     if(!rule)return null;
     const breakdown=localRuleBreakdown(rule,o.subject);
     if(!breakdown)return null;
     const academicMissing=Math.max(0,Number(breakdown.missingMain||0)+Number(breakdown.missingReq||0)+Number(breakdown.missingElective||0));
     const remaining=Math.max(academicMissing,Number(breakdown.missingInstitution||0));
     return {d,major:o.subject,remaining,breakdown,rule,verified:Boolean(rule.verified||d.verified),degreeTitle:degreeTitleFor(d,o.subject)};
   }).filter(Boolean).sort((a,b)=>(Number(b.verified)-Number(a.verified))||a.remaining-b.remaining||String(a.d.university||'').localeCompare(String(b.d.university||''),'sv')).slice(0,8);
 }
 if(!opts.some(x=>x.d?.university==='Chalmers tekniska högskola'))opts.push(chalmersCourseProviderOption(o));
 return opts;
}
function canonicalPathResult(o,profileId=''){
 if(!o)return {remaining:0,score:0,profileId:'',university:''};
 if(o.source==='advanced'){
   const opts=advancedUniversityOptions(o.subject,o.degreeType);
   const chosen=(profileId&&opts.find(x=>x.d?.id===profileId))||opts[0];
   if(chosen){
     const total=Number(o.total||(o.degreeType==='Magister'?60:120));
     const remaining=Number(chosen.remaining||0);
     return {remaining,score:Math.max(0,Math.min(100,Math.round(100*(total-remaining)/Math.max(1,total)))),profileId:chosen.d?.id||'',university:chosen.d?.university||''};
   }
   return {remaining:Number(o.remaining||0),score:Number(o.score||0),profileId:'',university:''};
 }
 const opts=universityOptionsForOpportunity(o);
 let preferred=profileId;
 if(!preferred){
   try{preferred=sessionStorage.getItem('lotsen_preferred_profile')||''}catch(e){}
 }
 const chosen=(preferred&&opts.find(x=>x.d?.id===preferred))||opts[0];
 if(chosen){
   const remaining=Number(chosen.remaining||0);
   return {remaining,score:Math.max(0,Math.min(100,Math.round(100*(180-remaining)/180))),profileId:chosen.d?.id||'',university:chosen.d?.university||''};
 }
 return {remaining:Number(o.remaining||0),score:Number(o.score||0),profileId:o.canonicalProfileId||'',university:o.canonicalUniversity||''};
}
function canonicalRemaining(o,profileId=''){return canonicalPathResult(o,profileId).remaining}

function degreeTotalHp(o){
 if(o?.source==='advanced')return Number(o.total||(String(o?.degreeType||'').toLowerCase()==='magister'?60:120));
 return 180;
}
function pathNumbers(o,profileId=''){
 const p=canonicalPathResult(o,profileId);
 return {total:degreeTotalHp(o),remaining:Number(p.remaining||0),score:Number(p.score||0),profileId:p.profileId||'',university:p.university||''};
}

