function studyPlanAnalysisMetrics(profileId,major){
  const detailKey=sessionStorage.getItem('lotsen_detail_key');
  const o=safeDegreeOpportunities().find(x=>x.key===detailKey)||{kind:'candidate',subject:major};
  const isAdvanced=o?.source==='advanced';
  const degreeKind=isAdvanced?(String(o?.degreeType||'master').toLowerCase()==='magister'?'magister':'master'):'candidate';
  const rule=localDegreeRule(profileId,major,degreeKind);
  let remaining=Number(o?.remaining||0), total=Number(rule?.total||o?.total||(isAdvanced?120:180));
  try{
    if(isAdvanced&&rule) remaining=Number(advancedRuleBreakdown(rule,major)?.remaining||0);
    else if(rule){const b=localRuleBreakdown(rule,major); if(b){const academic=Math.max(0,Number(b.missingMain||0)+Number(b.missingReq||0)+Number(b.missingElective||0));remaining=Math.max(academic,Number(b.missingInstitution||0));}}
  }catch(e){}
  const analyzed=courses.length;
  const prior=courses.filter(c=>courseUsedInPriorDegree(c)).length;
  const advanced=courses.filter(c=>isAdvancedCourse(c)).length;
  const counted=Math.max(0,total-remaining);
  const university=(flexibleDegreeCatalog.find(x=>x.id===profileId)||{}).university||'lärosätets';
  return {analyzed,prior,advanced,counted,remaining,total,university};
}
function showStudyPlanAnalysis(profileId,major,done){
  const m=studyPlanAnalysisMetrics(profileId,major);
  document.getElementById('studyPlanAnalysisOverlay')?.remove();
  const el=document.createElement('div');el.id='studyPlanAnalysisOverlay';el.className='analysis-overlay';
  el.innerHTML=`<div class="analysis-loader-card">
    <div class="analysis-loader-head"><span class="analysis-orbit">✦</span><div><small>Studielots analyserar</small><h2>Tar fram din studieplan</h2></div></div>
    <div class="analysis-big-number"><strong>${m.analyzed}</strong><span>kurser analyseras</span></div>
    <div class="analysis-steps">
      <div data-step="1"><i>✓</i><span>Matchar kurser mot ${escapeHtml(m.university)}</span><b>${fmtHp(m.counted)} hp</b></div>
      <div data-step="2"><i>✓</i><span>Kontrollerar tidigare examen</span><b>${m.prior} ${m.prior===1?'kurs':'kurser'}</b></div>
      <div data-step="3"><i>✓</i><span>Identifierar avancerad nivå</span><b>${m.advanced} ${m.advanced===1?'kurs':'kurser'}</b></div>
      <div data-step="4"><i>✓</i><span>Räknar återstående väg</span><b>${fmtHp(m.remaining)} hp kvar</b></div>
    </div>
    <div class="analysis-finish">Studieplan klar <b>✓</b></div>
  </div>`;
  document.body.appendChild(el);
  requestAnimationFrame(()=>el.classList.add('show'));
  [1,2,3,4].forEach((n,i)=>setTimeout(()=>el.querySelector(`[data-step="${n}"]`)?.classList.add('done'),260+i*250));
  setTimeout(()=>el.querySelector('.analysis-finish')?.classList.add('show'),1280);
  setTimeout(()=>{el.classList.remove('show');setTimeout(()=>{el.remove();done()},180)},1580);
}
function openUniversityPath(profileId,major){
  try{
    sessionStorage.setItem('lotsen_uni_profile',profileId);
    sessionStorage.setItem('lotsen_uni_major',major);
    sessionStorage.setItem('lotsen_preferred_profile',profileId||'');
  }catch(e){}
  if(profileId==='course-chalmers'){go('universityDetail');renderChalmersCourseProviderDetail(major);return;}
  showStudyPlanAnalysis(profileId,major,()=>go('universityDetail'));
}


const DISTANCE_API='/api/distance-courses';
let LIVE_DISTANCE_COURSES=[];
let distanceApiState={loaded:false,loading:false,error:false,updated:null};

async function loadDistanceCourses(o){
 if(distanceApiState.loading)return;
 distanceApiState.loading=true; distanceApiState.error=false;
 try{
   const q=new URLSearchParams({
     subject:String(o?.subject||''),
     kind:String(o?.kind||'candidate')
   });
   const r=await fetch(`${DISTANCE_API}?${q.toString()}`,{headers:{'Accept':'application/json'}});
   if(!r.ok)throw new Error('distance api '+r.status);
   const data=await r.json();
   LIVE_DISTANCE_COURSES=Array.isArray(data?.courses)?data.courses:[];
   distanceApiState.loaded=true;
   distanceApiState.updated=data?.updated||null;
 }catch(e){
   console.warn('Lotsen distance API',e);
   distanceApiState.error=true;
 }finally{
   distanceApiState.loading=false;
   try{renderDistancePath(o)}catch(e){}
   try{if(myPathMode==='distance')renderMyPath()}catch(e){}
 }
}
function allDistanceCourses(){
 return [...LIVE_DISTANCE_COURSES,...DISTANCE_COURSE_INDEX];
}

const DISTANCE_COURSE_INDEX=[
 // Only current offerings that have been explicitly verified as distance are stored here.
 // Campus offerings are deliberately excluded even when the subject itself is available.
 // The index is designed to be extended from a server/API without changing the matching UI.
];

function normalizeStudyPace(v){
 const n=Number(v||0); return [25,50,75,100].includes(n)?n:null;
}
function distanceCourseMatchesNeed(course,need){
 const subject=String(course.subject||'').toLowerCase();
 const label=String(need.label||'').toLowerCase();
 return !need.subject || subject===String(need.subject).toLowerCase() || label.includes(subject);
}
function verifiedDistanceCoursesForNeed(need){
 return allDistanceCourses().filter(c=>
   c.verified===true &&
   c.distance===true &&
   distanceCourseMatchesNeed(c,need) &&
   Number(c.hp||0)>0
 );
}
function distancePlanForOpportunity(o){
 const missing=missingForOpportunity(o)||[];
 const hp=Number(canonicalRemaining(o)||0);
 const needs=missing.map(m=>{
   const matches=verifiedDistanceCoursesForNeed(m);
   return {...m,matches};
 });
 const covered=needs.filter(n=>n.matches.length>0).reduce((s,n)=>s+Number(n.hp||0),0);
 return {
   hp,needs,covered,
   fullyVerified:hp===0 || (needs.length>0 && needs.every(n=>n.matches.length>0)),
   semesters100:hp?Math.ceil((hp/30)*2)/2:0,
   semesters50:hp?Math.ceil((hp/15)*2)/2:0
 };
}

function courseApplicationOpen(c){
 if(c?.applicationOpen===true)return true;
 if(c?.applicationOpen===false)return false;
 const status=String(c?.applicationStatus||c?.status||'').trim().toLowerCase();
 if(/ansökan öppen|öppen för anmälan|open for application|application open/.test(status))return true;
 if(/stängd|closed|ej öppen/.test(status))return false;
 const now=Date.now();
 const opens=c?.applicationOpensAt?Date.parse(c.applicationOpensAt):NaN;
 const closes=c?.applicationClosesAt?Date.parse(c.applicationClosesAt):NaN;
 if(Number.isFinite(opens)&&Number.isFinite(closes))return now>=opens&&now<=closes;
 return false;
}
function courseApplicationBadge(c){
 return courseApplicationOpen(c)
   ? '<span class="application-open-badge">Ansökan öppen</span>'
   : '<span class="application-closed-badge">Ansökan stängd</span>';
}
function antagningCourseUrl(c){
 const code=String(c?.code||'').trim();
 const name=String(c?.name||'').trim();
 const q=code||name;
 return `https://www.antagning.se/se/search?period=HT_2026&freeText=${encodeURIComponent(q)}`;
}
function distanceCourseCard(c){
 const meeting=c.noPhysicalMeetings===true?'Inga fysiska träffar':c.noPhysicalMeetings===false?'Distans med träffar':'Träffar ej verifierade';
 const pace=normalizeStudyPace(c.pace);
 return `<div class="distance-course-card">
   <div><strong>${escapeHtml(c.name)}</strong><span>${escapeHtml(c.university||'')}</span>${courseApplicationBadge(c)}</div>
   <b>${fmtHp(c.hp)} hp</b>
   <div class="distance-course-meta">
     <span>${pace?pace+' %':'Studietakt ej verifierad'}</span>
     <span>${escapeHtml(meeting)}</span>
     ${c.term?`<span>${escapeHtml(c.term)}</span>`:''}
   </div>
   ${c.url?`<a href="${escapeHtml(c.url)}" target="_blank" rel="noopener">Visa utbildningen</a>`:''}
 </div>`;
}
function distanceUniversityOptions(d){
 const map=new Map();
 d.needs.forEach(n=>n.matches.forEach(c=>{
   const name=String(c.university||'').trim();if(!name)return;
   if(!map.has(name))map.set(name,{name,courses:[],hp:0,noPhysicalMeetings:true});
   const row=map.get(name);
   if(!row.courses.some(x=>x.name===c.name)){row.courses.push(c);row.hp+=Number(c.hp||0)}
   if(c.noPhysicalMeetings!==true)row.noPhysicalMeetings=false;
 }));
 return [...map.values()].sort((a,b)=>b.hp-a.hp||a.name.localeCompare(b.name,'sv'));
}

async function openDistanceSuggestionsFromUniversity(subject){
 const box=document.getElementById('universityDistanceSuggestions');
 if(!box)return;
 box.innerHTML='<div class="distance-inline-state">Söker aktuella distanskurser…</div>';
 await loadDistanceCourses({subject,kind:'candidate'});
 const rows=allDistanceCourses().filter(c=>c.verified===true&&c.distance===true&&String(c.subject||'')===String(subject||''));
 if(!rows.length){
   box.innerHTML='<div class="distance-inline-state">Inga verifierade distanskurser finns inlagda ännu.</div>';
   return;
 }
 box.innerHTML=`<div class="distance-inline-list">${rows.slice(0,8).map(distanceCourseCard).join('')}</div>`;
}

function myPathDistancePlanHtml(o){
 const d=distancePlanForOpportunity(o);
 const needs=d.needs||[];
 const verifiedCount=needs.reduce((s,n)=>s+(n.matches?.length||0),0);
 return `<section class="mypath-distance-plan">
   <div class="mypath-distance-plan-head">
     <div><span>Distans</span><h3>Förslag att läsa</h3></div>
     <b>${d.hp?`${fmtHp(d.hp)} hp kvar`:'Ser klar ut'}</b>
   </div>
   <p class="mypath-distance-intro">Här ser du vilka delar som behöver täckas. När aktuella distanskurser är verifierade visas de direkt under respektive del.</p>
   ${needs.length?`<div class="mypath-distance-needs">
     ${needs.map((n,i)=>`<div class="mypath-distance-need">
       <div class="mypath-distance-need-head">
         <span class="mypath-distance-step">${i+1}</span>
         <div><strong>${escapeHtml(n.label)}</strong><small>${n.matches?.length?'Verifierade distansalternativ hittade':'Kurs behöver hittas på distans'}</small></div>
         <b>${fmtHp(n.hp||0)} hp</b>
       </div>
       ${n.matches?.length?`<div class="mypath-distance-matches">${n.matches.slice(0,4).map(distanceCourseCard).join('')}</div>`:''}
     </div>`).join('')}
   </div>`:'<div class="ready-box">Inga tydliga kompletteringar hittades.</div>'}
   ${!distanceApiState.loading && !verifiedCount ? `
   <div class="future-distance-box">
     <div class="future-distance-icon">↗</div>
     <div>
       <span>Kommande ansökningsperiod</span>
       <strong>Distansvägen kan fortfarande vara möjlig</strong>
       <p>Inga aktuella verifierade kurser är publicerade i Studielots just nu. Kurser som finns visas även när ansökan är stängd. När en kurs går att söka markeras den med “Ansökan öppen”.</p>
       <small>Studielots visar bara kurser som är verifierade som distans. Ansökningsstatus visas separat.</small>
     </div>
   </div>` : ''}
   <div class="mypath-distance-foot ${verifiedCount?'has-results':''}">
     ${distanceApiState.loading?'Söker aktuella distanskurser…':
       verifiedCount?`${verifiedCount} verifierade kursförslag hittade.`:
       distanceApiState.error?'Kunde inte hämta aktuella distanskurser just nu.':'Inga verifierade distanskurser finns inlagda ännu.'}
   </div>
 </section>`;
}
