function groupedDegreeOpportunities(){
 const rows=[];

 // Specific catalogue
 degrees.forEach(d=>{
   const r=calc(d);
   rows.push({
     key:(d.subject||d.name).toLowerCase(),
     name:d.name,
     subject:d.subject||'',
     score:Math.min(100,Number(r.pct||0)),
     remaining:Number(r.remaining||0),
     source:'specific',
     routeId:d.id
   });
 });

 // Flexible/university-specific rules collapsed to one degree per subject.
 if(typeof flexibleDegreeCandidates==='function'){
   flexibleDegreeCandidates().forEach(x=>{
     rows.push({
       key:String(x.major||x.degreeTitle?.title||x.d.name).toLowerCase(),
       name:`Kandidatexamen i ${x.major}`,
       subject:x.major||'',
       score:Math.max(0,Math.min(100,Math.round(100*(1-Math.max(Number(x.remaining||0),Number(x.majorMissing||0),Number(x.thesisMissing||0),Number(x.outsideMissing||0),Number(x.levelMissing||0))/Math.max(1,x.d.hp||180))))),
       remaining:Math.max(Number(x.remaining||0),Number(x.majorMissing||0),Number(x.thesisMissing||0),Number(x.outsideMissing||0),Number(x.levelMissing||0)),
       source:'flex'
     });
   });
 }

 const best=new Map();
 for(const r of rows){
   const key=(r.subject||r.name).toLowerCase();
   const prev=best.get(key);
   if(!prev || r.score>prev.score || (r.score===prev.score && r.remaining<prev.remaining)) best.set(key,r);
 }
 return [...best.values()]
   .filter(x=>!/(ospecificerad|generell examen|inom huvudområde)/i.test(x.name))
   .sort((a,b)=>b.score-a.score || a.remaining-b.remaining);
}




function opportunityUniversityRange(o){
 try{
   const rows=universityOptionsForOpportunity(o).filter(x=>Number.isFinite(Number(x.remaining)));
   if(!rows.length)return null;
   const vals=rows.map(x=>Number(x.remaining)).sort((a,b)=>a-b);
   return {min:vals[0],max:vals[vals.length-1],same:vals[0]===vals[vals.length-1]};
 }catch(e){return null}
}
function opportunityRemainingLabel(o){
 const r=opportunityUniversityRange(o);
 if(r){
   if(r.same)return r.min?`${fmtHp(r.min)} hp kvar`:'Klar';
   return `från ${fmtHp(r.min)} hp kvar`;
 }
 const hp=Number(canonicalRemaining(o)||0);
 return hp?`${fmtHp(hp)} hp kvar`:'Klar';
}
function opportunityUniversityCount(o){
 try{return universityOptionsForOpportunity(o).length}catch(e){return 0}
}
function opportunityHasDistance(o){
 try{
   if(o.source==='advanced'){
     return allDistanceCourses().some(c=>c.verified===true&&c.distance===true&&String(c.subject||'')===String(o.subject||''));
   }
   const ids=new Set(myPathDistanceProfiles(o.subject).map(x=>x.id));
   return ids.size>0;
 }catch(e){return false}
}
function opportunityStatus(o){
 const r=opportunityUniversityRange(o);
 const hp=r?Number(r.min||0):Number(canonicalRemaining(o)||0);
 if(!hp)return {label:'Klar',kind:'ready'};
 return {label:opportunityRemainingLabel(o),kind:hp<=30?'near':'normal'};
}
function chooseOpportunityForMyPath(key){
 const o=opportunityByKey(key);
 if(!o)return;
 if(o.source==='advanced'){
   try{sessionStorage.setItem('lotsen_detail_key',o.key)}catch(e){}
   go('degreeDetail');
   renderDegreeDetail(o.key);
   return;
 }
 try{sessionStorage.setItem('lotsen_detail_key',o.key)}catch(e){}
 go('degreeDetail');
 renderDegreeDetail(o.key);
}


