const syllabusResolvers={
 'Göteborgs universitet':{aliases:['göteborgs universitet','gothenburg university'],note:'Kurskod används för att hitta kursplan och utbildningsnivå.'},
 'Umeå universitet':{aliases:['umeå universitet','umea university'],note:'Kurskod används för att hitta kursplan och utbildningsnivå.'},
 'Mittuniversitetet':{aliases:['mittuniversitetet','mid sweden university'],note:'Kurskod kopplas direkt mot Mittuniversitetets kursplan.'},
 'Karlstads universitet':{aliases:['karlstads universitet','karlstad university'],note:'Kurskod kopplas mot Karlstads universitets kurssida.'},
 'Linnéuniversitetet':{aliases:['linnéuniversitetet','linneuniversitetet','linnaeus university'],note:'Kurskod används för att verifiera utbildningsnivå.'},
 'Högskolan i Halmstad':{aliases:['högskolan i halmstad','halmstad university'],note:'Kurskod används för att söka kursplan och utbildningsnivå.'}
};
function syllabusResolverForUniversity(university){
 const u=String(university||'').trim().toLowerCase();
 return Object.entries(syllabusResolvers).find(([,r])=>(r.aliases||[]).some(a=>u.includes(a)))||null;
}
function legacyCourseIdentity(c){
 return {
   code:String(c.code||c.courseCode||'').trim(),
   university:String(c.university||c.institution||c.school||'').trim(),
   term:String(c.term||c.completedTerm||c.period||'').trim(),
   name:String(c.name||'').trim()
 };
}

const SYLLABUS_API='/api/syllabus';
async function fetchHistoricalSyllabus(c){
 const id=legacyCourseIdentity(c), status=historicalSyllabusStatus(c);
 if(!status.ready)return {ok:false,status,error:status.label};
 const qs=new URLSearchParams({code:id.code,university:id.university,term:id.term,name:id.name});
 try{
   const res=await fetch(`${SYLLABUS_API}?${qs.toString()}`,{headers:{'Accept':'application/json'}});
   if(!res.ok)throw new Error(`HTTP ${res.status}`);
   const data=await res.json();
   if(!data)return {ok:false,status,error:'Kursplan hittades inte'};
   const hasLevel=Boolean(data.level);
   const hasGoals=Array.isArray(data.learningGoals)&&data.learningGoals.length>0;
   if(!hasLevel&&!hasGoals)return {ok:false,status,error:'Kursplan hittades men nivå och lärandemål saknas'};
   return {ok:true,status,data};
 }catch(err){
   return {ok:false,status,error:'Automatisk hämtning är inte ansluten ännu',technical:String(err?.message||err)};
 }
}
async function resolveImportedSyllabi(){
 enrichCourseSyllabusStatus();
 const candidates=courses.filter(c=>c.syllabusLookup?.ready&&!c.learningGoals?.length);
 if(!candidates.length)return {attempted:0,resolved:0};
 let resolved=0;
 for(const c of candidates){
   const r=await fetchHistoricalSyllabus(c);
   c.syllabusFetch=r;
   if(r.ok){
     c.learningGoals=r.data.learningGoals||[];
     c.content=r.data.content||'';
     c.level=c.level||r.data.level||'';
     c.syllabusUrl=r.data.url||'';
     c.syllabusVersion=r.data.version||c.term||'';
     resolved++;
   }
 }
 try{localStorage.setItem('lotsen_courses',JSON.stringify(courses))}catch(e){}
 return {attempted:candidates.length,resolved};
}

function historicalSyllabusStatus(c){
 const id=legacyCourseIdentity(c), hit=syllabusResolverForUniversity(id.university);
 if(!id.code) return {state:'missing-code',label:'Kurskod saknas',ready:false};
 if(!id.university) return {state:'missing-university',label:'Lärosäte saknas',ready:false};
 if(!hit) return {state:'unsupported',label:'Kursnivå behöver verifieras manuellt',ready:false};
 const [provider,r]=hit;
 return {state:'resolvable',label:'Kursnivå kan verifieras',ready:true,provider,note:r.note};
}
function enrichCourseSyllabusStatus(){
 courses.forEach(c=>{c.syllabusLookup=historicalSyllabusStatus(c)});
}

async function resolveMissingCourseLevelsInBackground(){
 enrichCourseSyllabusStatus();
 const pending=courses.filter(c=>!c.level && c.syllabusLookup?.ready);
 if(!pending.length)return {attempted:0,resolved:0};
 let resolved=0;
 for(const c of pending){
   try{
     const r=await fetchHistoricalSyllabus(c);
     c.syllabusFetch=r;
     if(r.ok && r.data?.level){
       const rawLevel=String(r.data.level||'');
       const level=detectCourseLevel(rawLevel)||rawLevel;
       if(level){
         c.level=level;
         c.progression=String(r.data.progression||r.data.levelCode||c.progression||'');
         c.levelSource=r.data.provider||'Kursplan';
         c.levelVerified=true;
         c.syllabusUrl=r.data.url||c.syllabusUrl||'';
         resolved++;
       }
     }
   }catch(e){}
 }
 if(resolved){
   try{sessionStorage.setItem('examensmatch_courses',JSON.stringify(courses))}catch(e){}
   try{renderCourses()}catch(e){}
   try{renderDegrees()}catch(e){}
 }
 return {attempted:pending.length,resolved};
}


function normalizedWords(v){
 return String(v||'').toLowerCase().replace(/[^\p{L}\p{N}\s]/gu,' ').split(/\s+/).filter(w=>w.length>3);
}
function overlapScore(a,b){
 const A=new Set(normalizedWords(a)), B=new Set(normalizedWords(b));
 if(!A.size||!B.size)return 0;
 let hit=0; A.forEach(w=>{if(B.has(w))hit++});
 return Math.round(100*hit/Math.max(1,Math.min(A.size,B.size)));
}
function syllabusEvidence(pc,c){
 const oldGoals=(c.learningGoals||c.goals||[]).join(' ');
 const newGoals=(pc.learningGoals||pc.goals||[]).join(' ');
 const oldContent=[c.content,c.description,c.name,c.subject].filter(Boolean).join(' ');
 const newContent=[pc.content,pc.description,pc.name,pc.subject,(pc.keywords||[]).join(' ')].filter(Boolean).join(' ');
 const goals=overlapScore(oldGoals,newGoals);
 const content=overlapScore(oldContent,newContent);
 const hasOld=Boolean(oldGoals||c.content||c.description);
 const hasNew=Boolean(newGoals||pc.content||pc.description||pc.goals?.length);
 return {goals,content,hasOld,hasNew,complete:hasOld&&hasNew};
}



function normalizedProgramCatalog(){
 // v215: merge duplicate record IDs first, then apply supersedes/supplements.
 // This prevents older thin duplicates from hiding richer Chalmers records.
 const cloned=programCatalog.filter(Boolean).map(p=>({
   ...p,
   courses:(p.courses||[]).map(c=>({...c})),
   rules:(p.rules||[]).map(r=>({...r,codes:Array.isArray(r.codes)?[...r.codes]:r.codes}))
 }));
 const byId=new Map();
 const courseKey=c=>String(c?.code||c?.name||'').trim().toUpperCase();
 const ruleKey=r=>JSON.stringify([r.type,r.hp||null,r.count||null,r.year||null,(r.codes||[]).map(String).sort(),r.label||'']);
 for(const p of cloned){
   if(!p.id){continue}
   if(!byId.has(p.id)){byId.set(p.id,p);continue}
   const b=byId.get(p.id);
   const courses=new Map((b.courses||[]).map(c=>[courseKey(c),c]));
   (p.courses||[]).forEach(c=>{
     const k=courseKey(c); if(!k)return;
     courses.set(k,courses.has(k)?Object.assign(courses.get(k),c):{...c});
   });
   b.courses=[...courses.values()];
   const seen=new Set((b.rules||[]).map(ruleKey));
   (p.rules||[]).forEach(r=>{const k=ruleKey(r);if(!seen.has(k)){b.rules.push({...r,codes:Array.isArray(r.codes)?[...r.codes]:r.codes});seen.add(k)}});
   // Prefer richer/newer metadata without losing an explicit complete marker.
   Object.assign(b,{...p,courses:b.courses,rules:b.rules,coverage:(b.coverage==='complete'||p.coverage==='complete')?'complete':(p.coverage||b.coverage)});
 }
 const all=[...byId.values()];
 const replacement=new Map();
 all.forEach(p=>{if(p.supersedes)replacement.set(p.supersedes,p.id)});
 const resolveActiveId=id=>{
   let cur=id, guard=0;
   while(replacement.has(cur)&&guard++<20)cur=replacement.get(cur);
   return cur;
 };
 const superseded=new Set(all.map(p=>p.supersedes).filter(Boolean));
 const base=all.filter(p=>!superseded.has(p.id)&&!p.supplementFor);
 const supplements=all.filter(p=>p.supplementFor);
 supplements.forEach(s=>{
   const activeId=resolveActiveId(s.supplementFor);
   const b=base.find(p=>p.id===activeId);
   if(!b)return;
   const courses=new Map((b.courses||[]).map(c=>[courseKey(c),c]));
   (s.courses||[]).forEach(c=>{
     const k=courseKey(c);if(!k)return;
     courses.set(k,courses.has(k)?Object.assign(courses.get(k),c):{...c});
   });
   b.courses=[...courses.values()];
   const seenRules=new Set((b.rules||[]).map(ruleKey));
   (s.rules||[]).forEach(r=>{const k=ruleKey(r);if(!seenRules.has(k)){b.rules.push({...r,codes:Array.isArray(r.codes)?[...r.codes]:r.codes});seenRules.add(k)}});
 });
 return base;
}




