function auditChalmersCatalog(){
 const ps=normalizedProgramCatalog().filter(p=>p.university==='Chalmers tekniska högskola');
 const byCode={};
 ps.forEach(p=>{(byCode[p.code]??=[]).push(p)});
 const duplicates=Object.entries(byCode).filter(([k,v])=>v.length>1).map(([code,v])=>({code,count:v.length}));
 const missingHp=ps.flatMap(p=>(p.courses||[]).filter(c=>!Number(c.hp)).map(c=>({program:p.code,course:c.code||c.name})));
 const gap=chalmersGapSnapshot();
 const result={programRecords:ps.length,uniqueProgramCodes:Object.keys(byCode).length,uniqueCourseCodes:new Set(ps.flatMap(p=>(p.courses||[]).map(c=>c.code).filter(Boolean))).size,duplicates,missingHp,thinPrograms:gap.thin,shallowPrograms:gap.shallow,depth:gap.depth,normalization:chalmersNormalizationAudit()};
 result.officialCatalog='Chalmers 2026/2027';
 result.auditVersion='v230';
 result.completeness=gap.partial.length?'partial':'complete';
 result.note=gap.partial.length?'Programbredden är strukturerad, men full kurs- och regelbredd återstår för program markerade partial.':'Samtliga strukturerade program är markerade complete.';
 console.info('Studielots Chalmers audit',result);
 return result;
}

function chalmersV2Coverage(){
 const ps=normalizedProgramCatalog().filter(p=>p.university==='Chalmers tekniska högskola'&&p.academicYear==='2026/2027');
 const degreePrograms=ps.filter(p=>!p.catalogOnly);
 const uniquePrograms=new Set(degreePrograms.map(p=>p.code));
 const uniqueCourses=new Set(ps.flatMap(p=>(p.courses||[]).map(c=>String(c.code||'').trim()).filter(Boolean)));
 return {programs:uniquePrograms.size,courses:uniqueCourses.size};
}

function courseSimilarity(pc,c){
 const targetCode=String(pc.code||'').trim().toUpperCase();
 const courseCode=String(c.code||'').trim().toUpperCase();
 const text=(String(c.name||'')+' '+String(c.subject||'')).toLowerCase();

 if(targetCode && courseCode && targetCode===courseCode){
   return {score:100,parts:{code:55,subject:20,content:15,credits:10,type:0,syllabus:0,level:0},syllabusEvidence:{complete:true,codeExact:true}};
 }

 let code=0,subject=0,content=0,credits=0,type=0,syllabus=0,level=0;
 if(targetCode && courseCode && targetCode.slice(0,3)===courseCode.slice(0,3))code=8;
 if(pc.subject && String(c.subject||'').toLowerCase()===String(pc.subject||'').toLowerCase())subject=25;

 const pcLevel=String(pc.level||'').toLowerCase();
 const cLevel=String(c.level||'').toLowerCase();
 if(pcLevel && cLevel){
   if((pcLevel.includes('avancer')&&cLevel.includes('avancer'))||(pcLevel.includes('grund')&&cLevel.includes('grund')))level=8;
   else level=-8;
 }

 let hits=0;
 (pc.keywords||[]).forEach(k=>{if(text.includes(String(k).toLowerCase()))hits++});
 if((pc.keywords||[]).length)content=Math.min(22,Math.round(22*hits/Math.max(1,Math.min(3,pc.keywords.length))));

 const ev=syllabusEvidence(pc,c);
 if(ev.complete){
   syllabus=Math.round(ev.goals*.17+ev.content*.10);
 }else if(ev.hasNew){
   let goalHits=0;
   (pc.goals||[]).forEach(g=>{const words=normalizedWords(g);if(words.some(w=>text.includes(w)))goalHits++});
   if(pc.goals?.length)content=Math.min(30,content+Math.min(10,goalHits*3));
 }

 if(pc.hp){
   const delta=Math.abs(Number(c.hp||0)-Number(pc.hp||0));
   credits=delta<=0.1?12:delta<=2.5?8:delta<=7.5?3:0;
 }

 const targetThesis=/examensarbete|kandidatuppsats|självständigt arbete/i.test(pc.name);
 if(targetThesis && c.thesis)type=8;

 return {score:Math.max(0,Math.min(100,code+subject+content+credits+type+syllabus+level)),parts:{code,subject,content,credits,type,syllabus,level},syllabusEvidence:ev};
}



// v205 — Chalmers v2 becomes the primary path engine.
function chalmersProgramsForMajor(major,degreeKind='candidate'){
  const m=String(major||'').trim().toLowerCase();
  const kind=String(degreeKind||'candidate').toLowerCase();
  let ps=[];
  try{ps=normalizedProgramCatalog().filter(p=>p.university==='Chalmers tekniska högskola'&&p.academicYear==='2026/2027'&&!p.catalogOnly)}catch(e){return []}
  return ps.filter(p=>{
    const adv=Boolean(p.advanced)||/avancerad/i.test(String(p.level||''))||Number(p.hp||0)<=120&&/^MP/.test(String(p.code||''));
    if((kind==='master'||kind==='magister')&&!adv)return false;
    if(kind==='candidate'&&adv)return false;
    const hay=[p.name,p.code,...(p.courses||[]).flatMap(c=>[c.subject,c.name,...(c.keywords||[])])].join(' ').toLowerCase();
    const words=normalizedWords(m).filter(w=>w.length>3);
    const aliases={
      'informationsteknik':['informationsteknik','datateknik','mjukvara','software'],
      'automation och mekatronik':['automation','mekatronik','reglerteknik'],
      'samhällsbyggnadsteknik':['samhällsbyggnad','bygg','construction'],
      'teknisk fysik':['teknisk fysik','fysik','matematik'],
      'teknikvetenskap':['teknik','ingenjör'],
      'kemiteknik':['kemiteknik','kemi'],
      'maskinteknik':['maskinteknik','mekanik'],
      'elektroteknik':['elektroteknik','elektronik'],
      'datateknik':['datateknik','programmering','datorsystem'],
      'medicinteknik':['medicinteknik','biomedicinsk'],
      'industriell ekonomi':['industriell ekonomi','management','ekonomi']
    };
    const xs=[...words,...(aliases[m]||[])];
    return xs.some(w=>hay.includes(String(w).toLowerCase()));
  }).sort((a,b)=>{
    const score=p=>{const n=String(p.name||'').toLowerCase();let sc=0;if(n.includes(m))sc+=50;for(const c of p.courses||[])if(String(c.subject||'').toLowerCase()===m)sc+=2;return sc};
    return score(b)-score(a)||String(a.name).localeCompare(String(b.name),'sv');
  });
}

function chalmersCourseMatchForProgram(program){
  const completed=(courses||[]).filter(c=>c.selected!==false);
  const byCode=new Map(completed.map(c=>[String(c.code||'').trim().toUpperCase(),c]).filter(([k])=>k));
  const used=[];
  const missing=[];
  const matchedCodes=new Set();
  for(const pc of (program.courses||[])){
    const code=String(pc.code||'').trim().toUpperCase();
    let best=null;
    if(code&&byCode.has(code)){best={course:byCode.get(code),score:100,exact:true}}
    else{
      for(const c of completed){
        const sim=courseSimilarity(pc,c);
        if(!best||sim.score>best.score)best={course:c,score:sim.score,exact:false};
      }
    }
    const threshold=pc.required?72:78;
    if(best&&best.score>=threshold&&!matchedCodes.has(String(best.course?.code||best.course?.name||''))){
      used.push({programCourse:pc,userCourse:best.course,score:best.score,exact:best.exact,countedHp:Math.min(Number(pc.hp||0),Number(best.course?.hp||0)||Number(pc.hp||0))});
      matchedCodes.add(String(best.course?.code||best.course?.name||''));
    }else{
      missing.push(pc);
    }
  }
  return {used,missing};
}

function evaluateChalmersProgramV2(program){
  if(!program)return null;
  const m=chalmersCourseMatchForProgram(program);
  const required=(program.courses||[]).filter(c=>c.required);
  const electives=(program.courses||[]).filter(c=>c.elective);
  const matchedProgramCourses=new Set(m.used.map(x=>String(x.programCourse.code||x.programCourse.name)));
  const requiredMatched=required.filter(c=>matchedProgramCourses.has(String(c.code||c.name)));
  const requiredMissing=required.filter(c=>!matchedProgramCourses.has(String(c.code||c.name)));
  const requiredHp=requiredMatched.reduce((s,c)=>s+Number(c.hp||0),0);
  const electiveMatched=electives.filter(c=>matchedProgramCourses.has(String(c.code||c.name)));
  const electiveHp=electiveMatched.reduce((s,c)=>s+Number(c.hp||0),0);
  const rules=[];
  for(const r of (program.rules||[])){
    if(r.type==='choice_min_hp'){
      const set=new Set((r.codes||[]).map(x=>String(x).toUpperCase()));
      const have=m.used.filter(x=>set.has(String(x.programCourse.code||'').toUpperCase())).reduce((s,x)=>s+Number(x.programCourse.hp||0),0);
      rules.push({...r,have,missing:Math.max(0,Number(r.hp||0)-have)});
    }else if(r.type==='thesis_required'){
      const set=new Set((r.codes||[]).map(x=>String(x).toUpperCase()));
      const have=m.used.filter(x=>x.programCourse.thesis||set.has(String(x.programCourse.code||'').toUpperCase())).reduce((s,x)=>s+Number(x.programCourse.hp||0),0);
      rules.push({...r,have,missing:Math.max(0,Number(r.hp||0)-have)});
    }else rules.push({...r,have:0,missing:0});
  }
  const explicitRuleMissing=rules.reduce((s,r)=>s+Number(r.missing||0),0);
  const mappedHp=m.used.reduce((s,x)=>s+Number(x.countedHp||0),0);
  // When program coverage is partial, never claim the entire degree is mapped.
  const coveragePartial=String(program.coverage||'').toLowerCase()!=='complete';
  const knownInventory=(program.courses||[]).reduce((s,c)=>s+Number(c.hp||0),0);
  const knownMissing=Math.max(0,knownInventory-mappedHp);
  const remaining=coveragePartial?Math.max(knownMissing,explicitRuleMissing):Math.max(0,Number(program.hp||0)-mappedHp,explicitRuleMissing);
  const scoreBase=coveragePartial?knownInventory:Number(program.hp||0);
  const score=scoreBase?Math.max(0,Math.min(100,Math.round(100*(scoreBase-Math.min(scoreBase,remaining))/scoreBase))):0;
  return {program,used:m.used,requiredMissing,rules,remaining,score,mappedHp,knownInventory,coveragePartial,requiredHp,electiveHp};
}

function bestChalmersV2Path(major,degreeKind='candidate'){
  const ps=chalmersProgramsForMajor(major,degreeKind);
  const rows=ps.map(evaluateChalmersProgramV2).filter(Boolean);
  rows.sort((a,b)=>a.remaining-b.remaining||b.score-a.score||Number(b.program.verified)-Number(a.program.verified));
  return rows[0]||null;
}

const _oldCanonicalPathResult=canonicalPathResult;
canonicalPathResult=function(o,profileId=''){
  try{
    const isChalmersProfile=profileId==='flex-chalmers'||String(profileId||'').startsWith('chalmers-');
    const preferred=profileId||sessionStorage.getItem('lotsen_preferred_profile')||'';
    const wantsChalmers=isChalmersProfile||preferred==='flex-chalmers'||String(o?.canonicalUniversity||'')==='Chalmers tekniska högskola';
    if(wantsChalmers&&o?.subject){
      const kind=o.source==='advanced'?(String(o.degreeType||'master').toLowerCase()==='magister'?'magister':'master'):'candidate';
      const v2=bestChalmersV2Path(o.subject,kind);
      if(v2){
        return {remaining:Number(v2.remaining||0),score:Number(v2.score||0),profileId:'flex-chalmers',university:'Chalmers tekniska högskola',engine:'v2',programCode:v2.program.code,programName:v2.program.name,v2};
      }
    }
  }catch(e){console.error('Chalmers v2 canonical path',e)}
  return _oldCanonicalPathResult(o,profileId);
};

const _oldMissingForOpportunity=missingForOpportunity;
missingForOpportunity=function(o){
  try{
    const p=canonicalPathResult(o);
    if(p?.engine==='v2'&&p.v2){
      const rows=[];
      p.v2.requiredMissing.forEach(c=>rows.push({label:`${c.name||c.code} (${fmtHp(c.hp)} hp)`,hp:Number(c.hp||0),type:c.thesis?'thesis':'required',subject:c.subject||o.subject,courseCode:c.code||''}));
      p.v2.rules.filter(r=>Number(r.missing||0)>0).forEach(r=>rows.push({label:r.label||'Programregel',hp:Number(r.missing||0),type:r.type||'rule'}));
      if(!rows.length&&Number(p.remaining||0)>0)rows.push({label:'Kvar enligt verifierat Chalmers-programunderlag',hp:Number(p.remaining||0),type:'program'});
      return rows;
    }
  }catch(e){console.error('Chalmers v2 missing',e)}
  return _oldMissingForOpportunity(o);
};

const _oldUniversityOptionsForOpportunity=universityOptionsForOpportunity;
universityOptionsForOpportunity=function(o){
  const opts=_oldUniversityOptionsForOpportunity(o);
  try{
    if(o?.subject){
      const kind=o.source==='advanced'?(String(o.degreeType||'master').toLowerCase()==='magister'?'magister':'master'):'candidate';
      const v2=bestChalmersV2Path(o.subject,kind);
      if(v2){
        const row={d:{id:'flex-chalmers',name:'Chalmers tekniska högskola',university:'Chalmers tekniska högskola',verified:true},major:o.subject,remaining:v2.remaining,verified:true,engine:'v2',v2,degreeTitle:{title:v2.program.name},programCode:v2.program.code};
        const filtered=opts.filter(x=>x.d?.university!=='Chalmers tekniska högskola');
        filtered.push(row);
        return filtered.sort((a,b)=>(Number(b.verified)-Number(a.verified))||Number(a.remaining||999)-Number(b.remaining||999));
      }
    }
  }catch(e){console.error('Chalmers v2 university options',e)}
  return opts;
};

const _oldChalmersCourseSuggestions=chalmersCourseSuggestions;
chalmersCourseSuggestions=function(major,o,limit=12){
  try{
    const kind=o?.source==='advanced'?(String(o?.degreeType||'master').toLowerCase()==='magister'?'magister':'master'):'candidate';
    const v2=bestChalmersV2Path(major,kind);
    if(v2){
      const missingCodes=new Set(v2.requiredMissing.map(c=>String(c.code||'').toUpperCase()).filter(Boolean));
      const completed=new Set((courses||[]).map(c=>String(c.code||'').trim().toUpperCase()).filter(Boolean));
      const direct=(v2.program.courses||[]).filter(c=>!completed.has(String(c.code||'').toUpperCase())).map(c=>({
        ...c,programCode:v2.program.code,programName:v2.program.name,programUrl:v2.program.sourceUrl||'',verified:v2.program.verified===true,
        score:(missingCodes.has(String(c.code||'').toUpperCase())?100:0)+(c.required?30:c.elective?10:0)+(c.thesis?15:0),
        reason:missingCodes.has(String(c.code||'').toUpperCase())?'saknas i din bästa Chalmers-programväg':c.required?'obligatorisk i din bästa Chalmers-programväg':'valbar i din bästa Chalmers-programväg'
      })).sort((a,b)=>b.score-a.score||String(a.name).localeCompare(String(b.name),'sv'));
      if(direct.length)return direct.slice(0,limit);
    }
  }catch(e){console.error('Chalmers v2 suggestions',e)}
  return _oldChalmersCourseSuggestions(major,o,limit);
};

