function inferBestMajor(){
 const sums={};
 courses.filter(c=>c.selected!==false).forEach(c=>{const s=c.subject||guessSubject(c.name||'');if(!s||s==='Övrigt')return;sums[s]=(sums[s]||0)+Number(c.hp||0)});
 return Object.entries(sums).sort((a,b)=>b[1]-a[1])[0]||[null,0];
}

function degreeTitleFor(d,major){
 let prefix=d.degreePrefix||'Filosofie';
 let caveat='';
 if(d.id==='flex-chalmers')return {title:`Teknologie kandidatexamen med huvudområdet ${major}`,caveat:'Program- och utbildningsplan kan innehålla ytterligare Chalmersspecifika krav.'};
 if(d.id==='flex-gu'){
   if(major==='Offentlig förvaltning'){prefix='Politices'}
   if(['Företagsekonomi','Nationalekonomi'].includes(major)){
     caveat='Ekonomie kan vara möjligt om särskilda kombinationskrav är uppfyllda; annars filosofie.';
   }
 }
 return {title:`${prefix} kandidatexamen med huvudområdet ${major}`,caveat};
}

function estimateFlexibleDegree(d,major){
 const audit=candidateCourseAudit(major);
 const selected=audit.count;
 const majorCourses=selected.filter(c=>(c.subject||guessSubject(c.name||''))===major);
 const rawMajor=majorCourses.reduce((s,c)=>s+Number(c.hp||0),0), majorHp=Math.min(d.majorHp,rawMajor);
 const thesisHp=Math.min(d.thesisHp,majorCourses.filter(c=>c.thesis||/examensarbete|kandidatuppsats|självständigt arbete/i.test(c.name||'')).reduce((s,c)=>s+Number(c.hp||0),0));
 const levelKnown=majorCourses.some(c=>c.level);
 const g2Hp=majorCourses.filter(c=>/^G2/i.test(String(c.progression||c.level||''))).reduce((s,c)=>s+Number(c.hp||0),0);
 const totalHp=Math.min(d.hp,selected.reduce((s,c)=>s+Number(c.hp||0),0));
 const outsideRaw=Math.max(0,totalHp-rawMajor);
 const freeHp=Math.min(d.hp-d.majorHp,outsideRaw);
 const majorMissing=Math.max(0,d.majorHp-majorHp), thesisMissing=Math.max(0,d.thesisHp-thesisHp);
 const outsideMissing=Math.max(0,(d.outsideMajorMinHp||0)-outsideRaw);
 const levelMissing=d.candidateLevelHp&&levelKnown?Math.max(0,d.candidateLevelHp-g2Hp):0;
 const remaining=Math.max(0,d.hp-majorHp-freeHp);
 let progressionStatus='Fördjupningsnivå behöver verifieras';
 if(levelKnown && d.candidateLevelHp) progressionStatus=levelMissing?`${fmtHp(levelMissing)} hp fördjupningsnivå saknas`:'Fördjupningsnivå ser uppfylld ut';
 else if(levelKnown) progressionStatus='Kursnivåer finns i underlaget';
 const score=majorHp*1.35+freeHp*.55-majorMissing*.45-thesisMissing*2-outsideMissing-levelMissing*.8;
 const missing=[];
 if(majorMissing>0) missing.push({type:'major',hp:majorMissing,label:`${fmtHp(majorMissing)} hp i ${major}`,subject:major});
 if(levelMissing>0) missing.push({type:'progression',hp:levelMissing,label:`${fmtHp(levelMissing)} hp på fördjupningsnivå i ${major}`,subject:major});
 if(thesisMissing>0) missing.push({type:'thesis',hp:thesisMissing,label:`${fmtHp(thesisMissing)} hp examensarbete i ${major}`,subject:major});
 if(outsideMissing>0) missing.push({type:'outside',hp:outsideMissing,label:`${fmtHp(outsideMissing)} hp utanför huvudområdet`});
 const generalMissing=Math.max(0,remaining-Math.max(majorMissing,outsideMissing));
 if(generalMissing>0) missing.push({type:'total',hp:generalMissing,label:`${fmtHp(generalMissing)} hp övriga kurser`});
 const degreeTitle=degreeTitleFor(d,major);
 return {d,major,majorHp,freeHp,remaining,majorMissing,thesisMissing,outsideMissing,levelMissing,levelKnown,progressionStatus,score,degreeTitle,missing,reviewCourses:audit.review,excludedCourses:audit.excluded};
}
function flexibleDegreeCandidates(){
 const [bestMajor]=inferBestMajor();
 const present=[...new Set(courses.filter(c=>c.selected!==false).map(c=>c.subject||guessSubject(c.name||'')).filter(s=>s&&s!=='Övrigt'))];
 const rows=[];
 flexibleDegreeCatalog.forEach(d=>{
   const majors=(d.majors||present).filter(x=>present.includes(x));
   (majors.length?majors:(bestMajor?[bestMajor]:[])).forEach(major=>rows.push(estimateFlexibleDegree(d,major)));
 });
 return rows;
}




let myPathSubject=sessionStorage.getItem('lotsen_mypath_subject')||'';
let myPathMode=sessionStorage.getItem('lotsen_mypath_mode')||'';

function myPathSubjects(){
 const preferred=['Företagsekonomi','Psykologi','Idrottsvetenskap'];
 const available=[...new Set(
   safeDegreeOpportunities()
     .filter(x=>x.source!=='advanced')
     .map(x=>x.subject)
     .filter(Boolean)
 )];
 return [...preferred,...available.filter(x=>!preferred.includes(x))]
   .filter((x,i,a)=>a.indexOf(x)===i);
}

function myPathOpportunity(subject){
 return safeDegreeOpportunities()
   .filter(x=>x.source!=='advanced'&&x.subject===subject)
   .sort((a,b)=>(b.score||0)-(a.score||0)||(a.remaining||999)-(b.remaining||999))[0];
}

function chooseMyPathSubject(subject){
 if(!subject)return;
 myPathSubject=subject;
 myPathMode='';
 sessionStorage.setItem('lotsen_mypath_subject',subject);
 sessionStorage.removeItem('lotsen_mypath_mode');
 renderMyPath();
 requestAnimationFrame(()=>{
   const el=document.getElementById('mypath-place');
   if(!el)return;
   const y=el.getBoundingClientRect().top+window.scrollY-18;
   window.scrollTo({top:y,behavior:'smooth'});
 });
}

function chooseMyPathMode(mode){
 myPathMode=mode;
 sessionStorage.setItem('lotsen_mypath_mode',mode);
 renderMyPath();
 if(mode==='distance'&&myPathSubject){
   loadDistanceCourses({subject:myPathSubject,kind:'candidate'}).then(()=>renderMyPath()).catch(()=>{});
 }
}

function myPathDistanceProfiles(subject){
 // Availability is loaded from the live distance endpoint; never depend on a missing local catalogue.
 const ids=[...new Set(allDistanceCourses().filter(c=>c.subject===subject&&c.distance===true).map(c=>c.profileId||c.uni).filter(Boolean))];
 return flexibleDegreeCatalog.filter(d=>ids.includes(d.id)&&localDegreeRule(d.id,subject,'candidate'));
}

function openMyPathUniversity(profileId,subject){
 const o=myPathOpportunity(subject);
 try{
   if(o)sessionStorage.setItem('lotsen_detail_key',o.key);
   sessionStorage.setItem('lotsen_preferred_profile',profileId||'');
 }catch(e){}
 openUniversityPath(profileId,subject);
}

