function renderProgramSearch(){
  const host=document.getElementById('programSearchResults');
  if(!host)return;
  const q=String(document.getElementById('programSearchInput')?.value||'').trim().toLowerCase();
  let rows=programCatalog.filter(p=>{
    if(!q)return true;
    return `${p.name} ${p.university}`.toLowerCase().includes(q);
  }).slice(0,20);
  host.innerHTML=rows.length?rows.map(p=>`
    <button class="program-search-row" type="button" onclick="selectProgramForMatch('${escapeHtml(p.id)}')">
      <div class="uni-name-with-logo">${universityLogoHtml(p.university,'sm')}<div><strong>${escapeHtml(p.name)}</strong><span>${escapeHtml(p.university)}</span></div></div><span>›</span>
    </button>`).join(''):'<div class="muted small program-empty">Inget program hittades i databasen.</div>';
}
function selectProgramForMatch(id){
  const p=programCatalog.find(x=>x.id===id);
  if(!p)return;
  try{sessionStorage.setItem('lotsen_selected_program',id)}catch(e){}
  renderProgramMatch(p);
  requestAnimationFrame(()=>document.getElementById('programMatchResult')?.scrollIntoView({behavior:'smooth',block:'start'}));
}
function recommendedProgramPlan(p,r){
 const rows=[];
 r.parts.forEach(x=>{
   const required=Number(x.pc.hp||0);
   const matched=Number(x.hp||0);
   const remaining=Math.max(0,required-matched);
   if(remaining<=0)return;
   rows.push({
     name:x.pc.name,
     hp:remaining,
     elective:Boolean(x.pc.elective),
     type:x.pc.elective?'Valbar del':(/examensarbete|självständigt arbete|uppsats/i.test(x.pc.name)?'Examensarbete':'Programkurs'),
     verified:Boolean(p.verified)
   });
 });
 const hp=rows.reduce((s,x)=>s+x.hp,0);
 return {rows,hp,terms:hp?Math.ceil((hp/30)*2)/2:0,verified:Boolean(p.verified)};
}
function renderProgramMatch(p){
  const host=document.getElementById('programMatchResult');if(!host)return;
  if(!courses.length){
    host.innerHTML='<div class="card empty"><strong>Hämta dina meriter först</strong><div class="small muted">Därefter kan Lotsen jämföra dem med programmet.</div></div>';
    return;
  }
  const r=estimateProgram(p);
  const accepted=r.parts.filter(x=>x.matchType==='replace');
  const review=r.parts.filter(x=>x.matchType==='review'||x.matchType==='degree');
  const plan=recommendedProgramPlan(p,r);
  const potentiallyUsed=Math.min(p.hp,Number(r.replaceHp||0)+Number(r.degreeHp||0)+Number(r.reviewHp||0));

  host.innerHTML=`
    <div class="program-result-head">
      <div class="uni-name-with-logo">${universityLogoHtml(p.university,'md')}<div><div class="eyebrow">${escapeHtml(p.university)}${p.code?` · ${escapeHtml(p.code)}`:''}</div><h2>${escapeHtml(p.name)}</h2>${p.academicYear?`<small class="program-source-year">Programplan ${escapeHtml(p.academicYear)}</small>`:''}${p.engine==='v2'?`<small class="program-coverage-status">${p.coverage==='complete'?'Komplett kursstruktur':'Kursstrukturen byggs ut'}</small>`:''}</div></div>
      <span class="badge ${potentiallyUsed>=p.hp*.7?'good':potentiallyUsed>=p.hp*.35?'warn':'bad'}">${fmtHp(potentiallyUsed)} hp</span>
    </div>
    ${p.engine==='v2'?`<div class="engine-v2-chip"><span>Matchningsmotor 2.0</span><small>Kurskod · hp · nivå · ämne · innehåll</small></div>`:''}${(est.programRules||[]).length?`<div class="program-rule-chip"><strong>${est.programRules.length} programregel behöver kontrolleras</strong><span>Studielots räknar inte en valregel som uppfylld enbart utifrån total hp.</span></div>`:''}

    <section class="recommended-plan">
      <div class="recommended-plan-head">
        <div><span class="eyebrow">Rekommenderad plan</span><h3>${plan.hp?`${fmtHp(plan.hp)} hp kvar`:'Du ser preliminärt klar ut'}</h3></div>
        <span class="plan-status ${plan.verified?'verified':'unverified'}">${plan.verified?'Verifierad struktur':'Preliminär'}</span>
      </div>
      ${plan.hp?`
        <div class="plan-summary"><strong>ca ${plan.terms} ${plan.terms===1?'termin':'terminer'}</strong><span>vid 30 hp per termin</span></div>
        <div class="recommended-course-list">
          ${plan.rows.map((x,i)=>`<div class="recommended-course">
            <span class="plan-step">${i+1}</span>
            <div><strong>${escapeHtml(x.name)}</strong><small>${escapeHtml(x.type)}</small></div>
            <b>${fmtHp(x.hp)} hp</b>
          </div>`).join('')}
        </div>`:
        '<div class="ready-box">Lotsen hittar ingen tydlig programdel som återstår.</div>'}
      <div class="tiny-help plan-help">${plan.verified?'Planen bygger på den verifierade programstrukturen. Exakta tillgodoräknanden beslutas av lärosätet.':'Planen bygger på den programstruktur Lotsen har. Kontrollera aktuellt upplägg med lärosätet innan kursval.'}</div>
      ${p.sourceUrl?`<a class="program-source-link" href="${escapeHtml(p.sourceUrl)}" target="_blank" rel="noopener">Öppna officiell programplan ↗</a>`:''}
    </section>

    <details class="detail-block program-credit-block">
      <summary><div><h3>Det du redan har</h3><span>${accepted.length+review.length} matchningar · ${fmtHp(potentiallyUsed)} hp</span></div><span class="detail-arrow">›</span></summary>
      <div class="program-credit-list">
        ${accepted.map(x=>programPartHtml(x,'Stark matchning')).join('')}
        ${review.map(x=>programPartHtml(x,x.matchType==='degree'?'Kan passa som valfri del':'Behöver granskas')).join('')}
        ${!accepted.length&&!review.length?'<div class="muted small">Ingen tydlig matchning hittad ännu.</div>':''}
      </div>
    </details>

    ${!r.eligibility.ok?`<section class="detail-block"><h3>Behörighet</h3><div class="tiny-help">${escapeHtml(r.eligibility.note)}</div></section>`:''}
  `;
}
function programPartHtml(x,label){
  const evidence=x.evidence||[];
  const names=evidence.length?evidence.map(e=>e.name).slice(0,3):[];
  return `<div class="program-credit-item">
    <div><strong>${escapeHtml(x.pc.name)}</strong><span class="program-match-label">${escapeHtml(label)}</span>
      ${names.length?`<small>${names.map(escapeHtml).join(' + ')}</small>`:`<small>${escapeHtml(x.reason||'')}</small>`}
    </div>
    <b>${fmtHp(x.hp)} hp</b>
  </div>`;
}

function programEligibility(p){
 if(!p.eligibility)return {ok:true,note:''};
 let ok=true, notes=[];
 if(p.eligibility?.workExperienceMonths){ok=false;notes.push(`${p.eligibility.workExperienceMonths} mån arbetslivserfarenhet behöver verifieras`)};
 if(p.eligibility?.priorSubjectStudies){ok=false;notes.push('tidigare ämnesstudier för lärarbehörighet behöver verifieras')};
 if(p.eligibility.degree){
   let issued=[];
   try{issued=JSON.parse(sessionStorage.getItem('lotsen_issued_degrees')||'[]')}catch(e){}
   if(!issued.length){ok=false;notes.push('kandidatexamen behöver verifieras')}
 }
 if(p.eligibility.subject){
   const hp=courses.filter(c=>c.selected!==false&&c.subject===p.eligibility.subject).reduce((s,c)=>s+Number(c.hp||0),0);
   if(hp<(p.eligibility.subjectHp||0)){ok=false;notes.push(`${fmtHp((p.eligibility.subjectHp||0)-hp)} hp ${p.eligibility.subject} saknas för behörighet`)}
 }
 if(p.eligibility.subjects){
   const accepted=p.eligibility.subjects;
   const hp=courses.filter(c=>c.selected!==false&&accepted.includes(c.subject)).reduce((s,c)=>s+Number(c.hp||0),0);
   if(hp<90){ok=false;notes.push('relevant kandidatexamen behöver verifieras')}
 }
 if(p.eligibility.thesis){
   const thesisHp=courses.filter(c=>c.selected!==false&&c.thesis).reduce((s,c)=>s+Number(c.hp||0),0);
   if(thesisHp<p.eligibility.thesis){ok=false;notes.push(`${fmtHp(p.eligibility.thesis)} hp självständigt arbete krävs`)}
 }
 return {ok,note:notes.join(' · ')};
}
function estimateProgram(p){
 const available=courses.filter(c=>c.selected!==false).map((c,i)=>({...c,_i:i}));
 const used=new Set(), parts=[];
 for(const pc of p.courses.filter(x=>!x.elective)){
   const ranked=available.filter(c=>!used.has(c._i)).map(c=>{const sim=courseSimilarity(pc,c);return {c,score:sim.score,parts:sim.parts,syllabusEvidence:sim.syllabusEvidence}}).sort((a,b)=>b.score-a.score);
   let need=pc.hp, matched=0, bestNames=[], bestScore=0, evidence=[];
   for(const hit of ranked){
     if(hit.score<35 || need<=0)break;
     const take=Math.min(need,Number(hit.c.hp||0));
     if(take<=0)continue;
     matched+=take;need-=take;used.add(hit.c._i);bestNames.push(hit.c.name);bestScore=Math.max(bestScore,hit.score);evidence.push({name:hit.c.name,score:hit.score,parts:hit.parts,hp:take,syllabusEvidence:hit.syllabusEvidence,syllabusLookup:hit.c.syllabusLookup});
   }
   const level=bestScore>=95?'Stark':bestScore>=70?'Trolig':matched>0?'Granska':'Ingen';
   const bestEvidence=evidence[0];
   const exactCode=Boolean(bestEvidence?.parts?.code>=55 || bestEvidence?.syllabusEvidence?.codeExact);
   const hasTwoSyllabi=Boolean(bestEvidence?.syllabusEvidence?.complete);
   const matchType=exactCode || (bestScore>=90&&hasTwoSyllabi) ? 'replace' : matched>0 ? 'review' : 'none';
   parts.push({pc,hp:matched,level,matchType,reason:bestNames.length?bestNames.slice(0,2).join(' + '):'Ingen tydlig motsvarighet hittad',evidence});
 }
 for(const pc of p.courses.filter(x=>x.elective)){
   const free=available.filter(c=>!used.has(c._i));
   const hp=Math.min(pc.hp,free.reduce((s,c)=>s+Number(c.hp||0),0));
   parts.push({pc,hp,level:hp?'Möjlig':'Låg',matchType:hp?'degree':'none',reason:hp?'Kan sannolikt användas som valfria poäng i examen':'Inga återstående kurser',evidence:[]});
 }
 const replaceHp=parts.filter(x=>x.matchType==='replace').reduce((s,x)=>s+x.hp,0);
 const degreeHp=parts.filter(x=>x.matchType==='degree').reduce((s,x)=>s+x.hp,0);
 const reviewHp=parts.filter(x=>x.matchType==='review').reduce((s,x)=>s+x.hp,0);
 const likely=replaceHp;
 const possible=degreeHp+reviewHp;
 const eligibility=programEligibility(p);
 return {p,parts,likely,possible,replaceHp,degreeHp,reviewHp,remaining:Math.max(0,p.hp-replaceHp-degreeHp-reviewHp),eligibility};
}


function populateCompareSelects(){
 const opts=safeDegreeOpportunities();
 const a=document.getElementById('compareA'),b=document.getElementById('compareB');
 if(!a||!b)return;
 const oldA=a.value,oldB=b.value;
 const options=opts.map(x=>`<option value="${escapeHtml(x.key)}">${escapeHtml(x.name)}</option>`).join('');
 a.innerHTML=options;b.innerHTML=options;
 if(oldA&&opts.some(x=>x.key===oldA))a.value=oldA;
 if(oldB&&opts.some(x=>x.key===oldB))b.value=oldB;
 if(!a.value&&opts[0])a.value=opts[0].key;
 if((!b.value||b.value===a.value)&&opts[1])b.value=opts[1].key;
}
