let homeFastestKeys={candidate:null,advanced:null};
function homeFastestByLevel(level){
 try{
   const rows=safeDegreeOpportunities()
     .filter(o=>Number.isFinite(Number(o.remaining)))
     .filter(o=>level==='candidate'?o.source!=='advanced':o.source==='advanced');
   if(!rows.length)return null;
   return rows.slice().sort((a,b)=>{
     const ar=Math.max(0,Number(a.remaining||0)),br=Math.max(0,Number(b.remaining||0));
     if(ar!==br)return ar-br;
     return Number(b.score||0)-Number(a.score||0) ||
       String(a.subject||a.name||'').localeCompare(String(b.subject||b.name||''),'sv');
   })[0]||null;
 }catch(e){return null}
}
function renderHomeFastest(){
 const stack=document.getElementById('homeFastestStack');
 if(!stack)return;
 if(!courses.length){
   stack.style.display='none';
   homeFastestKeys={candidate:null,advanced:null};
   return;
 }
 const levels=[
   ['candidate','homeFastestCandidate','homeFastestCandidateName','homeFastestCandidateMeta'],
   ['advanced','homeFastestAdvanced','homeFastestAdvancedName','homeFastestAdvancedMeta']
 ];
 let any=false;
 levels.forEach(([level,rowId,nameId,metaId])=>{
   const row=document.getElementById(rowId),o=homeFastestByLevel(level);
   if(!row)return;
   if(!o){row.style.display='none';homeFastestKeys[level]=null;return}
   any=true;homeFastestKeys[level]=o.key;
   const rem=Math.max(0,Number(o.remaining||0));
   const total=level==='candidate'?180:(String(o.degreeType||'').toLowerCase()==='magister'?60:120);
   const used=Math.max(0,Math.min(total,total-rem));
   document.getElementById(nameId).textContent=o.name||o.subject||'Närmaste examen';
   document.getElementById(metaId).textContent=(used?fmtHp(used)+' hp kan räknas · ':'')+(rem?fmtHp(rem)+' hp kvar':'Ser klar ut');
   row.style.display='flex';
 });
 stack.style.display=any?'block':'none';
}
function openHomeFastestLevel(level){
 const key=homeFastestKeys[level];
 if(key){openDegreeDetails(key);return}
 go('degrees');
}

