async function admissionFileText(file){
 if(!file)return '';
 if(/^image\//i.test(file.type||''))throw new Error('image-needs-ocr');
 if(file.type==='application/pdf'||/\.pdf$/i.test(file.name||'')){
  const pdfjsLib=await loadPdfJs().catch(()=>null);if(!pdfjsLib)return '';
  const buf=await file.arrayBuffer(),pdf=await pdfjsLib.getDocument({data:buf}).promise;let text='';
  for(let i=1;i<=pdf.numPages;i++){const page=await pdf.getPage(i),c=await page.getTextContent();text+=' '+c.items.map(x=>x.str).join(' ')}
  return text;
 }
 return await file.text();
}
function gradeValue(letter){return ({A:20,B:17.5,C:15,D:12.5,E:10,F:0})[String(letter||'').toUpperCase()]}
function inferGrundskolaMerit(text){
 const t=String(text||'').replace(/\s+/g,' '),grades=[];
 const re=/(?:^|\s)(A|B|C|D|E|F)(?=\s|$|,|;)/g;let m;
 while((m=re.exec(t))&&grades.length<30)grades.push(m[1]);
 if(grades.length<8)return null;
 const vals=grades.map(gradeValue).filter(Number.isFinite).sort((a,b)=>b-a);
 const take=Math.min(vals.length,17);return Math.round(vals.slice(0,take).reduce((s,x)=>s+x,0)*10)/10;
}
function inferHigherMerit(text){
 const t=String(text||'');
 const patterns=[/meritv(?:ä|a)rde\s*[:\-]?\s*(\d{1,2}[,.]\d{1,2})/i,/j(?:ä|a)mf(?:ö|o)relsetal\s*[:\-]?\s*(\d{1,2}[,.]\d{1,2})/i];
 for(const p of patterns){const m=t.match(p);if(m){const n=Number(m[1].replace(',','.'));if(n>=0&&n<=22.5)return n}}
 return null;
}
async function importAdmissionGrades(input,kind){
 const file=input?.files?.[0];if(!file)return;
 const status=document.getElementById(kind==='gymnasium'?'gymGradeStatus':'higherGradeStatus');if(status)status.textContent='Läser betygen…';
 try{
  const text=await admissionFileText(file);
  if(kind==='gymnasium'){
   const merit=inferGrundskolaMerit(text);
   if(merit!=null){admissionProfile.gymMerit=merit;sessionStorage.setItem('studielots_gym_merit',String(merit));if(status)status.innerHTML=`<strong>${file.name}</strong> · preliminärt meritvärde ${String(merit).replace('.',',')}`}
   else if(status)status.innerHTML=`<strong>${file.name}</strong> uppladdad. Meritvärdet kunde inte räknas säkert – fyll i det manuellt.`;
  }else{
   const merit=inferHigherMerit(text);
   if(merit!=null){admissionProfile.higherMerit=merit;sessionStorage.setItem('studielots_higher_merit',String(merit));if(status)status.innerHTML=`<strong>${file.name}</strong> · meritvärde ${String(merit).replace('.',',')} hittades.`}
   else if(status)status.innerHTML=`<strong>${file.name}</strong> uppladdad. Fyll i ditt meritvärde ovan om det inte framgår i dokumentet.`;
  }
  restoreAdmissionProfile();scheduleAdmissionSearch(kind);
 }catch(e){console.warn('admission import',e);if(status)status.textContent=e?.message==='image-needs-ocr'?'Bild uppladdad. Bildavläsning kopplas in senare – använd PDF eller fyll i värdet manuellt.':'Kunde inte läsa dokumentet. Fyll i värdet manuellt.'}
 input.value='';
}
function scheduleAdmissionSearch(kind){clearTimeout(admissionSearchTimer);admissionSearchTimer=setTimeout(()=>searchAdmissionHistory(kind),250)}

function admissionComparison(score,cutoff){
 if(score==null||cutoff==null||!Number.isFinite(Number(cutoff)))return null;
 const diff=Math.round((Number(score)-Number(cutoff))*100)/100;
 return {diff,above:diff>=0};
}
function admissionComparisonLabel(score,cutoff){
 const c=admissionComparison(score,cutoff);
 if(!c)return '';
 const val=String(Math.abs(c.diff)).replace('.',',');
 return c.above
   ? `<span class="admission-chance above">+${val} över</span>`
   : `<span class="admission-chance below">−${val} under</span>`;
}
function admissionScoreLabel(kind){
 if(kind==='gymnasium')return 'Ditt meritvärde';
 return admissionProfile.higherGroup==='HP'?'Ditt högskoleprov':`Ditt meritvärde · ${admissionProfile.higherGroup}`;
}
function admissionScoreValue(kind){
 return kind==='gymnasium'
   ? admissionProfile.gymMerit
   : (admissionProfile.higherGroup==='HP'?admissionProfile.hp:admissionProfile.higherMerit);
}
function admissionHistorySummary(kind,rows,score){
 const valid=(rows||[]).filter(r=>Number.isFinite(Number(r.cutoff)));
 if(!valid.length)return '';
 const cutoffs=valid.map(r=>Number(r.cutoff));
 const latest=valid[0];
 const comparisons=score==null?[]:valid.map(r=>admissionComparison(score,Number(r.cutoff))).filter(Boolean);
 const aboveCount=comparisons.filter(x=>x.above).length;
 const min=Math.min(...cutoffs),max=Math.max(...cutoffs);
 const latestCmp=score==null?null:admissionComparison(score,Number(latest.cutoff));
 return `<section class="admission-result-summary">
   <div class="admission-result-summary-head">
     <div><span>Din jämförelse</span><h3>${escapeHtml(admissionScoreLabel(kind))}</h3></div>
     <strong>${score==null?'–':String(score).replace('.',',')}</strong>
   </div>
   <div class="admission-result-metrics">
     <div><span>Senaste gräns</span><b>${String(latest.cutoff).replace('.',',')}</b>${latestCmp?admissionComparisonLabel(score,Number(latest.cutoff)):''}</div>
     <div><span>Historiskt spann</span><b>${String(min).replace('.',',')}–${String(max).replace('.',',')}</b><small>${valid.length} ${valid.length===1?'period':'perioder'}</small></div>
     <div><span>Du hade legat över</span><b>${score==null?'–':`${aboveCount} av ${comparisons.length}`}</b><small>${score==null?'Lägg in dina meriter för jämförelse':'historiska gränser'}</small></div>
   </div>
   <div class="admission-result-note">${score==null
     ? 'Lägg in ditt meritvärde eller högskoleprovsresultat för att se hur du hade legat till.'
     : latestCmp?.above
       ? 'Ditt resultat ligger över den senaste historiska gränsen i den här jämförelsen.'
       : 'Ditt resultat ligger under den senaste historiska gränsen i den här jämförelsen.'}
   </div>
 </section>`;
}
function renderAdmissionRows(kind,rows){
 const host=document.getElementById(kind==='gymnasium'?'gymAdmissionResults':'higherAdmissionResults');if(!host)return;
 if(!rows.length){
   host.innerHTML='<div class="admission-empty"><strong>Ingen historik hittades ännu.</strong><span>När antagningsdatan är ansluten visas tidigare års gränser här. Funktionen är byggd för att fyllas på utan att gränssnittet behöver göras om.</span></div>';
   return;
 }
 const score=admissionScoreValue(kind);
 const sorted=[...rows].sort((a,b)=>{
   const ya=String(a.year||a.term||''),yb=String(b.year||b.term||'');
   return yb.localeCompare(ya,'sv',{numeric:true});
 });
 const summary=admissionHistorySummary(kind,sorted,score);
 const cards=sorted.map((r,i)=>{
   const cutoff=Number(r.cutoff);
   const cmp=admissionComparison(score,cutoff);
   const status=cmp?(cmp.above?'above':'below'):'neutral';
   return `<article class="admission-history-card ${status}">
     <div class="admission-history-top">
       <div>
         <span>${escapeHtml(r.year||r.term||'')}</span>
         <h3>${escapeHtml(r.name||r.program||'')}</h3>
         <small>${escapeHtml(r.school||r.university||'')}</small>
       </div>
       <div class="admission-cutoff"><strong>${String(r.cutoff??'–').replace('.',',')}</strong><span>Antagningsgräns</span></div>
     </div>
     <div class="admission-history-comparison">
       ${score!=null?`<div><span>${escapeHtml(admissionScoreLabel(kind))}</span><strong>${String(score).replace('.',',')}</strong></div>`:''}
       ${admissionComparisonLabel(score,cutoff)}
     </div>
     <div class="admission-history-meta">
       ${r.group?`<span>${escapeHtml(r.group)}</span>`:''}
       ${r.term?`<span>${escapeHtml(r.term)}</span>`:''}
       ${r.source?`<span>${escapeHtml(r.source)}</span>`:''}
       ${i===0?'<span class="latest-history">Senaste</span>':''}
     </div>
   </article>`;
 }).join('');
 host.innerHTML=summary+`<div class="admission-history-list">${cards}</div>`;
}


