const STUDIELOTS_GYM_SOURCE='https://skolkoll.se/nedladdning/antagning.csv';
const STUDIELOTS_UHR_STATS='https://www.uhr.se/studier-och-antagning/antagningsstatistik/';

function parseSwedishCsv(text){
 const lines=String(text||'').replace(/^\uFEFF/,'').split(/\r?\n/).filter(Boolean);
 if(lines.length<2)return [];
 const heads=lines[0].split(';').map(x=>x.trim().toLowerCase());
 return lines.slice(1).map(line=>{
   const vals=line.split(';'),o={};
   heads.forEach((k,i)=>o[k]=(vals[i]||'').trim());
   return o;
 });
}
function normalizeSearchText(s){
 return String(s||'').toLowerCase().normalize('NFD').replace(/[\u0300-\u036f]/g,'').replace(/\s+/g,' ').trim();
}
async function fetchNationalGymAdmissions(a,b){
 const res=await fetch(STUDIELOTS_GYM_SOURCE,{cache:'no-store'});
 if(!res.ok)throw new Error('gym-source-'+res.status);
 const rows=parseSwedishCsv(await res.text());
 const qa=normalizeSearchText(a),qb=normalizeSearchText(b);
 return rows.filter(r=>{
   const place=normalizeSearchText(`${r.skolnamn||''} ${r.kommun||''}`);
   const prog=normalizeSearchText(`${r.program||''} ${r.inriktning||''}`);
   return (!qa||place.includes(qa))&&(!qb||prog.includes(qb));
 }).map(r=>({
   name:[r.program,r.inriktning].filter(Boolean).join(' – '),
   program:r.program||'',
   school:r.skolnamn||'',
   year:r.ar||'',
   term:r.ar||'',
   cutoff:Number(String(r.antagningspoang||'').replace(',','.')),
   group:'Slutlig antagning',
   source:'Skolverket'
 })).filter(r=>Number.isFinite(r.cutoff)).sort((x,y)=>String(y.year).localeCompare(String(x.year),'sv',{numeric:true}));
}
function officialStatsLink(kind,a,b){
 const q=[a,b].filter(Boolean).join(' ');
 if(kind==='higher')return STUDIELOTS_UHR_STATS;
 return 'https://www.skolverket.se/';
}
