 const a=String(f.a?.value||'').trim(), b=String(f.b?.value||'').trim();
 if(!a&&!b){host.innerHTML='<div class="admission-empty">Skriv skola/lärosäte eller program och tryck Sök.</div>';return}
 if(f.host)f.host.innerHTML='';
