// v206 — remove remaining legacy Chalmers authority and make v2 confidence-aware.
const _v205EvaluateChalmersProgramV2=evaluateChalmersProgramV2;
evaluateChalmersProgramV2=function(program){
  const r=_v205EvaluateChalmersProgramV2(program);
  if(!r)return r;
  const complete=String(program.coverage||'').toLowerCase()==='complete';
  const knownInventory=Math.max(0,Number(r.knownInventory||0));
  const degreeHp=Math.max(0,Number(program.hp||0));
  const unknownHp=complete?0:Math.max(0,degreeHp-Math.min(degreeHp,knownInventory));
  const knownMissing=Math.max(0,Number(r.remaining||0));
  // Conservative while the catalogue is partial: unknown programme hp remains unresolved.
  const remaining=complete?knownMissing:Math.max(knownMissing,unknownHp+knownMissing);
  const score=degreeHp?Math.max(0,Math.min(complete?100:99,Math.round(100*(degreeHp-Math.min(degreeHp,remaining))/degreeHp))):0;
  return {...r,remaining,score,complete,unknownHp,knownMissing,coveragePartial:!complete,canClaimComplete:complete&&remaining===0};
};

// Chalmers generic legacy degree rules are no longer an authority. Other universities keep them.
const _v205LocalDegreeRule=localDegreeRule;
localDegreeRule=function(profileId,major,degreeKind='candidate'){
  const id=String(profileId||'').toLowerCase();
  if(id.includes('chalmers')||id==='flex-chalmers')return null;
  return _v205LocalDegreeRule(profileId,major,degreeKind);
};

// Advanced Chalmers choices now come from v2 rather than localDegreeRule().
const _v205AdvancedUniversityOptions=advancedUniversityOptions;
advancedUniversityOptions=function(subject,degreeType){
  let opts=_v205AdvancedUniversityOptions(subject,degreeType).filter(x=>x.d?.university!=='Chalmers tekniska högskola');
  try{
    const kind=String(degreeType||'').toLowerCase()==='magister'?'magister':'master';
    const v2=bestChalmersV2Path(subject,kind);
    if(v2){
      opts.push({d:{id:'flex-chalmers',name:'Chalmers tekniska högskola',university:'Chalmers tekniska högskola',verified:true},rule:null,breakdown:null,remaining:v2.remaining,verified:true,major:subject,advanced:true,engine:'v2',v2,degreeTitle:{title:v2.program.name}});
    }
  }catch(e){console.error('v206 advanced Chalmers options',e)}
  return opts.sort((a,b)=>(Number(b.verified)-Number(a.verified))||Number(a.remaining||999)-Number(b.remaining||999));
};

// Candidate readiness may use v2 for Chalmers discovery, but partial programmes never unlock 100% readiness.
const _v205CandidateReadiness=candidateReadiness;
candidateReadiness=function(){
  const rows=_v205CandidateReadiness();
  try{
    const ch=flexibleDegreeCatalog.find(x=>x.id==='flex-chalmers');
    for(const subject of (ch?.majors||[])){
      const v2=bestChalmersV2Path(subject,'candidate');
      if(!v2)continue;
      const existing=rows.find(x=>String(x.subject||'').toLowerCase()===String(subject).toLowerCase());
      const row={subject,name:v2.program.name,score:v2.score,remaining:v2.remaining,subjectMissing:v2.remaining,ready:Boolean(v2.canClaimComplete),near:Boolean(v2.complete&&v2.remaining<=30&&v2.score>=80),engine:'v2',programCode:v2.program.code};
      if(existing){
        if(row.ready || (!existing.ready && row.score>Number(existing.score||0)))Object.assign(existing,row);
      }else rows.push(row);
    }
  }catch(e){console.error('v206 candidate readiness',e)}
  return rows.sort((a,b)=>(Number(b.ready)-Number(a.ready))||(Number(b.score)-Number(a.score))||(Number(a.remaining||999)-Number(b.remaining||999)));
};

