// v207 — unified Chalmers v2 engine layer + correct elective accounting.
function chalmersRuleEvaluation(program, used){
  const usedByProgramCode=new Map((used||[]).map(x=>[String(x.programCourse?.code||'').trim().toUpperCase(),x]));
  const results=[];
  const coveredCodes=new Set();
  for(const r of (program.rules||[])){
    const codes=(r.codes||[]).map(x=>String(x).trim().toUpperCase()).filter(Boolean);
    const codeSet=new Set(codes);
    if(r.type==='choice_min_hp'){
      const have=[...usedByProgramCode.entries()].filter(([code])=>codeSet.has(code)).reduce((sum,[,x])=>sum+Number(x.countedHp||x.programCourse?.hp||0),0);
      const target=Math.max(0,Number(r.hp||0));
      codes.forEach(c=>coveredCodes.add(c));
      results.push({...r,have,target,missing:Math.max(0,target-have),engineType:'choice'});
    }else if(r.type==='thesis_required'){
      const thesisUsed=(used||[]).filter(x=>x.programCourse?.thesis||codeSet.has(String(x.programCourse?.code||'').toUpperCase()));
      const have=thesisUsed.reduce((sum,x)=>sum+Number(x.countedHp||x.programCourse?.hp||0),0);
      const target=Math.max(0,Number(r.hp||0));
      codes.forEach(c=>coveredCodes.add(c));
      results.push({...r,have,target,missing:Math.max(0,target-have),engineType:'thesis'});
    }else{
      results.push({...r,have:0,target:0,missing:0,engineType:'other'});
    }
  }
  return {results,coveredCodes};
}

const _v206EvaluateChalmersProgramV2=evaluateChalmersProgramV2;
evaluateChalmersProgramV2=function(program){
  if(!program)return null;
  const match=chalmersCourseMatchForProgram(program);
  const matchedCodes=new Set(match.used.map(x=>String(x.programCourse?.code||x.programCourse?.name||'').trim().toUpperCase()));
  const required=(program.courses||[]).filter(c=>c.required);
  const requiredMissing=required.filter(c=>!matchedCodes.has(String(c.code||c.name||'').trim().toUpperCase()));
  const requiredMatched=required.filter(c=>matchedCodes.has(String(c.code||c.name||'').trim().toUpperCase()));
  const requiredTotalHp=required.reduce((s,c)=>s+Number(c.hp||0),0);
  const requiredMatchedHp=requiredMatched.reduce((s,c)=>s+Number(c.hp||0),0);

  const ruleEval=chalmersRuleEvaluation(program,match.used);
  // A rule can point to courses already marked required. Only the part outside the
  // required block expands the verified programme structure.
  let extraRuleStructureHp=0;
  let extraRuleSatisfiedHp=0;
  for(const r of ruleEval.results){
    const target=Number(r.target||0); if(!target)continue;
    const ruleCourses=(program.courses||[]).filter(c=>(r.codes||[]).map(x=>String(x).toUpperCase()).includes(String(c.code||'').toUpperCase()));
    const requiredInRule=ruleCourses.filter(c=>c.required).reduce((s,c)=>s+Number(c.hp||0),0);
    const extraTarget=Math.max(0,target-Math.min(target,requiredInRule));
    extraRuleStructureHp+=extraTarget;
    const extraHave=Math.max(0,Number(r.have||0)-Math.min(Number(r.have||0),requiredInRule));
    extraRuleSatisfiedHp+=Math.min(extraTarget,extraHave);
  }

  const verifiedStructureHp=Math.min(Number(program.hp||Infinity),requiredTotalHp+extraRuleStructureHp);
  const verifiedSatisfiedHp=Math.min(verifiedStructureHp,requiredMatchedHp+extraRuleSatisfiedHp);
  const knownMissing=Math.max(0,verifiedStructureHp-verifiedSatisfiedHp);
  const complete=String(program.coverage||'').toLowerCase()==='complete';
  const degreeHp=Math.max(0,Number(program.hp||0));
  const unresolvedStructureHp=complete?0:Math.max(0,degreeHp-verifiedStructureHp);
  const remaining=Math.max(0,knownMissing+unresolvedStructureHp);
  const mappedHp=Math.min(degreeHp,verifiedSatisfiedHp);
  const score=degreeHp?Math.max(0,Math.min(complete?100:99,Math.round(100*(degreeHp-Math.min(degreeHp,remaining))/degreeHp))):0;

  const electiveOptions=(program.courses||[]).filter(c=>c.elective&&!c.required);
  const electiveMatched=electiveOptions.filter(c=>matchedCodes.has(String(c.code||c.name||'').trim().toUpperCase()));
  return {
    program,used:match.used,requiredMissing,rules:ruleEval.results,
    remaining,score,mappedHp,knownInventory:(program.courses||[]).reduce((s,c)=>s+Number(c.hp||0),0),
    verifiedStructureHp,verifiedSatisfiedHp,unresolvedStructureHp,unknownHp:unresolvedStructureHp,
    knownMissing,complete,coveragePartial:!complete,canClaimComplete:complete&&remaining===0,
    requiredHp:requiredMatchedHp,electiveHp:electiveMatched.reduce((s,c)=>s+Number(c.hp||0),0),
    electiveOptions,electiveMatched
  };
};

// One adapter is now the single public engine contract for Chalmers UI/flows.
function chalmersV2EngineResult(o,major,profileId='flex-chalmers'){
  if(profileId!=='flex-chalmers'&&profileId!=='course-chalmers'&&!String(profileId||'').startsWith('chalmers-'))return null;
  const subject=String(major||o?.subject||'').trim(); if(!subject)return null;
  const kind=o?.source==='advanced'?(String(o?.degreeType||'master').toLowerCase()==='magister'?'magister':'master'):'candidate';
  const v2=bestChalmersV2Path(subject,kind); if(!v2)return null;
  return {
    engine:'v2',provider:'Chalmers tekniska högskola',profileId:'flex-chalmers',subject,kind,
    program:v2.program,programCode:v2.program.code,programName:v2.program.name,
    remaining:Number(v2.remaining||0),score:Number(v2.score||0),complete:Boolean(v2.complete),
    used:v2.used||[],requiredMissing:v2.requiredMissing||[],rules:v2.rules||[],
    mappedHp:Number(v2.mappedHp||0),verifiedStructureHp:Number(v2.verifiedStructureHp||0),
    unresolvedStructureHp:Number(v2.unresolvedStructureHp||0),knownMissing:Number(v2.knownMissing||0),v2
  };
}

const _v206CanonicalPathResult=canonicalPathResult;
canonicalPathResult=function(o,profileId=''){
  try{
    let preferred=profileId;
    if(!preferred){try{preferred=sessionStorage.getItem('lotsen_preferred_profile')||''}catch(e){}}
    const wantsChalmers=preferred==='flex-chalmers'||String(preferred).startsWith('chalmers-')||String(o?.canonicalUniversity||'')==='Chalmers tekniska högskola';
    if(wantsChalmers){
      const e=chalmersV2EngineResult(o,o?.subject,preferred||'flex-chalmers');
      if(e)return {...e,university:e.provider};
    }
  }catch(e){console.error('v207 canonical Chalmers adapter',e)}
  return _v206CanonicalPathResult(o,profileId);
};

const _v206MissingForOpportunity=missingForOpportunity;
missingForOpportunity=function(o){
  try{
    const p=canonicalPathResult(o);
    if(p?.engine==='v2'&&p.v2){
      const rows=[];
      for(const c of (p.requiredMissing||[]))rows.push({label:c.name||c.code,hp:Number(c.hp||0),type:c.thesis?'thesis':'required',subject:c.subject||o?.subject,courseCode:c.code||''});
      for(const r of (p.rules||[]))if(Number(r.missing||0)>0)rows.push({label:r.label||'Valregel',hp:Number(r.missing||0),type:r.type||'rule'});
      if(Number(p.unresolvedStructureHp||0)>0)rows.push({label:'Programstruktur ännu inte komplett kartlagd',hp:Number(p.unresolvedStructureHp||0),type:'coverage',unresolved:true});
      return rows;
    }
  }catch(e){console.error('v207 missing adapter',e)}
  return _v206MissingForOpportunity(o);
};

// Suggestions now distinguish required missing courses from elective alternatives.
const _v206ChalmersCourseSuggestions=chalmersCourseSuggestions;
chalmersCourseSuggestions=function(major,o,limit=12){
  try{
    const e=chalmersV2EngineResult(o,major,'flex-chalmers');
    if(e){
      const completed=new Set((courses||[]).map(c=>String(c.code||'').trim().toUpperCase()).filter(Boolean));
      const missingCodes=new Set((e.requiredMissing||[]).map(c=>String(c.code||'').trim().toUpperCase()).filter(Boolean));
      const rows=(e.program.courses||[]).filter(c=>!completed.has(String(c.code||'').trim().toUpperCase())).map(c=>{
        const requiredMissing=missingCodes.has(String(c.code||'').trim().toUpperCase());
        const ruleRelevant=(e.rules||[]).some(r=>Number(r.missing||0)>0&&(r.codes||[]).map(x=>String(x).toUpperCase()).includes(String(c.code||'').toUpperCase()));
        return {...c,programCode:e.program.code,programName:e.program.name,programUrl:e.program.sourceUrl||'',verified:e.program.verified===true,
          score:requiredMissing?120:ruleRelevant?90:c.required?70:c.elective?25:10,
          reason:requiredMissing?'obligatorisk kurs som saknas i din Chalmersväg':ruleRelevant?'alternativ som kan uppfylla en återstående valregel':c.required?'obligatorisk i programmet':'valbar kurs i programmet'};
      }).sort((a,b)=>b.score-a.score||String(a.name||'').localeCompare(String(b.name||''),'sv'));
      if(rows.length)return rows.slice(0,limit);
    }
  }catch(e){console.error('v207 suggestions adapter',e)}
  return _v206ChalmersCourseSuggestions(major,o,limit);
};

console.info('Studielots v207: unified Chalmers v2 engine layer; elective inventory no longer counted as missing requirements');
;
// v208 — complete Chalmers rule semantics + regression guardrails.
function chalmersRuleCourseHp(program,codes){
  const set=new Set((codes||[]).map(x=>String(x).trim().toUpperCase()).filter(Boolean));
  return (program.courses||[]).filter(c=>set.has(String(c.code||'').trim().toUpperCase())).map(c=>Number(c.hp||0)).filter(h=>h>0);
}
function chalmersChoiceCountTargetHp(program,r){
  const count=Math.max(0,Number(r.count||1));
  const hps=chalmersRuleCourseHp(program,r.codes).sort((a,b)=>a-b);
  if(!count||!hps.length)return 0;
  // Conservative minimum hp needed to satisfy a count-based rule.
  const picks=[];for(let i=0;i<count;i++)picks.push(hps[Math.min(i,hps.length-1)]||0);
  return picks.reduce((s,h)=>s+h,0);
}
function chalmersApplyOverlapExclusions(program,used){
  let rows=(used||[]).slice();
  for(const r of (program.rules||[]).filter(x=>x.type==='overlap_exclusion')){
    const set=new Set((r.codes||[]).map(x=>String(x).trim().toUpperCase()));
    const maxCount=Math.max(1,Number(r.maxCount||1));
    const inGroup=rows.filter(x=>set.has(String(x.programCourse?.code||'').trim().toUpperCase()))
      .sort((a,b)=>Number(b.score||0)-Number(a.score||0)||Number(b.countedHp||0)-Number(a.countedHp||0));
    const keep=new Set(inGroup.slice(0,maxCount));
    rows=rows.filter(x=>!set.has(String(x.programCourse?.code||'').trim().toUpperCase())||keep.has(x));
  }
  return rows;
}
chalmersRuleEvaluation=function(program,used){
  const effectiveUsed=chalmersApplyOverlapExclusions(program,used);
  const usedByProgramCode=new Map((effectiveUsed||[]).map(x=>[String(x.programCourse?.code||'').trim().toUpperCase(),x]));
  const results=[]; const coveredCodes=new Set();
  for(const r of (program.rules||[])){
    const codes=(r.codes||[]).map(x=>String(x).trim().toUpperCase()).filter(Boolean);
    const set=new Set(codes); codes.forEach(c=>coveredCodes.add(c));
    const matched=[...usedByProgramCode.entries()].filter(([code])=>set.has(code)).map(([,x])=>x);
    const matchedHp=matched.reduce((s,x)=>s+Number(x.countedHp||x.programCourse?.hp||0),0);
    if(r.type==='choice_min_hp'){
      const target=Math.max(0,Number(r.hp||0));
      results.push({...r,have:Math.min(target,matchedHp),target,missing:Math.max(0,target-matchedHp),engineType:'choice_hp'});
    }else if(r.type==='choice_count'||r.type==='required_choice'){
      const targetCount=Math.max(0,Number(r.count||1));
      const haveCount=Math.min(targetCount,matched.length);
      const target=chalmersChoiceCountTargetHp(program,{...r,count:targetCount});
      const satisfiedHp=Math.min(target,matched.slice().sort((a,b)=>Number(a.programCourse?.hp||0)-Number(b.programCourse?.hp||0)).slice(0,targetCount).reduce((s,x)=>s+Number(x.countedHp||x.programCourse?.hp||0),0));
      const missingCount=Math.max(0,targetCount-haveCount);
      results.push({...r,have:satisfiedHp,target,haveCount,targetCount,missingCount,missing:missingCount?Math.max(0,target-satisfiedHp):0,engineType:'choice_count'});
    }else if(r.type==='thesis_required'||r.type==='thesis_choice'){
      const thesisMatches=(effectiveUsed||[]).filter(x=>x.programCourse?.thesis||set.has(String(x.programCourse?.code||'').trim().toUpperCase()));
      const have=thesisMatches.reduce((s,x)=>s+Number(x.countedHp||x.programCourse?.hp||0),0);
      const target=Math.max(0,Number(r.hp||0)||chalmersChoiceCountTargetHp(program,{...r,count:1}));
      results.push({...r,have:Math.min(target,have),target,missing:Math.max(0,target-have),engineType:'thesis'});
    }else if(r.type==='overlap_exclusion'){
      const rawCount=(used||[]).filter(x=>set.has(String(x.programCourse?.code||'').trim().toUpperCase())).length;
      const maxCount=Math.max(1,Number(r.maxCount||1));
      results.push({...r,have:Math.min(rawCount,maxCount),target:maxCount,missing:0,excludedCount:Math.max(0,rawCount-maxCount),engineType:'overlap'});
    }else{
      results.push({...r,have:0,target:0,missing:0,engineType:'other'});
    }
  }
  return {results,coveredCodes,effectiveUsed};
};

const _v207EvaluateChalmersProgramV2=evaluateChalmersProgramV2;
evaluateChalmersProgramV2=function(program){
  if(!program)return null;
  const rawMatch=chalmersCourseMatchForProgram(program);
  const ruleEval=chalmersRuleEvaluation(program,rawMatch.used);
  const used=ruleEval.effectiveUsed||rawMatch.used;
  const matchedCodes=new Set(used.map(x=>String(x.programCourse?.code||x.programCourse?.name||'').trim().toUpperCase()));
  const required=(program.courses||[]).filter(c=>c.required);
  const requiredMissing=required.filter(c=>!matchedCodes.has(String(c.code||c.name||'').trim().toUpperCase()));
  const requiredMatched=required.filter(c=>matchedCodes.has(String(c.code||c.name||'').trim().toUpperCase()));
  const requiredTotalHp=required.reduce((s,c)=>s+Number(c.hp||0),0);
  const requiredMatchedHp=requiredMatched.reduce((s,c)=>s+Number(c.hp||0),0);

  // Build verified structure from required courses plus rule requirements not already contained in required courses.
  let extraRuleStructureHp=0, extraRuleSatisfiedHp=0;
  for(const r of ruleEval.results){
    const target=Math.max(0,Number(r.target||0)); if(!target||r.engineType==='overlap')continue;
    const codeSet=new Set((r.codes||[]).map(x=>String(x).trim().toUpperCase()));
    const requiredInRule=required.filter(c=>codeSet.has(String(c.code||'').trim().toUpperCase())).reduce((s,c)=>s+Number(c.hp||0),0);
    const extraTarget=Math.max(0,target-Math.min(target,requiredInRule));
    extraRuleStructureHp+=extraTarget;
    const ruleHave=Math.max(0,Number(r.have||0));
    const extraHave=Math.max(0,ruleHave-Math.min(ruleHave,requiredInRule));
    extraRuleSatisfiedHp+=Math.min(extraTarget,extraHave);
  }
  const degreeHp=Math.max(0,Number(program.hp||0));
  const verifiedStructureHp=Math.min(degreeHp||Infinity,requiredTotalHp+extraRuleStructureHp);
  const verifiedSatisfiedHp=Math.min(verifiedStructureHp,requiredMatchedHp+extraRuleSatisfiedHp);
  const knownMissing=Math.max(0,verifiedStructureHp-verifiedSatisfiedHp);
  const complete=String(program.coverage||'').toLowerCase()==='complete';
  const unresolvedStructureHp=complete?0:Math.max(0,degreeHp-verifiedStructureHp);
  const remaining=Math.max(0,knownMissing+unresolvedStructureHp);
  const mappedHp=Math.min(degreeHp,verifiedSatisfiedHp);
  const score=degreeHp?Math.max(0,Math.min(complete?100:99,Math.round(100*(degreeHp-Math.min(degreeHp,remaining))/degreeHp))):0;
  const electiveOptions=(program.courses||[]).filter(c=>c.elective&&!c.required);
  const electiveMatched=electiveOptions.filter(c=>matchedCodes.has(String(c.code||c.name||'').trim().toUpperCase()));
  return {program,used,requiredMissing,rules:ruleEval.results,remaining,score,mappedHp,
    knownInventory:(program.courses||[]).reduce((s,c)=>s+Number(c.hp||0),0),verifiedStructureHp,verifiedSatisfiedHp,
    unresolvedStructureHp,unknownHp:unresolvedStructureHp,knownMissing,complete,coveragePartial:!complete,
    canClaimComplete:complete&&remaining===0,requiredHp:requiredMatchedHp,electiveHp:electiveMatched.reduce((s,c)=>s+Number(c.hp||0),0),
    electiveOptions,electiveMatched,overlapExcluded:(ruleEval.results||[]).reduce((s,r)=>s+Number(r.excludedCount||0),0)};
};

function chalmersV2RegressionAudit(){
  const programs=normalizedProgramCatalog().filter(p=>p.university==='Chalmers tekniska högskola'&&p.academicYear==='2026/2027'&&!p.catalogOnly);
  const issues=[];
  for(const p of programs){
    const e=evaluateChalmersProgramV2(p); if(!e)continue;
    if(e.coveragePartial&&e.score>=100)issues.push({code:p.code,type:'partial_100'});
    if(e.remaining<0||e.knownMissing<0||e.unresolvedStructureHp<0)issues.push({code:p.code,type:'negative'});
    const rawElective=(p.courses||[]).filter(c=>c.elective&&!c.required).reduce((s,c)=>s+Number(c.hp||0),0);
    if(e.verifiedStructureHp>Number(p.hp||0)&&Number(p.hp||0)>0)issues.push({code:p.code,type:'structure_over_degree'});
    if(rawElective>0&&!(p.rules||[]).length&&e.verifiedStructureHp> (p.courses||[]).filter(c=>c.required).reduce((s,c)=>s+Number(c.hp||0),0)+0.01)issues.push({code:p.code,type:'elective_inventory_counted'});
  }
  const result={version:'v208',programs:programs.length,issues,passed:issues.length===0};
  return result;
}
