function applyChalmersV2SafetyUi(host){
  if(!host)return;
  const gate=chalmersV2GateState();
  const chip=host.querySelector('.verify-chip');
  const summary=host.querySelector('.detail-summary');
  host.querySelectorAll('.v213-safe-warning').forEach(x=>x.remove());

  if(!gate.known){
    if(chip){chip.classList.remove('verified');chip.classList.add('unverified');chip.textContent='v2 självtest pågår';}
    return;
  }
  if(gate.ready){
    if(chip){chip.classList.remove('unverified');chip.classList.add('verified');chip.textContent='Verifierad programplan · v2 tester OK';}
    return;
  }

  if(chip){chip.classList.remove('verified');chip.classList.add('unverified');chip.textContent='Kontrolläge · ej slutverifierad';}
  const warning=document.createElement('div');
  warning.className='course-provider-note v213-safe-warning';
  warning.innerHTML=`<strong>Studielots kontrolläge:</strong> Chalmers-v2:s interna kvalitetstester har flaggat ${escapeHtml((gate.failedSuites||[]).join(', ')||'en avvikelse')}. Programmatchning och kursförslag visas fortfarande, men resultatet används inte som ett slutligt “klar”-besked förrän testerna passerar igen.`;
  if(summary)summary.insertAdjacentElement('afterend',warning);
  else host.prepend(warning);

  // Defensive UI guard: never show a 100% badge while safe mode is active.
  host.querySelectorAll('.badge').forEach(b=>{
    if(/^\s*100%\s*$/.test(b.textContent||''))b.textContent='99%';
  });
}

