function chalmersV2StructuralReadiness(){
  let programs=[];
  try{
    programs=(typeof normalizedProgramCatalog==='function'?normalizedProgramCatalog():(programCatalog||[]))
      .filter(p=>p&&p.university==='Chalmers tekniska högskola'&&!p.superseded&&!p.catalogOnly);
  }catch(e){}

  const problems=[];
  programs.forEach(p=>{
    if(p.integrityQuarantined)problems.push(`${p.code||p.name}:integrity`);
    if(p.selfTestFailed)problems.push(`${p.code||p.name}:self-test`);
    if(p.coverage==='complete'){
      if(!Array.isArray(p.courses)||!p.courses.length)problems.push(`${p.code||p.name}:courses`);
      if(p.canCalculateCompletion===false)problems.push(`${p.code||p.name}:completion-disabled`);
    }
  });

  return {
    version:CHALMERS_V2_BUILD,
    ready:programs.length>0 && problems.length===0,
    programmes:programs.length,
    failedSuites:problems,
    structural:true,
    checkedAt:new Date().toISOString()
  };
}

function chalmersV2CachedGate(){
  try{
    const raw=sessionStorage.getItem(CHALMERS_V2_GATE_CACHE);
    if(!raw)return null;
    const parsed=JSON.parse(raw);
    return parsed&&parsed.version===CHALMERS_V2_BUILD?parsed:null;
  }catch(e){return null}
}

function chalmersV2RunVerificationOnce({force=false}={}){
  if(!force){
    const cached=chalmersV2CachedGate();
    if(cached)return Promise.resolve(chalmersV2SetGateResult(cached));
  }
  return Promise.resolve(chalmersV2SetGateResult(chalmersV2StructuralReadiness()));
}

