// Hard-block localDegreeRule as a calculator inside migrated v2 scopes.
const _v232LegacyLocalDegreeRule=localDegreeRule;
localDegreeRule=function(profileId,major,degreeKind='candidate'){
  const uni=profileUniversity(profileId);
  if(migratedV2Scope({university:uni,profileId,major})){
    return null;
  }
  return _v232LegacyLocalDegreeRule(profileId,major,degreeKind);
};

// Canonical path is the single calculation route. V2 wins before legacy can run.
const _v232CanonicalPathResult=canonicalPathResult;
canonicalPathResult=function(o,profileId=''){
  let preferred=profileId;
  if(!preferred){try{preferred=sessionStorage.getItem('lotsen_preferred_profile')||''}catch(e){}}
  const uni=profileUniversity(preferred)||String(o?.canonicalUniversity||'');
  const v2=v2EngineResultFor({university:uni,profileId:preferred,major:o?.subject||'',opportunity:o});
  if(v2)return {...v2,university:v2.provider};
  return _v232CanonicalPathResult(o,profileId);
};

// Missing requirements always derive from the same canonical v2 result.
const _v232MissingForOpportunity=missingForOpportunity;
missingForOpportunity=function(o){
  try{
    const path=canonicalPathResult(o);
    if(path?.engine==='v2'){
      const rows=[];
      for(const c of (path.requiredMissing||[])){
        rows.push({label:c.name||c.code||'Obligatorisk kurs',hp:Number(c.hp||0),type:c.thesis?'thesis':'required',subject:c.subject||o?.subject,courseCode:c.code||''});
      }
      for(const r of (path.rules||[])){
        if(Number(r.missing||0)>0)rows.push({label:r.label||r.type,hp:Number(r.missing||0),type:r.type,subject:r.subject||''});
      }
      if(Number(path.unresolvedStructureHp||0)>0)rows.push({label:'Programstruktur ännu inte komplett kartlagd',hp:Number(path.unresolvedStructureHp||0),type:'coverage',unresolved:true});
      return rows;
    }
  }catch(e){console.error('v232 missing router',e)}
  return _v232MissingForOpportunity(o);
};

// Generic v2 detail renderer for migrated non-Chalmers scopes.
function renderGenericUniversityV2Detail(engine){
  const host=document.getElementById('universityDetailContent'); if(!host||!engine)return;
  const used=engine.used||[];
  const missing=engine.requiredMissing||[];
  const ruleRows=(engine.rules||[]).filter(r=>Number(r.missing||0)>0);
  host.innerHTML=`
   <div class="detail-hero">
    <div><div class="uni-detail-brand">${universityLogoHtml(engine.provider,'lg')}<div><div class="eyebrow">${escapeHtml(engine.provider)} · v2</div><h1>${escapeHtml(engine.programName)}</h1></div></div>
    <div class="verify-chip ${engine.complete?'verified':'unverified'}">${engine.complete?'Verifierad programstruktur · v2':'Verifierad källa · delvis kartlagd v2'}</div></div>
    <span class="badge ${engine.remaining===0&&engine.complete?'good':engine.remaining<=30?'warn':'bad'}">${engine.complete&&engine.remaining===0?'100%':engine.score+'%'}</span>
   </div>
   <div class="detail-summary"><strong>${fmtHp(engine.remaining)} hp kvar/olöst i v2</strong>${engine.unresolvedStructureHp?` · ${fmtHp(engine.unresolvedStructureHp)} hp ännu ej strukturerat`:''}</div>
   <section class="detail-block"><h2>Tillgodoräknat mot programmet</h2>
    ${used.length?`<div class="suggested-course-list">${used.map(x=>`<div class="suggested-course-row"><div><strong>${escapeHtml(x.programCourse?.name||x.programCourse?.code||'Kurs')}</strong><small>${escapeHtml(x.userCourse?.name||'Matchad merit')}</small></div><b>${fmtHp(x.countedHp||x.programCourse?.hp||0)} hp</b></div>`).join('')}</div>`:'<div class="card empty">Inga programkurser matchade ännu.</div>'}
   </section>
   <section class="detail-block"><h2>Kvarstående verifierade krav</h2>
    ${(missing.length||ruleRows.length)?`<div class="suggested-course-list">
      ${missing.map(c=>`<div class="suggested-course-row"><div><strong>${escapeHtml(c.name||c.code||'Obligatorisk kurs')}</strong><small>${escapeHtml(c.code||c.subject||'')}</small></div><b>${fmtHp(c.hp||0)} hp</b></div>`).join('')}
      ${ruleRows.map(r=>`<div class="suggested-course-row"><div><strong>${escapeHtml(r.label||r.type)}</strong><small>Programregel</small></div><b>${fmtHp(r.missing||0)} hp</b></div>`).join('')}
    </div>`:'<div class="ready-box">Alla verifierade krav vi känner till är uppfyllda.</div>'}
   </section>`;
}

// University detail is intercepted before legacy for migrated v2 scopes.
const _v232RenderUniversityDetail=renderUniversityDetail;
renderUniversityDetail=function(profileId,major){
  const uni=profileUniversity(profileId);
  const scope=migratedV2Scope({university:uni,profileId,major});
  if(scope){
    const detailKey=sessionStorage.getItem('lotsen_detail_key');
    const o=(typeof safeDegreeOpportunities==='function'?safeDegreeOpportunities():[]).find(x=>x.key===detailKey)||{subject:major,source:'specific'};
    const engine=v2EngineResultFor({university:uni,profileId,major,opportunity:o});
    if(engine){
      if(uni==='Chalmers tekniska högskola'&&typeof renderChalmersV2DegreeDetail==='function')return renderChalmersV2DegreeDetail(major,o);
      return renderGenericUniversityV2Detail(engine);
    }
  }
  return _v232RenderUniversityDetail(profileId,major);
};

// Audit: migrated scopes must never be allowed to calculate with legacy.
function legacyIsolationAudit(){
  const tests=[];
  const add=(name,pass,details={})=>tests.push({name,pass:Boolean(pass),...details});
  add('chalmers_legacy_blocked',localDegreeRule('flex-chalmers','Datateknik','candidate')===null);
  add('gu_fek_legacy_blocked',localDegreeRule('flex-gu','Företagsekonomi','candidate')===null);
  add('gu_nek_legacy_blocked',localDegreeRule('flex-gu','Nationalekonomi','candidate')===null);
  add('gu_psykologi_still_legacy_until_migrated',localDegreeRule('flex-gu','Psykologi','candidate')!==null);
  add('chalmers_fallback_disabled',V2_MIGRATION_SCOPES['Chalmers tekniska högskola'].legacyFallback===false);
  const failed=tests.filter(t=>!t.pass);
  return {version:'v232',passed:failed.length===0,total:tests.length,failed:failed.length,failures:failed};
}
