// v248 — GU migration resolver/audit.
// Every original inventory record resolves to exact v2, family v2, or remains explicitly pending.
function guNormalizeProgrammeName(name){
 return String(name||'')
  .toLowerCase()
  .normalize('NFD').replace(/[\u0300-\u036f]/g,'')
  .replace(/[,–—:()/]/g,' ')
  .replace(/\b(kandidatprogram|masterprogram|magisterprogram|programmet|program)\b/g,' ')
  .replace(/\s+/g,' ').trim();
}
function guResolveInventoryProgram(inventoryProgram){
 if(!inventoryProgram||inventoryProgram.university!=='Göteborgs universitet')return null;
 const all=normalizedProgramCatalog().filter(p=>p.university==='Göteborgs universitet'&&p.academicYear==='2026/2027'&&!p.catalogOnly);
 const invName=guNormalizeProgrammeName(inventoryProgram.name);
 // 1. exact official code if known.
 const official=String(inventoryProgram.officialCode||inventoryProgram.code||'').toUpperCase();
 if(official&&!official.startsWith('GUINV-')){
   const exactCode=all.find(p=>String(p.officialCode||p.code||'').toUpperCase()===official);
   if(exactCode)return {type:'exact_code',program:exactCode};
 }
 // 2. exact/near normalized programme name.
 let exact=all.find(p=>{
   const n=guNormalizeProgrammeName(p.name);
   return n===invName || (n.length>12&&invName.length>12&&(n.includes(invName)||invName.includes(n)));
 });
 if(exact)return {type:'exact_name',program:exact};
 // 3. verified family template.
 if(typeof guFamilyForInventoryProgram==='function'){
   const fam=guFamilyForInventoryProgram(inventoryProgram);
   if(fam)return {type:'family',program:fam};
 }
 return null;
}
function guMigrationAudit(){
 const all=normalizedProgramCatalog().filter(p=>p.university==='Göteborgs universitet'&&p.academicYear==='2026/2027');
 const inventory=all.filter(p=>p.catalogOnly);
 const structured=all.filter(p=>!p.catalogOnly&&!p.degreePath);
 const degreePaths=all.filter(p=>p.degreePath);
 const covered=[],pending=[];
 inventory.forEach(p=>{
   const hit=guResolveInventoryProgram(p);
   if(hit)covered.push({inventoryCode:p.code,name:p.name,resolution:hit.type,v2Code:hit.program.code});
   else pending.push({inventoryCode:p.code,name:p.name,category:p.category||'',level:p.level||'',hp:p.hp||0});
 });
 const byCategory={};
 pending.forEach(p=>{byCategory[p.category]=(byCategory[p.category]||0)+1});
 const byLevel={};
 pending.forEach(p=>{byLevel[p.level]=(byLevel[p.level]||0)+1});
 return {
   version:'v249',
   status:pending.length===0?'source_complete':'building',
   inventory:inventory.length,
   structuredPrograms:structured.length,
   degreePaths:degreePaths.length,
   coveredInventory:covered.length,
   pendingInventory:pending.length,
   pendingByCategory:byCategory,
   pendingByLevel:byLevel,
   covered,
   pending
 };
}
