// v269 — GU final catalogue closure.
//
// Policy:
// 1) The official GU programme inventory is the source-of-truth for programme presence.
// 2) Exact/structured v2 records win.
// 3) Any still-unresolved active 2026/27 inventory item receives a SAFE v2 catalogue shell.
// 4) A catalogue shell has no invented courses/rules, is source-limited and can never claim 100%.
// 5) Once every current inventory item resolves to v2, legacy is disabled for all GU scopes.

const GU_V269_CATALOGUE_SOURCE={
 ground:'https://www.gu.se/studera-vid-goteborgs-universitet/program-pa-grundniva',
 advanced:'https://www.gu.se/studera-vid-goteborgs-universitet/program-pa-avancerad-niva',
 checkedAt:'2026-08-24',
 policy:'official_catalogue_inventory_is_presence_truth'
};

function guV269MakeSafeShell(inv){
 const hp=Number(inv?.hp||0);
 const level=String(inv?.level||'');
 const code='GU-SAFE-'+String(inv?.code||inv?.id||Math.random().toString(36).slice(2)).replace(/[^A-Za-z0-9-]/g,'').toUpperCase();
 return {
   id:'gu-safe-'+String(inv?.id||inv?.code||code).replace(/[^A-Za-z0-9-]/g,'').toLowerCase(),
   code,
   officialCode:String(inv?.officialCode||''),
   inventoryCode:String(inv?.code||''),
   academicYear:'2026/2027',
   name:String(inv?.name||'Göteborgs universitetsprogram'),
   university:'Göteborgs universitet',
   hp,
   verified:true,
   coverage:'partial',
   sourceLimited:true,
   catalogShell:true,
   safeMode:true,
   noFalse100:true,
   canCalculateCompletion:false,
   sourceLevel:'official_catalogue_inventory',
   level,
   engine:'v2',
   category:String(inv?.category||''),
   sourceUrl:/Avancerad/i.test(level)?GU_V269_CATALOGUE_SOURCE.advanced:GU_V269_CATALOGUE_SOURCE.ground,
   courses:[],
   rules:[],
   sourceLimitedNote:'Programmet är verifierat i GU:s officiella programkatalog för 2026/27, men exakt kurs-/regelstruktur är ännu inte tillräckligt publicerad eller detaljmappad. Studielots får därför inte påstå full matchning eller föreslå ej verifierade kurser.'
 };
}

function guV269Inventory(){
 return normalizedProgramCatalog().filter(p=>
   p.university==='Göteborgs universitet' &&
   p.academicYear==='2026/2027' &&
   p.catalogOnly===true
 );
}

function guV269UnresolvedInventory(){
 return guV269Inventory().filter(p=>{
   try{return !guResolveInventoryProgram(p)}catch(e){return true}
 });
}

// Materialise safe v2 shells only for inventory items that still have no exact/family/replacement resolution.
const __guV269Before=guV269UnresolvedInventory();
for(const inv of __guV269Before){
 const shell=guV269MakeSafeShell(inv);
 // Avoid duplicate shells when GU's official overview repeats a programme under multiple subject categories.
 const existing=normalizedProgramCatalog().find(p=>
   p.university==='Göteborgs universitet' &&
   !p.catalogOnly &&
   String(p.name||'').trim().toLowerCase()===String(shell.name||'').trim().toLowerCase() &&
   p.academicYear==='2026/2027'
 );
 if(!existing) programCatalog.push(shell);
}

// All GU 2026 inventory now has a v2 representation. Disable legacy globally for GU.
if(typeof V2_MIGRATION_SCOPES!=='undefined' && V2_MIGRATION_SCOPES['Göteborgs universitet']){
 V2_MIGRATION_SCOPES['Göteborgs universitet'].all=true;
 V2_MIGRATION_SCOPES['Göteborgs universitet'].legacyFallback=false;
}
if(typeof UNIVERSITY_V2_REGISTRY!=='undefined' && UNIVERSITY_V2_REGISTRY['Göteborgs universitet']){
 UNIVERSITY_V2_REGISTRY['Göteborgs universitet'].status='source_complete';
 UNIVERSITY_V2_REGISTRY['Göteborgs universitet'].locked=true;
 UNIVERSITY_V2_REGISTRY['Göteborgs universitet'].legacyFallback=false;
}

function guV269FinalAudit(){
 const inv=guV269Inventory();
 const unresolved=inv.filter(p=>{
   try{return !guResolveInventoryProgram(p)}catch(e){return true}
 });
 const activeV2=normalizedProgramCatalog().filter(p=>
   p.university==='Göteborgs universitet' &&
   p.academicYear==='2026/2027' &&
   !p.catalogOnly
 );
 const shells=activeV2.filter(p=>p.catalogShell===true);
 const exact=activeV2.filter(p=>p.catalogShell!==true && p.coverage==='complete');
 const partial=activeV2.filter(p=>p.catalogShell!==true && p.coverage==='partial');
 const unsafeShells=shells.filter(p=>
   p.coverage!=='partial' ||
   p.sourceLimited!==true ||
   p.canCalculateCompletion!==false ||
   (p.courses||[]).length!==0
 );
 const futureWrong=activeV2.filter(p=>p.code==='N1CAI'||p.officialCode==='N1CAI');
 const legacyOff=Boolean(
   V2_MIGRATION_SCOPES?.['Göteborgs universitet']?.all===true &&
   V2_MIGRATION_SCOPES?.['Göteborgs universitet']?.legacyFallback===false
 );
 const passed=unresolved.length===0 && unsafeShells.length===0 && futureWrong.length===0 && legacyOff;
 return {
   version:'v269',
   status:passed?'source_complete':'audit_failed',
   ready:passed,
   officialInventoryRecords:inv.length,
   v2Records:activeV2.length,
   exactCourseOrRuleMapped:exact.length,
   structuredPartial:partial.length,
   safeCatalogueShells:shells.length,
   unresolvedInventory:unresolved.map(p=>({code:p.code,name:p.name})),
   unsafeShells:unsafeShells.map(p=>({code:p.code,name:p.name})),
   futureMisclassified:futureWrong.map(p=>({code:p.code,name:p.name})),
   legacyDisabledForAllGU:legacyOff,
   policy:{
     inventory:'All active 2026/27 GU catalogue records must resolve to v2.',
     partial:'Partial/source-limited records may be searchable but may not claim exact completion.',
     legacy:'Legacy is disabled for all GU once inventory coverage reaches zero unresolved.'
   }
 };
}

