// v293 — harden LU v2 catalogue while the official Lubas inventory audit continues.
// We must not count aliases/older placeholders as separate programmes.
const LU_V293_CANONICAL_ALIASES={
 'HIST-K-LU':'HGHIS',
 'BIOMED-K-LU':'MGBIM',
 'PUBLIC-HEALTH-LU':'FOLKH-M-LU',
 'AUDIONOM-LU':'VGAUD',
 'FOLKVARLD-K-LU':'KGMUS-FOVÄ',
 'KGKYM':'KGKYM'
};

function luCanonicalCodeV293(code){
 return LU_V293_CANONICAL_ALIASES[code]||code;
}

function lundCanonicalProgramsV293(){
 const lu=normalizedProgramCatalog().filter(p=>
   p.university==='Lunds universitet' &&
   p.academicYear==='2026/2027' &&
   !p.catalogOnly
 );
 const byKey=new Map();
 for(const p of lu){
   const code=luCanonicalCodeV293(p.officialCode||p.code||p.id);
   const key=code || String(p.name||'').toLowerCase().replace(/\s+/g,' ').trim();
   const prev=byKey.get(key);
   // Prefer complete structure, otherwise latest v2 record.
   if(!prev || (prev.coverage!=='complete' && p.coverage==='complete')) byKey.set(key,p);
   else if(prev.coverage===p.coverage) byKey.set(key,p);
 }
 return [...byKey.values()];
}

function lundV293Audit(){
 const raw=normalizedProgramCatalog().filter(p=>p.university==='Lunds universitet'&&p.academicYear==='2026/2027'&&!p.catalogOnly);
 const canon=lundCanonicalProgramsV293();
 const rawCodes=raw.map(p=>luCanonicalCodeV293(p.officialCode||p.code||p.id));
 const duplicateCodes=[...new Set(rawCodes.filter((c,i,a)=>c&&a.indexOf(c)!==i))];
 const unsafe=canon.filter(p=>p.safeMode===true&&(
   p.noFalse100!==true ||
   p.canCalculateCompletion!==false ||
   (p.courses||[]).length>0
 ));
 const invalidComplete=canon.filter(p=>p.coverage==='complete' && (!(p.courses||[]).length || !(p.rules||[]).length));
 return {
   version:'v293',
   status:'building',
   rawLundRecords:raw.length,
   canonicalLundRecords:canon.length,
   duplicateCanonicalCodes:duplicateCodes,
   unsafeSafeRecords:unsafe.map(p=>p.code),
   structurallySuspiciousComplete:invalidComplete.map(p=>p.code),
   migratedRecordsV2Only:true,
   universityWideSourceComplete:false,
   sourceOfTruth:'LU Lubas / official lu.se programme presentations',
   blocker:'LU states that Lubas contains all courses and programmes. A complete programme-only 2026/27 Lubas export is not yet materialised in this static file, so a global sourceComplete=true would still be unverified.'
 };
}
