function lundV312Audit(){
 const lu=normalizedProgramCatalog().filter(p=>p.university==='Lunds universitet'&&p.academicYear==='2026/2027'&&!p.catalogOnly);
 const codes=new Set(lu.map(p=>p.code));
 const groups={};
 let allConfirmed=[];
 for(const [k,v] of Object.entries(LU_V312_HT26_EVIDENCE_MATRIX)){
   if(!v.confirmed) continue;
   const missing=v.confirmed.filter(c=>!codes.has(c));
   groups[k]={expected:v.confirmed.length,missing,accounted:missing.length===0};
   allConfirmed.push(...v.confirmed);
 }
 allConfirmed=[...new Set(allConfirmed)];
 const allMissing=allConfirmed.filter(c=>!codes.has(c));
 const unsafe=lu.filter(p=>p.safeMode===true&&(
   p.noFalse100!==true || p.canCalculateCompletion!==false || (p.courses||[]).length>0
 ));
 return {
   version:'v312',
   status:'building',
   evidenceGroups:groups,
   confirmedEvidenceCodes:allConfirmed.length,
   confirmedEvidenceMissing:allMissing,
   confirmedEvidenceAccounted:allMissing.length===0,
   unsafeSafeRecords:unsafe.map(p=>p.code),
   totalLundV2Records:lu.length,
   universityWideSourceComplete:false,
   closureChecklist:{
     officialMultiRoundModelCaptured:true,
     lthProgrammePlanAuditSubstantiallyReconciled:true,
     knownDiscontinuationGuarded:true,
     facultyEvidenceMatrixBuilt:true,
     wholeUniversityCanonicalZeroGap:false
   },
   remainingGate:'Build/verify the remaining faculty programme families against official HT26/Lubas-backed sources, then run canonical duplicate + zero-gap closure.'
 };
}
