window.__studielotsV366={version:'v366',engine:'v2',activeUniversities:[...V2_ACTIVE_UNIVERSITIES],v2OnlyUi:true,stableHpSource:true};
console.info('Studielots v366: v2-only university gate + stable hp source installed');

// v373 — Matchningsmotor v2.1: one selected university + one relevant programme = one canonical result.
// Removes the cross-program Chalmers fallback and uses the same result for credit, remaining HP and suggestions.
(function(){
 const V21_UNIVERSITIES=[
  {id:'v21:chalmers',name:'Chalmers tekniska högskola'},
  {id:'v21:gu',name:'Göteborgs universitet'},
  {id:'v21:lund',name:'Lunds universitet'}
 ];
 const norm=v=>String(v||'').trim().toLocaleLowerCase('sv-SE');
 const words=v=>typeof normalizedWords==='function'?normalizedWords(v):norm(v).split(/[^a-zåäö0-9]+/i).filter(Boolean);
 function degreeKindFor(o){return o?.source==='advanced'?(norm(o?.degreeType).includes('magister')?'magister':'master'):'candidate'}
 function degreeHpFor(o){return degreeKindFor(o)==='candidate'?180:degreeKindFor(o)==='magister'?60:120}
 function universityForProfile(id){
   const hit=V21_UNIVERSITIES.find(x=>x.id===id); if(hit)return hit.name;
   const s=norm(id); if(s.includes('chalmers'))return 'Chalmers tekniska högskola'; if(s==='flex-gu'||s==='gu'||s.startsWith('gu-'))return 'Göteborgs universitet'; if(s.includes('lund')||s==='lu'||s.startsWith('lu-'))return 'Lunds universitet';
   try{return (flexibleDegreeCatalog||[]).find(x=>String(x.id)===String(id))?.university||''}catch(e){return ''}
 }
 function programmeScore(p,major,kind,total){
   if(!p||p.catalogOnly||p.engine!=='v2'||p.academicYear!=='2026/2027')return -9999;
   if(p.safeMode===true&&p.canCalculateCompletion===false)return -9999;
   const hp=Number(p.hp||0); if(hp!==total)return -9999;
   const n=norm(p.name), t=norm(p.track), s=norm(p.subject), m=norm(major);
   const advanced=/avancerad/i.test(String(p.level||''))||p.advanced===true;
   if(kind==='candidate'&&advanced)return -9999;
   if(kind!=='candidate'&&!advanced)return -9999;
   let score=0;
   if(s===m)score+=180;
   if(t===m)score+=170;
   if(n.includes(`kandidatexamen i ${m}`)||n.includes(`kandidatspår i ${m}`))score+=190;
   if(n.includes(m))score+=100;
   if(t.includes(m)||m.includes(t)&&t.length>4)score+=90;
   if(s.includes(m)||m.includes(s)&&s.length>4)score+=90;
   const mw=words(m).filter(x=>x.length>3);
   mw.forEach(w=>{if(n.includes(w))score+=22;if(t.includes(w))score+=20});
   const exactSubjectCourses=(p.courses||[]).filter(c=>norm(c.subject)===m).length;
   score+=Math.min(70,exactSubjectCourses*10);
   if(p.degreePath)score+=35;
   if(norm(p.coverage)==='complete')score+=25;
   if(p.verified===true)score+=15;
   // Explicit economics programme aliases.
   if(m==='företagsekonomi'&&/ekonomie kandidatprogram/.test(n))score+=130;
   if(m==='nationalekonomi'&&/ekonomie kandidatprogram/.test(n))score+=90;
   // Professional programmes must not masquerade as generic candidate paths.
   if(kind==='candidate'&&/psykologprogrammet|juristprogrammet|sjökapten|sjöingenjör|lärarprogram|arbetsterapeutprogram/.test(n))score-=180;
   return score;
 }
 function relevantProgrammes(university,major,kind,total){
   let ps=[];try{ps=normalizedProgramCatalog().filter(p=>p.university===university)}catch(e){return []}
   return ps.map(p=>({p,score:programmeScore(p,major,kind,total)})).filter(x=>x.score>=95)
     .sort((a,b)=>b.score-a.score||Number(b.p.coverage==='complete')-Number(a.p.coverage==='complete')||String(a.p.name).localeCompare(String(b.p.name),'sv'));
 }
 function v21PathFor(university,major,o){
   const kind=degreeKindFor(o), total=degreeHpFor(o);
   const candidates=relevantProgrammes(university,major,kind,total); if(!candidates.length)return null;
   // Relevance chooses the programme. Remaining HP may never choose a different programme.
   const program=candidates[0].p;
   let result=null;try{result=evaluateUniversityProgramV2(program)}catch(e){console.error('v373 evaluate',e)}
   if(!result)return null;
   if(result.canClaimComplete===false&&result.remaining===0)result={...result,remaining:Math.max(1,Number(result.unresolvedStructureHp||1)),score:Math.min(99,Number(result.score||0))};
   return {
     engine:'v2.1',provider:university,profileId:V21_UNIVERSITIES.find(x=>x.name===university)?.id||'',subject:major,kind,
     program,programCode:program.code||'',programName:program.name||'',remaining:Number(result.remaining||0),score:Number(result.score||0),
     complete:Boolean(result.complete),used:result.used||[],requiredMissing:result.requiredMissing||[],rules:result.rules||[],
     mappedHp:Number(result.mappedHp||0),verifiedStructureHp:Number(result.verifiedStructureHp||0),unresolvedStructureHp:Number(result.unresolvedStructureHp||0),
     knownMissing:Number(result.knownMissing||0),v2:result
   };
 }
 window.v21PathFor=v21PathFor;

 const previousProfileUniversity=window.profileUniversity||profileUniversity;
 profileUniversity=function(profileId){return universityForProfile(profileId)||previousProfileUniversity(profileId)};
 window.profileUniversity=profileUniversity;

 const previousOptions=universityOptionsForOpportunity;
 universityOptionsForOpportunity=function(o){
   const subject=o?.subject||''; if(!subject)return [];
   const rows=[];
   for(const u of V21_UNIVERSITIES){
     const path=v21PathFor(u.name,subject,o); if(!path)continue;
     rows.push({d:{id:u.id,name:u.name,university:u.name,verified:true,hp:degreeHpFor(o)},major:subject,remaining:path.remaining,verified:true,engine:'v2.1',v2:path,degreeTitle:{title:path.programName},programCode:path.programCode});
   }
   return rows.sort((a,b)=>Number(a.remaining)-Number(b.remaining)||Number(b.v2?.score||0)-Number(a.v2?.score||0));
 };
 window.universityOptionsForOpportunity=universityOptionsForOpportunity;

 const previousCanonical=canonicalPathResult;
 canonicalPathResult=function(o,profileId=''){
   if(!o)return {remaining:0,score:0,profileId:'',university:''};
   let preferred=profileId;try{preferred=preferred||sessionStorage.getItem('lotsen_preferred_profile')||''}catch(e){}
   const opts=universityOptionsForOpportunity(o);
   let chosen=preferred?opts.find(x=>x.d?.id===preferred):null;
   if(!chosen)chosen=opts[0];
   if(chosen?.v2){const p=chosen.v2;return {...p,profileId:chosen.d.id,university:chosen.d.university}}
   return {remaining:Number(o.remaining||degreeHpFor(o)),score:Number(o.score||0),profileId:'',university:''};
 };
 window.canonicalPathResult=canonicalPathResult;

 missingForOpportunity=function(o){
   const p=canonicalPathResult(o); if(!p||!p.engine?.startsWith('v2'))return [];
   const rows=[]; const seen=new Set();
   const add=r=>{const k=[r.label,r.type,r.courseCode].join('|');if(!seen.has(k)&&Number(r.hp||0)>0){seen.add(k);rows.push(r)}};
   (p.requiredMissing||[]).forEach(c=>add({label:c.name||c.code||'Obligatorisk kurs',hp:Number(c.hp||0),type:c.thesis?'thesis':'required',subject:c.subject||o.subject,courseCode:c.code||''}));
   (p.rules||[]).forEach(r=>{if(Number(r.missing||0)>0)add({label:r.label||'Programkrav',hp:Number(r.missing||0),type:r.type||'rule',subject:r.subject||''})});
   if(Number(p.unresolvedStructureHp||0)>0)add({label:'Programstruktur ännu inte komplett kartlagd',hp:Number(p.unresolvedStructureHp),type:'coverage'});
   return rows;
 };
 window.missingForOpportunity=missingForOpportunity;

 function v21CourseCard(c,path){
   const url=typeof antagningCourseUrl==='function'?antagningCourseUrl(c):'https://www.antagning.se/se/search?period=HT_2026&freeText='+encodeURIComponent(c.code||c.name||'');
   return `<article class="chalmers-suggestion compact"><div class="chalmers-suggestion-top"><div>${c.code?`<div class="eyebrow">${escapeHtml(c.code)}</div>`:''}<h3>${escapeHtml(c.name||'Kurs')}</h3></div><b>${fmtHp(c.hp||0)} hp</b></div><div class="chalmers-suggestion-reason">${c.thesis?'Examensarbete som saknas':c.required?'Obligatorisk kurs som saknas':'Kurs som kan passa i vald väg'}</div><div class="chalmers-application">${typeof courseApplicationBadge==='function'?courseApplicationBadge(c):''}<a href="${escapeHtml(url)}" target="_blank" rel="noopener">Visa på Antagning.se ↗</a></div></article>`;
 }
 function v21SuggestionSection(path){
   const missing=(path.requiredMissing||[]).filter(c=>Number(c.hp||0)>0);
   const ruleMissing=(path.rules||[]).filter(r=>Number(r.missing||0)>0);
   if(path.program?.safeMode===true||path.program?.canCalculateCompletion===false){
     return `<div class="course-provider-note"><strong>Detaljerad kursplan ännu inte verifierad.</strong> Studielots gissar därför inte vilka enskilda kurser du ska läsa.</div>`;
   }
   if(missing.length){
     const first=missing.slice(0,6),rest=missing.slice(6);
     return `<div class="chalmers-suggestion-list">${first.map(c=>v21CourseCard(c,path)).join('')}</div>${rest.length?`<details class="path-details"><summary>Visa ${rest.length} fler kurser</summary><div class="chalmers-suggestion-list">${rest.map(c=>v21CourseCard(c,path)).join('')}</div></details>`:''}`;
   }
   if(ruleMissing.length){
     return `<div class="course-provider-note suggestion-empty"><strong>Inga verifierade kursförslag ännu.</strong><span>Kraven visas under Kvar. Studielots föreslår bara riktiga kurser när en verifierad kurslista finns för den valda vägen.</span></div>`;
   }
   return '<div class="ready-box">Inga verifierade kompletteringar återstår i den kartlagda strukturen.</div>';
 }

 function v21CreditedRows(path){
   const rows=[], seen=new Set();
   for(const x of (path.used||[])){
     const hp=Number(x.countedHp||0); if(hp<=0)continue;
     const name=x.userCourse?.name||'Tidigare kurs';
     const target=x.programCourse?.name||'programkrav';
     const key='course|'+name+'|'+target+'|'+hp; if(seen.has(key))continue; seen.add(key);
     rows.push({kind:'course',name,target,hp});
   }
   // Rule-level credits are legitimate credits in the degree even when they do not replace one named course.
   for(const r of (path.rules||[])){
     const target=Math.max(0,Number(r.hp||r.target||0));
     const have=Math.max(0,Math.min(target,Number(r.have||0)));
     if(have<=0)continue;
     const label=r.label||r.subject||
       (r.type==='elective_min_hp'?'Valbara/fria kurser':
       r.type==='choice_subject_min_hp'?'Ämnesblock':
       r.type==='subject_min_hp'?'Huvudområde':
       r.type==='advanced_min_hp'?'Avancerad nivå':
       r.type==='thesis_total_hp'||r.type==='thesis_required'?'Självständigt arbete':'Examenskrav');
     const key='rule|'+label+'|'+have; if(seen.has(key))continue; seen.add(key);
     rows.push({kind:'rule',name:label,target:'Kan användas i examen',hp:have});
   }
   return rows;
 }
 function renderV21Detail(path,o){
   const host=document.getElementById('universityDetailContent');if(!host)return;
   const used=path.used||[], credited=v21CreditedRows(path), miss=missingForOpportunity(o); const total=degreeHpFor(o); const counted=Math.max(0,total-Number(path.remaining||0));
   const safeComplete=path.complete&&Number(path.remaining||0)===0&&Number(path.unresolvedStructureHp||0)===0;
   host.innerHTML=`
    <div class="detail-hero"><div><div class="uni-detail-brand">${universityLogoHtml(path.provider,'lg')}<div><div class="eyebrow">${escapeHtml(path.provider)} · motor v2.1</div><h1>${escapeHtml(path.programName)}</h1></div></div><div class="verify-chip verified">Verifierad källa · v2.1</div></div><span class="badge ${safeComplete?'good':path.remaining<=30?'warn':'bad'}">${safeComplete?'100%':Math.max(0,Math.min(99,Number(path.score||0)))+'%'}</span></div>
    <div class="detail-summary"><strong>${fmtHp(counted)} hp kan räknas</strong> · <strong>${fmtHp(path.remaining)} hp kvar/olöst</strong></div>
    <section class="detail-block credited-compact"><details class="credited-details"><summary><span><small>Tillgodoräknat</small><strong>${fmtHp(counted)} hp</strong></span><b>Visa vilka kurser <i>›</i></b></summary><div class="credited-detail-body">${credited.length?`<div class="suggested-course-list">${credited.map(x=>`<div class="suggested-course-row"><div><strong>${escapeHtml(x.name)}</strong><small>${x.kind==='course'?'→ '+escapeHtml(x.target):escapeHtml(x.target)}</small></div><b>${fmtHp(x.hp)} hp</b></div>`).join('')}</div>`:`<div class="credit-explanation"><strong>${fmtHp(counted)} hp kan räknas enligt examensreglerna.</strong><p>Poängen är ännu inte kopplade till enskilda ersättningskurser. De används mot huvudområde, valbara poäng eller andra examenskrav.</p></div>`}</div></details></section>
    <section class="detail-block remaining-compact"><details class="remaining-details"><summary><span><small>Kvar</small><strong>${fmtHp(Math.max(0,Number(path.remaining||0)))} hp</strong></span><b>Visa vilka krav <i>›</i></b></summary><div class="remaining-detail-body">${miss.length?`<div class="remaining-detail-meta">${miss.length} krav återstår</div><div class="suggested-course-list">${miss.map((m,i)=>`<div class="suggested-course-row"><span class="suggested-step">${i+1}</span><div><strong>${escapeHtml(m.label)}</strong></div><b>${fmtHp(m.hp)} hp</b></div>`).join('')}</div>`:'<div class="ready-box">Inga verifierade krav återstår.</div>'}</div></details></section>
    ${typeof window.__studielotsCanonicalStudyPlanHtml==='function'?window.__studielotsCanonicalStudyPlanHtml(path,path.requiredMissing||[],{optimized:true}):''}`;
 }
 const previousRenderUniversityDetail=renderUniversityDetail;
 renderUniversityDetail=function(profileId,major){
   const uni=universityForProfile(profileId); const detailKey=sessionStorage.getItem('lotsen_detail_key'); const o=opportunityByKey(detailKey)||{subject:major,source:'specific'};
   const path=uni?v21PathFor(uni,major,o):null;
   if(path){try{sessionStorage.setItem('lotsen_selected_university_name',uni);sessionStorage.setItem('lotsen_preferred_profile',path.profileId)}catch(e){};return renderV21Detail(path,o)}
   const host=document.getElementById('universityDetailContent');if(host)host.innerHTML='<div class="card empty"><strong>Detaljerad v2.1-väg saknas ännu.</strong><div class="small muted">Studielots visar inte en gissad studieplan för detta lärosäte.</div></div>';
 };
 window.renderUniversityDetail=renderUniversityDetail;

 // Disable the old pseudo-university/course-provider route completely.
 window.renderChalmersCourseProviderDetail=function(){const host=document.getElementById('universityDetailContent');if(host)host.innerHTML='<div class="card empty">Den gamla generella kursfallbacken är borttagen i motor v2.1.</div>'};

 function v373Audit(){
   const dummy={subject:'Företagsekonomi',source:'specific',remaining:180,score:0};
   const opts=universityOptionsForOpportunity(dummy);
   const pseudo=opts.some(x=>x.courseProviderOnly||x.d?.id==='course-chalmers');
   const cross=opts.some(x=>!V21_UNIVERSITIES.some(u=>u.name===x.d?.university));
   return {version:'v373',engine:'v2.1',passed:!pseudo&&!cross,universities:opts.map(x=>({university:x.d.university,program:x.v2?.programName,remaining:x.remaining})),pseudoProviderRemoved:!pseudo,onlyActiveV2Universities:!cross};
 }
 window.v373Audit=v373Audit;try{window.__studielotsV373Audit=v373Audit()}catch(e){console.error(e)}
 console.info('Studielots v373: v2.1 relevance-first router enabled; cross-program course fallback removed');
})();
