/* v424 — LTU v2 batch 20: QA hardening + completion readiness */
(function(){
 const LTU='Luleå tekniska universitet';

 // Harden all LTU records: only explicitly complete records may calculate exact completion.
 const ltu=(programCatalog||[]).filter(p=>p&&p.university===LTU);
 ltu.forEach(p=>{
   if(p.coverage!=='complete'){
     p.safeMode=true;
     p.noFalse100=true;
     p.canCalculateCompletion=false;
     p.exactRemainingHp=false;
     p.exactCreditTransfer=false;
   } else {
     p.exactRemainingHp=true;
     p.exactCreditTransfer=true;
   }
 });

 // Duplicate handling: prefer complete > structure > partial/rules > inventory/selector.
 const rank={complete:5,structure:4,partial:3,rules:3,inventory:2,selector:1};
 const groups={};
 ltu.forEach(p=>{
   const key=[p.code||p.officialCode||p.id,p.track||'',p.distance?'distance':''].join('|');
   (groups[key]??=[]).push(p);
 });
 Object.values(groups).forEach(arr=>{
   if(arr.length<2)return;
   arr.sort((a,b)=>(rank[b.coverage]||0)-(rank[a.coverage]||0));
   arr.slice(1).forEach(p=>{
     p.superseded=true;
     p.hiddenFromRecommendations=true;
     p.canCalculateCompletion=false;
   });
 });

 // Never recommend already-earned degree paths when imported certificate marks degree as awarded.
 window.__studielotsLTURules=window.__studielotsLTURules||{};
 window.__studielotsLTURules.excludeAwardedDegreePath=true;
 window.__studielotsLTURules.excludeAwardedDegreeFromFastestPath=true;
 window.__studielotsLTURules.allowHigherLevelContinuation=true;
 window.__studielotsLTURules.preferDistanceAlternativeWhenFaster=true;
 window.__studielotsLTURules.requireRealCourseForAlternativeSuggestion=true;

 // QA summary for deterministic completion work.
 const active=ltu.filter(p=>!p.superseded);
 const complete=active.filter(p=>p.coverage==='complete');
 const gated=active.filter(p=>p.coverage!=='complete');
 const qaByCoverage=gated.reduce((o,p)=>{o[p.coverage||'unknown']=(o[p.coverage||'unknown']||0)+1;return o;},{});
 window.__studielotsUniversityCoverage=window.__studielotsUniversityCoverage||{};
 const cov=window.__studielotsUniversityCoverage[LTU]||{};
 window.__studielotsUniversityCoverage[LTU]={
   ...cov,version:'v424',
   activeProgramRecords:active.length,
   completeProgramRecords:complete.length,
   gatedProgramRecords:gated.length,
   qaByCoverage,
   duplicateSuppression:true,
   awardedDegreeExclusion:true,
   alternativeCourseRequiresRealCourse:true,
   currentStatus:gated.length===0?'complete':'in-progress'
 };
 window.__studielotsLTU={...(window.__studielotsLTU||{}),version:'v424',
   activeProgramRecords:active.length,completeProgramRecords:complete.length,
   qaRemaining:gated.length,qaByCoverage};
 console.info('Studielots v424: LTU QA hardening and completion readiness loaded',window.__studielotsLTU);
})();
;
