/* v429 — LTU v2 batch 25: QA prioritization + advanced-level routing */
(function(){
 const LTU='Luleå tekniska universitet';
 const active=()=> (programCatalog||[]).filter(p=>p&&p.university===LTU&&!p.superseded);

 // Advanced-level routing: bachelor's degree holders should surface magister/master paths,
 // while already-awarded degrees are excluded from "fastest degree" recommendations.
 window.__studielotsLTURules=window.__studielotsLTURules||{};
 Object.assign(window.__studielotsLTURules,{
   routeBachelorToAdvancedLevel:true,
   advancedLevelLabels:['Magister 60 hp','Master 120 hp'],
   excludeAwardedDegreePath:true,
   excludeAwardedDegreeFromFastestPath:true,
   allowSameSubjectAdvancedContinuation:true,
   preferCompleteAdvancedProgramme:true,
   doNotReuseAwardedDegreeCoursesUnlessUniversityAllows:true
 });

 // Give every incomplete LTU programme a deterministic QA priority.
 active().forEach(p=>{
   if(['complete','selector'].includes(p.coverage)) return;
   let score=0;
   if(p.advanced) score+=30;
   if(p.distance) score+=20;
   if(p.hp===60 || p.hp===120) score+=15;
   if(p.coverage==='structure') score+=12;
   if(p.coverage==='partial' || p.coverage==='rules') score+=10;
   if(p.coverage==='inventory') score+=5;
   if(p.professionalDegree) score-=5; // exact mapping is slower; still retained.
   p.qaPriority=score;
   p.qaReason=[
     p.advanced?'avancerad nivå':null,
     p.distance?'distans':null,
     (p.hp===60||p.hp===120)?'kort examensväg':null,
     p.professionalDegree?'yrkesexamen – kräver exakt kursmatchning':null
   ].filter(Boolean).join(', ');
 });

 // Build priority queue; this is internal and not shown as a fake user-facing result.
 const qa=active()
   .filter(p=>!['complete','selector'].includes(p.coverage))
   .sort((a,b)=>(b.qaPriority||0)-(a.qaPriority||0))
   .map(p=>({
      code:p.code||'',name:p.name||'',hp:p.hp||0,level:p.level||'',
      coverage:p.coverage||'unknown',priority:p.qaPriority||0,reason:p.qaReason||''
   }));

 // Harden recommendation eligibility.
 active().forEach(p=>{
   p.recommendationEligible = p.coverage==='complete' && !p.superseded;
   if(p.coverage!=='complete'){
     p.hiddenFromExactFastestPath=true;
     p.canCalculateCompletion=false;
   }
 });

 window.__studielotsUniversityCoverage=window.__studielotsUniversityCoverage||{};
 const cov=window.__studielotsUniversityCoverage[LTU]||{};
 const complete=active().filter(p=>p.coverage==='complete');
 window.__studielotsUniversityCoverage[LTU]={
   ...cov,version:'v429',
   qaQueue:qa,
   qaTop10:qa.slice(0,10),
   qaRemaining:qa.length,
   completeProgramRecords:complete.length,
   advancedRouting:true,
   exactFastestPathCompleteOnly:true,
   currentStatus:qa.length===0?'complete':'in-progress'
 };
 window.__studielotsLTU={...(window.__studielotsLTU||{}),version:'v429',
   qaRemaining:qa.length,qaTop10:qa.slice(0,10),advancedRouting:true};
 console.info('Studielots v429: LTU QA prioritization + advanced routing',window.__studielotsLTU);
})();
;
/* v430 — LTU v2 batch 26: advanced-program recommendation safety + shortlist */
(function(){
 const LTU='Luleå tekniska universitet';
 const active=()=> (programCatalog||[]).filter(p=>p&&p.university===LTU&&!p.superseded);

 // Mark advanced programmes with a recommendation tier.
 active().forEach(p=>{
   if(!p.advanced && !String(p.level||'').includes('Avancerad')) return;
   if(p.coverage==='complete'){
     p.advancedRecommendationTier='exact';
     p.recommendationEligible=true;
   } else if(['structure','partial','rules'].includes(p.coverage)){
     p.advancedRecommendationTier='preliminary';
     p.recommendationEligible=false;
     p.preliminaryEligibilityOnly=true;
     p.canCalculateCompletion=false;
   } else {
     p.advancedRecommendationTier='discovery';
     p.recommendationEligible=false;
     p.canCalculateCompletion=false;
   }
 });

 // Build an internal shortlist for users with an awarded bachelor degree.
 const advanced=active()
   .filter(p=>p.advanced || String(p.level||'').includes('Avancerad'))
   .sort((a,b)=>{
     const tier={exact:3,preliminary:2,discovery:1};
     const ta=tier[a.advancedRecommendationTier]||0;
     const tb=tier[b.advancedRecommendationTier]||0;
     if(tb!==ta) return tb-ta;
     if(!!b.distance!==!!a.distance) return (b.distance?1:0)-(a.distance?1:0);
     return (a.hp||999)-(b.hp||999);
   });

 window.__studielotsLTURules=window.__studielotsLTURules||{};
 Object.assign(window.__studielotsLTURules,{
   advancedShortlistEnabled:true,
   advancedShortlistExactFirst:true,
   preliminaryAdvancedMustSay:'Behörighet och tillgodoräknande behöver verifieras av universitetet.',
   neverShowPreliminaryAsExactHpRemaining:true,
   neverShowDiscoveryAsMatchedProgramme:true
 });

 // Explicitly protect Magister & master screen from showing 0 alternatives when relevant advanced inventory exists.
 window.__studielotsLTUAdvancedFallback={
   exact:advanced.filter(p=>p.advancedRecommendationTier==='exact').map(p=>p.id),
   preliminary:advanced.filter(p=>p.advancedRecommendationTier==='preliminary').map(p=>p.id),
   discovery:advanced.filter(p=>p.advancedRecommendationTier==='discovery').map(p=>p.id),
   rule:'Show exact first. If no exact match exists, show preliminary relevant alternatives with verification disclaimer. Never invent hp remaining.'
 };

 // Recompute QA summary.
 const qa=active().filter(p=>!['complete','selector'].includes(p.coverage));
 const qaByCoverage=qa.reduce((o,p)=>{o[p.coverage||'unknown']=(o[p.coverage||'unknown']||0)+1;return o;},{});
 const complete=active().filter(p=>p.coverage==='complete');

 window.__studielotsUniversityCoverage=window.__studielotsUniversityCoverage||{};
 const cov=window.__studielotsUniversityCoverage[LTU]||{};
 window.__studielotsUniversityCoverage[LTU]={
   ...cov,version:'v430',
   completeProgramRecords:complete.length,
   qaRemaining:qa.length,
   qaByCoverage,
   advancedExactCount:advanced.filter(p=>p.advancedRecommendationTier==='exact').length,
   advancedPreliminaryCount:advanced.filter(p=>p.advancedRecommendationTier==='preliminary').length,
   advancedDiscoveryCount:advanced.filter(p=>p.advancedRecommendationTier==='discovery').length,
   currentStatus:qa.length===0?'complete':'in-progress'
 };
 window.__studielotsLTU={...(window.__studielotsLTU||{}),version:'v430',
   qaRemaining:qa.length,
   advancedExactCount:advanced.filter(p=>p.advancedRecommendationTier==='exact').length,
   advancedPreliminaryCount:advanced.filter(p=>p.advancedRecommendationTier==='preliminary').length,
   advancedDiscoveryCount:advanced.filter(p=>p.advancedRecommendationTier==='discovery').length
 };
 console.info('Studielots v430: LTU advanced recommendation tiers + fallback shortlist loaded');
})();
;
/* v431 — LTU v2 batch 27: QA integrity audit + fastest-path consistency */
(function(){
 const LTU='Luleå tekniska universitet';
 const active=()=> (programCatalog||[]).filter(p=>p&&p.university===LTU&&!p.superseded);

 // One canonical eligibility rule shared by Home, Opportunities, Program and Fastest path.
 window.__studielotsLTURules=window.__studielotsLTURules||{};
 Object.assign(window.__studielotsLTURules,{
   canonicalExactEligibility:'coverage-complete',
   exactResultRequiresCompleteCoverage:true,
   homeUsesSameExactEligibility:true,
   opportunitiesUsesSameExactEligibility:true,
   programPageUsesSameExactEligibility:true,
   fastestPathUsesSameExactEligibility:true,
   advancedFallbackMayBePreliminary:true,
   preliminaryNeverCountsAsExact:true
 });

 // Normalize all active LTU programme records.
 active().forEach(p=>{
   const exact=p.coverage==='complete';
   p.exactMatchEligible=exact;
   p.exactRemainingHp=exact;
   p.exactCreditTransfer=exact;
   if(!exact){
     p.canCalculateCompletion=false;
     p.noFalse100=true;
     p.safeMode=true;
   }
   // Already awarded degree paths are never fastest-path candidates.
   p.excludeIfAwardedDegree=true;
 });

 // Audit common data integrity problems without pretending they are fixed.
 const issues=[];
 active().forEach(p=>{
   if(!p.id) issues.push({type:'missing-id',name:p.name||''});
   if(!p.name) issues.push({type:'missing-name',id:p.id||''});
   if(!p.hp) issues.push({type:'missing-hp',id:p.id||'',name:p.name||''});
   if(p.coverage==='complete' && (!Array.isArray(p.courses)||!p.courses.length))
     issues.push({type:'complete-without-courses',id:p.id||'',name:p.name||''});
   if(p.coverage==='complete'){
     const sum=(p.courses||[]).reduce((s,c)=>s+(Number(c.hp)||0),0);
     if(p.hp && Math.abs(sum-p.hp)>0.01)
       issues.push({type:'course-hp-sum-mismatch',id:p.id||'',name:p.name||'',programHp:p.hp,courseHp:sum});
   }
 });

 // Duplicate active IDs/codes are surfaced for later cleanup.
 const ids={};
 active().forEach(p=>{ if(p.id)(ids[p.id]??=[]).push(p); });
 Object.entries(ids).forEach(([id,arr])=>{
   if(arr.length>1) issues.push({type:'duplicate-id',id,count:arr.length});
 });

 const qa=active().filter(p=>!['complete','selector'].includes(p.coverage));
 const complete=active().filter(p=>p.coverage==='complete');
 const qaByCoverage=qa.reduce((o,p)=>{o[p.coverage||'unknown']=(o[p.coverage||'unknown']||0)+1;return o;},{});

 window.__studielotsUniversityCoverage=window.__studielotsUniversityCoverage||{};
 const cov=window.__studielotsUniversityCoverage[LTU]||{};
 window.__studielotsUniversityCoverage[LTU]={
   ...cov,
   version:'v431',
   activeProgramRecords:active().length,
   completeProgramRecords:complete.length,
   qaRemaining:qa.length,
   qaByCoverage,
   integrityIssues:issues,
   integrityIssueCount:issues.length,
   canonicalEligibilityAcrossViews:true,
   currentStatus:qa.length===0 && issues.length===0 ? 'complete' : 'in-progress'
 };
 window.__studielotsLTU={...(window.__studielotsLTU||{}),
   version:'v431',
   qaRemaining:qa.length,
   integrityIssueCount:issues.length,
   canonicalEligibilityAcrossViews:true
 };
 console.info('Studielots v431: LTU QA integrity audit + cross-view consistency',window.__studielotsLTU);
})();
;
/* v432 — LTU v2 batch 28: integrity auto-quarantine + QA cleanup */
(function(){
 const LTU='Luleå tekniska universitet';
 const active=()=> (programCatalog||[]).filter(p=>p&&p.university===LTU&&!p.superseded);

 // Auto-quarantine any "complete" record whose course sum does not match programme hp.
 active().forEach(p=>{
   if(p.coverage!=='complete') return;
   const courses=Array.isArray(p.courses)?p.courses:[];
   const sum=courses.reduce((s,c)=>s+(Number(c.hp)||0),0);
   const mismatch=p.hp && Math.abs(sum-p.hp)>0.01;
   if(!courses.length || mismatch){
     p.integrityQuarantined=true;
     p.previousCoverage='complete';
     p.coverage='partial';
     p.safeMode=true;
     p.noFalse100=true;
     p.canCalculateCompletion=false;
     p.exactRemainingHp=false;
     p.exactCreditTransfer=false;
     p.recommendationEligible=false;
     p.hiddenFromExactFastestPath=true;
     p.integrityReason=!courses.length
       ? 'Komplett program saknar kurslista.'
       : `Kurslistan summerar till ${sum} hp men programmet är ${p.hp} hp.`;
   }
 });

 // Quarantined records remain discoverable, but never exact.
 active().forEach(p=>{
   if(p.integrityQuarantined){
     p.uiNote=(p.uiNote? p.uiNote+' ' : '')+
       'Tillfälligt spärrad från exakt beräkning tills kurs-hp är avstämt.';
   }
 });

 // Shared exact-result helper for all LTU views.
 window.__studielotsLTUCanShowExact=function(program){
   return !!(
     program &&
     program.university===LTU &&
     !program.superseded &&
     !program.integrityQuarantined &&
     program.coverage==='complete' &&
     program.canCalculateCompletion!==false
   );
 };

 // Shared preliminary helper for advanced alternatives.
 window.__studielotsLTUCanShowPreliminary=function(program){
   return !!(
     program &&
     program.university===LTU &&
     !program.superseded &&
     !program.integrityQuarantined &&
     ['structure','partial','rules'].includes(program.coverage)
   );
 };

 // Ensure exact/100% display flags follow the canonical helper.
 active().forEach(p=>{
   const exact=window.__studielotsLTUCanShowExact(p);
   p.exactMatchEligible=exact;
   p.allow100Percent=exact;
   p.allowExactRemainingHp=exact;
   p.allowExactCreditTransfer=exact;
   if(!exact){
     p.noFalse100=true;
     p.canCalculateCompletion=false;
   }
 });

 // Rebuild integrity and QA summaries after quarantine.
 const records=active();
 const complete=records.filter(p=>window.__studielotsLTUCanShowExact(p));
 const qa=records.filter(p=>!['selector'].includes(p.coverage) && !window.__studielotsLTUCanShowExact(p));
 const quarantined=records.filter(p=>p.integrityQuarantined);

 const qaByCoverage=qa.reduce((o,p)=>{
   o[p.coverage||'unknown']=(o[p.coverage||'unknown']||0)+1;
   return o;
 },{});

 const quarantineIssues=quarantined.map(p=>({
   id:p.id||'',code:p.code||'',name:p.name||'',reason:p.integrityReason||''
 }));

 window.__studielotsUniversityCoverage=window.__studielotsUniversityCoverage||{};
 const cov=window.__studielotsUniversityCoverage[LTU]||{};
 window.__studielotsUniversityCoverage[LTU]={
   ...cov,
   version:'v432',
   activeProgramRecords:records.length,
   completeProgramRecords:complete.length,
   qaRemaining:qa.length,
   qaByCoverage,
   quarantinedProgramRecords:quarantined.length,
   quarantineIssues,
   canonicalExactHelper:true,
   autoQuarantine:true,
   currentStatus:qa.length===0 && quarantined.length===0 ? 'complete' : 'in-progress'
 };

 window.__studielotsLTU={
   ...(window.__studielotsLTU||{}),
   version:'v432',
   completeProgramRecords:complete.length,
   qaRemaining:qa.length,
   quarantinedProgramRecords:quarantined.length,
   canonicalExactHelper:true
 };

 console.info('Studielots v432: LTU integrity auto-quarantine + QA cleanup',window.__studielotsLTU);
})();
;
/* v433 — LTU v2 batch 29: repair obvious aggregate placeholders before integrity gate */
(function(){
 const LTU='Luleå tekniska universitet';
 const active=()=> (programCatalog||[]).filter(p=>p&&p.university===LTU&&!p.superseded);

 // Aggregate placeholder rows were useful during mapping, but must never masquerade as verified courses.
 active().forEach(p=>{
   if(!Array.isArray(p.courses)) return;
   p.courses.forEach(c=>{
     const n=String(c.name||'').toLowerCase();
     if(
       n.includes('övriga obligatoriska programkurser') ||
       n.includes('övriga obligatoriska') ||
       n.includes('profilens valbara kurser') ||
       n.includes('valfritt utrymme')
     ){
       c.aggregatePlaceholder=true;
       c.notARealCourse=true;
     }
   });
 });

 // Exact alternative-course suggestions may only use real named courses.
 window.__studielotsLTUAlternativeCourseEligible=function(course){
   return !!(
     course &&
     course.name &&
     Number(course.hp)>0 &&
     !course.aggregatePlaceholder &&
     !course.notARealCourse
   );
 };

 // A programme can only be "fully course mapped" if all rows are actual courses,
 // except explicit elective-space rows which are handled by degree rules rather than course equivalence.
 active().forEach(p=>{
   const cs=Array.isArray(p.courses)?p.courses:[];
   const fake=cs.filter(c=>c.notARealCourse);
   p.aggregatePlaceholderCount=fake.length;
   p.hasAggregatePlaceholders=fake.length>0;

   if(p.coverage==='complete' && fake.some(c=>!String(c.name||'').toLowerCase().includes('valfritt'))){
     p.integrityQuarantined=true;
     p.previousCoverage=p.previousCoverage||'complete';
     p.coverage='partial';
     p.safeMode=true;
     p.noFalse100=true;
     p.canCalculateCompletion=false;
     p.exactRemainingHp=false;
     p.exactCreditTransfer=false;
     p.allow100Percent=false;
     p.integrityReason='Programmet innehåller fortfarande aggregerade platshållare i stället för riktiga kursrader.';
   }
 });

 // Recalculate course totals using real course rows + explicit elective space.
 active().forEach(p=>{
   const cs=Array.isArray(p.courses)?p.courses:[];
   p.realMappedCourseHp=cs
     .filter(c=>!c.notARealCourse)
     .reduce((s,c)=>s+(Number(c.hp)||0),0);
   p.explicitElectiveSpaceHp=cs
     .filter(c=>c.aggregatePlaceholder && String(c.name||'').toLowerCase().includes('valfritt'))
     .reduce((s,c)=>s+(Number(c.hp)||0),0);
 });

 // QA prioritizes quarantined records that are closest to completion.
 const qa=active()
   .filter(p=>!['selector'].includes(p.coverage) && p.coverage!=='complete')
   .map(p=>({
     id:p.id||'',code:p.code||'',name:p.name||'',coverage:p.coverage||'unknown',
     mappedHp:p.realMappedCourseHp||0,totalHp:p.hp||0,
     missingHp:Math.max(0,(Number(p.hp)||0)-(Number(p.realMappedCourseHp)||0)-(Number(p.explicitElectiveSpaceHp)||0)),
     quarantined:!!p.integrityQuarantined
   }))
   .sort((a,b)=>{
     if(a.quarantined!==b.quarantined) return a.quarantined?-1:1;
     return a.missingHp-b.missingHp;
   });

 const exact=active().filter(p=>
   p.coverage==='complete' && !p.integrityQuarantined && p.canCalculateCompletion!==false
 );

 window.__studielotsUniversityCoverage=window.__studielotsUniversityCoverage||{};
 const cov=window.__studielotsUniversityCoverage[LTU]||{};
 window.__studielotsUniversityCoverage[LTU]={
   ...cov,
   version:'v433',
   completeProgramRecords:exact.length,
   qaRemaining:qa.length,
   qaQueue:qa,
   aggregatePlaceholderAudit:true,
   realCourseAlternativeRule:true,
   currentStatus:qa.length===0?'complete':'in-progress'
 };

 window.__studielotsLTU={...(window.__studielotsLTU||{}),
   version:'v433',
   completeProgramRecords:exact.length,
   qaRemaining:qa.length,
   aggregatePlaceholderAudit:true
 };

 console.info('Studielots v433: LTU aggregate placeholder audit + QA repair queue',window.__studielotsLTU);
})();
;
