/* v435 — LTU v2 batch 31: study-plan sequencing + faster-course suggestion guardrails */
(function(){
 const LTU='Luleå tekniska universitet';
 const active=()=> (programCatalog||[]).filter(p=>p&&p.university===LTU&&!p.superseded);

 // Central study-plan sequencing rules.
 window.__studielotsStudyPlanner=window.__studielotsStudyPlanner||{};
 Object.assign(window.__studielotsStudyPlanner,{
   version:'v435',
   chronologicalPlanning:true,
   sortByNextOffering:true,
   respectPrerequisites:true,
   respectStudyPeriod:true,
   preferEarlierCompletion:true,
   preferDistanceWhenEquivalentAndEarlier:true,
   neverReplaceRequiredCourseWithoutEquivalenceEvidence:true,
   universityConfirmationRequired:true
 });

 // Normalize scheduling metadata without inventing dates.
 active().forEach(p=>{
   if(!Array.isArray(p.courses)) return;
   p.courses.forEach((c,index)=>{
     c.planOrder = Number.isFinite(Number(c.planOrder)) ? Number(c.planOrder) : index+1;
     c.scheduleKnown = !!(c.nextOffering || c.term || c.studyPeriod || c.startDate);
     c.requiresScheduleVerification = !c.scheduleKnown;
   });
 });

 // Candidate alternative course helper:
 // only real, named courses may be proposed and only as preliminary unless equivalence is verified.
 window.__studielotsLTUCanSuggestAlternativeCourse=function(course){
   if(!course || !course.name || Number(course.hp)<=0) return false;
   if(course.aggregatePlaceholder || course.notARealCourse) return false;
   return true;
 };

 window.__studielotsLTUAlternativeCourseStatus=function(course){
   if(!window.__studielotsLTUCanSuggestAlternativeCourse(course)) return 'blocked';
   if(course.equivalenceVerified===true) return 'verified';
   return 'preliminary';
 };

 // Faster-path candidate model. This does not invent availability:
 // unknown schedules are explicitly flagged for verification.
 active().forEach(p=>{
   if(!Array.isArray(p.courses)) return;
   p.studyPlannerEnabled=true;
   p.studyPlannerCourses=p.courses
     .filter(c=>!c.aggregatePlaceholder && !c.notARealCourse)
     .map(c=>({
       name:c.name,
       hp:Number(c.hp)||0,
       subject:c.subject||'',
       planOrder:c.planOrder,
       nextOffering:c.nextOffering||null,
       term:c.term||null,
       studyPeriod:c.studyPeriod||null,
       startDate:c.startDate||null,
       scheduleKnown:!!c.scheduleKnown,
       distance:!!c.distance,
       prerequisite:c.prerequisite||null
     }));
 });

 // Shared rules for "Snabbare alternativ" UI.
 window.__studielotsLTUFastAlternativeRules={
   compareAgainstRequiredCourse:true,
   requireRealCourse:true,
   requireEquivalentContentOrRuleMatch:true,
   preferEarlierOffering:true,
   preferDistanceIfEarlier:true,
   unknownOfferingNeverClaimedFaster:true,
   preliminaryDisclaimer:'Tillgodoräknandet behöver bekräftas av universitetet.',
   scheduleDisclaimer:'Kontrollera aktuell kursstart och ansökningsperiod.'
 };

 // QA now tracks how much scheduling data is still missing.
 const records=active();
 const scheduleStats=records.reduce((o,p)=>{
   (p.studyPlannerCourses||[]).forEach(c=>{
     o.total++;
     if(c.scheduleKnown)o.known++;else o.unknown++;
   });
   return o;
 },{total:0,known:0,unknown:0});

 const qa=records.filter(p=>!['complete','selector'].includes(p.coverage));
 const exact=records.filter(p=>p.coverage==='complete'&&!p.integrityQuarantined&&p.canCalculateCompletion!==false);

 window.__studielotsUniversityCoverage=window.__studielotsUniversityCoverage||{};
 const cov=window.__studielotsUniversityCoverage[LTU]||{};
 window.__studielotsUniversityCoverage[LTU]={
   ...cov,
   version:'v435',
   completeProgramRecords:exact.length,
   qaRemaining:qa.length,
   studyPlannerSequencing:true,
   fasterAlternativeEngine:true,
   scheduleStats,
   currentStatus:qa.length===0?'complete':'in-progress'
 };

 window.__studielotsLTU={...(window.__studielotsLTU||{}),
   version:'v435',
   completeProgramRecords:exact.length,
   qaRemaining:qa.length,
   studyPlannerSequencing:true,
   fasterAlternativeEngine:true,
   scheduleStats
 };

 console.info('Studielots v435: LTU study-plan sequencing + faster-course guardrails',window.__studielotsLTU);
})();
;
