     id:program.id,
     name:program.name,
     university:program.university,
     hp:program.hp,
     level:program.level,
     subject:program.subject,
     track:program.track||null,
     distance:!!program.distance,
     applicationStatus:program.applicationStatus||null,
     result:r,
     canShowExact:program.coverage==='complete' &&
                  !program.integrityQuarantined &&
                  program.canCalculateCompletion!==false,
     disclaimer:program.coverage==='complete'
