/* v445 — LTU v2 batch 40: QA promotion safety + advanced-path catalogue hardening */
(function(){
 const LTU='Luleå tekniska universitet';
 const records=()=> (programCatalog||[]).filter(p=>p&&p.university===LTU&&!p.superseded);

 // A programme can only be promoted from QA when all exact-result requirements are met.
 window.__studielotsLTUCanPromoteToComplete=function(p){
   if(!p || p.university!==LTU || p.superseded) return false;
   if(p.integrityQuarantined) return false;
   if(!Array.isArray(p.courses) || !p.courses.length) return false;
   if(p.courses.some(c=>c.aggregatePlaceholder || c.notARealCourse)) return false;

   const total=Number(p.hp)||0;
   const courseHp=p.courses.reduce((s,c)=>s+(Number(c.hp)||0),0);
   if(total && Math.abs(courseHp-total)>0.01) return false;

   if(p.advanced){
     const thesis=p.courses.filter(c=>c.thesis).reduce((s,c)=>s+(Number(c.hp)||0),0);
     if((p.hp===120 || String(p.name||'').toLowerCase().includes('master')) && thesis<30) return false;
     if((p.hp===60 || String(p.name||'').toLowerCase().includes('magister')) && thesis<15) return false;
   }
   return true;
 };

 // Re-audit records previously labelled complete. This prevents later patches from bypassing QA.
 records().forEach(p=>{
   if(p.coverage!=='complete') return;
   if(!window.__studielotsLTUCanPromoteToComplete(p)){
     p.previousCoverage='complete';
     p.coverage='partial';
     p.integrityQuarantined=true;
     p.canCalculateCompletion=false;
     p.exactMatchEligible=false;
     p.allow100Percent=false;
     p.hiddenFromExactFastestPath=true;
     p.integrityReason=p.integrityReason||'Programmet klarade inte v445:s fullständighetskontroll.';
   }else{
     p.integrityQuarantined=false;
     p.canCalculateCompletion=true;
     p.exactMatchEligible=true;
     p.allow100Percent=true;
   }
 });

 // Advanced programmes get a canonical subject/degree lane for matching.
 records().forEach(p=>{
   const n=String(p.name||'').toLowerCase();
   if(p.advanced || String(p.level||'').toLowerCase().includes('avancerad')){
     p.advanced=true;
     p.fastestPathLane='advanced';
     p.requiresPriorDegree = p.requiresPriorDegree!==false;
     p.advancedDegreeType =
       n.includes('magister') ? 'magister' :
       n.includes('master') ? 'master' :
       n.includes('civilingenjör') ? 'civilingenjor' :
       (p.normalizedDegreeType||'advanced');
   }
 });

 // Build the actual remaining QA ledger after the stricter audit.
 const all=records();
 const remaining=all
   .filter(p=>!['complete','selector'].includes(p.coverage) || p.integrityQuarantined)
   .map(p=>({
     id:p.id||'', code:p.code||'', name:p.name||'',
     hp:Number(p.hp)||0, level:p.level||'',
     coverage:p.coverage||'unknown',
     advanced:!!p.advanced,
     professionalDegree:!!p.professionalDegree,
     integrityQuarantined:!!p.integrityQuarantined,
     mappedCourseHp:Array.isArray(p.courses)
       ? p.courses.filter(c=>!c.aggregatePlaceholder&&!c.notARealCourse)
           .reduce((s,c)=>s+(Number(c.hp)||0),0)
       : 0
   }))
   .sort((a,b)=>{
     if(a.integrityQuarantined!==b.integrityQuarantined) return a.integrityQuarantined?-1:1;
     if(a.advanced!==b.advanced) return a.advanced?-1:1;
     const am=Math.max(0,a.hp-a.mappedCourseHp);
     const bm=Math.max(0,b.hp-b.mappedCourseHp);
     if(am!==bm) return am-bm;
     return a.name.localeCompare(b.name,'sv');
   });

 const exact=all.filter(p=>p.coverage==='complete'&&!p.integrityQuarantined&&p.canCalculateCompletion!==false);

 window.__studielotsLTUCompletionGate={
   version:'v445',
   university:LTU,
   remaining,
   remainingCount:remaining.length,
   isComplete:remaining.length===0,
   strictPromotionAudit:true
 };

 window.__studielotsLTUNextQaBatch=remaining.slice(0,12);

 window.__studielotsUniversityCoverage=window.__studielotsUniversityCoverage||{};
 const cov=window.__studielotsUniversityCoverage[LTU]||{};
 window.__studielotsUniversityCoverage[LTU]={
   ...cov, version:'v445',
   activeProgramRecords:all.length,
   completeProgramRecords:exact.length,
   qaRemaining:remaining.length,
   qaLedger:remaining,
   nextQaBatch:remaining.slice(0,12),
   strictPromotionAudit:true,
   advancedCatalogueHardened:true,
   currentStatus:remaining.length===0?'complete':'in-progress'
 };

 window.__studielotsLTU={
   ...(window.__studielotsLTU||{}),
   version:'v445',
   completeProgramRecords:exact.length,
   qaRemaining:remaining.length,
   isComplete:remaining.length===0,
   nextQaBatch:remaining.slice(0,12)
 };

 console.info('Studielots v445: strict LTU QA promotion audit + advanced catalogue hardening',window.__studielotsLTU);
})();
;
