/* v448 — LTU v2 batch 43: QA self-test + exact-result contract */
(function(){
 const LTU='Luleå tekniska universitet';
 const all=()=> (programCatalog||[]).filter(p=>p&&p.university===LTU&&!p.superseded);

 function courseHp(p){
   return (Array.isArray(p.courses)?p.courses:[])
     .reduce((s,c)=>s+(Number(c.hp)||0),0);
 }

 const tests=[];
 function add(name,pass,detail){ tests.push({name,pass:!!pass,detail:detail||''}); }

 const records=all();
 records.forEach(p=>{
   if(p.coverage!=='complete') return;
   add(
     `hp-sum:${p.code||p.id}`,
     Math.abs(courseHp(p)-(Number(p.hp)||0))<0.01,
     `${courseHp(p)} / ${Number(p.hp)||0} hp`
   );
   add(
     `course-list:${p.code||p.id}`,
     Array.isArray(p.courses)&&p.courses.length>0,
     `${Array.isArray(p.courses)?p.courses.length:0} rows`
   );
   add(
     `no-placeholder:${p.code||p.id}`,
     !(p.courses||[]).some(c=>c.aggregatePlaceholder||c.notARealCourse),
     ''
   );
   if(p.advanced && (p.hp===120 || String(p.name||'').toLowerCase().includes('master'))){
     const th=(p.courses||[]).filter(c=>c.thesis).reduce((s,c)=>s+(Number(c.hp)||0),0);
     add(`master-thesis:${p.code||p.id}`,th>=30,`${th} hp`);
   }
   if(p.advanced && (p.hp===60 || String(p.name||'').toLowerCase().includes('magister'))){
     const th=(p.courses||[]).filter(c=>c.thesis).reduce((s,c)=>s+(Number(c.hp)||0),0);
     add(`magister-thesis:${p.code||p.id}`,th>=15,`${th} hp`);
   }
 });

 // Cross-view exact-result contract.
 window.__studielotsExactResultContract={
   version:'v448',
   fields:['programId','matchedHp','remainingHp','percent','exact'],
   exactRequires:[
     'coverage=complete',
     'not integrityQuarantined',
     'canCalculateCompletion!=false',
     'course hp equals programme hp'
   ],
   views:['home','opportunities','program','studyPlanner','fastestForYou']
 };

 // Any failed complete-program self-test blocks exact output.
 const failedCodes=new Set(
   tests.filter(t=>!t.pass).map(t=>{
     const m=t.name.match(/:(.+)$/); return m?m[1]:'';
   }).filter(Boolean)
 );
 records.forEach(p=>{
   const key=String(p.code||p.id||'');
   if(failedCodes.has(key)){
     p.selfTestFailed=true;
     p.integrityQuarantined=true;
     p.canCalculateCompletion=false;
     p.exactMatchEligible=false;
     p.allow100Percent=false;
     p.hiddenFromExactFastestPath=true;
   }
 });

 const remaining=records.filter(p=>
   !['complete','selector'].includes(p.coverage) ||
   p.integrityQuarantined ||
   p.selfTestFailed
 );
 const exact=records.filter(p=>
   p.coverage==='complete' &&
   !p.integrityQuarantined &&
   !p.selfTestFailed &&
   p.canCalculateCompletion!==false
 );

 window.__studielotsLTUSelfTest={
   version:'v448',
   total:tests.length,
   passed:tests.filter(t=>t.pass).length,
   failed:tests.filter(t=>!t.pass),
   allPassed:tests.every(t=>t.pass)
 };

 window.__studielotsUniversityCoverage=window.__studielotsUniversityCoverage||{};
 const cov=window.__studielotsUniversityCoverage[LTU]||{};
 window.__studielotsUniversityCoverage[LTU]={
   ...cov,
   version:'v448',
   completeProgramRecords:exact.length,
   qaRemaining:remaining.length,
   selfTest:window.__studielotsLTUSelfTest,
   exactResultContract:true,
   currentStatus:remaining.length===0 && tests.every(t=>t.pass)?'complete':'in-progress'
 };

 window.__studielotsLTU={
   ...(window.__studielotsLTU||{}),
   version:'v448',
   completeProgramRecords:exact.length,
   qaRemaining:remaining.length,
   selfTestFailed:tests.filter(t=>!t.pass).length,
   isComplete:remaining.length===0 && tests.every(t=>t.pass)
 };

 console.info('Studielots v448: LTU QA self-test + exact-result contract',window.__studielotsLTU);
})();
