/* v449 — LTU v2 batch 44: QA diagnostics + user-facing result safety */
(function(){
 const LTU='Luleå tekniska universitet';
 const records=(programCatalog||[]).filter(p=>p&&p.university===LTU&&!p.superseded);

 function realHp(p){
   return (Array.isArray(p.courses)?p.courses:[])
     .filter(c=>!c.aggregatePlaceholder&&!c.notARealCourse)
     .reduce((s,c)=>s+(Number(c.hp)||0),0);
 }

 // Diagnose remaining records so next mapping batches target actual data gaps.
 const diagnostics=records
   .filter(p=>!['complete','selector'].includes(p.coverage)||p.integrityQuarantined||p.selfTestFailed)
   .map(p=>{
     const mapped=realHp(p), total=Number(p.hp)||0;
     const issues=[];
     if(p.integrityQuarantined) issues.push('integrity');
     if(p.selfTestFailed) issues.push('self-test');
     if(!Array.isArray(p.courses)||!p.courses.length) issues.push('no-course-map');
     if(mapped<total) issues.push(`missing-${Math.max(0,total-mapped)}hp`);
     if((p.courses||[]).some(c=>c.aggregatePlaceholder||c.notARealCourse)) issues.push('placeholder');
     if(p.advanced){
       const thesis=(p.courses||[]).filter(c=>c.thesis).reduce((s,c)=>s+(Number(c.hp)||0),0);
       if((p.hp===120||String(p.name||'').toLowerCase().includes('master'))&&thesis<30) issues.push('master-thesis');
       if((p.hp===60||String(p.name||'').toLowerCase().includes('magister'))&&thesis<15) issues.push('magister-thesis');
     }
     return {
       id:p.id||'',code:p.code||'',name:p.name||'',coverage:p.coverage||'unknown',
       hp:total,mappedHp:mapped,missingHp:Math.max(0,total-mapped),
       advanced:!!p.advanced,distance:!!p.distance,issues
     };
   })
   .sort((a,b)=>{
     if(a.issues.includes('self-test')!==b.issues.includes('self-test')) return a.issues.includes('self-test')?-1:1;
     if(a.advanced!==b.advanced) return a.advanced?-1:1;
     if(a.distance!==b.distance) return a.distance?-1:1;
     if(a.missingHp!==b.missingHp) return a.missingHp-b.missingHp;
     return a.name.localeCompare(b.name,'sv');
   });

 window.__studielotsLTUQaDiagnostics={
   version:'v449',
   remainingCount:diagnostics.length,
   records:diagnostics,
   nextBatch:diagnostics.slice(0,10)
 };

 // Central UI safety status: exact / preliminary / discovery / blocked.
 window.__studielotsProgrammeResultStatus=function(p){
   if(!p) return 'blocked';
   if(p.integrityQuarantined||p.selfTestFailed) return 'blocked';
   if(p.coverage==='complete'&&p.canCalculateCompletion!==false) return 'exact';
   if(['partial','structure','rules'].includes(p.coverage)) return 'preliminary';
   if(p.coverage==='inventory') return 'discovery';
   return 'blocked';
 };

 window.__studielotsProgrammeDisclaimer=function(p){
   const s=window.__studielotsProgrammeResultStatus(p);
   if(s==='exact') return 'Tillgodoräknandet behöver bekräftas av universitetet.';
   if(s==='preliminary') return 'Möjlig examensväg – kursstruktur och tillgodoräknande behöver verifieras.';
   if(s==='discovery') return 'Utbildningen finns i katalogen men är ännu inte färdigkartlagd.';
   return 'Exakt beräkning är tillfälligt spärrad medan utbildningen kvalitetssäkras.';
 };

 // Never render numeric exact-looking values for non-exact records.
 window.__studielotsSafeDisplayResult=function(p,result){
   const status=window.__studielotsProgrammeResultStatus(p);
   if(status!=='exact'){
     return {
       status,
       matchedHp:null,
       remainingHp:null,
       percent:null,
       disclaimer:window.__studielotsProgrammeDisclaimer(p)
     };
   }
   return {
     status,
     matchedHp:Number(result?.matchedHp||0),
     remainingHp:Number(result?.remainingHp||0),
     percent:Number(result?.percent||0),
     disclaimer:window.__studielotsProgrammeDisclaimer(p)
   };
 };

 const exact=records.filter(p=>window.__studielotsProgrammeResultStatus(p)==='exact');

 window.__studielotsUniversityCoverage=window.__studielotsUniversityCoverage||{};
 const cov=window.__studielotsUniversityCoverage[LTU]||{};
 window.__studielotsUniversityCoverage[LTU]={
   ...cov,version:'v449',
   completeProgramRecords:exact.length,
   qaRemaining:diagnostics.length,
   qaDiagnostics:diagnostics,
   nextQaBatch:diagnostics.slice(0,10),
   safeUserFacingResults:true,
   currentStatus:diagnostics.length===0?'complete':'in-progress'
 };

 window.__studielotsLTU={...(window.__studielotsLTU||{}),
   version:'v449',
   completeProgramRecords:exact.length,
   qaRemaining:diagnostics.length,
   nextQaBatch:diagnostics.slice(0,10),
   safeUserFacingResults:true,
   isComplete:diagnostics.length===0
 };

 
})();
