/* v450 — LTU v2 batch 45: deterministic QA batching + incomplete-program isolation */
(function(){
 const LTU='Luleå tekniska universitet';
 const records=()=> (programCatalog||[]).filter(p=>p&&p.university===LTU&&!p.superseded);

 function mappedConcreteHp(p){
   return (Array.isArray(p.courses)?p.courses:[])
     .filter(c=>!c.aggregatePlaceholder&&!c.notARealCourse&&!c.isElectiveBlock)
     .reduce((s,c)=>s+(Number(c.hp)||0),0);
 }

 // Explicitly isolate incomplete programmes from every exact-result consumer.
 records().forEach(p=>{
   const exact = p.coverage==='complete' &&
                 !p.integrityQuarantined &&
                 !p.selfTestFailed &&
                 p.canCalculateCompletion!==false;

   p.ltuResultTier = exact ? 'exact' :
     ['partial','structure','rules'].includes(p.coverage) ? 'preliminary' :
     p.coverage==='inventory' ? 'discovery' : 'blocked';

   p.exactMatchEligible=exact;
   p.allowExactRemainingHp=exact;
   p.allowExactCreditTransfer=exact;
   p.allow100Percent=exact;
   p.hiddenFromExactFastestPath=!exact;

   if(!exact) p.canCalculateCompletion=false;
 });

 // Deterministic QA score: repair broken near-complete records first,
 // then advanced/distance, then smallest missing map.
 const qa=records()
   .filter(p=>p.ltuResultTier!=='exact' && p.coverage!=='selector')
   .map(p=>{
     const total=Number(p.hp)||0;
     const mapped=mappedConcreteHp(p);
     const missing=Math.max(0,total-mapped);
     let priority=0;
     if(p.integrityQuarantined||p.selfTestFailed) priority+=100;
     if(p.coverage==='partial') priority+=60;
     if(p.coverage==='structure') priority+=45;
     if(p.coverage==='rules') priority+=35;
     if(p.advanced) priority+=30;
     if(p.distance) priority+=15;
     if(total && missing<=30) priority+=20;
     else if(total && missing<=60) priority+=10;
     if(p.professionalDegree) priority-=10;
     return {
       id:p.id||'',code:p.code||'',name:p.name||'',
       hp:total,mappedConcreteHp:mapped,missingHp:missing,
       coverage:p.coverage||'unknown',tier:p.ltuResultTier,
       advanced:!!p.advanced,distance:!!p.distance,
       professionalDegree:!!p.professionalDegree,
       integrityQuarantined:!!p.integrityQuarantined,
       selfTestFailed:!!p.selfTestFailed,
       priority
     };
   })
   .sort((a,b)=>b.priority-a.priority || a.missingHp-b.missingHp || a.name.localeCompare(b.name,'sv'));

 window.__studielotsLTUQaQueue={
   version:'v450',
   count:qa.length,
   records:qa,
   currentBatch:qa.slice(0,8),
   nextBatch:qa.slice(8,16)
 };

 // One helper for all screens, preventing accidental use of preliminary numbers.
 window.__studielotsLTUResultForView=function(program,result){
   if(!program || program.university!==LTU) return result;
   if(program.ltuResultTier!=='exact'){
     return {
       programId:program.id,
       status:program.ltuResultTier,
       matchedHp:null,
       remainingHp:null,
       percent:null,
       exact:false,
       disclaimer:typeof window.__studielotsProgrammeDisclaimer==='function'
         ? window.__studielotsProgrammeDisclaimer(program)
         : 'Tillgodoräknandet behöver verifieras.'
     };
   }
   const hp=Number(program.hp)||0;
   const matched=Math.min(hp,Math.max(0,Number(result?.matchedHp)||0));
   return {
     ...(result||{}),
     programId:program.id,
     status:'exact',
     matchedHp:matched,
     remainingHp:Math.max(0,hp-matched),
     percent:hp?Math.round((matched/hp)*1000)/10:0,
     exact:true,
     disclaimer:'Tillgodoräknandet behöver bekräftas av universitetet.'
   };
 };

 const exact=records().filter(p=>p.ltuResultTier==='exact');

 window.__studielotsUniversityCoverage=window.__studielotsUniversityCoverage||{};
 const cov=window.__studielotsUniversityCoverage[LTU]||{};
 window.__studielotsUniversityCoverage[LTU]={
   ...cov,
   version:'v450',
   activeProgramRecords:records().length,
   completeProgramRecords:exact.length,
   qaRemaining:qa.length,
   qaQueue:qa,
   currentQaBatch:qa.slice(0,8),
   deterministicQaPriority:true,
   incompleteProgrammeIsolation:true,
   currentStatus:qa.length===0?'complete':'in-progress'
 };

 window.__studielotsLTU={
   ...(window.__studielotsLTU||{}),
   version:'v450',
   completeProgramRecords:exact.length,
   qaRemaining:qa.length,
   currentQaBatch:qa.slice(0,8),
   isComplete:qa.length===0
 };

 console.info('Studielots v450: deterministic LTU QA batching + incomplete-program isolation',window.__studielotsLTU);
})();
