/* v451 — LTU v2 batch 46: course-level replacement engine + distance-first acceleration */
(function(){
 const LTU='Luleå tekniska universitet';

 window.__studielotsCourseReplacementScore=function(required,candidate){
   if(!required||!candidate) return {eligible:false,score:0,reasons:['missing-course']};
   if(candidate.aggregatePlaceholder||candidate.notARealCourse||candidate.isElectiveBlock)
     return {eligible:false,score:0,reasons:['not-real-course']};

   const rh=Number(required.hp)||0, ch=Number(candidate.hp)||0;
   const rs=String(required.subject||'').toLowerCase().trim();
   const cs=String(candidate.subject||'').toLowerCase().trim();
   const reasons=[];
   let score=0;

   if(rh>0 && ch>=rh){ score+=30; reasons.push('hp'); }
   else return {eligible:false,score:0,reasons:['insufficient-hp']};

   if(rs && cs && (rs===cs || rs.includes(cs) || cs.includes(rs))){
     score+=30; reasons.push('subject');
   }

   if(candidate.equivalenceVerified===true){
     score+=40; reasons.push('verified-equivalence');
   }else if(candidate.ruleMatch===true || candidate.contentMatch===true){
     score+=20; reasons.push('preliminary-content-match');
   }

   if(candidate.distance===true){ score+=10; reasons.push('distance'); }
   if(candidate.offeredEarlier===true){ score+=20; reasons.push('earlier'); }

   // A same-subject/hp match alone is not enough to claim replacement.
   const evidence = candidate.equivalenceVerified===true ||
                    candidate.ruleMatch===true ||
                    candidate.contentMatch===true;

   return {
     eligible: evidence && ch>=rh,
     score,
     verified:candidate.equivalenceVerified===true,
     reasons
   };
 };

 window.__studielotsRankCourseReplacements=function(required,candidates){
   return (candidates||[])
     .map(c=>({course:c,...window.__studielotsCourseReplacementScore(required,c)}))
     .filter(x=>x.eligible)
     .sort((a,b)=>{
       if(a.verified!==b.verified) return a.verified?-1:1;
       if(a.course.offeredEarlier!==b.course.offeredEarlier) return a.course.offeredEarlier?-1:1;
       if(a.course.distance!==b.course.distance) return a.course.distance?-1:1;
       return b.score-a.score;
     });
 };

 // Planner may recommend a faster course only when timing evidence exists.
 window.__studielotsBuildAccelerationSuggestion=function(required,candidate){
   const match=window.__studielotsCourseReplacementScore(required,candidate);
   if(!match.eligible) return null;

   const timingKnown=!!(
     candidate.startDate || candidate.nextOffering ||
     candidate.term || candidate.studyPeriod
   );
   if(!timingKnown || candidate.offeredEarlier!==true) return null;

   return {
     requiredCourse:required.name,
     alternativeCourse:candidate.name,
     hp:Number(candidate.hp)||0,
     distance:!!candidate.distance,
     verified:!!match.verified,
     status:match.verified?'verified':'preliminary',
     reason:candidate.distance
       ? 'Kan ge en snabbare väg och läsas på distans.'
       : 'Kan ge en snabbare väg.',
     disclaimer:match.verified
       ? 'Kontrollera aktuell kursstart och ansökningsperiod.'
       : 'Tillgodoräknandet behöver bekräftas av universitetet.'
   };
 };

 // LTU catalogue-wide guardrails for alternative courses.
 (programCatalog||[])
   .filter(p=>p&&p.university===LTU&&!p.superseded)
   .forEach(p=>{
     (p.alternativeCourses||[]).forEach(c=>{
       c.replacementCandidate=true;
       c.replacementVerified=c.equivalenceVerified===true;
       c.requiresUniversityConfirmation=c.equivalenceVerified!==true;
       if(!c.startDate&&!c.nextOffering&&!c.term&&!c.studyPeriod){
         c.scheduleKnown=false;
         c.mayClaimFaster=false;
       }
     });
   });

 window.__studielotsLTURules=window.__studielotsLTURules||{};
 Object.assign(window.__studielotsLTURules,{
   courseReplacementEngine:true,
   distanceFirstAcceleration:true,
   sameSubjectAloneNeverEnoughForReplacement:true,
   unknownScheduleNeverClaimsFaster:true,
   unverifiedReplacementNeedsUniversityConfirmation:true
 });

 const records=(programCatalog||[]).filter(p=>p&&p.university===LTU&&!p.superseded);
 const qa=records.filter(p=>p.coverage!=='selector' && (
   p.coverage!=='complete'||p.integrityQuarantined||p.selfTestFailed
 ));
 const exact=records.filter(p=>
   p.coverage==='complete'&&!p.integrityQuarantined&&!p.selfTestFailed&&
   p.canCalculateCompletion!==false
 );

 window.__studielotsUniversityCoverage=window.__studielotsUniversityCoverage||{};
 const cov=window.__studielotsUniversityCoverage[LTU]||{};
 window.__studielotsUniversityCoverage[LTU]={
   ...cov,version:'v451',
   completeProgramRecords:exact.length,
   qaRemaining:qa.length,
   courseReplacementEngine:true,
   distanceFirstAcceleration:true,
   currentStatus:qa.length===0?'complete':'in-progress'
 };

 window.__studielotsLTU={...(window.__studielotsLTU||{}),
   version:'v451',completeProgramRecords:exact.length,qaRemaining:qa.length,
   courseReplacementEngine:true,isComplete:qa.length===0
 };

 console.info('Studielots v451: LTU course replacement + distance-first acceleration loaded');
})();
