/* v452 — LTU v2 batch 47: prevent stale duplicate programme records */
(function(){
 const LTU='Luleå tekniska universitet';
 const rows=(programCatalog||[]).filter(p=>p&&p.university===LTU&&!p.superseded);

 function key(p){
   const code=String(p.code||p.officialCode||'').trim().toUpperCase();
   if(code) return 'code:'+code;
   return 'name:'+String(p.name||'').toLowerCase().replace(/\s+/g,' ').trim();
 }
 function quality(p){
   let q=0;
   if(p.coverage==='complete') q+=100;
   else if(p.coverage==='partial') q+=60;
   else if(p.coverage==='structure') q+=40;
   else if(p.coverage==='rules') q+=30;
   else if(p.coverage==='inventory') q+=10;
   if(p.verified) q+=20;
   if(p.canCalculateCompletion!==false) q+=10;
   if(p.integrityQuarantined) q-=100;
   if(p.selfTestFailed) q-=100;
   q+=(Array.isArray(p.courses)?p.courses.length:0);
   return q;
 }

 const groups=new Map();
 rows.forEach(p=>{
   const k=key(p);
   if(!groups.has(k)) groups.set(k,[]);
   groups.get(k).push(p);
 });

 const duplicateAudit=[];
 groups.forEach((items,k)=>{
   if(items.length<2) return;
   const ranked=[...items].sort((a,b)=>quality(b)-quality(a));
   const winner=ranked[0];
   ranked.slice(1).forEach(p=>{
     p.superseded=true;
     p.supersededBy=winner.id||winner.code||winner.name;
     p.canCalculateCompletion=false;
     p.exactMatchEligible=false;
     p.allow100Percent=false;
     p.hiddenFromExactFastestPath=true;
   });
   duplicateAudit.push({
     key:k,
     kept:winner.id||winner.code||winner.name,
     removed:ranked.slice(1).map(p=>p.id||p.code||p.name)
   });
 });

 // Rebuild LTU status from de-duplicated active records only.
 const active=(programCatalog||[]).filter(p=>p&&p.university===LTU&&!p.superseded);
 const exact=active.filter(p=>
   p.coverage==='complete' &&
   !p.integrityQuarantined &&
   !p.selfTestFailed &&
   p.canCalculateCompletion!==false
 );
 const qa=active.filter(p=>
   p.coverage!=='selector' &&
   (p.coverage!=='complete'||p.integrityQuarantined||p.selfTestFailed||p.canCalculateCompletion===false)
 );

 window.__studielotsLTUDuplicateAudit={
   version:'v452',
   duplicateGroups:duplicateAudit.length,
   groups:duplicateAudit,
   activeRecords:active.length
 };

 // All programme discovery should prefer the active catalogue.
 window.__studielotsActiveProgramCatalog=function(){
   return (programCatalog||[]).filter(p=>p&&!p.superseded);
 };

 window.__studielotsFindProgram=function(idOrCode){
   const s=String(idOrCode||'');
   return window.__studielotsActiveProgramCatalog().find(p=>
     String(p.id||'')===s || String(p.code||'')===s || String(p.officialCode||'')===s
   )||null;
 };

 window.__studielotsLTURules=window.__studielotsLTURules||{};
 Object.assign(window.__studielotsLTURules,{
   duplicateProgrammeIsolation:true,
   activeCatalogueOnly:true,
   staleProgrammeRecordsCannotMatch:true
 });

 window.__studielotsUniversityCoverage=window.__studielotsUniversityCoverage||{};
 const cov=window.__studielotsUniversityCoverage[LTU]||{};
 window.__studielotsUniversityCoverage[LTU]={
   ...cov,
   version:'v452',
   activeProgramRecords:active.length,
   completeProgramRecords:exact.length,
   qaRemaining:qa.length,
   duplicateAudit:window.__studielotsLTUDuplicateAudit,
   duplicateProgrammeIsolation:true,
   currentStatus:qa.length===0?'complete':'in-progress'
 };

 window.__studielotsLTU={
   ...(window.__studielotsLTU||{}),
   version:'v452',
   activeProgramRecords:active.length,
   completeProgramRecords:exact.length,
   qaRemaining:qa.length,
   duplicateGroupsRemoved:duplicateAudit.length,
   isComplete:qa.length===0
 };

 console.info('Studielots v452: LTU stale duplicate programme records isolated',window.__studielotsLTU);
})();
