/* v477 — LTU: split degree-map QA from special-program QA; preserve strict exact-match gate */
(function(){
 const LTU='Luleå tekniska universitet';
 const active=(programCatalog||[]).filter(p=>p&&p.university===LTU&&!p.superseded);
 const byCode=c=>active.filter(p=>String(p.code||p.officialCode||'').toUpperCase()===c);

 // These are legitimate programmes, but they require programme-specific admission/
 // professional-degree logic rather than ordinary "reuse courses toward a general degree".
 ['LYKUG','LYKPG','LYSKG','TCÖPA'].forEach(code=>byCode(code).forEach(p=>{
   p.coverage='special-program';
   p.specialProgramme=true;
   p.requiresProgrammeSpecificLogic=true;
   p.excludeFromGeneralDegreeQA=true;
   p.excludeFromGeneralDegreeMatching=true;
   p.canCalculateCompletion=false;
   p.exactMatchEligible=false;
   p.allow100Percent=false;
   p.hiddenFromExactFastestPath=true;
   p.qaReason='Hanteras i separat programspecifik motor, inte som generell examensmatchning.';
 }));

 // Preparatory/admission-only records are catalogue-complete once correctly classified.
 active.filter(p=>p.preparatoryProgramme||p.admissionRoute||p.excludeFromDegreeMatching).forEach(p=>{
   if(p.coverage!=='complete' && !p.specialProgramme) p.coverage='selector';
   p.excludeFromGeneralDegreeQA=true;
 });

 const isExact=p=>p.coverage==='complete'&&!p.integrityQuarantined&&!p.selfTestFailed&&p.canCalculateCompletion!==false;
 const generalQA=active.filter(p=>
   p.coverage!=='selector' &&
   p.coverage!=='special-program' &&
   !p.excludeFromGeneralDegreeQA &&
   !isExact(p)
 );
 const specialQA=active.filter(p=>p.coverage==='special-program');
 const exact=active.filter(isExact);

 window.__studielotsLTUGeneralDegreeQAQueue=generalQA.map(p=>({
   code:String(p.code||p.officialCode||''),
   name:String(p.name||''),
   coverage:p.coverage||'unknown',
   reason:p.qaReason||p.courseRowsNeedSourceExtraction&&'Kursrader behöver källextraheras'||'Ej komplett verifierad'
 }));
 window.__studielotsLTUSpecialProgrammeQueue=specialQA.map(p=>({
   code:String(p.code||p.officialCode||''),
   name:String(p.name||''),
   reason:p.qaReason
 }));

 window.__studielotsUniversityCoverage=window.__studielotsUniversityCoverage||{};
 const old=window.__studielotsUniversityCoverage[LTU]||{};
 window.__studielotsUniversityCoverage[LTU]={
   ...old,version:'v477',
   completeProgramRecords:exact.length,
   qaRemaining:generalQA.length,
   generalDegreeQA:window.__studielotsLTUGeneralDegreeQAQueue,
   specialProgrammeRemaining:specialQA.length,
   specialProgrammeQueue:window.__studielotsLTUSpecialProgrammeQueue,
   currentStatus:generalQA.length===0?'general-degree-complete':'in-progress'
 };
 window.__studielotsLTU={...(window.__studielotsLTU||{}),
   version:'v477',
   completeProgramRecords:exact.length,
   qaRemaining:generalQA.length,
   qaQueue:window.__studielotsLTUGeneralDegreeQAQueue,
   specialProgrammeRemaining:specialQA.length,
   isComplete:generalQA.length===0 && specialQA.length===0
 };
 console.info('Studielots v477 LTU split QA',window.__studielotsLTU);
})();
;
