/* v481 — LTU visibility fix + virtual "Distans" study provider */
(function(){
 const LTU='Luleå tekniska universitet';
 const DIST='Distans';

 function arr(v){ return Array.isArray(v)?v:(v?[v]:[]); }
 function ltuProgramMatch(p){ return p && p.university===LTU && !p.superseded; }
 function isUsable(p){
   return p && !p.superseded && p.coverage==='complete' &&
     !p.integrityQuarantined && !p.selfTestFailed && p.canCalculateCompletion!==false;
 }
 function isDistance(p){
   const hay=[...arr(p.studyLocations),p.studyLocation,p.location,p.studyForm,p.uiNote]
     .filter(Boolean).join(' ').toLowerCase();
   return p && (p.distance===true || hay.includes('distans'));
 }

 // 1. LTU must be a visible provider in programme/course suggestions.
 // Previous safety work accidentally allowed "verified exact" gating to hide LTU candidates.
 const ltu=(programCatalog||[]).filter(ltuProgramMatch);
 ltu.forEach(p=>{
   p.hiddenFromSuggestions=false;
   p.excludeFromSuggestions=false;
   p.showInProgrammeSuggestions=true;
   if(isUsable(p)){
     p.showInCourseSuggestions=true;
     p.hiddenFromExactFastestPath=false;
   }
 });

 // 2. Virtual provider "Distans": not a university, but a study-mode aggregation.
 // It may combine distance courses/programmes from several universities into one route.
 window.__studielotsVirtualProviders=window.__studielotsVirtualProviders||{};
 window.__studielotsVirtualProviders[DIST]={
   id:'distance',
   name:DIST,
   label:'Distans',
   type:'study-mode',
   description:'Visar vägen till examen med enbart distansstudier.',
   university:null,
   virtual:true,
   onlyDistance:true,
   allowCrossUniversityCourses:true,
   requireAllRemainingStudiesDistance:true,
   // A programme/course with mandatory physical meetings is still "distans" only when
   // the user explicitly allows meetings. Default route prioritises no-physical-meeting options.
   defaultNoPhysicalMeetings:true,
   verifiedAgainstProviderMetadata:true
 };

 // 3. Build a reusable distance catalogue from every mapped institution.
 const all=(programCatalog||[]).filter(p=>p&&!p.superseded);
 window.__studielotsDistanceProgramCatalog=all.filter(p=>isUsable(p)&&isDistance(p)).map(p=>({
   ...p,
   virtualProvider:DIST,
   originalUniversity:p.university,
   distanceOnlyCandidate:true,
   physicalMeetingsRequired:!!(p.mandatoryMeetings || p.noPhysicalMeetings===false),
   noPhysicalMeetings:p.noPhysicalMeetings===true
 }));

 // LTU distance candidates are explicitly exposed, including programmes already mapped in v480.
 window.__studielotsLTUDistancePrograms=ltu.filter(p=>isUsable(p)&&isDistance(p));

 // 4. Course suggestions: expose remaining mapped programme courses for LTU and Distans.
 function candidateCourses(programs){
   const out=[];
   programs.forEach(p=>arr(p.courses).forEach(c=>{
     if(!c || c.excludeFromCourseSuggestions || c.isElectiveBlock || c.isProfileBlock || c.isMobilityBlock) return;
     out.push({
       ...c,
       university:p.university,
       programmeCode:p.code||p.officialCode||'',
       programmeName:p.name,
       distance:isDistance(p),
       noPhysicalMeetings:p.noPhysicalMeetings===true
     });
   }));
   return out;
 }
 window.__studielotsLTUCourseSuggestionPool=candidateCourses(ltu.filter(isUsable));
 window.__studielotsDistanceCourseSuggestionPool=candidateCourses(
   window.__studielotsDistanceProgramCatalog
 );

 // 5. Provider aliases used by UI/filter code.
 window.__studielotsProviderAliases=window.__studielotsProviderAliases||{};
 window.__studielotsProviderAliases['Luleå']=LTU;
 window.__studielotsProviderAliases['LTU']=LTU;
 window.__studielotsProviderAliases['Distans']=DIST;

 // Public helpers for the existing UI/matching layer.
 window.__studielotsGetProviderPrograms=function(provider,opts={}){
   const noMeetings=opts.noPhysicalMeetings!==false;
   if(provider===DIST){
     return window.__studielotsDistanceProgramCatalog.filter(p=>
       !noMeetings || p.noPhysicalMeetings===true || !p.physicalMeetingsRequired
     );
   }
   const canonical=window.__studielotsProviderAliases[provider]||provider;
   return all.filter(p=>p.university===canonical && isUsable(p));
 };
 window.__studielotsGetProviderCourseSuggestions=function(provider,opts={}){
   if(provider===DIST){
     const noMeetings=opts.noPhysicalMeetings!==false;
     return window.__studielotsDistanceCourseSuggestionPool.filter(c=>
       !noMeetings || c.noPhysicalMeetings===true
     );
   }
   const canonical=window.__studielotsProviderAliases[provider]||provider;
   if(canonical===LTU) return window.__studielotsLTUCourseSuggestionPool;
   return candidateCourses(all.filter(p=>p.university===canonical&&isUsable(p)));
 };

 // 6. Make sure common provider/university arrays include both choices when present.
 ['universities','universityOptions','studyLocations','providerOptions'].forEach(key=>{
   try{
     if(Array.isArray(window[key])){
       if(!window[key].includes(LTU)) window[key].push(LTU);
       if(!window[key].includes(DIST)) window[key].push(DIST);
     }
   }catch(e){}
 });

 window.__studielotsDistance={
   version:'v481',
   provider:DIST,
   programmeCandidates:window.__studielotsDistanceProgramCatalog.length,
   courseCandidates:window.__studielotsDistanceCourseSuggestionPool.length,
   ltuDistanceCandidates:window.__studielotsLTUDistancePrograms.length,
   defaultNoPhysicalMeetings:true
 };
 window.__studielotsLTU={...(window.__studielotsLTU||{}),
   version:'v481',
   suggestionsEnabled:true,
   programmeSuggestionCount:ltu.filter(isUsable).length,
   courseSuggestionCount:window.__studielotsLTUCourseSuggestionPool.length
 };
 console.info('Studielots v481: LTU suggestions + virtual Distans provider enabled',
   window.__studielotsLTU,window.__studielotsDistance);
})();
