/* v485 — Motor 2.0 QA: canonical scoring, anti-double-counting, cross-view consistency */
(function(){
  const arr=v=>Array.isArray(v)?v:(v?[v]:[]);
  const norm=s=>String(s||'').toLowerCase().replace(/\s+/g,' ').trim();

  // Canonical course-match score used by Möjligheter, Program and Distans.
  window.__studielotsScoreCourseMatch=function(required,candidate,ctx={}){
    if(!required||!candidate) return {eligible:false,score:0,reasons:['missing']};

    let score=0;
    const reasons=[];
    const reqHp=Number(required.hp)||0;
    const candHp=Number(candidate.hp)||0;

    if(candHp>=reqHp && reqHp>0){ score+=20; reasons.push('hp'); }
    else if(reqHp>0) return {eligible:false,score:0,reasons:['hp-too-low']};

    const rs=norm(required.subject||ctx.subject);
    const cs=norm(candidate.subject);
    if(rs&&cs&&(rs===cs||rs.includes(cs)||cs.includes(rs))){
      score+=25; reasons.push('subject');
    }

    const rl=norm(required.level||ctx.level);
    const cl=norm(candidate.level);
    if(rl&&cl&&rl===cl){ score+=15; reasons.push('level'); }
    else if(!rl||!cl){ score+=5; reasons.push('level-unknown'); }

    if(candidate.equivalenceVerified===true){
      score+=30; reasons.push('verified-equivalence');
    }else if(candidate.contentMatch===true || candidate.ruleMatch===true){
      score+=15; reasons.push('content/rule-match');
    }

    if(candidate.prerequisitesSatisfied===true){
      score+=10; reasons.push('prerequisites');
    }else if(candidate.prerequisitesSatisfied===false){
      return {eligible:false,score:0,reasons:['prerequisites-fail']};
    }

    if(candidate.offeredEarlier===true){ score+=10; reasons.push('earlier'); }
    if(candidate.distance===true){ score+=5; reasons.push('distance'); }

    const eligible =
      score>=45 &&
      (candidate.equivalenceVerified===true ||
       candidate.contentMatch===true ||
       candidate.ruleMatch===true);

    const status =
      candidate.equivalenceVerified===true ? 'verified' :
      score>=70 ? 'strong' :
      eligible ? 'possible' : 'weak';

    return {eligible,score,status,reasons};
  };

  // Prevent re-use of the same prior merit and the same replacement course in one plan.
  window.__studielotsAllocateCoursesOnce=function(requirements,candidates){
    const usedPrior=new Set();
    const usedAlternatives=new Set();

    return arr(requirements).map(req=>{
      const ranked=arr(candidates).map(c=>{
        const m=window.__studielotsScoreCourseMatch(req,c);
        return {course:c,...m};
      }).filter(x=>x.eligible)
        .sort((a,b)=>b.score-a.score);

      const pick=ranked.find(x=>{
        const cid=String(x.course.code||x.course.id||x.course.name||'');
        const priorId=String(x.course.sourceMeritId||'');
        return !usedAlternatives.has(cid) && (!priorId || !usedPrior.has(priorId));
      });

      if(!pick) return {required:req,alternative:null};

      const cid=String(pick.course.code||pick.course.id||pick.course.name||'');
      const priorId=String(pick.course.sourceMeritId||'');
      usedAlternatives.add(cid);
      if(priorId) usedPrior.add(priorId);

      return {required:req,alternative:pick.course,match:pick};
    });
  };

  // Thesis and main-field safeguards.
  window.__studielotsDegreeSafeguards={
    version:'v485',
    thesisCanOnlyCountOnce:true,
    awardedDegreeCoursesCannotBeReusedByDefault:true,
    advancedCoursesDoNotFillBasicDegreeByDefault:true,
    mainFieldMustBeSatisfied:true,
    samePriorCourseCannotFillTwoRequirements:true
  };

  window.__studielotsCanReuseMerit=function(merit,ctx={}){
    if(!merit) return false;
    if(merit.usedInAwardedDegree===true && ctx.allowAwardedDegreeReuse!==true) return false;
    if(merit.thesis===true && ctx.thesisAlreadyUsed===true) return false;
    if(ctx.targetLevel==='basic' && norm(merit.level).includes('avancerad')) return false;
    return true;
  };

  // Canonical result object shared across views.
  window.__studielotsBuildCanonicalDegreeResult=function(program,matchedCourses){
    const total=Number(program?.hp)||0;
    const seen=new Set();
    let matched=0;

    arr(matchedCourses).forEach(x=>{
      const c=x.course||x;
      const id=String(c.sourceMeritId||c.code||c.id||c.name||'');
      if(!id || seen.has(id)) return;
      seen.add(id);
      matched+=Number(c.hp)||0;
    });

    matched=Math.min(total,Math.max(0,matched));
    return {
      programId:program?.id||program?.code||'',
      matchedHp:matched,
      remainingHp:Math.max(0,total-matched),
      percent:total?Math.round((matched/total)*1000)/10:0,
      exact:true,
      sourceCourseCount:seen.size
    };
  };

  // Distans route validator: every remaining course must be remote and feasible.
  window.__studielotsValidateDistancePlan=function(plan){
    const remaining=arr(plan?.remainingCourses);
    const invalid=remaining.filter(c=>
      c.distance!==true ||
      c.mandatoryMeetings===true ||
      c.prerequisitesSatisfied===false
    );
    return {
      valid:invalid.length===0,
      invalid,
      rule:'All remaining studies must be distance and prerequisite-feasible.'
    };
  };

  // Wire Motor 2.0 into existing alternative planning if present.
  const oldBuilder=window.__studielotsBuildCoursePlanWithAlternatives;
  window.__studielotsBuildCoursePlanWithAlternatives=function(required,candidates){
    const result=window.__studielotsAllocateCoursesOnce(required,candidates);
    return result.length?result:(typeof oldBuilder==='function'?oldBuilder(required,candidates):[]);
  };

  window.__studielotsMotor2QA={
    version:'v485',
    canonicalScoring:true,
    antiDoubleCounting:true,
    thesisSafeguard:true,
    mainFieldSafeguard:true,
    crossViewCanonicalResult:true,
    distancePlanValidation:true,
    statuses:['verified','strong','possible']
  };

  console.info('Studielots v485: Motor 2.0 QA enabled',window.__studielotsMotor2QA);
})();
;
