/* v488 — preserve cross-university distance acceleration inside a selected programme */
(function(){
  const arr=v=>Array.isArray(v)?v:(v?[v]:[]);
  const norm=s=>String(s||'').toLowerCase().replace(/\s+/g,' ').trim();

  // Build replacement candidates from:
  // 1) programme's own alternatives
  // 2) same-university alternatives
  // 3) verified distance courses from ANY university
  window.__studielotsBuildCrossProviderReplacementPool=function(programme){
    if(!programme) return [];
    const own=arr(programme.alternativeCourses);
    const mappedDistance=arr(window.__studielotsDistanceCourseSuggestionPool);
    const verifiedDistance=arr(window.__studielotsVerifiedDistanceCourses);

    const sameUniversity=[];
    arr(window.programCatalog).filter(p=>
      p && !p.superseded &&
      p.university===programme.university &&
      p.coverage==='complete' &&
      p.canCalculateCompletion!==false
    ).forEach(p=>{
      arr(p.courses).forEach(c=>{
        if(!c || c.excludeFromCourseSuggestions || c.isElectiveBlock || c.isProfileBlock || c.isMobilityBlock) return;
        sameUniversity.push({...c,university:p.university,programmeName:p.name});
      });
    });

    const pool=[...own,...sameUniversity,...mappedDistance,...verifiedDistance];
    const seen=new Set();
    return pool.filter(c=>{
      const id=String(c.code||c.id||c.name||'')+'|'+String(c.university||'');
      if(!id || seen.has(id)) return false;
      seen.add(id);
      return true;
    });
  };

  // Cross-provider acceleration is allowed only when it is genuinely faster
  // and passes Motor 2.0 matching guardrails.
  window.__studielotsFindFasterDistanceAlternative=function(required,programme,ctx={}){
    const pool=window.__studielotsBuildCrossProviderReplacementPool(programme);
    const ranked=pool.map(c=>{
      const match=typeof window.__studielotsScoreCourseMatch==='function'
        ? window.__studielotsScoreCourseMatch(required,c,{subject:required.subject,level:required.level})
        : {eligible:false,score:0,status:'weak',reasons:[]};

      const remote=c.distance===true && c.mandatoryMeetings!==true && c.noPhysicalMeetings!==false;
      const timingKnown=!!(c.startDate||c.nextOffering||c.term||c.studyPeriod);
      const faster=c.offeredEarlier===true || c.faster===true;

      return {course:c,...match,remote,timingKnown,faster};
    }).filter(x=>
      x.eligible &&
      x.remote &&
      x.timingKnown &&
      x.faster
    ).sort((a,b)=>{
      if(a.status!==b.status){
        const rank={verified:3,strong:2,possible:1,weak:0};
        return (rank[b.status]||0)-(rank[a.status]||0);
      }
      return b.score-a.score;
    });

    return ranked[0]||null;
  };

  // Unified plan builder for Program and Möjligheter.
  window.__studielotsBuildProgrammePlanWithAcceleration=function(programme,requiredCourses){
    const used=new Set();

    return arr(requiredCourses).map(required=>{
      const fast=window.__studielotsFindFasterDistanceAlternative(required,programme);

      if(fast){
        const id=String(fast.course.code||fast.course.id||fast.course.name||'')+'|'+String(fast.course.university||'');
        if(!used.has(id)){
          used.add(id);
          return {
            required,
            alternative:fast.course,
            match:fast,
            accelerated:true,
            crossUniversity:fast.course.university && fast.course.university!==programme.university,
            disclaimer:fast.status==='verified'
              ? 'Motsvarigheten är verifierad i StudieLots.'
              : 'Tillgodoräknandet behöver bekräftas av universitetet som utfärdar examen.'
          };
        }
      }

      // Fall back to existing same-view planner.
      const fallback=typeof window.__studielotsBuildCoursePlanWithAlternatives==='function'
        ? window.__studielotsBuildCoursePlanWithAlternatives([required],window.__studielotsBuildCrossProviderReplacementPool(programme))[0]
        : null;

      return fallback || {required,alternative:null,accelerated:false};
    });
  };

  window.__studielotsAccelerationRules={
    version:'v488',
    allowCrossUniversityDistanceReplacement:true,
    keepProgrammeUniversityAsDegreeIssuer:true,
    requireFasterOffering:true,
    requireRemoteCourse:true,
    requireMotor2Match:true,
    universityConfirmationRequiredWhenUnverified:true,
    sameAlternativeCannotFillTwoRequirements:true
  };

  console.info('Studielots v488: cross-university distance acceleration preserved');
})();
