/* v491 — connect visible distance courses to the "Förslag att läsa" requirements + tidy top distance list */
(function(){
  const arr=v=>Array.isArray(v)?v:(v?[v]:[]);
  const norm=s=>String(s||'').toLowerCase().replace(/\s+/g,' ').trim();

  function distanceCourses(){
    const pool=[
      ...arr(window.__studielotsVerifiedDistanceCourses),
      ...arr(window.__studielotsDistanceCourseSuggestionPool),
      ...(Array.isArray(window.LIVE_DISTANCE_COURSES)?window.LIVE_DISTANCE_COURSES:[])
    ];
    const seen=new Set();
    return pool.filter(c=>{
      if(!c||!c.name) return false;
      const id=String(c.code||c.id||c.name)+'|'+String(c.university||'');
      if(seen.has(id)) return false;
      seen.add(id);
      return c.distance===true && c.mandatoryMeetings!==true && c.noPhysicalMeetings!==false;
    });
  }

  // Requirements shown in distance plans may be generic 30 hp blocks.
  // Match a real distance course against the block by subject/level and allocate its hp into the gap.
  window.__studielotsMatchDistanceCoursesToRequirement=function(req,courses){
    const subject=norm(req.subject||req.name);
    const level=norm(req.level||'grundnivå');
    const needHp=Number(req.hp)||0;

    const ranked=arr(courses).map(c=>{
      const cs=norm(c.subject||c.name);
      const cl=norm(c.level);
      let score=0;
      if(subject && (cs.includes(subject)||subject.includes(cs))) score+=60;
      if(!cl || !level || cl===level || (level.includes('grund')&&cl.includes('grund'))) score+=20;
      if(Number(c.hp)>0) score+=10;
      if(c.verified===true) score+=10;
      return {course:c,score};
    }).filter(x=>x.score>=60).sort((a,b)=>b.score-a.score);

    let covered=0;
    const picked=[];
    const used=new Set();
    for(const x of ranked){
      if(covered>=needHp) break;
      const id=String(x.course.code||x.course.id||x.course.name)+'|'+String(x.course.university||'');
      if(used.has(id)) continue;
      used.add(id);
      picked.push(x.course);
      covered+=Number(x.course.hp)||0;
    }
    return {courses:picked,coveredHp:Math.min(needHp,covered),remainingHp:Math.max(0,needHp-covered)};
  };

  // Render the distance plan requirements with concrete matches directly underneath.
  function enhanceDistancePlan(){
    const cards=[...document.querySelectorAll('section,div')].filter(el=>{
      const t=(el.innerText||'');
      return t.includes('Förslag att läsa') && t.includes('Kurs behöver hittas på distans');
    });

    const pool=distanceCourses();

    cards.forEach(card=>{
      if(card.dataset.distanceLinkedV491==='1') return;

      const rows=[...card.querySelectorAll('div')].filter(el=>{
        const t=(el.innerText||'').trim();
        return t.includes('Kurs behöver hittas på distans') &&
          ![...el.children].some(ch=>(ch.innerText||'').includes('Kurs behöver hittas på distans'));
      });

      rows.forEach(row=>{
        // Try to infer requirement name + hp from the row.
        const txt=(row.innerText||'').trim();
        const hpMatch=txt.match(/(\d+(?:[,.]\d+)?)\s*hp/i);
        const hp=hpMatch?Number(hpMatch[1].replace(',','.')):0;
        const name=(txt.split('\n').find(x=>x && !/Kurs behöver hittas|^\d+$|hp/i.test(x))||'').trim();
        if(!name||!hp) return;

        const subject=name.replace(/:\s*(Grundkurs|Fortsättningskurs|Forskningsmetod.*)$/i,'').trim();
        const match=window.__studielotsMatchDistanceCoursesToRequirement({name,subject,hp,level:'Grundnivå'},pool);
        if(!match.courses.length) return;

        const detail=document.createElement('div');
        detail.style.cssText='margin:10px 0 2px 38px;padding:10px 12px;border-radius:14px;background:rgba(22,94,78,.055);';
        detail.innerHTML=match.courses.map(c=>{
          const app=typeof window.__studielotsCourseApplicationState==='function'
            ? window.__studielotsCourseApplicationState(c):null;
          return `
            <div style="padding:8px 0;border-top:1px solid rgba(20,50,55,.08);">
              <div style="display:flex;justify-content:space-between;gap:10px;font-weight:750;">
                <span>${c.name}</span><span style="white-space:nowrap">${Number(c.hp)||''} hp</span>
              </div>
              <div style="font-size:.84em;opacity:.62;margin-top:3px;">
                ${c.university||''} · Distans${c.term?' · '+c.term:''}
              </div>
              <div style="font-size:.8em;color:#19715f;font-weight:700;margin-top:3px;">
                Möjlig del av detta krav · tillgodoräknandet behöver bekräftas av examenslärosätet.
              </div>
              ${app?`<div style="font-size:.8em;opacity:.62;margin-top:3px;">${app.label}${app.detail?' · '+app.detail:''}</div>`:''}
            </div>`;
        }).join('')+
        (match.remainingHp>0?`<div style="font-size:.82em;opacity:.62;margin-top:6px;">${match.remainingHp} hp återstår att hitta på distans för detta krav.</div>`:'');
        row.appendChild(detail);
      });

      card.dataset.distanceLinkedV491='1';
    });
  }

  // Tidy the loose top course list into a compact "Hittade distanskurser" card.
  function tidyTopDistanceCourses(){
    const headers=[...document.querySelectorAll('h1,h2,h3,div')].filter(el=>
      (el.innerText||'').trim()==='På distans'
    );
    if(!headers.length) return;

    const known=distanceCourses();
    if(!known.length) return;

    // find visible rows that match known course names
    const visibleRows=[];
    known.forEach(c=>{
      const el=[...document.querySelectorAll('div,section')].find(x=>{
        const t=(x.innerText||'').trim();
        return t.includes(c.name) && t.includes(String(c.hp)+' hp') &&
          ![...x.children].some(ch=>(ch.innerText||'').includes(c.name));
      });
      if(el) visibleRows.push({el,c});
    });
    if(!visibleRows.length) return;

    const first=visibleRows[0].el;
    if(document.querySelector('[data-distance-found-card="v491"]')) return;

    const card=document.createElement('section');
    card.setAttribute('data-distance-found-card','v491');
    card.style.cssText='margin:18px 26px 12px;padding:18px 20px;border-radius:22px;background:#fff;box-shadow:0 8px 24px rgba(20,40,45,.06);';
    card.innerHTML=`
      <div style="display:flex;justify-content:space-between;gap:12px;align-items:flex-start;">
        <div>
          <div style="font-size:.78em;letter-spacing:.08em;text-transform:uppercase;font-weight:800;color:#19715f;">Distans</div>
          <div style="font-size:1.12em;font-weight:800;margin-top:2px;">Hittade distanskurser</div>
        </div>
        <div style="font-weight:800;color:#19715f;">${visibleRows.length} st</div>
      </div>
      <div style="font-size:.9em;opacity:.62;margin-top:6px;">Kurser som kan bidra till den valda examensvägen.</div>
    `;

    visibleRows.forEach(({c})=>{
      const app=typeof window.__studielotsCourseApplicationState==='function'
        ? window.__studielotsCourseApplicationState(c):null;
      const row=document.createElement('div');
      row.style.cssText='padding:13px 0;border-top:1px solid rgba(20,50,55,.09);margin-top:8px;';
      row.innerHTML=`
        <div style="display:flex;justify-content:space-between;gap:10px;font-weight:750;">
          <span>${c.name}</span><span style="white-space:nowrap">${Number(c.hp)||''} hp</span>
        </div>
        <div style="font-size:.84em;opacity:.62;margin-top:3px;">${c.university||''} · Distans${c.term?' · '+c.term:''}</div>
        ${app?`<div style="font-size:.8em;opacity:.62;margin-top:3px;">${app.label}${app.detail?' · '+app.detail:''}</div>`:''}
      `;
      card.appendChild(row);
    });

    first.parentNode.insertBefore(card,first);
    visibleRows.forEach(({el})=>{ el.style.display='none'; });
  }

  function run(){
    enhanceDistancePlan();
    tidyTopDistanceCourses();
  }

  if(document.readyState==='loading') document.addEventListener('DOMContentLoaded',run); else run();
  document.addEventListener('studielots:screen-rendered',()=>requestAnimationFrame(run));

  window.__studielotsDistance={...(window.__studielotsDistance||{}),version:'v491',
    requirementsLinkedToRealCourses:true,topDistanceCoursesTidied:true};

  console.info('Studielots v491: distance courses linked into requirements and top list tidied');
})();
