/* v502 — root fix for Study Planner: no year-only shortcuts, no duplicate alternatives */
(function(){
  const norm=s=>String(s||'').trim().toLocaleLowerCase('sv-SE');
  const thesisLike=c=>Boolean(c?.thesis)||/(examensarbete|kandidatuppsats|magisteruppsats|masteruppsats|självständigt arbete)/i.test(String(c?.name||''));
  const levelBand=c=>{
    const s=norm(c?.level||c?.progression);
    if(/avancerad|a1n|a1f|a2e|a2f/.test(s))return 'advanced';
    if(/grund|g1n|g1f|g2f|g2e/.test(s))return 'basic';
    return '';
  };

  function actualOfferingDate(c){
    const vals=[c?.startDate,c?.nextOffering,c?.term,c?.semester,c?.studyPeriod];
    for(const v of vals){
      if(!v)continue;
      const s=String(v).trim();

      const iso=s.match(/\b(20\d{2})-(\d{2})-(\d{2})\b/);
      if(iso)return new Date(Number(iso[1]),Number(iso[2])-1,Number(iso[3]));

      const sw=s.match(/\b(HT|VT)\s*[- ]?(20\d{2})\b/i);
      if(sw)return new Date(Number(sw[2]),sw[1].toUpperCase()==='HT'?7:0,1);
    }
    return null;
  }

  function today(){
    const d=new Date();d.setHours(0,0,0,0);return d;
  }

  function actualFutureOffering(c){
    if(c?.ended===true||c?.offeringPast===true)return false;
    const d=actualOfferingDate(c);
    if(d)return d>=today();

    // Application-open data can establish a live/future course round.
    if(typeof courseApplicationOpen==='function' && courseApplicationOpen(c)===true)return true;

    // "År 1", "År 2" etc are programme order, NOT calendar availability.
    return false;
  }

  function targetFutureDate(target){
    return actualOfferingDate(target);
  }

  function plannerSameUniversityCoursePool(path){
    const uni=String(path?.provider||path?.program?.university||'');
    if(!uni)return [];
    let programs=[];
    try{
      programs=(typeof normalizedProgramCatalog==='function'?normalizedProgramCatalog():programCatalog||[])
        .filter(p=>p&&p.university===uni&&p.engine==='v2'&&!p.catalogOnly)
        .filter(p=>!p.academicYear||p.academicYear==='2026/2027');
    }catch(e){return []}

    const seen=new Map();
    programs.forEach(p=>(p.courses||[]).forEach(c=>{
      if(!c||Number(c.hp||0)<=0)return;
      const key=norm(c.code)||`${norm(c.name)}|${Number(c.hp||0)}`;
      const row={...c,_sourceProgram:p.name||'',_sourceProgramCode:p.code||'',_sourceUrl:p.sourceUrl||''};
      const prev=seen.get(key);
      if(!prev||Number(Boolean(row.verified))>Number(Boolean(prev.verified)))seen.set(key,row);
    }));
    return [...seen.values()];
  }

  function explicitEquivalent(alt,target){
    const targetCode=norm(target?.code), targetName=norm(target?.name);
    const vals=[
      ...(Array.isArray(alt?.equivalentTo)?alt.equivalentTo:[alt?.equivalentTo]),
      ...(Array.isArray(alt?.equivalents)?alt.equivalents:[alt?.equivalents]),
      ...(Array.isArray(alt?.replaces)?alt.replaces:[alt?.replaces])
    ].filter(Boolean).map(norm);
    return vals.some(v=>v===targetCode||v===targetName);
  }

  // Replace legacy candidate logic completely.
  const __legacy_fasterAlternativeCandidates_1=function(target,path){
    const pool=plannerSameUniversityCoursePool(path);
    const targetSubj=norm(target?.subject);
    const targetBand=levelBand(target);
    const targetHp=Number(target?.hp||0);
    const targetThesis=thesisLike(target);
    const targetDate=targetFutureDate(target);

    return pool.map(c=>{
      if((c.code&&target?.code&&norm(c.code)===norm(target.code))||norm(c.name)===norm(target?.name))return null;
      if(targetThesis!==thesisLike(c))return null;

      const subj=norm(c.subject);
      if(!targetSubj||subj!==targetSubj)return null;

      const band=levelBand(c);
      if(targetBand&&band&&band!==targetBand)return null;

      const hp=Number(c.hp||0);
      if(targetHp&&hp<Math.min(targetHp,7.5))return null;

      const explicit=explicitEquivalent(c,target);
      const candidateDate=actualOfferingDate(c);
      const future=actualFutureOffering(c);
      if(!future)return null;

      // Concrete speed advantage only:
      // - candidate has a dated future offering earlier than target's dated offering, OR
      // - candidate is currently open while target isn't, OR
      // - explicit verified equivalence AND a real future offering exists.
      const targetOpen=typeof courseApplicationOpen==='function'?courseApplicationOpen(target):false;
      const candOpen=typeof courseApplicationOpen==='function'?courseApplicationOpen(c):false;
      const datedEarlier=Boolean(candidateDate&&targetDate&&candidateDate<targetDate);
      const opensSooner=Boolean(candOpen&&!targetOpen);
      if(!explicit&&!datedEarlier&&!opensSooner)return null;

      let score=0;
      if(explicit)score+=1000;
      score+=180; // exact subject
      if(targetBand&&band===targetBand)score+=100;
      if(targetHp&&Math.abs(hp-targetHp)<0.01)score+=70;
      if(candOpen)score+=100;
      if(datedEarlier)score+=80;
      if(c.distance===true)score+=75;
      if(c.noPhysicalMeetings===true)score+=20;
      if(c.verified===true)score+=30;

      return {
        course:c,
        score,
        verifiedEquivalent:explicit,
        earlier:datedEarlier,
        opensSooner,
        distance:Boolean(c.distance===true),
        noPhysicalMeetings:Boolean(c.noPhysicalMeetings===true),
        reason:explicit?'Verifierad motsvarighet':
          c.distance===true&&datedEarlier?'Distans och tidigare faktisk kursstart':
          c.distance===true&&opensSooner?'Distans och sökbar tidigare':
          datedEarlier?'Tidigare faktisk kursstart':
          opensSooner?'Går att söka tidigare':'Möjligt alternativ'
      };
    }).filter(Boolean).sort((a,b)=>b.score-a.score);
  };

  const __legacy_bestFasterAlternative_2=function(target,path,used){
    const rows=window.fasterAlternativeCandidates(target,path);
    return rows.find(hit=>{
      const c=hit.course;
      const id=norm(c.code)||`${norm(c.name)}|${Number(c.hp||0)}`;
      return !used||!used.has(id);
    })||null;
  };

  function offeringLabel(c){
    const bits=[];
    const d=actualOfferingDate(c);
    if(c?.term||c?.semester)bits.push(String(c.term||c.semester).toUpperCase());
    else if(d)bits.push(d.toLocaleDateString('sv-SE',{year:'numeric',month:'short'}));
    if(c?.distance===true)bits.push('Distans');
    return bits.join(' · ');
  }

  // Replace Study Planner itself so one shared used-set spans the WHOLE plan.
  window.studyPlannerSection=function(path){
    if(path?.program?.safeMode===true||path?.program?.canCalculateCompletion===false)return '';

    const missing=(path.requiredMissing||[])
      .filter(c=>Number(c.hp||0)>0)
      .slice();

    if(!missing.length)return '';

    // Preserve actual programme order, but don't pretend study-year numbers are dates.
    missing.sort((a,b)=>{
      const ay=Number(a?.year||a?.studyYear||99), by=Number(b?.year||b?.studyYear||99);
      if(ay!==by)return ay-by;
      const ap=Number(String(a?.period||'').match(/\d+/)?.[0]||99);
      const bp=Number(String(b?.period||'').match(/\d+/)?.[0]||99);
      return ap-bp;
    });

    const groups=[[]]; let hp=0;
    missing.forEach(c=>{
      const chp=Number(c.hp||0);
      if(hp>0&&hp+chp>30){groups.push([]);hp=0}
      groups[groups.length-1].push(c); hp+=chp;
    });

    const usedAlternatives=new Set();
    let fasterCount=0, verifiedCount=0;

    const cards=groups.map((g,gi)=>`<div class="planner-term">
      <div class="planner-term-head"><strong>Period ${gi+1}</strong><span>${fmtHp(g.reduce((s,c)=>s+Number(c.hp||0),0))} hp</span></div>
      ${g.map(c=>{
        const hit=window.bestFasterAlternative(c,path,usedAlternatives);
        const alt=hit?.course;

        if(alt){
          const id=norm(alt.code)||`${norm(alt.name)}|${Number(alt.hp||0)}`;
          usedAlternatives.add(id);
          fasterCount++;
          if(hit.verifiedEquivalent)verifiedCount++;
        }

        const ordinaryLabel=[
          c.code,
          c.year&&Number(c.year)<90?'År '+c.year:null
        ].filter(Boolean).map(escapeHtml).join(' · ');

        return `<div class="planner-row"><div><strong>${escapeHtml(c.name||'Kurs')}</strong><small>${ordinaryLabel}</small></div><b>${fmtHp(c.hp||0)} hp</b></div>
        ${alt?`<div class="planner-alt ${hit.verifiedEquivalent?'verified-fast-alt':''} ${hit.distance?'distance-fast-alt':''}">
          <span>${hit.verifiedEquivalent?(hit.distance?'Verifierat distansalternativ':'Verifierat snabbare alternativ'):(hit.distance?'Möjligt distansalternativ':'Möjligt snabbare alternativ')}</span>
          <strong>${escapeHtml(alt.name||'Alternativ kurs')} · ${fmtHp(alt.hp||0)} hp</strong>
          <small>${escapeHtml(offeringLabel(alt))}${courseApplicationOpen(alt)?`${offeringLabel(alt)?' · ':''}Ansökan öppen`:''}</small>
          <small>${hit.verifiedEquivalent?'✓ Verifierat tillgodoräknande':'Tillgodoräknandet behöver bekräftas av universitetet.'}</small>
          <a href="${escapeHtml(antagningCourseUrl(alt))}" target="_blank" rel="noopener">Visa kurs ↗</a>
        </div>`:''}`;
      }).join('')}
    </div>`).join('');

    return `<section class="detail-block study-planner-block faster-degree-engine">
      <div class="suggested-course-head"><div><h2>Snabbaste studieplanen</h2><p>Alternativ visas bara när en verklig framtida kursomgång kan ge tidsvinst.</p></div><span class="planner-beta">OPTIMERAD</span></div>
      ${fasterCount?`<div class="fast-engine-summary"><strong>⚡ ${fasterCount} ${fasterCount===1?'möjlig genväg hittad':'möjliga genvägar hittade'}</strong><span>${verifiedCount?`${verifiedCount} verifierad${verifiedCount===1?'':'e'}`:'Kräver verifiering av tillgodoräknande'}</span></div>`:''}
      ${cards}
      <div class="planner-note">År 1/År 2 används bara som studieordning, aldrig som bevis på att en kurs går att läsa tidigare idag.</div>
    </section>`;
  };

  // Rebind the active detail renderer one final time so v502's planner wins.
  const prior=window.renderV21Detail;
  if(typeof prior==='function'){
    window.renderV21Detail=function(path,o){
      prior(path,o);
      const host=document.getElementById('universityDetailContent');
      if(!host)return;
      const old=host.querySelector('.study-planner-block');
      const html=window.studyPlannerSection(path);
      if(old){
        if(html)old.outerHTML=html;
        else old.remove();
      }
    };
  }

  window.__studielotsMotor2QA={
    ...(window.__studielotsMotor2QA||{}),
    version:'v502',
    rootStudyPlannerFixed:true,
    yearOnlyNeverMeansFaster:true,
    actualFutureOfferingRequired:true,
    duplicateAlternativeBlockedAcrossWholePlan:true
  };

  console.info('Studielots v502: root Study Planner timing + dedupe fixed');
})();
