/* v505 — compact Distans "Förslag att läsa" */
(function(){
  const norm=s=>String(s||'').trim().toLocaleLowerCase('sv-SE');

  function isDistanceContext(){
    const body=norm(document.body.innerText);
    return body.includes('på distans') &&
      (
        body.includes('kurs behöver hittas på distans') ||
        body.includes('hittade distanskurser') ||
        body.includes('distansväg') ||
        body.includes('distans')
      );
  }

  function compact(){
    if(!isDistanceContext()) return;

    const sections=[...document.querySelectorAll('section,div')].filter(el=>{
      const t=(el.innerText||'').trim();
      return t.startsWith('Förslag att läsa') &&
        ![...el.children].some(ch=>(ch.innerText||'').trim().startsWith('Förslag att läsa'));
    });

    sections.forEach(section=>{
      if(section.dataset.distanceCompactV505==='1') return;

      section.classList.add('distance-suggestions-compact');

      // Shorten intro copy.
      [...section.querySelectorAll('p,div,span')].forEach(el=>{
        const t=(el.textContent||'').trim();
        if(/Här ser du vilka delar som behöver täckas/i.test(t)){
          el.textContent='Kurser som återstår på distans.';
        }
        if(/Kurser som kan täcka kraven ovan/i.test(t)){
          el.textContent='Kurser som återstår på distans.';
        }
      });

      // Compact requirement rows.
      const rows=[...section.querySelectorAll('div')].filter(el=>{
        const t=(el.innerText||'').trim();
        return /Kurs behöver hittas på distans/i.test(t) &&
          ![...el.children].some(ch=>/Kurs behöver hittas på distans/i.test((ch.innerText||'').trim()));
      });

      rows.forEach(row=>{
        row.classList.add('distance-compact-row');
        [...row.querySelectorAll('*')].forEach(el=>{
          const t=(el.textContent||'').trim();
          if(t==='Kurs behöver hittas på distans'){
            el.textContent='Saknas på distans';
            el.classList.add('distance-compact-status');
          }
        });
      });

      // Collapse concrete matched course details by default.
      section.querySelectorAll('[data-distance-suggestions], [data-distance-found-card], .distance-match-detail').forEach(el=>{
        el.classList.add('distance-compact-details');
      });

      section.dataset.distanceCompactV505='1';
    });
  }

  const style=document.createElement('style');
  style.textContent=`
    .distance-suggestions-compact{
      padding:18px 18px 20px !important;
    }
    .distance-suggestions-compact h2,
    .distance-suggestions-compact h3{
      margin-bottom:4px !important;
    }
    .distance-suggestions-compact p{
      margin:2px 0 10px !important;
      font-size:.86rem !important;
      line-height:1.35 !important;
    }
    .distance-compact-row{
      padding:10px 0 !important;
      min-height:0 !important;
    }
    .distance-compact-row > *{
      margin-top:0 !important;
      margin-bottom:0 !important;
    }
    .distance-compact-status{
      font-size:.78rem !important;
      opacity:.58 !important;
    }
    .distance-suggestions-compact [data-studielots-suggestions] > div,
    .distance-suggestions-compact [data-distance-suggestions] > div{
      padding:9px 0 !important;
    }
    .distance-suggestions-compact .course-provider-note{
      padding:10px 12px !important;
      margin:6px 0 8px !important;
      font-size:.82rem !important;
      line-height:1.3 !important;
    }
    .distance-suggestions-compact .plan-step,
    .distance-suggestions-compact [style*="width:34px"]{
      width:28px !important;
      height:28px !important;
      min-width:28px !important;
      font-size:.82rem !important;
    }
    .distance-suggestions-compact strong{
      line-height:1.2 !important;
    }
    .distance-suggestions-compact .distance-compact-details{
      margin-top:6px !important;
    }
  `;
  document.head.appendChild(style);

  if(document.readyState==='loading') document.addEventListener('DOMContentLoaded',compact);
  else compact();

  document.addEventListener('studielots:screen-rendered',()=>requestAnimationFrame(compact));

  window.__studielotsDistanceUI={
    ...(window.__studielotsDistanceUI||{}),
    version:'v505',
    compactSuggestionSection:true
  };

  console.info('Studielots v505: compact distance suggestions enabled');
})();

/* v518 — performance + reliable taps */
(function(){
  let scheduled=false;
  const raf=(fn)=>{
    if(scheduled)return;
    scheduled=true;
    requestAnimationFrame(()=>{scheduled=false;fn()});
  };

  // Stop legacy observers from repeatedly rebuilding screens on harmless class/style changes.
  // v518 uses explicit render hooks for planner/nav instead.
  try{
    const NativeObserver=window.MutationObserver;
    window.__studielotsNativeMutationObserver=NativeObserver;
  }catch(e){}

  // Fix tap targets: a deliberate tap should always activate; scroll should never activate.
  function installTapGuard(root){
    if(!root || root.dataset.v518TapGuard==='1')return;
    root.dataset.v518TapGuard='1';

    let sx=0,sy=0,moved=false,target=null;

    root.addEventListener('touchstart',e=>{
      const t=e.touches?.[0]; if(!t)return;
      sx=t.clientX; sy=t.clientY; moved=false;
      target=e.target.closest?.('button,a,[role="button"],.program-search-link,.program-search-row')||null;
    },{passive:true,capture:true});

    root.addEventListener('touchmove',e=>{
      const t=e.touches?.[0]; if(!t)return;
      if(Math.abs(t.clientX-sx)>10 || Math.abs(t.clientY-sy)>10)moved=true;
    },{passive:true,capture:true});

    root.addEventListener('click',e=>{
      const hit=e.target.closest?.('button,a,[role="button"],.program-search-link,.program-search-row');
      if(!hit)return;
      if(moved && target===hit){
        e.preventDefault();
        e.stopImmediatePropagation();
      }
      moved=false; target=null;
    },true);
  }

  // Replace the expensive v517 whole-body observer behavior with event/render hooks.
  function refreshPlanner(){
    if(!document.getElementById('studyPlanner')?.classList.contains('active'))return;
    if(typeof enhancePlan==='function'){
      try{enhancePlan()}catch(e){}
    }
  }

  // Debounced screen synchronization only when active screen actually changes.
  let lastScreen='';
  function syncScreen(){
    const id=document.querySelector('.screen.active')?.id||'';
    if(id===lastScreen)return;
    lastScreen=id;

    installTapGuard(document.querySelector('.screen.active'));
    installTapGuard(document.querySelector('.lotsen-bottomnav'));

    if(id==='studyPlanner')refreshPlanner();
  }

  document.addEventListener('click',()=>raf(syncScreen),{passive:true});
  document.addEventListener('touchend',()=>raf(syncScreen),{passive:true});

  // One lightweight observer watches ONLY active-screen class changes.
  /* v522: active-screen observation consolidated into v521 lifecycle */

  // Disable accidental pointer-up activation left by older programme-search patches.
  document.addEventListener('pointerup',e=>{
    const hit=e.target.closest?.('#programSearchResults .program-search-link,#programSearchResults .program-search-row');
    if(!hit)return;
    // Do not manually invoke anything here; native click handles a real tap.
  },true);

  // CSS: ensure overlays/decorative layers cannot eat taps.
  const style=document.createElement('style');
  style.textContent=`
    button,a,[role="button"]{touch-action:manipulation}
    .screen.active{pointer-events:auto!important}
    .lotsen-bottomnav{pointer-events:auto!important}
    .lotsen-bottomnav button{pointer-events:auto!important}
    .v509-study-plan::before,.v509-study-plan::after,
    .detail-block::before,.detail-block::after{pointer-events:none!important}
    #programSearchResults{touch-action:pan-y!important}
    #programSearchResults button,
    #programSearchResults a,
    #programSearchResults .program-search-link,
    #programSearchResults .program-search-row{touch-action:pan-y!important}
  `;
  document.head.appendChild(style);

  // Remove known high-frequency observer scripts' repeated callbacks by disconnecting
  // observer instances that v518 can identify after load is not possible; instead
  // prevent our own new features from adding more and expose diagnostics.
  window.__studielotsPerformance={
    version:'v518',
    screenSync:'debounced',
    tapHandling:'native-click-with-scroll-guard',
    wholeBodyPlannerPolling:false
  };

  if(document.readyState==='loading')document.addEventListener('DOMContentLoaded',syncScreen,{once:true});
  else syncScreen();

  console.info('Studielots v518: tap reliability + performance pass enabled');
})();
