/* v521 — consolidated runtime: cached calculations + lightweight active-screen sync */
(function(){
  const arr=v=>Array.isArray(v)?v:(v?[v]:[]);
  const caches={program:new Map(),path:new Map()};

  function meritSig(){
    try{
      const rows=typeof getStoredCourses==='function'?arr(getStoredCourses()):
        arr(window.userCourses||window.importedCourses||[]);
      return rows.map(c=>[
        c.code||c.courseCode||c.name||'',
        Number(c.hp||0),c.grade||c.status||''
      ].join(':')).sort().join('|');
    }catch(e){return 'session'}
  }

  if(typeof window.estimateProgram==='function' && !window.estimateProgram.__v521){
    const native=window.estimateProgram;
    const wrapped=function(p){
      const key=String(p?.id||p?.code||p?.name||'program')+'::'+meritSig();
      if(caches.program.has(key))return caches.program.get(key);
      const result=native(p);
      caches.program.set(key,result);
      return result;
    };
    wrapped.__v521=true;
    window.estimateProgram=wrapped;
  }

  if(typeof window.studyPlanPathForProfile==='function' && !window.studyPlanPathForProfile.__v521){
    const native=window.studyPlanPathForProfile;
    const wrapped=function(profile,subject){
      const key=[profile||'',subject||'',meritSig()].join('::');
      if(caches.path.has(key))return caches.path.get(key);
      const result=native(profile,subject);
      caches.path.set(key,result);
      return result;
    };
    wrapped.__v521=true;
    window.studyPlanPathForProfile=wrapped;
  }

  window.__studielotsClearEngineCache=function(){
    caches.program.clear(); caches.path.clear();
  };

  let last='';
  function activeSync(){
    const id=document.querySelector('.screen.active')?.id||'';
    if(id===last)return;
    last=id;
    document.dispatchEvent(new CustomEvent('studielots:screen-rendered',{detail:{screen:id}}));
    if(id==='studyPlanner' && typeof window.__studielotsPlannerRefresh==='function'){
      requestAnimationFrame(()=>window.__studielotsPlannerRefresh());
    }
  }

  try{
    const main=document.querySelector('.main');
    if(main)new MutationObserver(activeSync).observe(main,{
      subtree:true,attributes:true,attributeFilter:['class']
    });
  }catch(e){}

  window.__studielotsBuild={
    version:'v521',
    baseline:'consolidated',
    architecture:{opportunities:'analysis',program:'analysis',studyplanner:'planning'},
    cacheStats:()=>({programs:caches.program.size,paths:caches.path.size})
  };
  console.info('Studielots v521: consolidated runtime active');
})();
