/* v532 — lazy feature initialization by active screen */
(function(){
  const loaded=new Set();

  const features={
    program(){
      if(loaded.has('program'))return;
      loaded.add('program');
      try{if(typeof install==='function')install()}catch(e){}
      try{if(typeof upgradeRenderedCards==='function')upgradeRenderedCards()}catch(e){}
      try{if(typeof decorateAdvancedCards==='function')decorateAdvancedCards()}catch(e){}
    },
    opportunities(){
      if(loaded.has('opportunities'))return;
      loaded.add('opportunities');
      try{if(typeof revealSafeModeSuggestions==='function')revealSafeModeSuggestions()}catch(e){}
      try{if(typeof decorate==='function')decorate()}catch(e){}
    },
    planner(){
      if(loaded.has('planner'))return;
      loaded.add('planner');
      try{if(typeof plannerCoreBoot==='function')plannerCoreBoot()}catch(e){}
      try{if(typeof plannerChooserBoot==='function')plannerChooserBoot()}catch(e){}
    },
    distance(){
      if(loaded.has('distance'))return;
      loaded.add('distance');
      try{if(typeof renderDistanceCard==='function')renderDistanceCard()}catch(e){}
      try{if(typeof addStatuses==='function')addStatuses()}catch(e){}
      try{if(typeof compact==='function')compact()}catch(e){}
    }
  };

  function initForScreen(id){
    if(!id)return;

    if(id==='programMatch' || id==='program') features.program();
    if(id==='degrees' || id==='degreeDetail' || id==='universityDetail') features.opportunities();
    if(id==='studyPlanner' || id==='myPath') features.planner();

    const body=document.getElementById(id);
    const txt=body?.innerText||'';
    if(/distans/i.test(txt))features.distance();
  }

  document.addEventListener('studielots:screen-rendered',e=>{
    initForScreen(e?.detail?.screen||'');
  });

  if(document.readyState==='loading'){
    document.addEventListener('DOMContentLoaded',()=>{
      initForScreen(document.querySelector('.screen.active')?.id||'');
    },{once:true});
  }else{
    initForScreen(document.querySelector('.screen.active')?.id||'');
  }

  window.__studielotsLazy={
    version:'v532',
    loadedFeatures:()=>[...loaded]
  };

  window.__studielotsBuild={...(window.__studielotsBuild||{}),
    version:'v532',
    lazyFeatureInitialization:true
  };

  console.info('Studielots v532: lazy feature initialization active');
})();

/* v533 — privacy-first import */
(function(){
 const allowed=new Set(['name','code','hp','grade','date','term','institution','university','level','levelSource','levelVerified','progression','subject','mainField','thesis','selected','duplicate','verified','source']);
 const piiKey=/^(studentName|fullName|firstName|lastName|personnummer|personalNumber|personId|ssn|birthDate|email|phone|address|documentId|verificationCode|verificationUrl|ladokId)$/i;
 function personalNumber(v){return /^(?:19|20)?\\d{6}[-+]?\\d{4}$/.test(String(v||'').replace(/\\s/g,''))}
 function sanitizeCourse(c){
   const out={};
   Object.entries(c||{}).forEach(([k,v])=>{
     if(piiKey.test(k)||!allowed.has(k)||personalNumber(v))return;
     out[k]=v;
   });
   return out;
 }
 function sanitizeRows(rows){return (Array.isArray(rows)?rows:[]).map(sanitizeCourse)}
 try{
   const stored=sessionStorage.getItem('examensmatch_courses');
   if(stored)sessionStorage.setItem('examensmatch_courses',JSON.stringify(sanitizeRows(JSON.parse(stored))));
   if(typeof courses!=='undefined'&&Array.isArray(courses)){
     const clean=sanitizeRows(courses); courses.splice(0,courses.length,...clean);
   }
 }catch(e){}
 window.openDocumentPrivacy=function(){
   try{if(typeof toggleMoreMenu==='function')toggleMoreMenu(false)}catch(e){}
   if(typeof go==='function')go('documentPrivacy');
 };
 window.__studielotsPrivacy={version:'v533',processing:'local-browser',originalPdfStored:false,meritStorage:'sessionStorage',sanitizeCourse};
 window.__studielotsBuild={...(window.__studielotsBuild||{}),version:'v533',privacyFirstImport:true};
})();

/* v536 — cross-university credit matching is university-neutral */
(function(){
  const norm=s=>String(s||'').toLocaleLowerCase('sv-SE')
    .normalize('NFD').replace(/[\u0300-\u036f]/g,'')
    .replace(/[^a-z0-9åäö]+/g,' ').trim();
  const hp=v=>Number(String(v??0).replace(',','.'))||0;
  const words=s=>new Set(norm(s).split(/\s+/).filter(x=>x.length>2));
  const overlap=(a,b)=>{
    const A=words(a),B=words(b); if(!A.size||!B.size)return 0;
    let n=0; A.forEach(x=>B.has(x)&&n++);
    return n/Math.max(1,Math.min(A.size,B.size));
  };
  const level=c=>norm(c?.level||c?.educationLevel||c?.cycle||c?.progression||'');
  const subject=c=>norm(c?.subject||c?.mainField||c?.track||'');
  const title=c=>String(c?.name||c?.title||'');
  const code=c=>norm(c?.code||c?.courseCode||'');
  const university=c=>String(c?.university||c?.provider||c?.institution||'');

  function scoreCourse(source,target){
    if(!source||!target)return {score:0,confidence:'none',reasons:[]};
    let score=0,reasons=[];
    const sh=hp(source.hp),th=hp(target.hp);
    const hpdiff=Math.abs(sh-th);
    if(sh&&th){
      if(hpdiff<0.01){score+=22;reasons.push('samma omfattning');}
      else if(sh>=th){score+=16;reasons.push('tillräcklig omfattning');}
      else if(hpdiff<=2.5){score+=8;reasons.push('nära omfattning');}
      else score-=15;
    }
    const nameOverlap=overlap(title(source),title(target));
    score+=Math.round(nameOverlap*38);
    if(nameOverlap>=.6)reasons.push('starkt innehålls-/namnöverlapp');
    else if(nameOverlap>=.35)reasons.push('möjligt innehållsöverlapp');

    const ss=subject(source),ts=subject(target);
    if(ss&&ts){
      if(ss===ts){score+=22;reasons.push('samma ämne');}
      else if(ss.includes(ts)||ts.includes(ss)){score+=14;reasons.push('närliggande ämne');}
    }

    const sl=level(source),tl=level(target);
    if(sl&&tl){
      if(sl===tl){score+=12;reasons.push('samma nivå');}
      else if((/avancer|a1|a2/.test(tl))&&!(/avancer|a1|a2/.test(sl))) score-=30;
    }

    // Course code is useful only inside the same institution. Never penalize
    // a course merely because it comes from another Swedish university.
    if(code(source)&&code(target)&&code(source)===code(target)){
      score+= university(source)&&university(target)&&norm(university(source))===norm(university(target)) ? 18 : 5;
    }

    const confidence=score>=70?'strong':score>=48?'possible':'weak';
    return {score:Math.max(0,Math.min(100,score)),confidence,reasons,
      crossUniversity:!!(university(source)&&university(target)&&norm(university(source))!==norm(university(target)))};
  }

  function importedCourses(){
    try{
      const c=JSON.parse(sessionStorage.getItem('examensmatch_courses')||'[]');
      return Array.isArray(c)?c:[];
    }catch(e){return []}
  }

  function bestMatch(target,used=new Set()){
    let best=null;
    for(const source of importedCourses()){
      const id=[norm(university(source)),code(source)||norm(title(source)),hp(source.hp)].join('|');
      if(used.has(id))continue;
      const m=scoreCourse(source,target);
      if(!best||m.score>best.match.score)best={source,target,match:m,id};
    }
    return best&&best.match.score>=48?best:null;
  }

  window.__studielotsCrossUniversityCredit={
    version:'v536',
    universityNeutral:true,
    scoreCourse,
    bestMatch,
    importedCourses
  };

  // Enrich the canonical plan with preliminary matches from any university.
  const old=window.__studielotsCanonicalStudyPlanHtml;
  if(typeof old==='function'&&!old.__v536){
    const wrapped=function(path,required,opts={}){
      const html=old.apply(this,arguments);
      const req=Array.isArray(required)?required:[];
      const used=new Set();
      const matches=req.map(r=>bestMatch(r,used)).filter(Boolean).filter(x=>{
        if(x.match.confidence==='strong'){used.add(x.id);return true}
        return false;
      });
      try{
        sessionStorage.setItem('studielots_cross_university_matches',JSON.stringify(matches.map(x=>({
          sourceName:title(x.source),sourceUniversity:university(x.source),
          targetName:title(x.target),hp:Math.min(hp(x.source.hp),hp(x.target.hp)),
          score:x.match.score,confidence:x.match.confidence,crossUniversity:x.match.crossUniversity
        }))));
      }catch(e){}
      return html;
    };
    wrapped.__v536=true;
    window.__studielotsCanonicalStudyPlanHtml=wrapped;
  }

  window.__studielotsBuild={...(window.__studielotsBuild||{}),version:'v536',
    crossUniversityCredit:true,universityNeutralMatching:true};
})();

/* v538 — show hp remaining directly in programme search */
(function(){
  const hp=v=>Number(String(v??0).replace(',','.'))||0;
  const fmt=v=>hp(v).toLocaleString('sv-SE',{maximumFractionDigits:1});

  function remainingFor(p){
    if(!p)return null;
    try{
      if(typeof estimateProgram==='function'){
        const r=estimateProgram(p);
        const remaining=Number(r?.remaining ?? r?.remainingHp ?? r?.hpRemaining);
        if(Number.isFinite(remaining))return Math.max(0,remaining);
        const credited=Number(r?.creditedHp ?? r?.mappedHp ?? r?.transferHp);
        const total=hp(p.hp);
        if(Number.isFinite(credited)&&total)return Math.max(0,total-credited);
      }
    }catch(e){}
    try{
      if(typeof evaluateProgramV2==='function'){
        const r=evaluateProgramV2(p);
        const remaining=Number(r?.remaining);
        if(Number.isFinite(remaining))return Math.max(0,remaining);
      }
    }catch(e){}
    return null;
  }

  function decorate(){
    const host=document.getElementById('programSearchResults');
    if(!host)return;

    host.querySelectorAll('.program-hit-v393').forEach(row=>{
      if(row.querySelector('.v538-hp-left'))return;
      const key=row.dataset.v393Key||'';
      const p=window.__v393ProgramHits?.[key];
      if(!p)return;

      const remaining=remainingFor(p);
      const badge=document.createElement('span');
      badge.className='v538-hp-left';
      badge.textContent=remaining==null?'Ej beräknat':`${fmt(remaining)} hp kvar`;

      const arrow=row.querySelector(':scope > span:last-child');
      if(arrow)arrow.insertAdjacentElement('beforebegin',badge);
      else row.appendChild(badge);
    });

    // Compatibility with older row renderer if it is ever used.
    host.querySelectorAll('[data-program-id]').forEach(row=>{
      if(row.querySelector('.v538-hp-left'))return;
      const id=decodeURIComponent(row.dataset.programId||'');
      const p=(window.programCatalog||[]).find(x=>String(x.id)===String(id));
      if(!p)return;
      const remaining=remainingFor(p);
      const badge=document.createElement('span');
      badge.className='v538-hp-left';
      badge.textContent=remaining==null?'Ej beräknat':`${fmt(remaining)} hp kvar`;
      const arrow=row.querySelector('.program-row-arrow');
      if(arrow)arrow.insertAdjacentElement('beforebegin',badge);
      else row.appendChild(badge);
    });
  }

  const oldRender=window.renderProgramSearch;
  if(typeof oldRender==='function'&&!oldRender.__v538){
    const wrapped=function(){
      const out=oldRender.apply(this,arguments);
      requestAnimationFrame(decorate);
      return out;
    };
    wrapped.__v538=true;
    window.renderProgramSearch=wrapped;
    try{renderProgramSearch=wrapped}catch(e){}
  }

  document.addEventListener('studielots:screen-rendered',e=>{
    if(e?.detail?.screen==='programMatch')requestAnimationFrame(decorate);
  });

  window.__studielotsBuild={...(window.__studielotsBuild||{}),version:'v538',programSearchRemainingHp:true};
})();

/* v549 — clean isolated Planner module; legacy planner renderers cannot touch this screen */
(function(){
 const A=v=>Array.isArray(v)?v:(v?[v]:[]);
 const N=v=>Number(String(v??0).replace(',','.'))||0;
 const F=v=>N(v).toLocaleString('sv-SE',{maximumFractionDigits:1});
 const Q=s=>String(s||'').toLocaleLowerCase('sv-SE').normalize('NFD').replace(/[\u0300-\u036f]/g,'').replace(/[^a-z0-9åäö]+/g,' ').trim();
 const E=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));

 function selection(){try{return JSON.parse(sessionStorage.getItem('studielots_planner_selection')||'{}')}catch(e){return{}}}
 function setSelection(v){try{sessionStorage.setItem('studielots_planner_selection',JSON.stringify(v||{}))}catch(e){}}

 function visibleHandoff(){
   const id=document.querySelector('.screen.active')?.id||'';
   const host=id==='universityDetail'?document.getElementById('universityDetailContent'):
              id==='programMatch'?document.getElementById('programMatchResult'):null;
   if(!host)return null;
   const txt=host.innerText||'';
   let m=txt.match(/([0-9]+(?:[,.][0-9]+)?)\s*hp\s*kan räknas\s*[·\-]\s*([0-9]+(?:[,.][0-9]+)?)\s*hp\s*kvar/i);
   if(!m)m=txt.match(/Tillgodoräknat\s*([0-9]+(?:[,.][0-9]+)?)\s*hp[\s\S]*?Kvar\s*([0-9]+(?:[,.][0-9]+)?)\s*hp/i);
   if(!m)return null;
   return {creditedHp:N(m[1]),remainingHp:N(m[2]),source:id};
 }

 function freeze(){
   const s=selection();
   const vis=visibleHandoff();
   let prior=null;
   try{prior=JSON.parse(sessionStorage.getItem('studielots_planner_frozen_handoff')||'null')}catch(e){}
   const h={
     version:'v549',
     selection:s,
     creditedHp:vis?vis.creditedHp:N(prior?.creditedHp),
     remainingHp:vis?vis.remainingHp:N(prior?.remainingHp),
     source:vis?.source||prior?.source||'selection'
   };
   // Copy any known match identities, but do not let them change totals.
   try{
     const c=window.__studielotsCanonicalMatch?.current?.();
     if(c && Math.abs(N(c.creditedHp)-h.creditedHp)<.01 && Math.abs(N(c.remainingHp)-h.remainingHp)<.01){
       h.matches=A(c.matches).map(x=>({
         targetName:x.requirement?.name||x.requirement?.title||'',
         targetCode:x.requirement?.code||'',
         sourceName:x.source?.name||x.source?.title||'',
         sourceUniversity:x.source?.university||x.source?.institution||'',
         hp:N(x.hp)
       }));
     }
   }catch(e){}
   h.matches=A(h.matches);
   try{sessionStorage.setItem('studielots_planner_clean_handoff',JSON.stringify(h))}catch(e){}
   return h;
 }
 function handoff(){try{return JSON.parse(sessionStorage.getItem('studielots_planner_clean_handoff')||'null')}catch(e){return null}}

 function resolveProgram(s){
   const cat=A(window.programCatalog);
   if(s?.source==='program'){
     return cat.find(x=>String(x.id||'')===String(s.programId||''))||
            cat.find(x=>s.programCode&&String(x.code||x.officialCode||'')===String(s.programCode))||null;
   }
   let o=null,path=null;
   try{if(s?.opportunityKey&&typeof opportunityByKey==='function')o=opportunityByKey(s.opportunityKey)}catch(e){}
   const profile=s?.profileId||(()=>{try{return sessionStorage.getItem('lotsen_preferred_profile')||s?.university||''}catch(e){return s?.university||''}})();
   try{if(typeof studyPlanPathForProfile==='function')path=studyPlanPathForProfile(profile,o?.subject||s?.subject)}catch(e){}
   try{if(!path&&typeof bestV21Path==='function')path=bestV21Path(profile,o?.subject||s?.subject)}catch(e){}
   return path?.program||null;
 }
 function resolvePath(s,p){
   let o=null,path=null;
   try{if(s?.opportunityKey&&typeof opportunityByKey==='function')o=opportunityByKey(s.opportunityKey)}catch(e){}
   const profile=s?.profileId||(()=>{try{return sessionStorage.getItem('lotsen_preferred_profile')||s?.university||''}catch(e){return s?.university||''}})();
   try{if(typeof studyPlanPathForProfile==='function')path=studyPlanPathForProfile(profile,o?.subject||s?.subject)}catch(e){}
   try{if(!path&&typeof bestV21Path==='function')path=bestV21Path(profile,o?.subject||s?.subject)}catch(e){}
   return path||{program:p,provider:p?.university||s?.university||''};
 }
 function structure(p){
   const out=[],seen=new Set();
   const add=(x,t)=>{
     if(!x||N(x.hp)<=0)return;
     const k=Q(x.code||x.name||x.title||x.label)+'|'+N(x.hp)+'|'+(x.term||x.semester||x.year||t||'');
     if(seen.has(k))return;seen.add(k);
     out.push({...x,_term:Number(x.term||x.semester||x.year||t)||null});
   };
   A(p?.courses).forEach(x=>add(x));
   ['verifiedOverviewCourses','courseStructure','programStructure','programmeStructure','requiredCourses'].forEach(k=>{
     const v=p?.[k];
     if(Array.isArray(v))v.forEach(x=>add(x));
     else if(v&&typeof v==='object')Object.entries(v).forEach(([t,xs])=>A(xs).forEach(x=>add(x,t.match(/\d+/)?.[0])));
   });
   return out.sort((a,b)=>(a._term||99)-(b._term||99));
 }
 function mapMatches(h){
   const code=new Map(),name=new Map();
   A(h?.matches).forEach(m=>{if(Q(m.targetCode))code.set(Q(m.targetCode),m);if(Q(m.targetName))name.set(Q(m.targetName),m)});
   return {code,name};
 }

 function altId(c){return Q(c?.code)||`${Q(c?.name)}|${N(c?.hp)}`}
 function faster(req,path,used){
   if(typeof window.bestFasterAlternative!=='function')return null;
   try{
     const hit=window.bestFasterAlternative(req,path,used);
     const c=hit?.course||null;if(!c)return null;
     const id=altId(c);if(!id||used.has(id))return null;
     used.add(id);return {hit,course:c};
   }catch(e){return null}
 }
 function offering(c){
   const bits=[];
   if(c?.term||c?.semester)bits.push(String(c.term||c.semester).toUpperCase());
   if(c?.distance===true)bits.push('Distans');
   try{if(typeof courseApplicationOpen==='function'&&courseApplicationOpen(c))bits.push('Ansökan öppen')}catch(e){}
   return bits.join(' · ');
 }
 function url(c){
   try{if(typeof antagningCourseUrl==='function')return antagningCourseUrl(c)||''}catch(e){}
   return c?.url||c?.applicationUrl||'';
 }

 function render(){
   const host=document.getElementById('plannerCleanContent');if(!host)return;
   const h=handoff(); const s=h?.selection||selection();
   if(!s?.source){
     host.innerHTML='<div class="detail-block"><h2>Skapa en studieplan</h2><p>Välj en examen eller ett program så bygger Planeraren en personlig väg.</p></div>';
     return;
   }
   const p=resolveProgram(s),path=resolvePath(s,p),rows=structure(p);
   if(!p||!rows.length){
     host.innerHTML='<div class="detail-block"><h2>Studieplan</h2><p>Den valda vägen saknar en tillräckligt detaljerad kursstruktur för att visa en fullständig plan ännu.</p></div>';
     return;
   }

   const credited=N(h?.creditedHp),remaining=N(h?.remainingHp),mm=mapMatches(h);
   const usedAlt=new Set();let body='',term=null,altCount=0;

   rows.forEach(r=>{
     if(r._term!==term){term=r._term;body+=`<div class="v549-term"><strong>Termin ${term||''}</strong></div>`}
     const m=(Q(r.code)&&mm.code.get(Q(r.code)))||mm.name.get(Q(r.name||r.title||r.label))||null;
     body+=`<div class="v549-course ${m?'credit':''}"><div class="v549-main"><div><strong>${E(r.name||r.title||r.label||'Kurs')}</strong><small>${m?'Kan tillgodoräknas':'Återstår att läsa'}</small>${m?.sourceName?`<em>${E(m.sourceName)}${m.sourceUniversity?` · ${E(m.sourceUniversity)}`:''}</em>`:''}</div><b>${F(r.hp)} hp</b></div>`;
     if(!m){
       const alt=faster(r,path,usedAlt);
       if(alt){
         altCount++;
         const label=alt.hit?.verifiedEquivalent?(alt.hit?.distance?'VERIFIERAT DISTANSALTERNATIV':'VERIFIERAT SNABBARE ALTERNATIV'):(alt.hit?.distance?'MÖJLIGT DISTANSALTERNATIV':'MÖJLIGT SNABBARE ALTERNATIV');
         const u=url(alt.course);
         body+=`<div class="v549-alt"><span>${label}</span><div><strong>${E(alt.course.name||'Alternativ kurs')}</strong><b>${F(alt.course.hp)} hp</b></div>${offering(alt.course)?`<small>${E(offering(alt.course))}</small>`:''}${u?`<a href="${E(u)}" target="_blank" rel="noopener">Visa kurs ↗</a>`:''}</div>`;
       }
     }
     body+='</div>';
   });

   host.innerHTML=`<section class="v549-selected"><div><span>VALD VÄG</span><strong>${E(s.subject||s.programName||p.name||'Studieplan')}</strong><small>${E(s.university||p.university||'')}</small></div><button type="button" class="ghost" onclick="window.__v549NewPlan()">Ändra</button></section>
   <section class="v549-summary"><div><strong>${F(credited)} hp</strong><span>kan räknas in</span></div><div><strong>${F(remaining)} hp</strong><span>kvar</span></div></section>
   <section class="detail-block v549-plan"><div class="v549-head"><div><h2>Din studieplan</h2><p>Ordinarie väg med möjliga snabbare alternativ.</p></div>${altCount?`<span>⚡ ${altCount} genväg${altCount===1?'':'ar'}</span>`:''}</div>${body}
   <p class="v549-note">Tillgodoräknanden och alternativa kurser är preliminära tills universitetet fattat beslut. Samma alternativkurs används aldrig för mer än ett krav.</p></section>`;
 }

 window.__v549NewPlan=function(){
   try{sessionStorage.removeItem('studielots_planner_clean_handoff');sessionStorage.removeItem('studielots_planner_selection')}catch(e){}
   if(typeof go==='function'){go('degrees')}
 };

 // FINAL planner entry point. Does not call any legacy openStudyPlanner wrapper.
 window.openStudyPlanner=function(){
   freeze();
   if(typeof go==='function')go('plannerClean');
   requestAnimationFrame(render);
 };

 // CTAs already call openStudyPlanner, so no extra legacy handoff is needed.
 document.addEventListener('studielots:screen-rendered',e=>{
   if(e?.detail?.screen==='plannerClean')requestAnimationFrame(render);
 });

 // Bottom-nav button always goes to the clean planner.
 function wireNav(){
   const nav=document.querySelector('.lotsen-bottomnav');if(!nav)return;
   const btn=[...nav.querySelectorAll('button')].find(b=>/planeraren/i.test(b.innerText||''));
   if(btn){btn.onclick=()=>window.openStudyPlanner();btn.dataset.navTarget='plannerClean'}
 }
 if(document.readyState==='loading')document.addEventListener('DOMContentLoaded',wireNav,{once:true});else wireNav();
 document.addEventListener('studielots:screen-rendered',wireNav);

 window.__studielotsBuild={...(window.__studielotsBuild||{}),version:'v549',cleanPlannerModule:true,legacyPlannerIsolated:true};
})();

/* v550 — clean planner integration: CTA + nav, no legacy planner wrappers */
(function(){
  function readDetailTotals(){
    const host=document.getElementById('universityDetailContent');
    if(!host)return null;
    const txt=host.innerText||'';
    let m=txt.match(/([0-9]+(?:[,.][0-9]+)?)\s*hp\s*kan räknas\s*[·\-]\s*([0-9]+(?:[,.][0-9]+)?)\s*hp\s*kvar/i);
    if(!m)m=txt.match(/Tillgodoräknat\s*([0-9]+(?:[,.][0-9]+)?)\s*hp[\s\S]*?Kvar\s*([0-9]+(?:[,.][0-9]+)?)\s*hp/i);
    if(!m)return null;
    return {creditedHp:Number(m[1].replace(',','.')),remainingHp:Number(m[2].replace(',','.'))};
  }

  function currentOpportunityPayload(){
    let key='',profile='',o=null,path=null;
    try{
      key=sessionStorage.getItem('lotsen_detail_key')||'';
      profile=sessionStorage.getItem('lotsen_preferred_profile')||'';
      if(key&&typeof opportunityByKey==='function')o=opportunityByKey(key);
      if(typeof studyPlanPathForProfile==='function')path=studyPlanPathForProfile(profile,o?.subject||'');
    }catch(e){}
    return {
      source:'opportunity',
      profileId:profile,
      opportunityKey:key,
      subject:o?.subject||path?.subject||path?.program?.subject||'',
      university:path?.provider||path?.program?.university||profile||'',
      programId:path?.program?.id||'',
      programCode:path?.program?.code||''
    };
  }

  function selectedProgramPayload(){
    let id='',p=null;
    try{
      id=sessionStorage.getItem('lotsen_selected_program')||'';
      p=(window.programCatalog||[]).find(x=>String(x.id||'')===String(id));
    }catch(e){}
    if(!p)return null;
    return {
      source:'program',
      programId:p.id||'',
      programCode:p.code||p.officialCode||'',
      programName:p.name||'',
      university:p.university||'',
      subject:p.subject||p.track||''
    };
  }

  function saveSelection(payload, totals){
    try{
      sessionStorage.setItem('studielots_planner_selection',JSON.stringify(payload||{}));
      if(totals){
        sessionStorage.setItem('studielots_planner_clean_handoff',JSON.stringify({
          version:'v550',
          selection:payload||{},
          creditedHp:Number(totals.creditedHp||0),
          remainingHp:Number(totals.remainingHp||0),
          matches:[],
          source:'clean-cta'
        }));
      }
    }catch(e){}
  }

  function ensureOpportunityCTA(){
    if(document.querySelector('.screen.active')?.id!=='universityDetail')return;
    const host=document.getElementById('universityDetailContent');
    if(!host||host.querySelector('[data-v550-plan-cta]'))return;
    const wrap=document.createElement('div');
    wrap.dataset.v550PlanCta='1';
    wrap.className='v550-plan-cta';
    wrap.innerHTML='<button type="button" class="primary v550-plan-button"><span>Skapa plan i Planeraren</span><b>›</b></button><small>Bygger en personlig studieordning utifrån det som kan räknas och det du har kvar.</small>';
    wrap.querySelector('button').addEventListener('click',()=>{
      const payload=currentOpportunityPayload();
      saveSelection(payload,readDetailTotals());
      if(typeof window.openStudyPlanner==='function')window.openStudyPlanner();
    });
    host.appendChild(wrap);
  }

  function ensureProgramCTA(){
    if(document.querySelector('.screen.active')?.id!=='programMatch')return;
    const host=document.getElementById('programMatchResult');
    if(!host||host.querySelector('[data-v550-plan-cta]'))return;
    const payload=selectedProgramPayload();
    if(!payload)return;
    const wrap=document.createElement('div');
    wrap.dataset.v550PlanCta='1';
    wrap.className='v550-plan-cta';
    wrap.innerHTML='<button type="button" class="primary v550-plan-button"><span>Skapa plan i Planeraren</span><b>›</b></button>';
    wrap.querySelector('button').addEventListener('click',()=>{
      saveSelection(payload,null);
      if(typeof window.openStudyPlanner==='function')window.openStudyPlanner();
    });
    host.appendChild(wrap);
  }

  function wirePlannerNav(){
    const nav=document.querySelector('.lotsen-bottomnav');
    if(!nav)return;
    const btn=[...nav.querySelectorAll('button')].find(b=>/planeraren/i.test(b.innerText||''));
    if(btn){
      btn.onclick=()=>window.openStudyPlanner?.();
      btn.dataset.navTarget='plannerClean';
    }
  }

  function ensureStudiesUnderMore(){
    const sheet=document.querySelector('.more-menu-sheet');
    if(!sheet||sheet.querySelector('[data-v551-studies]'))return;
    const btn=document.createElement('button');
    btn.type='button';
    btn.className='more-menu-item';
    btn.dataset.v551Studies='1';
    btn.innerHTML='<span aria-hidden="true">▤</span><div><strong>Studier</strong><small>Se och hantera dina importerade meriter</small></div><b>›</b>';
    btn.addEventListener('click',()=>{
      try{if(typeof toggleMoreMenu==='function')toggleMoreMenu(false)}catch(e){}
      if(typeof go==='function')go('studies');
    });
    const first=sheet.querySelector('.more-menu-item');
    if(first)first.parentNode.insertBefore(btn,first);
    else sheet.appendChild(btn);
  }

  function sync(){
    wirePlannerNav();
    ensureStudiesUnderMore();
    ensureOpportunityCTA();
    ensureProgramCTA();
  }

  document.addEventListener('studielots:screen-rendered',()=>requestAnimationFrame(sync));
  if(document.readyState==='loading')document.addEventListener('DOMContentLoaded',sync,{once:true});
  else requestAnimationFrame(sync);

  window.__studielotsBuild={...(window.__studielotsBuild||{}),version:'v551',legacyPlannerScriptsRemoved:true,legacyPlannerBundleSplit:true};
})();

/* v552 — single faster-alternative engine */
(function(){
  const A=v=>Array.isArray(v)?v:(v?[v]:[]);
  const N=v=>Number(String(v??0).replace(',','.'))||0;
  const Q=s=>String(s||'').toLocaleLowerCase('sv-SE')
    .normalize('NFD').replace(/[\u0300-\u036f]/g,'')
    .replace(/[^a-z0-9åäö]+/g,' ').trim();

  function levelBand(c){
    const v=Q(c?.level||c?.progression||c?.educationLevel||c?.cycle);
    if(/a1|a2|avancer/.test(v))return 'advanced';
    if(/g1|g2|grund/.test(v))return 'basic';
    return '';
  }

  function thesisLike(c){
    return Boolean(c?.thesis===true||/uppsats|examensarbete|thesis/.test(Q(c?.name)));
  }

  function actualDate(c){
    for(const v of [c?.startDate,c?.courseStart,c?.nextStart,c?.offeringDate]){
      if(!v)continue;
      const d=new Date(v);
      if(!Number.isNaN(d.getTime()))return d;
    }
    const s=String(c?.nextOffering||c?.term||c?.semester||'');
    let m=s.match(/\b(VT|HT)\s*[- ]?(20\d{2})\b/i);
    if(m)return new Date(+m[2],m[1].toUpperCase()==='VT'?0:7,1);
    return null;
  }

  function applicationOpen(c){
    try{
      if(typeof window.__studielotsCourseApplicationState==='function'){
        const s=window.__studielotsCourseApplicationState(c);
        if(s&&typeof s.open==='boolean')return s.open;
      }
      if(typeof courseApplicationOpen==='function')return courseApplicationOpen(c)===true;
    }catch(e){}
    return c?.applicationOpen===true;
  }

  function explicitEquivalent(alt,target){
    const tc=Q(target?.code),tn=Q(target?.name);
    const vals=[
      ...A(alt?.equivalentTo),
      ...A(alt?.equivalents),
      ...A(alt?.replaces)
    ].filter(Boolean).map(Q);
    return vals.some(v=>(tc&&v===tc)||(tn&&v===tn));
  }

  function coursePool(path){
    const university=String(path?.provider||path?.program?.university||'');
    if(!university)return [];
    let programs=[];
    try{
      programs=typeof normalizedProgramCatalog==='function'
        ? normalizedProgramCatalog()
        : A(window.programCatalog);
    }catch(e){programs=A(window.programCatalog)}

    const seen=new Map();
    programs
      .filter(p=>p&&String(p.university||'')===university)
      .filter(p=>p.catalogOnly!==true)
      .forEach(p=>{
        A(p.courses).forEach(c=>{
          if(!c||N(c.hp)<=0)return;
          const key=Q(c.code)||`${Q(c.name)}|${N(c.hp)}`;
          const row={...c,_sourceProgram:p.name||'',_sourceProgramCode:p.code||''};
          const prev=seen.get(key);
          if(!prev||Number(Boolean(row.verified))>Number(Boolean(prev.verified)))seen.set(key,row);
        });
      });
    return [...seen.values()];
  }

  function candidates(target,path){
    const pool=coursePool(path);
    const targetSubject=Q(target?.subject||target?.mainField);
    const targetLevel=levelBand(target);
    const targetHp=N(target?.hp);
    const targetDate=actualDate(target);
    const targetOpen=applicationOpen(target);
    const targetThesis=thesisLike(target);

    return pool.map(c=>{
      if((c.code&&target?.code&&Q(c.code)===Q(target.code))||Q(c.name)===Q(target?.name))return null;
      if(thesisLike(c)!==targetThesis)return null;

      const subject=Q(c.subject||c.mainField);
      if(targetSubject&&subject&&subject!==targetSubject)return null;

      const band=levelBand(c);
      if(targetLevel&&band&&band!==targetLevel)return null;

      const chp=N(c.hp);
      if(targetHp&&chp<Math.min(targetHp,7.5))return null;

      const explicit=explicitEquivalent(c,target);
      const candDate=actualDate(c);
      const candOpen=applicationOpen(c);
      const datedEarlier=Boolean(candDate&&targetDate&&candDate<targetDate);
      const opensSooner=Boolean(candOpen&&!targetOpen);

      // No "faster" label without a concrete advantage or explicit equivalence.
      if(!explicit&&!datedEarlier&&!opensSooner)return null;

      let score=0;
      if(explicit)score+=1000;
      if(targetSubject&&subject===targetSubject)score+=180;
      if(targetLevel&&band===targetLevel)score+=100;
      if(targetHp&&Math.abs(chp-targetHp)<.01)score+=70;
      if(candOpen)score+=100;
      if(datedEarlier)score+=120;
      if(c.distance===true)score+=40;
      if(c.verified===true)score+=30;

      return {
        course:c,
        score,
        verifiedEquivalent:explicit,
        earlier:datedEarlier,
        opensSooner,
        distance:Boolean(c.distance===true),
        reason:explicit?'Verifierad motsvarighet':
          datedEarlier&&c.distance===true?'Distans och tidigare faktisk kursstart':
          datedEarlier?'Tidigare faktisk kursstart':
          opensSooner?'Går att söka tidigare':'Möjligt alternativ'
      };
    }).filter(Boolean).sort((a,b)=>b.score-a.score);
  }

  function best(target,path,used){
    const rows=candidates(target,path);
    return rows.find(hit=>{
      const c=hit.course;
      const id=Q(c.code)||`${Q(c.name)}|${N(c.hp)}`;
      return !used||!used.has(id);
    })||null;
  }

  window.fasterAlternativeCandidates=candidates;
  window.bestFasterAlternative=best;
  window.__studielotsFasterEngine={
    version:'v552',
    coursePool,
    candidates,
    best
  };
  window.__studielotsBuild={...(window.__studielotsBuild||{}),version:'v553',
    singleFasterAlternativeEngine:true,legacyFasterExportsDisabled:true};
})();

/* v553 — optimization engine ownership guard */
(function(){
  const engine=window.__studielotsFasterEngine;
  if(engine){
    window.fasterAlternativeCandidates=engine.candidates;
    window.bestFasterAlternative=engine.best;
  }
  window.__studielotsEngineAudit={
    planner:'v549-clean',
    fasterAlternatives:'v552-single',
    legacyFasterExportsDisabled:true
  };
})();

/* v554 — lightweight runtime: no page-wide MutationObservers for nav/scroll/planner */
(function(){
  let lastScreen='';

  function activeScreen(){
    return document.querySelector('.screen.active')?.id||'';
  }

  function syncBottomNav(){
    const nav=document.querySelector('.lotsen-bottomnav');
    if(!nav)return;
    const id=activeScreen();
    [...nav.querySelectorAll('button')].forEach(btn=>{
      const label=(btn.innerText||'').toLocaleLowerCase('sv-SE');
      let active=false;
      if(id==='plannerClean'&&label.includes('planeraren'))active=true;
      else if(id==='programMatch'&&label.includes('program'))active=true;
      else if((id==='degrees'||id==='degreeDetail'||id==='universityDetail')&&label.includes('möjligheter'))active=true;
      else if(id==='home'&&label.includes('hem'))active=true;
      else if(id==='more'&&label.includes('mer'))active=true;
      btn.classList.toggle('active',active);
    });
  }

  function syncScroll(){
    const id=activeScreen();
    if(id===lastScreen)return;
    lastScreen=id;
    // Each page uses the document as the only vertical scroll owner.
    document.documentElement.style.overflowY='auto';
    document.body.style.overflowY='auto';
    document.body.style.touchAction='pan-y';
  }

  function sync(){
    syncBottomNav();
    syncScroll();
  }

  document.addEventListener('studielots:screen-rendered',()=>requestAnimationFrame(sync));
  window.addEventListener('pageshow',()=>requestAnimationFrame(sync),{passive:true});
  if(document.readyState==='loading')document.addEventListener('DOMContentLoaded',sync,{once:true});
  else requestAnimationFrame(sync);

  window.__studielotsBuild={...(window.__studielotsBuild||{}),version:'v554',
    lightweightRuntimeSync:true,
    mutationObserverScrollFixRemoved:true};
})();

/* v555 — final legacy cleanup */
(function(){
  window.__studielotsBuild={...(window.__studielotsBuild||{}),version:'v555',
    singlePlannerOwner:true,
    oldPlannerScreenRemoved:true,
    legacyPlannerStylesTrimmed:true
  };
})();

/* v556 — planner resolves the exact programme carried from Möjligheter/Program */
(function(){
  const A=v=>Array.isArray(v)?v:(v?[v]:[]);
  const N=v=>Number(String(v??0).replace(',','.'))||0;
  const F=v=>N(v).toLocaleString('sv-SE',{maximumFractionDigits:1});
  const Q=s=>String(s||'').toLocaleLowerCase('sv-SE')
    .normalize('NFD').replace(/[\u0300-\u036f]/g,'')
    .replace(/[^a-z0-9åäö]+/g,' ').trim();
  const E=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));

  function handoff(){
    try{
      return JSON.parse(
        sessionStorage.getItem('studielots_planner_clean_handoff') ||
        sessionStorage.getItem('studielots_planner_frozen_handoff') ||
        'null'
      );
    }catch(e){return null}
  }

  function selection(){
    const h=handoff();
    if(h?.selection)return h.selection;
    try{return JSON.parse(sessionStorage.getItem('studielots_planner_selection')||'{}')}catch(e){return{}}
  }

  function findProgram(s){
    const cat=A(window.programCatalog);

    // 1. Exact programme identity passed from the previous view.
    if(s?.programId){
      const p=cat.find(x=>String(x.id||'')===String(s.programId));
      if(p)return p;
    }
    if(s?.programCode){
      const p=cat.find(x=>String(x.code||x.officialCode||'')===String(s.programCode));
      if(p)return p;
    }

    // 2. Programme name + university.
    if(s?.programName){
      const p=cat.find(x=>
        Q(x.name)===Q(s.programName) &&
        (!s.university || Q(x.university)===Q(s.university))
      );
      if(p)return p;
    }

    // 3. Re-resolve opportunity only as fallback.
    let o=null,path=null;
    try{
      if(s?.opportunityKey&&typeof opportunityByKey==='function'){
        o=opportunityByKey(s.opportunityKey);
      }
    }catch(e){}
    const profile=s?.profileId||(()=>{
      try{return sessionStorage.getItem('lotsen_preferred_profile')||s?.university||''}
      catch(e){return s?.university||''}
    })();

    try{
      if(typeof studyPlanPathForProfile==='function'){
        path=studyPlanPathForProfile(profile,o?.subject||s?.subject);
      }
    }catch(e){}
    try{
      if(!path&&typeof bestV21Path==='function'){
        path=bestV21Path(profile,o?.subject||s?.subject);
      }
    }catch(e){}

    return path?.program||null;
  }

  function resolvePath(s,p){
    let o=null,path=null;
    try{
      if(s?.opportunityKey&&typeof opportunityByKey==='function'){
        o=opportunityByKey(s.opportunityKey);
      }
    }catch(e){}
    const profile=s?.profileId||(()=>{
      try{return sessionStorage.getItem('lotsen_preferred_profile')||s?.university||''}
      catch(e){return s?.university||''}
    })();
    try{
      if(typeof studyPlanPathForProfile==='function'){
        path=studyPlanPathForProfile(profile,o?.subject||s?.subject);
      }
    }catch(e){}
    try{
      if(!path&&typeof bestV21Path==='function'){
        path=bestV21Path(profile,o?.subject||s?.subject);
      }
    }catch(e){}
    return path||{program:p,provider:p?.university||s?.university||''};
  }

  function structure(p,path){
    const out=[],seen=new Set();

    function add(x,term){
      if(!x||N(x.hp)<=0)return;
      const k=Q(x.code||x.name||x.title||x.label)+'|'+N(x.hp)+'|'+(x.term||x.semester||x.year||term||'');
      if(seen.has(k))return;
      seen.add(k);
      out.push({...x,_term:Number(x.term||x.semester||x.year||term)||null});
    }

    // Full programme structures first.
    A(p?.courses).forEach(x=>add(x));
    ['verifiedOverviewCourses','courseStructure','programStructure','programmeStructure','requiredCourses'].forEach(k=>{
      const v=p?.[k];
      if(Array.isArray(v))v.forEach(x=>add(x));
      else if(v&&typeof v==='object'){
        Object.entries(v).forEach(([t,xs])=>{
          A(xs).forEach(x=>add(x,t.match(/\d+/)?.[0]));
        });
      }
    });

    // Path data can carry the structure even if the programme object is thin.
    if(!out.length){
      ['courses','courseStructure','requiredCourses','requirements'].forEach(k=>{
        const v=path?.[k];
        if(Array.isArray(v))v.forEach(x=>add(x));
        else if(v&&typeof v==='object'){
          Object.entries(v).forEach(([t,xs])=>A(xs).forEach(x=>add(x,t.match(/\d+/)?.[0])));
        }
      });
    }

    // Last resort: remaining requirements are still better than an empty planner.
    if(!out.length){
      A(path?.requiredMissing).forEach(x=>add(x));
    }

    return out.sort((a,b)=>(a._term||99)-(b._term||99));
  }

  function matchMap(h){
    const code=new Map(),name=new Map();
    A(h?.matches).forEach(m=>{
      if(Q(m.targetCode))code.set(Q(m.targetCode),m);
      if(Q(m.targetName))name.set(Q(m.targetName),m);
    });
    return {code,name};
  }

  function altId(c){return Q(c?.code)||`${Q(c?.name)}|${N(c?.hp)}`}
  function faster(req,path,used){
    if(typeof window.bestFasterAlternative!=='function')return null;
    try{
      const hit=window.bestFasterAlternative(req,path,used);
      const c=hit?.course||null;
      if(!c)return null;
      const id=altId(c);
      if(!id||used.has(id))return null;
      used.add(id);
      return {hit,course:c};
    }catch(e){return null}
  }

  function render(){
    if(document.querySelector('.screen.active')?.id!=='plannerClean')return;

    const host=document.getElementById('plannerCleanContent');
    if(!host)return;

    const h=handoff()||{};
    const s=selection();
    const p=findProgram(s);
    const path=resolvePath(s,p);
    const rows=structure(p,path);

    if(!p && !rows.length){
      host.innerHTML='<div class="detail-block"><h2>Studieplan</h2><p>StudieLots kunde inte hitta den valda utbildningen. Gå tillbaka till Möjligheter eller Program och välj vägen igen.</p></div>';
      return;
    }

    if(!rows.length){
      host.innerHTML='<div class="detail-block"><h2>Studieplan</h2><p>Kursstrukturen för den valda vägen är ännu inte tillräckligt detaljerad för att bygga planen.</p></div>';
      return;
    }

    const credited=N(h.creditedHp);
    const remaining=Number.isFinite(Number(h.remainingHp))
      ? N(h.remainingHp)
      : Math.max(0,(N(p?.hp)||rows.reduce((sum,x)=>sum+N(x.hp),0))-credited);

    const mm=matchMap(h);
    const usedAlt=new Set();
    let body='',term=null,altCount=0;

    rows.forEach((r,i)=>{
      const currentTerm=r._term||Math.floor(i/2)+1;
      if(currentTerm!==term){
        term=currentTerm;
        body+=`<div class="v556-term"><strong>Termin ${term}</strong></div>`;
      }

      const m=(Q(r.code)&&mm.code.get(Q(r.code)))||mm.name.get(Q(r.name||r.title||r.label))||null;

      body+=`<div class="v556-course ${m?'credit':''}">
        <div class="v556-main">
          <div>
            <strong>${E(r.name||r.title||r.label||'Kurs')}</strong>
            <small>${m?'Kan tillgodoräknas':'Återstår att läsa'}</small>
            ${m?.sourceName?`<em>${E(m.sourceName)}${m.sourceUniversity?` · ${E(m.sourceUniversity)}`:''}</em>`:''}
          </div>
          <b>${F(r.hp)} hp</b>
        </div>`;

      if(!m){
        const alt=faster(r,path,usedAlt);
        if(alt){
          altCount++;
          body+=`<div class="v556-alt">
            <span>${alt.hit?.verifiedEquivalent?'VERIFIERAT SNABBARE ALTERNATIV':'MÖJLIGT SNABBARE ALTERNATIV'}</span>
            <div><strong>${E(alt.course.name||alt.course.title||'Alternativ kurs')}</strong><b>${F(alt.course.hp)} hp</b></div>
          </div>`;
        }
      }
      body+='</div>';
    });

    host.innerHTML=`
      <section class="v556-selected">
        <div>
          <span>VALD VÄG</span>
          <strong>${E(s.subject||s.programName||p?.name||'Studieplan')}</strong>
          <small>${E(s.university||p?.university||'')}</small>
        </div>
        <button type="button" class="ghost" onclick="window.__v549NewPlan?.()">Ändra</button>
      </section>

      <section class="v556-summary">
        <div><strong>${F(credited)} hp</strong><span>kan räknas in</span></div>
        <div><strong>${F(remaining)} hp</strong><span>kvar</span></div>
      </section>

      <section class="detail-block v556-plan">
        <div class="v556-head">
          <div><h2>Din studieplan</h2><p>Ordinarie väg med möjliga snabbare alternativ.</p></div>
          ${altCount?`<span>⚡ ${altCount} genväg${altCount===1?'':'ar'}</span>`:''}
        </div>
        ${body}
        <p class="v556-note">Tillgodoräknanden och alternativa kurser är preliminära tills universitetet fattat beslut.</p>
      </section>`;
  }

  // Override only the clean planner render lifecycle, not navigation.
  document.addEventListener('studielots:screen-rendered',e=>{
    if(e?.detail?.screen==='plannerClean')requestAnimationFrame(render);
  });

  const priorOpen=window.openStudyPlanner;
  window.openStudyPlanner=function(){
    const r=typeof priorOpen==='function'?priorOpen.apply(this,arguments):undefined;
    requestAnimationFrame(()=>requestAnimationFrame(render));
    return r;
  };

  window.__studielotsBuild={...(window.__studielotsBuild||{}),version:'v556',
    plannerExactProgramResolution:true,
    plannerStructureFallback:true};
})();

/* v557 — planner receives a full route snapshot; no programme re-lookup after navigation */
(function(){
  const A=v=>Array.isArray(v)?v:(v?[v]:[]);
  const N=v=>Number(String(v??0).replace(',','.'))||0;
  const F=v=>N(v).toLocaleString('sv-SE',{maximumFractionDigits:1});
  const Q=s=>String(s||'').toLocaleLowerCase('sv-SE')
    .normalize('NFD').replace(/[\u0300-\u036f]/g,'')
    .replace(/[^a-z0-9åäö]+/g,' ').trim();
  const E=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));

  function readSelection(){
    try{return JSON.parse(sessionStorage.getItem('studielots_planner_selection')||'{}')}catch(e){return{}}
  }

  function visibleTotals(){
    const active=document.querySelector('.screen.active')?.id||'';
    const host=active==='universityDetail'
      ? document.getElementById('universityDetailContent')
      : active==='programMatch'
        ? document.getElementById('programMatchResult')
        : null;
    if(!host)return null;
    const txt=host.innerText||'';
    let m=txt.match(/([0-9]+(?:[,.][0-9]+)?)\s*hp\s*kan räknas\s*[·\-]\s*([0-9]+(?:[,.][0-9]+)?)\s*hp\s*kvar/i);
    if(!m)m=txt.match(/Tillgodoräknat\s*([0-9]+(?:[,.][0-9]+)?)\s*hp[\s\S]*?Kvar\s*([0-9]+(?:[,.][0-9]+)?)\s*hp/i);
    return m?{creditedHp:N(m[1]),remainingHp:N(m[2])}:null;
  }

  function currentOpportunity(){
    let key='',profile='',o=null,path=null;
    try{
      key=sessionStorage.getItem('lotsen_detail_key')||'';
      profile=sessionStorage.getItem('lotsen_preferred_profile')||'';
      if(key&&typeof opportunityByKey==='function')o=opportunityByKey(key);
      if(typeof studyPlanPathForProfile==='function'){
        path=studyPlanPathForProfile(profile,o?.subject||'');
      }
      if(!path&&typeof bestV21Path==='function'){
        path=bestV21Path(profile,o?.subject||'');
      }
    }catch(e){}
    return {key,profile,o,path};
  }

  function selectedProgram(){
    let id='',p=null;
    try{
      id=sessionStorage.getItem('lotsen_selected_program')||'';
      p=A(window.programCatalog).find(x=>String(x.id||'')===String(id));
    }catch(e){}
    return p;
  }

  function rowsFrom(program,path){
    const out=[],seen=new Set();
    const add=(x,t)=>{
      if(!x||N(x.hp)<=0)return;
      const key=Q(x.code||x.name||x.title||x.label)+'|'+N(x.hp)+'|'+(x.term||x.semester||x.year||t||'');
      if(seen.has(key))return;
      seen.add(key);
      out.push({
        name:x.name||x.title||x.label||'Kurs',
        code:x.code||x.courseCode||'',
        hp:N(x.hp),
        subject:x.subject||x.mainField||'',
        level:x.level||x.progression||x.educationLevel||'',
        term:Number(x.term||x.semester||x.year||t)||null,
        distance:x.distance===true,
        startDate:x.startDate||x.courseStart||x.nextStart||'',
        nextOffering:x.nextOffering||'',
        applicationOpen:x.applicationOpen===true,
        equivalentTo:x.equivalentTo||x.equivalents||x.replaces||null
      });
    };

    A(program?.courses).forEach(x=>add(x));
    ['verifiedOverviewCourses','courseStructure','programStructure','programmeStructure','requiredCourses'].forEach(k=>{
      const v=program?.[k];
      if(Array.isArray(v))v.forEach(x=>add(x));
      else if(v&&typeof v==='object'){
        Object.entries(v).forEach(([t,xs])=>A(xs).forEach(x=>add(x,t.match(/\d+/)?.[0])));
      }
    });

    if(!out.length){
      ['courses','courseStructure','requiredCourses','requirements'].forEach(k=>{
        const v=path?.[k];
        if(Array.isArray(v))v.forEach(x=>add(x));
        else if(v&&typeof v==='object'){
          Object.entries(v).forEach(([t,xs])=>A(xs).forEach(x=>add(x,t.match(/\d+/)?.[0])));
        }
      });
    }

    // Include the complete required structure when that's what the path carries.
    if(!out.length)A(path?.requiredMissing).forEach(x=>add(x));

    return out.sort((a,b)=>(a.term||99)-(b.term||99));
  }

  function knownMatches(totals){
    try{
      const c=window.__studielotsCanonicalMatch?.current?.();
      if(c && totals &&
         Math.abs(N(c.creditedHp)-N(totals.creditedHp))<.01 &&
         Math.abs(N(c.remainingHp)-N(totals.remainingHp))<.01){
        return A(c.matches).map(x=>({
          targetName:x.requirement?.name||x.requirement?.title||'',
          targetCode:x.requirement?.code||'',
          sourceName:x.source?.name||x.source?.title||'',
          sourceUniversity:x.source?.university||x.source?.institution||'',
          hp:N(x.hp)
        }));
      }
    }catch(e){}
    return [];
  }

  function makeSnapshot(){
    const active=document.querySelector('.screen.active')?.id||'';
    let selection=readSelection(),program=null,path=null;

    if(active==='universityDetail'){
      const cur=currentOpportunity();
      path=cur.path;
      program=path?.program||null;
      selection={
        source:'opportunity',
        profileId:cur.profile,
        opportunityKey:cur.key,
        subject:cur.o?.subject||path?.subject||program?.subject||selection.subject||'',
        university:path?.provider||program?.university||selection.university||'',
        programId:program?.id||selection.programId||'',
        programCode:program?.code||selection.programCode||'',
        programName:program?.name||selection.programName||''
      };
    }else if(active==='programMatch'){
      program=selectedProgram();
      selection={
        source:'program',
        programId:program?.id||selection.programId||'',
        programCode:program?.code||program?.officialCode||selection.programCode||'',
        programName:program?.name||selection.programName||'',
        university:program?.university||selection.university||'',
        subject:program?.subject||program?.track||selection.subject||''
      };
      path={program,provider:program?.university||''};
    }else{
      // Build from saved selection if called from bottom nav.
      const cur=currentOpportunity();
      if(selection.source==='opportunity'&&cur.path){
        path=cur.path;program=cur.path.program||null;
      }else if(selection.source==='program'){
        program=A(window.programCatalog).find(x=>
          (selection.programId&&String(x.id||'')===String(selection.programId)) ||
          (selection.programCode&&String(x.code||x.officialCode||'')===String(selection.programCode))
        )||null;
        path={program,provider:program?.university||selection.university||''};
      }
    }

    const totals=visibleTotals()||(()=>{
      try{
        const old=JSON.parse(sessionStorage.getItem('studielots_planner_clean_handoff')||'null');
        if(old)return {creditedHp:N(old.creditedHp),remainingHp:N(old.remainingHp)};
      }catch(e){}
      return null;
    })();

    const rows=rowsFrom(program,path);
    const snap={
      version:'v557',
      selection,
      creditedHp:N(totals?.creditedHp),
      remainingHp:Number.isFinite(Number(totals?.remainingHp))
        ? N(totals.remainingHp)
        : Math.max(0,(N(program?.hp)||rows.reduce((s,x)=>s+N(x.hp),0))-N(totals?.creditedHp)),
      totalHp:N(program?.hp)||rows.reduce((s,x)=>s+N(x.hp),0),
      program:{
        id:program?.id||selection.programId||'',
        code:program?.code||program?.officialCode||selection.programCode||'',
        name:program?.name||selection.programName||selection.subject||'',
        university:program?.university||selection.university||''
      },
      rows,
      matches:knownMatches(totals)
    };

    try{
      sessionStorage.setItem('studielots_planner_selection',JSON.stringify(selection));
      sessionStorage.setItem('studielots_planner_snapshot',JSON.stringify(snap));
    }catch(e){}
    return snap;
  }

  function snapshot(){
    try{return JSON.parse(sessionStorage.getItem('studielots_planner_snapshot')||'null')}catch(e){return null}
  }

  function matchMaps(s){
    const code=new Map(),name=new Map();
    A(s?.matches).forEach(m=>{
      if(Q(m.targetCode))code.set(Q(m.targetCode),m);
      if(Q(m.targetName))name.set(Q(m.targetName),m);
    });
    return {code,name};
  }

  function faster(req,path,used){
    if(typeof window.bestFasterAlternative!=='function')return null;
    try{
      const hit=window.bestFasterAlternative(req,path,used);
      const c=hit?.course;
      if(!c)return null;
      const id=Q(c.code)||`${Q(c.name)}|${N(c.hp)}`;
      if(!id||used.has(id))return null;
      used.add(id);
      return {hit,course:c};
    }catch(e){return null}
  }

  function render(){
    if(document.querySelector('.screen.active')?.id!=='plannerClean')return;
    const host=document.getElementById('plannerCleanContent');
    if(!host)return;

    let s=snapshot();
    if(!s||!A(s.rows).length){
      s=makeSnapshot();
    }

    if(!s||!A(s.rows).length){
      host.innerHTML='<div class="detail-block"><h2>Studieplan</h2><p>StudieLots saknar ännu själva kursstrukturen för den valda vägen. Välj vägen från Möjligheter eller Program igen så sparas hela strukturen direkt till Planeraren.</p></div>';
      return;
    }

    const mm=matchMaps(s),usedAlt=new Set();
    const path={provider:s.program?.university||s.selection?.university||'',program:{
      ...s.program,
      courses:A(s.rows).map(r=>({...r,_term:r.term}))
    }};

    let term=null,body='',altCount=0;
    A(s.rows).forEach((r,i)=>{
      const t=r.term||Math.floor(i/2)+1;
      if(t!==term){
        term=t;
        body+=`<div class="v557-term"><strong>Termin ${term}</strong></div>`;
      }
      const m=(Q(r.code)&&mm.code.get(Q(r.code)))||mm.name.get(Q(r.name))||null;

      body+=`<div class="v557-course ${m?'credit':''}">
        <div class="v557-main">
          <div>
            <strong>${E(r.name)}</strong>
            <small>${m?'Kan tillgodoräknas':'Återstår att läsa'}</small>
            ${m?.sourceName?`<em>${E(m.sourceName)}${m.sourceUniversity?` · ${E(m.sourceUniversity)}`:''}</em>`:''}
          </div>
          <b>${F(r.hp)} hp</b>
        </div>`;

      if(!m){
        const alt=faster(r,path,usedAlt);
        if(alt){
          altCount++;
          body+=`<div class="v557-alt">
            <span>${alt.hit?.verifiedEquivalent?'VERIFIERAT SNABBARE ALTERNATIV':'MÖJLIGT SNABBARE ALTERNATIV'}</span>
            <div><strong>${E(alt.course.name||alt.course.title||'Alternativ kurs')}</strong><b>${F(alt.course.hp)} hp</b></div>
          </div>`;
        }
      }
      body+='</div>';
    });

    host.innerHTML=`
      <section class="v557-selected">
        <div>
          <span>VALD VÄG</span>
          <strong>${E(s.selection?.subject||s.program?.name||'Studieplan')}</strong>
          <small>${E(s.program?.university||s.selection?.university||'')}</small>
        </div>
        <button type="button" class="ghost" onclick="window.__v549NewPlan?.()">Ändra</button>
      </section>

      <section class="v557-summary">
        <div><strong>${F(s.creditedHp)} hp</strong><span>kan räknas in</span></div>
        <div><strong>${F(s.remainingHp)} hp</strong><span>kvar</span></div>
      </section>

      <section class="detail-block v557-plan">
        <div class="v557-head">
          <div><h2>Din studieplan</h2><p>Ordinarie väg med möjliga snabbare alternativ.</p></div>
          ${altCount?`<span>⚡ ${altCount} genväg${altCount===1?'':'ar'}</span>`:''}
        </div>
        ${body}
        <p class="v557-note">Tillgodoräknanden och alternativa kurser är preliminära tills universitetet fattat beslut.</p>
      </section>`;
  }

  // Capture the complete route BEFORE the old CTA navigates away.
  document.addEventListener('click',e=>{
    const b=e.target.closest?.('button');
    if(!b)return;
    if(/Skapa plan i Planeraren/i.test(b.innerText||b.textContent||'')){
      makeSnapshot();
    }
  },true);

  const priorOpen=window.openStudyPlanner;
  window.openStudyPlanner=function(){
    if(!snapshot()||!A(snapshot()?.rows).length)makeSnapshot();
    const r=typeof priorOpen==='function'?priorOpen.apply(this,arguments):undefined;
    requestAnimationFrame(()=>requestAnimationFrame(render));
    return r;
  };

  document.addEventListener('studielots:screen-rendered',e=>{
    if(e?.detail?.screen==='plannerClean')requestAnimationFrame(render);
  });

  window.__studielotsBuild={...(window.__studielotsBuild||{}),version:'v557',
    plannerRouteSnapshot:true,
    noProgrammeLookupAfterNavigation:true};
})();

/* v558 — final planner flow: snapshot → full plan → faster alternatives */
(function(){
  const A=v=>Array.isArray(v)?v:(v?[v]:[]);
  const N=v=>Number(String(v??0).replace(',','.'))||0;
  const F=v=>N(v).toLocaleString('sv-SE',{maximumFractionDigits:1});
  const Q=s=>String(s||'').toLocaleLowerCase('sv-SE')
    .normalize('NFD').replace(/[\u0300-\u036f]/g,'')
    .replace(/[^a-z0-9åäö]+/g,' ').trim();
  const E=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));

  function snap(){
    try{return JSON.parse(sessionStorage.getItem('studielots_planner_snapshot')||'null')}catch(e){return null}
  }

  function maps(s){
    const code=new Map(),name=new Map();
    A(s?.matches).forEach(m=>{
      if(Q(m.targetCode))code.set(Q(m.targetCode),m);
      if(Q(m.targetName))name.set(Q(m.targetName),m);
    });
    return {code,name};
  }

  function courseKey(c){
    return Q(c?.code)||`${Q(c?.name)}|${N(c?.hp)}`;
  }

  function faster(req,path,used){
    if(typeof window.bestFasterAlternative!=='function')return null;
    try{
      const hit=window.bestFasterAlternative(req,path,used);
      const c=hit?.course||null;
      if(!c)return null;
      const id=courseKey(c);
      if(!id||used.has(id))return null;
      used.add(id);
      return {hit,course:c};
    }catch(e){return null}
  }

  function offeringMeta(c){
    const bits=[];
    if(c?.term||c?.semester)bits.push(String(c.term||c.semester).toUpperCase());
    if(c?.distance===true)bits.push('Distans');
    try{
      if(typeof courseApplicationOpen==='function'&&courseApplicationOpen(c))bits.push('Ansökan öppen');
    }catch(e){}
    return bits.join(' · ');
  }

  function courseUrl(c){
    try{
      if(typeof antagningCourseUrl==='function'){
        const u=antagningCourseUrl(c);
        if(u)return u;
      }
    }catch(e){}
    return c?.url||c?.applicationUrl||'';
  }

  function render(){
    if(document.querySelector('.screen.active')?.id!=='plannerClean')return;
    const host=document.getElementById('plannerCleanContent');
    if(!host)return;

    const s=snap();
    if(!s||!A(s.rows).length){
      host.innerHTML='<div class="detail-block"><h2>Studieplan</h2><p>Ingen komplett studieplan är sparad ännu. Välj en examen eller ett program och tryck på “Skapa plan i Planeraren”.</p></div>';
      return;
    }

    const mm=maps(s);
    const usedAlternatives=new Set();
    const path={
      provider:s.program?.university||s.selection?.university||'',
      program:{
        id:s.program?.id||'',
        code:s.program?.code||'',
        name:s.program?.name||'',
        university:s.program?.university||'',
        courses:A(s.rows)
      }
    };

    let body='',term=null,altCount=0,verifiedAltCount=0;
    A(s.rows).forEach((r,i)=>{
      const currentTerm=r.term||Math.floor(i/2)+1;
      if(currentTerm!==term){
        term=currentTerm;
        body+=`<div class="v558-term"><div><strong>Termin ${term}</strong></div></div>`;
      }

      const match=(Q(r.code)&&mm.code.get(Q(r.code)))||mm.name.get(Q(r.name))||null;

      body+=`<div class="v558-course ${match?'credit':''}">
        <div class="v558-course-main">
          <div>
            <strong>${E(r.name||'Kurs')}</strong>
            <small>${match?'Kan tillgodoräknas':'Återstår att läsa'}</small>
            ${match?.sourceName?`<em>${E(match.sourceName)}${match.sourceUniversity?` · ${E(match.sourceUniversity)}`:''}</em>`:''}
          </div>
          <b>${F(r.hp)} hp</b>
        </div>`;

      if(!match){
        const alt=faster(r,path,usedAlternatives);
        if(alt){
          altCount++;
          if(alt.hit?.verifiedEquivalent)verifiedAltCount++;
          const label=alt.hit?.verifiedEquivalent
            ? (alt.hit?.distance?'VERIFIERAT DISTANSALTERNATIV':'VERIFIERAT SNABBARE ALTERNATIV')
            : (alt.hit?.distance?'MÖJLIGT DISTANSALTERNATIV':'MÖJLIGT SNABBARE ALTERNATIV');
          const url=courseUrl(alt.course);
          body+=`<div class="v558-alt ${alt.hit?.verifiedEquivalent?'verified':''}">
            <span>${label}</span>
            <div class="v558-alt-title">
              <strong>${E(alt.course.name||alt.course.title||'Alternativ kurs')}</strong>
              <b>${F(alt.course.hp)} hp</b>
            </div>
            ${offeringMeta(alt.course)?`<small>${E(offeringMeta(alt.course))}</small>`:''}
            ${alt.hit?.reason?`<small>${E(alt.hit.reason)}</small>`:''}
            ${url?`<a href="${E(url)}" target="_blank" rel="noopener">Visa kurs ↗</a>`:''}
          </div>`;
        }
      }

      body+='</div>';
    });

    const optimized=altCount?`
      <div class="v558-optimized">
        <span>OPTIMERAD</span>
        <strong>⚡ ${altCount} ${altCount===1?'möjlig genväg':'möjliga genvägar'} hittad${altCount===1?'':'e'}</strong>
        <small>${verifiedAltCount?`${verifiedAltCount} verifierad${verifiedAltCount===1?'':'e'} motsvarighet${verifiedAltCount===1?'':'er'}. `:''}Alternativ visas bara där motorn hittar en konkret möjlighet att korta vägen.</small>
      </div>`:'';

    host.innerHTML=`
      <section class="v558-selected">
        <div>
          <span>VALD VÄG</span>
          <strong>${E(s.selection?.subject||s.program?.name||'Studieplan')}</strong>
          <small>${E(s.program?.university||s.selection?.university||'')}</small>
        </div>
        <button type="button" class="ghost" onclick="window.__v549NewPlan?.()">Ändra</button>
      </section>

      <section class="v558-summary">
        <div><strong>${F(s.creditedHp)} hp</strong><span>kan räknas in</span></div>
        <div><strong>${F(s.remainingHp)} hp</strong><span>kvar</span></div>
      </section>

      <section class="detail-block v558-plan">
        <div class="v558-head">
          <div>
            <div class="eyebrow">PLANERAREN</div>
            <h2>Din studieplan</h2>
            <p>Ordinarie väg med möjliga snabbare alternativ.</p>
          </div>
          <span>${F(s.remainingHp)} hp kvar</span>
        </div>
        ${optimized}
        ${body}
        <p class="v558-note">Tillgodoräknanden och alternativa kurser är preliminära tills universitetet fattat beslut. Samma alternativkurs används aldrig för mer än ett krav.</p>
      </section>`;
  }

  // This renderer runs last on the clean planner screen.
  document.addEventListener('studielots:screen-rendered',e=>{
    if(e?.detail?.screen==='plannerClean'){
      requestAnimationFrame(()=>requestAnimationFrame(render));
    }
  });

  const priorOpen=window.openStudyPlanner;
  window.openStudyPlanner=function(){
    const r=typeof priorOpen==='function'?priorOpen.apply(this,arguments):undefined;
    requestAnimationFrame(()=>requestAnimationFrame(()=>requestAnimationFrame(render)));
    return r;
  };

  window.__studielotsBuild={...(window.__studielotsBuild||{}),version:'v558',
    snapshotPlannerFinal:true,
    fullTermPlan:true,
    fasterAlternativesInPlan:true};
})();

/* v559 — GU Psychology degree-rule engine */
(function(){
  const N=v=>Number(String(v??0).replace(',','.'))||0;
  const A=v=>Array.isArray(v)?v:(v?[v]:[]);
  const Q=s=>String(s||'').toLocaleLowerCase('sv-SE')
    .normalize('NFD').replace(/[\u0300-\u036f]/g,'')
    .replace(/[^a-z0-9åäö]+/g,' ').trim();

  const GU_PSYCH={
    id:'gu-psychology-bachelor-2026',
    university:'Göteborgs universitet',
    subject:'Psykologi',
    degree:'Filosofie kandidatexamen',
    totalHp:180,
    electiveHp:90,
    source:'Göteborgs universitets examensbeskrivning',
    requirements:[
      {code:'PX1100',name:'Psykologi: Grundkurs',hp:30,term:1},
      {code:'PX1200',name:'Psykologi: Fortsättningskurs',hp:30,term:2,prereq:['PX1100']},
      {code:'PX1500',name:'Psykologi: Forskningsmetod och kandidatuppsats',hp:30,term:3,prereq:['PX1100','PX1200'],thesisHp:15,methodHp:15}
    ]
  };
  window.STUDIELOTS_VERIFIED_DEGREE_RULES=window.STUDIELOTS_VERIFIED_DEGREE_RULES||{};
  window.STUDIELOTS_VERIFIED_DEGREE_RULES[GU_PSYCH.id]=GU_PSYCH;

  function importedCourses(){
    const pools=[
      window.importedCourses, window.courses, window.merits,
      window.appState?.courses, window.state?.courses,
      window.__studielotsState?.courses
    ];
    for(const p of pools) if(Array.isArray(p)&&p.length)return p;
    try{
      for(const k of Object.keys(localStorage)){
        const v=JSON.parse(localStorage.getItem(k)||'null');
        if(Array.isArray(v)&&v.length&&v.some(x=>x&&('hp'in x||'credits'in x)&&('name'in x||'title'in x)))return v;
        if(Array.isArray(v?.courses)&&v.courses.length)return v.courses;
      }
    }catch(e){}
    return [];
  }
  function code(c){return Q(c?.code||c?.courseCode||c?.kurskod)}
  function name(c){return Q(c?.name||c?.title||c?.courseName||c?.kursnamn)}
  function hp(c){return N(c?.hp||c?.credits||c?.points)}
  function isPassed(c){
    const s=Q(c?.status||c?.grade||c?.result||'godkand');
    return !/(underkand|fail|ej godkand|u$)/.test(s);
  }
  function exactReq(c,r){
    if(code(c)===Q(r.code))return true;
    return name(c)===Q(r.name);
  }
  function build(){
    const all=importedCourses().filter(isPassed);
    const used=new Set();
    const rows=[];
    let core=0;

    for(const r of GU_PSYCH.requirements){
      const ix=all.findIndex((c,i)=>!used.has(i)&&exactReq(c,r));
      if(ix>=0){
        used.add(ix); core+=Math.min(r.hp,hp(all[ix])||r.hp);
        rows.push({...r,status:'credited',sourceName:all[ix].name||all[ix].title||r.name,sourceUniversity:all[ix].university||all[ix].institution||''});
      }else{
        rows.push({...r,status:'remaining'});
      }
    }

    // Any other passed higher-education courses can fill the 90 hp elective block,
    // capped at 90 hp. This is degree inclusion, not program-course equivalence.
    let electiveUsed=0;
    const electives=[];
    all.forEach((c,i)=>{
      if(used.has(i)||electiveUsed>=GU_PSYCH.electiveHp)return;
      const take=Math.min(hp(c),GU_PSYCH.electiveHp-electiveUsed);
      if(take>0){
        electiveUsed+=take;
        electives.push({name:c.name||c.title||'Valfri kurs',hp:take,status:'credited',
          sourceName:c.name||c.title||'',sourceUniversity:c.university||c.institution||''});
      }
    });

    const credited=Math.min(GU_PSYCH.totalHp,core+electiveUsed);
    const remaining=GU_PSYCH.totalHp-credited;

    // Add a single elective remainder block rather than inventing courses.
    if(electiveUsed<GU_PSYCH.electiveHp){
      rows.push({name:'Valfria kurser',hp:GU_PSYCH.electiveHp-electiveUsed,term:4,status:'remaining',
        note:'Kan fyllas med valfria högskolekurser.'});
    }
    // Imported electives are shown as already included.
    electives.forEach((e,i)=>rows.push({...e,term:4+Math.floor(i/4)}));

    return {rows,creditedHp:credited,remainingHp:remaining,coreHp:core,electiveHp:electiveUsed};
  }

  window.buildGuPsychologyDegreePlan=function(){
    const b=build();
    const snapshot={
      version:'v559',
      type:'degree',
      verifiedRule:true,
      ruleId:GU_PSYCH.id,
      selection:{subject:'Psykologi',university:'Göteborgs universitet',degree:'Filosofie kandidatexamen'},
      program:{id:GU_PSYCH.id,name:'Filosofie kandidatexamen i psykologi',university:'Göteborgs universitet'},
      rows:b.rows,
      creditedHp:b.creditedHp,
      remainingHp:b.remainingHp,
      degreeBreakdown:{psychologyCore:b.coreHp,electives:b.electiveHp},
      wording:{credited:'Kan räknas in i examen',remaining:'Återstår'}
    };
    sessionStorage.setItem('studielots_planner_snapshot',JSON.stringify(snapshot));
    return snapshot;
  };

  // Intercept the GU free-standing Psychology degree route before old fuzzy matching.
  document.addEventListener('click',function(e){
    const el=e.target.closest('button,a');
    if(!el)return;
    const txt=Q(el.textContent);
    const page=Q(document.body.innerText.slice(0,7000));
    const guPsych=page.includes('goteborgs universitet')&&page.includes('psykologi')&&
      (page.includes('fristaende vag')||page.includes('kandidatexamen i psykologi'));
    if(!guPsych)return;
    if(txt.includes('skapa plan')||txt.includes('planeraren')){
      window.buildGuPsychologyDegreePlan();
    }
  },true);

  window.__studielotsBuild={...(window.__studielotsBuild||{}),version:'v559',
    guPsychologyVerifiedDegreeRule:true,
    degreeVsProgramWording:true,
    electiveCap90:true,
    noFuzzyGuPsychDegreeCredit:true};
})();

/* v560 — GU verified degree framework + Business Administration */
(function(){
  const A=v=>Array.isArray(v)?v:(v?[v]:[]);
  const N=v=>Number(String(v??0).replace(',','.'))||0;
  const Q=s=>String(s||'').toLocaleLowerCase('sv-SE').normalize('NFD')
    .replace(/[\u0300-\u036f]/g,'').replace(/[^a-z0-9åäö]+/g,' ').trim();

  const RULE={
    id:'gu-business-administration-ekonomie-bachelor-2026',
    university:'Göteborgs universitet',
    subject:'Företagsekonomi',
    degree:'Ekonomie kandidatexamen',
    totalHp:180,
    requirements:[
      {key:'business',label:'Företagsekonomi',hp:90,thesisHp:15},
      {key:'economics',label:'Nationalekonomi',hp:30},
      {key:'statistics',label:'Statistik',hp:15},
      {key:'elective',label:'Valfria kurser',hp:45}
    ]
  };
  window.STUDIELOTS_VERIFIED_DEGREE_RULES=window.STUDIELOTS_VERIFIED_DEGREE_RULES||{};
  window.STUDIELOTS_VERIFIED_DEGREE_RULES[RULE.id]=RULE;

  function courses(){
    const pools=[window.importedCourses,window.courses,window.merits,
      window.appState?.courses,window.state?.courses,window.__studielotsState?.courses];
    for(const p of pools)if(Array.isArray(p)&&p.length)return p;
    try{
      for(const k of Object.keys(localStorage)){
        const v=JSON.parse(localStorage.getItem(k)||'null');
        if(Array.isArray(v?.courses)&&v.courses.length)return v.courses;
        if(Array.isArray(v)&&v.some(x=>x&&('hp'in x||'credits'in x)&&('name'in x||'title'in x)))return v;
      }
    }catch(e){}
    return [];
  }
  const hp=c=>N(c?.hp||c?.credits||c?.points);
  const nm=c=>Q(c?.name||c?.title||c?.courseName||c?.kursnamn);
  const subj=c=>Q(c?.subject||c?.subjectName||c?.mainField||c?.huvudomrade);
  const passed=c=>!/(underkand|fail|ej godkand)/.test(Q(c?.status||c?.grade||c?.result||'godkand'));

  function bucket(c){
    const s=subj(c),n=nm(c);
    if(/foretagsekonomi|business administration|business studies/.test(s+' '+n))return'business';
    if(/nationalekonomi|economics/.test(s+' '+n)&&!/business/.test(s+' '+n))return'economics';
    if(/statistik|statistics/.test(s+' '+n))return'statistics';
    return'elective';
  }
  function thesis(c){
    const x=nm(c);
    return /(kandidatuppsats|examensarbete|bachelor thesis|degree project)/.test(x);
  }

  window.buildGuBusinessDegreePlan=function(){
    const all=courses().filter(passed), caps={business:90,economics:30,statistics:15,elective:45};
    const used={business:0,economics:0,statistics:0,elective:0}, rows=[], leftovers=[];
    let thesisHp=0;

    // First fill subject-specific requirements. Anything beyond their caps becomes elective.
    all.forEach(c=>{
      let b=bucket(c), amount=hp(c);
      if(!amount)return;
      if(b!=='elective'){
        const take=Math.min(amount,Math.max(0,caps[b]-used[b]));
        if(take){
          used[b]+=take;
          rows.push({name:c.name||c.title||RULE.requirements.find(r=>r.key===b)?.label,hp:take,
            term:Math.max(1,Math.ceil(rows.length/2)),status:'credited',degreeBucket:b,
            sourceUniversity:c.university||c.institution||''});
          if(b==='business'&&thesis(c))thesisHp+=Math.min(take,15);
        }
        amount-=take;
      }
      if(amount>0)leftovers.push({...c,__remainingHp:amount});
    });

    // Elective block may be filled by any unused passed higher-education credits.
    leftovers.forEach(c=>{
      if(used.elective>=caps.elective)return;
      const take=Math.min(c.__remainingHp||hp(c),caps.elective-used.elective);
      if(take){
        used.elective+=take;
        rows.push({name:c.name||c.title||'Valfri kurs',hp:take,term:5,status:'credited',
          degreeBucket:'elective',sourceUniversity:c.university||c.institution||''});
      }
    });

    // Never claim the business main field is complete without a 15 hp thesis.
    const missing=[];
    RULE.requirements.forEach((r,i)=>{
      const left=Math.max(0,r.hp-used[r.key]);
      if(left)missing.push({name:r.label,hp:left,term:i<3?i+1:5,status:'remaining',degreeBucket:r.key});
    });
    if(used.business>=90 && thesisHp<15){
      // Reclassify 15 hp of the apparent business completion as unresolved thesis requirement.
      used.business=75;
      missing.push({name:'Kandidatuppsats i företagsekonomi',hp:15,term:6,status:'remaining',
        degreeBucket:'business',note:'Självständigt arbete inom huvudområdet krävs.'});
    }

    const credited=Math.min(180,used.business+used.economics+used.statistics+used.elective);
    const snap={
      version:'v560',type:'degree',verifiedRule:true,ruleId:RULE.id,
      selection:{subject:'Företagsekonomi',university:RULE.university,degree:RULE.degree},
      program:{id:RULE.id,name:'Ekonomie kandidatexamen med huvudområde företagsekonomi',university:RULE.university},
      rows:[...rows,...missing],creditedHp:credited,remainingHp:180-credited,
      degreeBreakdown:{...used,thesisHp},
      wording:{credited:'Kan räknas in i examen',remaining:'Återstår'}
    };
    sessionStorage.setItem('studielots_planner_snapshot',JSON.stringify(snap));
    return snap;
  };

  // Use the verified GU rule on the free-standing Business Administration degree route.
  document.addEventListener('click',e=>{
    const el=e.target.closest('button,a'); if(!el)return;
    const t=Q(el.textContent),p=Q(document.body.innerText.slice(0,7000));
    if((t.includes('skapa plan')||t.includes('planeraren')) &&
       p.includes('goteborgs universitet') && p.includes('foretagsekonomi') &&
       (p.includes('ekonomie kandidat')||p.includes('fristaende vag'))){
      window.buildGuBusinessDegreePlan();
    }
  },true);

  window.__studielotsBuild={...(window.__studielotsBuild||{}),version:'v560',
    guBusinessVerifiedDegreeRule:true,degreeFramework:true,thesisGuard:true,
    electiveOverflowReuse:true};
})();

/* v561 — GU Sport Science verified generic bachelor rule */
(function(){
  const Q=s=>String(s||'').toLocaleLowerCase('sv-SE').normalize('NFD')
    .replace(/[\u0300-\u036f]/g,'').replace(/[^a-z0-9åäö]+/g,' ').trim();
  const N=v=>Number(String(v??0).replace(',','.'))||0;

  const RULE={id:'gu-sport-science-bachelor-2026',university:'Göteborgs universitet',
    subject:'Idrottsvetenskap',degree:'Filosofie kandidatexamen',totalHp:180,
    mainFieldHp:90,thesisHp:15,electiveHp:90};
  window.STUDIELOTS_VERIFIED_DEGREE_RULES=window.STUDIELOTS_VERIFIED_DEGREE_RULES||{};
  window.STUDIELOTS_VERIFIED_DEGREE_RULES[RULE.id]=RULE;

  function courses(){
    const p=[window.importedCourses,window.courses,window.merits,window.appState?.courses,
      window.state?.courses,window.__studielotsState?.courses];
    for(const x of p)if(Array.isArray(x)&&x.length)return x;
    try{for(const k of Object.keys(localStorage)){const v=JSON.parse(localStorage.getItem(k)||'null');
      if(Array.isArray(v?.courses)&&v.courses.length)return v.courses;
      if(Array.isArray(v)&&v.some(c=>c&&('hp'in c||'credits'in c)))return v;}}catch(e){}
    return [];
  }
  const hp=c=>N(c?.hp||c?.credits||c?.points);
  const nm=c=>Q(c?.name||c?.title||c?.courseName||c?.kursnamn);
  const sj=c=>Q(c?.subject||c?.subjectName||c?.mainField||c?.huvudomrade);
  const passed=c=>!/(underkand|fail|ej godkand)/.test(Q(c?.status||c?.grade||c?.result||'godkand'));
  const sport=c=>/(idrottsvetenskap|sport science|sports coaching|idrott|tranarskap)/.test(sj(c)+' '+nm(c));
  const thesis=c=>/(kandidatuppsats|examensarbete|bachelor thesis|degree project)/.test(nm(c));

  window.buildGuSportScienceDegreePlan=function(){
    const all=courses().filter(passed),rows=[],main=[],other=[];
    all.forEach(c=>(sport(c)?main:other).push(c));
    let mainUsed=0,thesisUsed=0,electiveUsed=0;

    main.forEach(c=>{
      if(mainUsed>=90){other.push(c);return}
      const take=Math.min(hp(c),90-mainUsed); if(!take)return;
      mainUsed+=take;if(thesis(c))thesisUsed+=Math.min(take,15);
      rows.push({name:c.name||c.title||'Idrottsvetenskap',hp:take,term:Math.max(1,Math.ceil(rows.length/2)),
        status:'credited',degreeBucket:'main',sourceUniversity:c.university||c.institution||''});
      if(hp(c)>take)other.push({...c,hp:hp(c)-take});
    });
    other.forEach(c=>{
      if(electiveUsed>=90)return;
      const take=Math.min(hp(c),90-electiveUsed);if(!take)return;
      electiveUsed+=take;
      rows.push({name:c.name||c.title||'Valfri kurs',hp:take,term:4+Math.floor(rows.length/4),
        status:'credited',degreeBucket:'elective',sourceUniversity:c.university||c.institution||''});
    });

    const missing=[];
    if(mainUsed<90)missing.push({name:'Idrottsvetenskap med successiv fördjupning',hp:90-mainUsed,term:3,status:'remaining',degreeBucket:'main'});
    if(thesisUsed<15)missing.push({name:'Självständigt arbete i idrottsvetenskap',hp:15-thesisUsed,term:3,status:'remaining',
      degreeBucket:'main',note:'Minst 15 hp examensarbete inom huvudområdet krävs.'});
    if(electiveUsed<90)missing.push({name:'Övriga/valfria kurser',hp:90-electiveUsed,term:4,status:'remaining',degreeBucket:'elective'});

    // Thesis requirement is part of the 90 hp main field, not extra credits.
    const mainCredited=Math.min(mainUsed, thesisUsed>=15?90:75);
    const credited=Math.min(180,mainCredited+electiveUsed);
    const snap={version:'v561',type:'degree',verifiedRule:true,ruleId:RULE.id,
      selection:{subject:RULE.subject,university:RULE.university,degree:RULE.degree},
      program:{id:RULE.id,name:'Filosofie kandidatexamen med huvudområde idrottsvetenskap',university:RULE.university},
      rows:[...rows,...missing],creditedHp:credited,remainingHp:180-credited,
      degreeBreakdown:{mainFieldHp:mainCredited,thesisHp:thesisUsed,electiveHp:electiveUsed},
      wording:{credited:'Kan räknas in i examen',remaining:'Återstår'}};
    sessionStorage.setItem('studielots_planner_snapshot',JSON.stringify(snap));return snap;
  };

  document.addEventListener('click',e=>{
    const el=e.target.closest('button,a');if(!el)return;
    const t=Q(el.textContent),p=Q(document.body.innerText.slice(0,7000));
    if((t.includes('skapa plan')||t.includes('planeraren'))&&p.includes('goteborgs universitet')&&
       p.includes('idrottsvetenskap')&&(p.includes('kandidatexamen')||p.includes('fristaende vag'))){
      window.buildGuSportScienceDegreePlan();
    }
  },true);

  window.__studielotsBuild={...(window.__studielotsBuild||{}),version:'v561',
    guSportScienceVerifiedDegreeRule:true,sportScienceThesisGuard:true};
})();

/* v562 — one source of truth between opportunity detail and Planner */
(function(){
  const N=v=>Number(String(v??0).replace(',','.'))||0;
  const Q=s=>String(s||'').toLocaleLowerCase('sv-SE').normalize('NFD')
    .replace(/[\u0300-\u036f]/g,'').replace(/[^a-z0-9åäö]+/g,' ').trim();

  function visibleDegreeState(){
    const host=document.getElementById('universityDetailContent');
    if(!host)return null;
    const txt=host.innerText||'';
    let m=txt.match(/([0-9]+(?:[,.][0-9]+)?)\s*hp\s*kan räknas\s*[·\-]\s*([0-9]+(?:[,.][0-9]+)?)\s*hp\s*kvar(?:\/olöst)?/i);
    if(!m)m=txt.match(/Tillgodoräknat\s*([0-9]+(?:[,.][0-9]+)?)\s*hp[\s\S]*?Kvar\s*([0-9]+(?:[,.][0-9]+)?)\s*hp/i);
    if(!m)return null;
    return {creditedHp:N(m[1]),remainingHp:N(m[2]),totalHp:N(m[1])+N(m[2])};
  }

  function saveVisibleState(){
    const v=visibleDegreeState(); if(!v)return null;
    try{
      sessionStorage.setItem('studielots_visible_degree_totals',JSON.stringify(v));
      const canonical=window.__studielotsCanonicalMatch?.current?.();
      if(canonical && Math.abs(N(canonical.creditedHp)-v.creditedHp)<.01 &&
          Math.abs(N(canonical.remainingHp)-v.remainingHp)<.01){
        sessionStorage.setItem('studielots_visible_degree_matches',JSON.stringify(canonical.matches||[]));
      }else{
        sessionStorage.removeItem('studielots_visible_degree_matches');
      }
    }catch(e){}
    return v;
  }

  function forceSnapshotTotals(){
    let v=null,s=null;
    try{
      v=JSON.parse(sessionStorage.getItem('studielots_visible_degree_totals')||'null');
      s=JSON.parse(sessionStorage.getItem('studielots_planner_snapshot')||'null');
    }catch(e){}
    if(!v||!s)return;
    // The page the user just approved is authoritative for the handoff.
    s.creditedHp=N(v.creditedHp);
    s.remainingHp=N(v.remainingHp);
    s.totalHp=N(v.totalHp)||N(s.totalHp)||180;
    s.sourceOfTruth='visible-opportunity-detail';
    try{
      const matches=JSON.parse(sessionStorage.getItem('studielots_visible_degree_matches')||'[]');
      if(Array.isArray(matches)&&matches.length)s.matches=matches;
    }catch(e){}
    sessionStorage.setItem('studielots_planner_snapshot',JSON.stringify(s));
  }

  document.addEventListener('click',e=>{
    const el=e.target.closest('button,a'); if(!el)return;
    const t=Q(el.textContent);
    if(!(t.includes('skapa plan')||t.includes('planeraren')))return;
    if(document.querySelector('.screen.active')?.id!=='universityDetail')return;
    saveVisibleState();
    // Existing degree builders run in the same click. Reconcile immediately after them.
    queueMicrotask(forceSnapshotTotals);
    setTimeout(forceSnapshotTotals,0);
    setTimeout(forceSnapshotTotals,40);
  },true);

  // Also reconcile just before the clean planner paints.
  document.addEventListener('studielots:screen-rendered',e=>{
    if(e?.detail?.screen==='plannerClean')forceSnapshotTotals();
  },true);

  window.__studielotsBuild={...(window.__studielotsBuild||{}),version:'v562',
    plannerOpportunitySingleSourceOfTruth:true,
    visibleTotalsHandoff:true};
})();

/* v563 — one imported-merit source for degree engines and Planner */
(function(){
  const A=v=>Array.isArray(v)?v:(v?[v]:[]);
  const N=v=>Number(String(v??0).replace(',','.'))||0;
  const Q=s=>String(s||'').toLocaleLowerCase('sv-SE').normalize('NFD')
    .replace(/[\u0300-\u036f]/g,'').replace(/[^a-z0-9åäö]+/g,' ').trim();

  function allImportedCourses(){
    const pools=[];

    // Canonical runtime getter, when available.
    try{
      if(typeof getStoredCourses==='function')pools.push(...A(getStoredCourses()));
    }catch(e){}

    // Session import used by the current matching engine.
    try{
      pools.push(...A(JSON.parse(sessionStorage.getItem('examensmatch_courses')||'[]')));
    }catch(e){}

    // Persistent import used by the historical syllabus/import flow.
    try{
      pools.push(...A(JSON.parse(localStorage.getItem('lotsen_courses')||'[]')));
    }catch(e){}

    // Runtime aliases kept for compatibility.
    [
      window.userCourses,window.importedCourses,window.ladokCourses,
      window.courses,window.merits,window.appState?.courses,
      window.state?.courses,window.__studielotsState?.courses
    ].forEach(x=>pools.push(...A(x)));

    // Deduplicate without throwing away university or level metadata.
    const seen=new Map();
    pools.forEach(c=>{
      if(!c)return;
      const name=Q(c.name||c.title||c.courseName||c.kursnamn);
      const code=Q(c.code||c.courseCode||c.kurskod);
      const hp=N(c.hp||c.credits||c.points);
      if(!name&&!code)return;
      const key=(code||name)+'|'+hp+'|'+Q(c.university||c.institution||c.larosate);
      const prev=seen.get(key);
      if(!prev)seen.set(key,c);
      else{
        // Prefer the richer representation.
        const richness=o=>Object.values(o||{}).filter(v=>v!==null&&v!==undefined&&v!=='').length;
        if(richness(c)>richness(prev))seen.set(key,c);
      }
    });
    return [...seen.values()];
  }

  window.__studielotsImportedCourses=allImportedCourses;

  function hp(c){return N(c?.hp||c?.credits||c?.points)}
  function code(c){return Q(c?.code||c?.courseCode||c?.kurskod)}
  function name(c){return Q(c?.name||c?.title||c?.courseName||c?.kursnamn)}
  function passed(c){
    const s=Q(c?.status||c?.grade||c?.result||'godkand');
    return !/(underkand|fail|ej godkand)/.test(s);
  }

  // Rebuild GU Psychology using the real imported merit source.
  window.buildGuPsychologyDegreePlan=function(){
    const rule=window.STUDIELOTS_VERIFIED_DEGREE_RULES?.['gu-psychology-bachelor-2026'];
    if(!rule)return null;

    const all=allImportedCourses().filter(passed);
    const used=new Set(),rows=[];
    let core=0;

    A(rule.requirements).forEach(r=>{
      let best=-1;
      for(let i=0;i<all.length;i++){
        if(used.has(i))continue;
        if(code(all[i])===Q(r.code)||name(all[i])===Q(r.name)){best=i;break}
      }
      if(best>=0){
        used.add(best);
        const take=Math.min(N(r.hp),hp(all[best])||N(r.hp));
        core+=take;
        rows.push({...r,status:'credited',sourceName:all[best].name||all[best].title||r.name,
          sourceUniversity:all[best].university||all[best].institution||''});
      }else{
        rows.push({...r,status:'remaining'});
      }
    });

    let elective=0;
    all.forEach((c,i)=>{
      if(used.has(i)||elective>=90)return;
      const take=Math.min(hp(c),90-elective);
      if(take<=0)return;
      elective+=take;
      rows.push({name:c.name||c.title||'Valfri kurs',hp:take,term:4,status:'credited',
        sourceName:c.name||c.title||'',sourceUniversity:c.university||c.institution||'',
        degreeBucket:'elective'});
    });

    if(elective<90){
      rows.push({name:'Valfria kurser',hp:90-elective,term:4,status:'remaining',degreeBucket:'elective'});
    }

    const credited=Math.min(180,core+elective);
    const snap={
      version:'v563',type:'degree',verifiedRule:true,ruleId:rule.id,
      selection:{subject:'Psykologi',university:'Göteborgs universitet',degree:'Filosofie kandidatexamen'},
      program:{id:rule.id,name:'Filosofie kandidatexamen i psykologi',university:'Göteborgs universitet'},
      rows,creditedHp:credited,remainingHp:180-credited,totalHp:180,
      degreeBreakdown:{psychologyCore:core,electives:elective},
      wording:{credited:'Kan räknas in i examen',remaining:'Återstår'},
      meritSource:'v563-unified'
    };
    sessionStorage.setItem('studielots_planner_snapshot',JSON.stringify(snap));
    return snap;
  };

  function isGuPsychDetail(){
    if(document.querySelector('.screen.active')?.id!=='universityDetail')return false;
    const host=document.getElementById('universityDetailContent');
    const t=Q(host?.innerText||'');
    return t.includes('goteborgs universitet')&&t.includes('psykologi')&&
      (t.includes('fristaende vag')||t.includes('kandidatexamen i psykologi'));
  }

  function syncGuPsychDetail(){
    if(!isGuPsychDetail())return;
    const snap=window.buildGuPsychologyDegreePlan?.();
    if(!snap)return;

    const host=document.getElementById('universityDetailContent');
    if(!host)return;

    // Keep the detail page and Planner on exactly the same rule result.
    const banner=[...host.querySelectorAll('div')].find(el=>
      /hp\s*kan räknas/i.test(el.innerText||'') && /hp\s*kvar/i.test(el.innerText||'')
    );
    if(banner){
      banner.innerHTML=`<strong>${String(snap.creditedHp).replace('.',',')} hp kan räknas in i examen · ${String(snap.remainingHp).replace('.',',')} hp kvar</strong>`;
    }

    const cards=[...host.querySelectorAll('div')];
    const creditCard=cards.find(el=>/Tillgodoräknat/i.test(el.innerText||'')&&el.querySelector('strong'));
    const remainCard=cards.find(el=>/(^|\n)Kvar(\n|$)/i.test(el.innerText||'')&&el.querySelector('strong'));
    if(creditCard){
      const label=[...creditCard.querySelectorAll('*')].find(x=>/^Tillgodoräknat$/i.test((x.textContent||'').trim()));
      if(label)label.textContent='Kan räknas in i examen';
      const strong=creditCard.querySelector('strong');
      if(strong)strong.textContent=`${String(snap.creditedHp).replace('.',',')} hp`;
    }
    if(remainCard){
      const strong=remainCard.querySelector('strong');
      if(strong)strong.textContent=`${String(snap.remainingHp).replace('.',',')} hp`;
    }

    try{
      sessionStorage.setItem('studielots_visible_degree_totals',JSON.stringify({
        creditedHp:snap.creditedHp,remainingHp:snap.remainingHp,totalHp:180
      }));
    }catch(e){}
  }

  document.addEventListener('studielots:screen-rendered',e=>{
    if(e?.detail?.screen==='universityDetail')requestAnimationFrame(syncGuPsychDetail);
  });

  document.addEventListener('click',e=>{
    const b=e.target.closest('button,a');
    if(!b||!isGuPsychDetail())return;
    const t=Q(b.textContent);
    if(t.includes('skapa plan')||t.includes('planeraren')){
      const snap=window.buildGuPsychologyDegreePlan?.();
      if(snap){
        sessionStorage.setItem('studielots_visible_degree_totals',JSON.stringify({
          creditedHp:snap.creditedHp,remainingHp:snap.remainingHp,totalHp:180
        }));
      }
    }
  },true);

  window.__studielotsBuild={...(window.__studielotsBuild||{}),version:'v563',
    unifiedImportedMeritSource:true,
    guPsychDetailPlannerSameRule:true};
})();

/* v564 — global unified setup for all universities, degrees and programmes */
(function(){
  const A=v=>Array.isArray(v)?v:(v?[v]:[]);
  const N=v=>Number(String(v??0).replace(',','.'))||0;
  const Q=s=>String(s||'').toLocaleLowerCase('sv-SE').normalize('NFD')
    .replace(/[\u0300-\u036f]/g,'').replace(/[^a-z0-9åäö]+/g,' ').trim();

  /* ------------------------------------------------------------
     1. ONE merit source for the entire app
  ------------------------------------------------------------ */
  function importedMerits(){
    if(typeof window.__studielotsImportedCourses==='function'){
      try{
        const x=window.__studielotsImportedCourses();
        if(Array.isArray(x))return x;
      }catch(e){}
    }

    const pool=[];
    try{if(typeof getStoredCourses==='function')pool.push(...A(getStoredCourses()))}catch(e){}
    try{pool.push(...A(JSON.parse(sessionStorage.getItem('examensmatch_courses')||'[]')))}catch(e){}
    try{pool.push(...A(JSON.parse(localStorage.getItem('lotsen_courses')||'[]')))}catch(e){}
    [
      window.userCourses,window.importedCourses,window.ladokCourses,
      window.courses,window.merits,window.appState?.courses,
      window.state?.courses,window.__studielotsState?.courses
    ].forEach(x=>pool.push(...A(x)));

    const seen=new Map();
    pool.forEach(c=>{
      if(!c)return;
      const name=Q(c.name||c.title||c.courseName||c.kursnamn);
      const code=Q(c.code||c.courseCode||c.kurskod);
      const hp=N(c.hp||c.credits||c.points);
      const uni=Q(c.university||c.institution||c.larosate);
      if(!name&&!code)return;
      const key=(code||name)+'|'+hp+'|'+uni;
      const prev=seen.get(key);
      if(!prev)seen.set(key,c);
      else{
        const richness=o=>Object.values(o||{}).filter(v=>v!==null&&v!==undefined&&v!=='').length;
        if(richness(c)>richness(prev))seen.set(key,c);
      }
    });
    return [...seen.values()];
  }
  window.__studielotsImportedMerits=importedMerits;

  /* ------------------------------------------------------------
     2. ONE canonical result shape everywhere
  ------------------------------------------------------------ */
  function normalizeResult(raw={},ctx={}){
    const total=N(raw.totalHp||ctx.totalHp||ctx.program?.hp||180);
    const credited=Math.max(0,Math.min(total,N(raw.creditedHp||raw.possibleHp||raw.matchedHp||0)));
    const remaining=Math.max(0,Number.isFinite(Number(raw.remainingHp))
      ? N(raw.remainingHp)
      : total-credited);

    return {
      version:'v564',
      kind:ctx.kind||raw.kind||'program',
      university:ctx.university||raw.university||ctx.program?.university||'',
      subject:ctx.subject||raw.subject||ctx.program?.subject||'',
      programId:ctx.program?.id||raw.programId||'',
      programCode:ctx.program?.code||ctx.program?.officialCode||raw.programCode||'',
      programName:ctx.program?.name||raw.programName||'',
      totalHp:total,
      creditedHp:credited,
      remainingHp:remaining,
      matches:A(raw.matches),
      rows:A(raw.rows||raw.requirements||ctx.rows),
      verifiedRule:Boolean(raw.verifiedRule||ctx.verifiedRule),
      ruleId:raw.ruleId||ctx.ruleId||'',
      wording:ctx.kind==='degree'
        ? {credited:'Kan räknas in i examen',remaining:'Återstår'}
        : {credited:'Möjligt tillgodoräknande',remaining:'Återstår att läsa'}
    };
  }

  /* ------------------------------------------------------------
     3. SAME programme structure extraction everywhere
  ------------------------------------------------------------ */
  function programmeRows(program,path){
    const out=[],seen=new Set();
    const add=(x,t)=>{
      if(!x||N(x.hp)<=0)return;
      const key=Q(x.code||x.name||x.title||x.label)+'|'+N(x.hp)+'|'+(x.term||x.semester||x.year||t||'');
      if(seen.has(key))return;
      seen.add(key);
      out.push({
        name:x.name||x.title||x.label||'Kurs',
        code:x.code||x.courseCode||'',
        hp:N(x.hp),
        subject:x.subject||x.mainField||'',
        level:x.level||x.progression||x.educationLevel||'',
        term:Number(x.term||x.semester||x.year||t)||null,
        distance:x.distance===true,
        startDate:x.startDate||x.courseStart||x.nextStart||'',
        nextOffering:x.nextOffering||'',
        applicationOpen:x.applicationOpen===true
      });
    };

    A(program?.courses).forEach(x=>add(x));
    ['verifiedOverviewCourses','courseStructure','programStructure','programmeStructure','requiredCourses'].forEach(k=>{
      const v=program?.[k];
      if(Array.isArray(v))v.forEach(x=>add(x));
      else if(v&&typeof v==='object'){
        Object.entries(v).forEach(([t,xs])=>A(xs).forEach(x=>add(x,t.match(/\d+/)?.[0])));
      }
    });

    if(!out.length){
      ['courses','courseStructure','requiredCourses','requirements','requiredMissing'].forEach(k=>{
        const v=path?.[k];
        if(Array.isArray(v))v.forEach(x=>add(x));
        else if(v&&typeof v==='object'){
          Object.entries(v).forEach(([t,xs])=>A(xs).forEach(x=>add(x,t.match(/\d+/)?.[0])));
        }
      });
    }
    return out.sort((a,b)=>(a.term||99)-(b.term||99));
  }

  /* ------------------------------------------------------------
     4. SAME generic programme matching everywhere
        (verified degree engines can override this)
  ------------------------------------------------------------ */
  function genericProgramResult(program,path){
    let raw=null;
    try{
      if(typeof window.estimateProgram==='function')raw=window.estimateProgram(program);
    }catch(e){}
    if(!raw){
      try{
        if(typeof window.__studielotsEstimateAdvancedTransfer==='function'){
          const x=window.__studielotsEstimateAdvancedTransfer(program);
          raw={
            creditedHp:N(x?.possibleHp),
            remainingHp:Math.max(0,N(program?.hp)-N(x?.possibleHp)),
            matches:A(x?.matches)
          };
        }
      }catch(e){}
    }
    return normalizeResult(raw||{},{
      kind:'program',
      university:program?.university||'',
      subject:program?.subject||program?.track||'',
      program,
      rows:programmeRows(program,path),
      totalHp:N(program?.hp)
    });
  }

  /* ------------------------------------------------------------
     5. VERIFIED DEGREE RULE ROUTER
  ------------------------------------------------------------ */
  function verifiedDegreeResult(subject,university){
    const s=Q(subject),u=Q(university);

    // Existing specialised builders remain authoritative.
    try{
      if(u.includes('goteborgs universitet')&&s.includes('psykologi')&&
         typeof window.buildGuPsychologyDegreePlan==='function'){
        const x=window.buildGuPsychologyDegreePlan();
        return normalizeResult(x,{kind:'degree',verifiedRule:true,ruleId:x?.ruleId});
      }
      if(u.includes('goteborgs universitet')&&s.includes('foretagsekonomi')&&
         typeof window.buildGuBusinessDegreePlan==='function'){
        const x=window.buildGuBusinessDegreePlan();
        return normalizeResult(x,{kind:'degree',verifiedRule:true,ruleId:x?.ruleId});
      }
      if(u.includes('goteborgs universitet')&&s.includes('idrottsvetenskap')&&
         typeof window.buildGuSportScienceDegreePlan==='function'){
        const x=window.buildGuSportScienceDegreePlan();
        return normalizeResult(x,{kind:'degree',verifiedRule:true,ruleId:x?.ruleId});
      }
    }catch(e){}
    return null;
  }

  /* ------------------------------------------------------------
     6. ONE current-result resolver for EVERY view
  ------------------------------------------------------------ */
  function currentContext(){
    const active=document.querySelector('.screen.active')?.id||'';
    let selection={};
    try{selection=JSON.parse(sessionStorage.getItem('studielots_planner_selection')||'{}')}catch(e){}

    let program=null,path=null,subject=selection.subject||'',university=selection.university||'';

    if(active==='universityDetail'){
      try{
        const key=sessionStorage.getItem('lotsen_detail_key')||'';
        const profile=sessionStorage.getItem('lotsen_preferred_profile')||'';
        const o=key&&typeof opportunityByKey==='function'?opportunityByKey(key):null;
        subject=o?.subject||subject;
        if(typeof studyPlanPathForProfile==='function')path=studyPlanPathForProfile(profile,subject);
        if(!path&&typeof bestV21Path==='function')path=bestV21Path(profile,subject);
        program=path?.program||null;
        university=path?.provider||program?.university||university||profile;
        return {kind:'degree',active,selection,program,path,subject,university};
      }catch(e){}
    }

    if(active==='programMatch'||selection.source==='program'){
      try{
        const id=sessionStorage.getItem('lotsen_selected_program')||selection.programId||'';
        program=A(window.programCatalog).find(x=>String(x.id||'')===String(id))||
          A(window.programCatalog).find(x=>selection.programCode&&String(x.code||x.officialCode||'')===String(selection.programCode))||null;
      }catch(e){}
      university=program?.university||university;
      subject=program?.subject||program?.track||subject;
      return {kind:'program',active,selection,program,path:{program,provider:university},subject,university};
    }

    return {kind:selection.source==='opportunity'?'degree':'program',active,selection,program,path,subject,university};
  }

  function currentResult(){
    const ctx=currentContext();

    if(ctx.kind==='degree'){
      const verified=verifiedDegreeResult(ctx.subject,ctx.university);
      if(verified)return verified;

      // Unverified degree route: use current canonical engine, but keep degree wording.
      try{
        const c=window.__studielotsCanonicalMatch?.current?.();
        if(c){
          return normalizeResult(c,{
            kind:'degree',
            university:ctx.university,
            subject:ctx.subject,
            program:ctx.program,
            rows:programmeRows(ctx.program,ctx.path),
            totalHp:N(ctx.program?.hp)||180
          });
        }
      }catch(e){}
    }

    if(ctx.program)return genericProgramResult(ctx.program,ctx.path);
    return null;
  }

  window.__studielotsUnifiedResult={
    version:'v564',
    importedMerits,
    currentContext,
    currentResult,
    normalizeResult,
    programmeRows
  };

  /* ------------------------------------------------------------
     7. SAME snapshot / Planner handoff everywhere
  ------------------------------------------------------------ */
  function saveUnifiedSnapshot(){
    const r=currentResult();
    if(!r)return null;

    const snap={
      version:'v564',
      kind:r.kind,
      verifiedRule:r.verifiedRule,
      ruleId:r.ruleId,
      selection:{
        source:r.kind==='degree'?'opportunity':'program',
        subject:r.subject,
        university:r.university,
        programId:r.programId,
        programCode:r.programCode,
        programName:r.programName
      },
      program:{
        id:r.programId,
        code:r.programCode,
        name:r.programName||r.subject,
        university:r.university
      },
      rows:A(r.rows),
      matches:A(r.matches),
      creditedHp:r.creditedHp,
      remainingHp:r.remainingHp,
      totalHp:r.totalHp,
      wording:r.wording,
      sourceOfTruth:'v564-unified'
    };

    try{
      sessionStorage.setItem('studielots_planner_selection',JSON.stringify(snap.selection));
      sessionStorage.setItem('studielots_planner_snapshot',JSON.stringify(snap));
      sessionStorage.setItem('studielots_visible_degree_totals',JSON.stringify({
        creditedHp:r.creditedHp,remainingHp:r.remainingHp,totalHp:r.totalHp
      }));
    }catch(e){}
    return snap;
  }

  window.__studielotsSaveUnifiedSnapshot=saveUnifiedSnapshot;

  document.addEventListener('click',e=>{
    const el=e.target.closest('button,a');
    if(!el)return;
    const t=Q(el.textContent);
    if(t.includes('skapa plan')||t.includes('planeraren')){
      saveUnifiedSnapshot();
    }
  },true);

  /* ------------------------------------------------------------
     8. SAME labels in detail + Planner
  ------------------------------------------------------------ */
  function syncLabels(){
    const r=currentResult();
    if(!r)return;

    if(document.querySelector('.screen.active')?.id==='universityDetail'){
      const host=document.getElementById('universityDetailContent');
      if(!host)return;

      const banner=[...host.querySelectorAll('div')].find(el=>
        /hp\s*kan räknas/i.test(el.innerText||'')&&/hp\s*kvar/i.test(el.innerText||'')
      );
      if(banner){
        const label=r.kind==='degree'?'kan räknas in i examen':'möjligt tillgodoräknande';
        banner.innerHTML=`<strong>${String(r.creditedHp).replace('.',',')} hp ${label} · ${String(r.remainingHp).replace('.',',')} hp kvar</strong>`;
      }

      const cards=[...host.querySelectorAll('div')];
      const creditCard=cards.find(el=>/Tillgodoräknat|Kan räknas in i examen/i.test(el.innerText||'')&&el.querySelector('strong'));
      const remainCard=cards.find(el=>/(^|\n)Kvar(\n|$)/i.test(el.innerText||'')&&el.querySelector('strong'));
      if(creditCard){
        const label=[...creditCard.querySelectorAll('*')].find(x=>/^(Tillgodoräknat|Kan räknas in i examen)$/i.test((x.textContent||'').trim()));
        if(label)label.textContent=r.wording.credited;
        const strong=creditCard.querySelector('strong');
        if(strong)strong.textContent=`${String(r.creditedHp).replace('.',',')} hp`;
      }
      if(remainCard){
        const strong=remainCard.querySelector('strong');
        if(strong)strong.textContent=`${String(r.remainingHp).replace('.',',')} hp`;
      }
    }
  }

  document.addEventListener('studielots:screen-rendered',()=>requestAnimationFrame(syncLabels));

  window.__studielotsBuild={...(window.__studielotsBuild||{}),version:'v564',
    unifiedAllUniversities:true,
    unifiedAllPrograms:true,
    unifiedAllDegrees:true,
    oneMeritSource:true,
    onePlannerSnapshot:true,
    degreeProgramWordingSeparated:true};
})();

/* v565 — snapshot-only Planner + compact semester calendar */
(function(){
  const A=v=>Array.isArray(v)?v:(v?[v]:[]);
  const N=v=>Number(String(v??0).replace(',','.'))||0;
  const F=v=>N(v).toLocaleString('sv-SE',{maximumFractionDigits:1});
  const Q=s=>String(s||'').toLocaleLowerCase('sv-SE').normalize('NFD')
    .replace(/[\u0300-\u036f]/g,'').replace(/[^a-z0-9åäö]+/g,' ').trim();
  const E=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));

  function snapshot(){
    try{return JSON.parse(sessionStorage.getItem('studielots_planner_snapshot')||'null')}catch(e){return null}
  }

  function courseKey(c){
    return Q(c?.code)||`${Q(c?.name)}|${N(c?.hp)}`;
  }

  function matchesMap(s){
    const byCode=new Map(),byName=new Map();
    A(s?.matches).forEach(m=>{
      if(Q(m.targetCode))byCode.set(Q(m.targetCode),m);
      if(Q(m.targetName))byName.set(Q(m.targetName),m);
    });
    return {byCode,byName};
  }

  function fasterAlternative(req,s,used){
    if(typeof window.bestFasterAlternative!=='function')return null;
    try{
      const path={
        provider:s.program?.university||s.selection?.university||'',
        program:{
          ...s.program,
          university:s.program?.university||s.selection?.university||'',
          courses:A(s.rows)
        }
      };
      const hit=window.bestFasterAlternative(req,path,used);
      const c=hit?.course||null;
      if(!c)return null;
      const id=courseKey(c);
      if(!id||used.has(id))return null;
      used.add(id);
      return {hit,course:c};
    }catch(e){return null}
  }

  function stateForRow(r,match){
    if(match||r.status==='credited')return 'credited';
    return 'remaining';
  }

  function termGroups(rows){
    const map=new Map();
    A(rows).forEach((r,i)=>{
      const term=Number(r.term)||Math.max(1,Math.floor(i/2)+1);
      if(!map.has(term))map.set(term,[]);
      map.get(term).push(r);
    });
    return [...map.entries()].sort((a,b)=>a[0]-b[0]);
  }

  function renderCalendar(s,matchMap){
    const groups=termGroups(s.rows);
    if(!groups.length)return '';

    const items=groups.map(([term,rows])=>{
      const total=rows.reduce((sum,r)=>sum+N(r.hp),0);
      const credited=rows.reduce((sum,r)=>{
        const m=(Q(r.code)&&matchMap.byCode.get(Q(r.code)))||matchMap.byName.get(Q(r.name));
        return sum+(stateForRow(r,m)==='credited'?N(r.hp):0);
      },0);
      const remaining=Math.max(0,total-credited);
      const complete=remaining<=0.01;

      return `<button type="button" class="v565-cal-item ${complete?'done':''}" data-scroll-term="${term}">
        <span>Termin ${term}</span>
        <strong>${F(total)} hp</strong>
        <small>${complete?'Klar':credited?`${F(credited)} hp klara`:`${F(remaining)} hp kvar`}</small>
      </button>`;
    }).join('');

    return `<section class="v565-calendar">
      <div class="v565-calendar-head">
        <div>
          <span class="eyebrow">STUDIEKALENDER</span>
          <h3>Din väg termin för termin</h3>
        </div>
        <small>${groups.length} terminer</small>
      </div>
      <div class="v565-calendar-track">${items}</div>
    </section>`;
  }

  function renderPlanner(){
    if(document.querySelector('.screen.active')?.id!=='plannerClean')return;
    const host=document.getElementById('plannerCleanContent');
    if(!host)return;

    const s=snapshot();
    if(!s||!A(s.rows).length){
      host.innerHTML='<div class="detail-block"><h2>Studieplan</h2><p>Ingen färdig plan är sparad ännu. Välj en examen eller ett program och tryck på “Skapa plan i Planeraren”.</p></div>';
      return;
    }

    // SNAPSHOT IS AUTHORITATIVE. No recalculation of hp totals here.
    const credited=N(s.creditedHp);
    const remaining=N(s.remainingHp);
    const mm=matchesMap(s);
    const usedAlt=new Set();

    let body='',altCount=0,term=null;

    A(s.rows).forEach((r,i)=>{
      const currentTerm=Number(r.term)||Math.max(1,Math.floor(i/2)+1);
      if(currentTerm!==term){
        term=currentTerm;
        body+=`<section class="v565-term-block" id="v565-term-${term}">
          <div class="v565-term-head">
            <div><span>TERMIN ${term}</span><strong>Termin ${term}</strong></div>
            <b>${F(A(s.rows).filter((x,j)=>(Number(x.term)||Math.max(1,Math.floor(j/2)+1))===term).reduce((sum,x)=>sum+N(x.hp),0))} hp</b>
          </div>`;
      }

      const match=(Q(r.code)&&mm.byCode.get(Q(r.code)))||mm.byName.get(Q(r.name))||null;
      const st=stateForRow(r,match);

      body+=`<div class="v565-course ${st}">
        <div class="v565-course-main">
          <div>
            <strong>${E(r.name||'Kurs')}</strong>
            <small>${st==='credited'
              ? (s.kind==='degree'||s.wording?.credited==='Kan räknas in i examen'
                  ? 'Kan räknas in i examen'
                  : 'Möjligt tillgodoräknande')
              : 'Återstår att läsa'}</small>
            ${match?.sourceName?`<em>${E(match.sourceName)}${match.sourceUniversity?` · ${E(match.sourceUniversity)}`:''}</em>`:
              r.sourceName?`<em>${E(r.sourceName)}${r.sourceUniversity?` · ${E(r.sourceUniversity)}`:''}</em>`:''}
          </div>
          <b>${F(r.hp)} hp</b>
        </div>`;

      if(st!=='credited'){
        const alt=fasterAlternative(r,s,usedAlt);
        if(alt){
          altCount++;
          const verified=Boolean(alt.hit?.verifiedEquivalent);
          const distance=Boolean(alt.hit?.distance||alt.course?.distance);
          const label=verified
            ? (distance?'VERIFIERAT DISTANSALTERNATIV':'VERIFIERAT SNABBARE ALTERNATIV')
            : (distance?'MÖJLIGT DISTANSALTERNATIV':'MÖJLIGT SNABBARE ALTERNATIV');

          body+=`<div class="v565-alt ${verified?'verified':''}">
            <span>${label}</span>
            <div>
              <strong>${E(alt.course.name||alt.course.title||'Alternativ kurs')}</strong>
              <b>${F(alt.course.hp)} hp</b>
            </div>
            ${alt.hit?.reason?`<small>${E(alt.hit.reason)}</small>`:''}
          </div>`;
        }
      }

      body+='</div>';

      const next=A(s.rows)[i+1];
      const nextTerm=next?(Number(next.term)||Math.max(1,Math.floor((i+1)/2)+1)):null;
      if(nextTerm!==term)body+='</section>';
    });

    const calendar=renderCalendar(s,mm);

    host.innerHTML=`
      <section class="v565-selected">
        <div>
          <span>VALD VÄG</span>
          <strong>${E(s.selection?.subject||s.program?.name||'Studieplan')}</strong>
          <small>${E(s.program?.university||s.selection?.university||'')}</small>
        </div>
        <button type="button" class="ghost" onclick="window.__v549NewPlan?.()">Ändra</button>
      </section>

      <section class="v565-summary">
        <div><strong>${F(credited)} hp</strong><span>${s.kind==='degree'||s.wording?.credited==='Kan räknas in i examen'?'kan räknas in i examen':'möjligt tillgodoräknande'}</span></div>
        <div><strong>${F(remaining)} hp</strong><span>kvar</span></div>
      </section>

      ${calendar}

      <section class="detail-block v565-plan">
        <div class="v565-plan-head">
          <div>
            <span class="eyebrow">PLANERAREN</span>
            <h2>Din studieplan</h2>
            <p>Ordinarie väg med möjliga snabbare alternativ.</p>
          </div>
          <span>${F(remaining)} hp kvar</span>
        </div>
        ${altCount?`<div class="v565-opt"><strong>⚡ ${altCount} möjlig${altCount===1?'':'a'} genväg${altCount===1?'':'ar'}</strong><small>Visas bara där en konkret alternativ kurs kan korta vägen.</small></div>`:''}
        ${body}
        <p class="v565-note">Tillgodoräknanden och alternativa kurser är preliminära tills universitetet fattat beslut.</p>
      </section>`;

    host.querySelectorAll('[data-scroll-term]').forEach(btn=>{
      btn.addEventListener('click',()=>{
        const t=btn.getAttribute('data-scroll-term');
        document.getElementById('v565-term-'+t)?.scrollIntoView({behavior:'smooth',block:'start'});
      });
    });
  }

  // Disable all previous planner content by always rendering last.
  document.addEventListener('studielots:screen-rendered',e=>{
    if(e?.detail?.screen==='plannerClean'){
      requestAnimationFrame(()=>requestAnimationFrame(()=>requestAnimationFrame(renderPlanner)));
    }
  });

  // Final open wrapper only triggers render; never recalculates.
  const priorOpen=window.openStudyPlanner;
  window.openStudyPlanner=function(){
    const r=typeof priorOpen==='function'?priorOpen.apply(this,arguments):undefined;
    requestAnimationFrame(()=>requestAnimationFrame(()=>requestAnimationFrame(renderPlanner)));
    return r;
  };

  window.__studielotsPlannerSnapshotRender=renderPlanner;
  window.__studielotsBuild={...(window.__studielotsBuild||{}),version:'v565',
    plannerSnapshotOnly:true,
    noPlannerRecalculation:true,
    compactStudyCalendar:true};
})();

/* v566 — canonical result sync + planner row reconciliation */
(function(){
  const A=v=>Array.isArray(v)?v:(v?[v]:[]);
  const N=v=>Number(String(v??0).replace(',','.'))||0;
  const Q=s=>String(s||'').toLocaleLowerCase('sv-SE').normalize('NFD')
    .replace(/[\u0300-\u036f]/g,'').replace(/[^a-z0-9åäö]+/g,' ').trim();

  function snap(){
    try{return JSON.parse(sessionStorage.getItem('studielots_planner_snapshot')||'null')}catch(e){return null}
  }
  function save(s){
    sessionStorage.setItem('studielots_planner_snapshot',JSON.stringify(s));
  }

  // Reconcile row statuses against the authoritative hp totals.
  // This prevents the planner from saying 90/90 while every row says "Återstår att läsa".
  function reconcile(s){
    if(!s||!A(s.rows).length)return s;
    const target=Math.max(0,N(s.creditedHp));
    let rows=A(s.rows).map(r=>({...r}));
    let current=rows.filter(r=>r.status==='credited').reduce((a,r)=>a+N(r.hp),0);

    // Prefer explicit match rows, then rows already carrying source evidence.
    const matchedNames=new Set(A(s.matches).flatMap(m=>[Q(m.targetName),Q(m.name)].filter(Boolean)));
    const matchedCodes=new Set(A(s.matches).flatMap(m=>[Q(m.targetCode),Q(m.code)].filter(Boolean)));

    rows.sort((a,b)=>{
      const sa=(a.status==='credited'?4:0)+(matchedCodes.has(Q(a.code))?3:0)+(matchedNames.has(Q(a.name))?2:0)+(a.sourceName?1:0);
      const sb=(b.status==='credited'?4:0)+(matchedCodes.has(Q(b.code))?3:0)+(matchedNames.has(Q(b.name))?2:0)+(b.sourceName?1:0);
      return sb-sa;
    });

    // Only mark enough rows to equal the canonical credited hp.
    let used=0;
    for(const r of rows){
      const hp=N(r.hp);
      const explicit=r.status==='credited'||matchedCodes.has(Q(r.code))||matchedNames.has(Q(r.name))||Boolean(r.sourceName);
      if(explicit && used+hp<=target+0.01){
        r.status='credited'; used+=hp;
      }else{
        r.status='remaining';
      }
    }

    // If source matching is coarser than program blocks, don't invent a course match.
    // Preserve canonical totals but leave unmatched remainder as remaining.
    s.rows=rows.sort((a,b)=>(N(a.term)-N(b.term))||0);
    return s;
  }

  function canonicalFromVisibleDetail(){
    // Read the blue canonical banner if present: "90 hp ... 90 hp kvar"
    const active=document.querySelector('.screen.active');
    if(!active)return null;
    const txt=active.innerText||'';
    const m=txt.match(/(\d+(?:[,.]\d+)?)\s*hp\s+kan räknas(?:\s+in i examen)?[\s\S]{0,40}?(\d+(?:[,.]\d+)?)\s*hp\s+kvar/i);
    if(!m)return null;
    return {credited:N(m[1]),remaining:N(m[2])};
  }

  function syncDetailCards(){
    const c=canonicalFromVisibleDetail();
    if(!c)return;
    const active=document.querySelector('.screen.active');
    if(!active)return;

    // Replace legacy numeric cards only inside visible detail page.
    const els=[...active.querySelectorAll('*')].filter(el=>el.children.length===0);
    for(const el of els){
      const t=(el.textContent||'').trim();
      if(/^(97[,.]5|82[,.]5)\s*hp$/i.test(t)){
        const parentText=(el.parentElement?.innerText||'').toLowerCase();
        if(parentText.includes('tillgodoräkn')) el.textContent=c.credited.toLocaleString('sv-SE',{maximumFractionDigits:1})+' hp';
        else if(parentText.includes('kvar')) el.textContent=c.remaining.toLocaleString('sv-SE',{maximumFractionDigits:1})+' hp';
      }
    }

    let s=snap();
    if(s){
      s.creditedHp=c.credited;
      s.remainingHp=c.remaining;
      save(reconcile(s));
    }
  }

  function refreshPlanner(){
    let s=snap();
    if(!s)return;
    s=reconcile(s); save(s);
    if(typeof window.__studielotsPlannerSnapshotRender==='function'){
      window.__studielotsPlannerSnapshotRender();
    }
  }

  // Synchronize once after each completed screen render.
  document.addEventListener('studielots:screen-rendered',()=>{
    setTimeout(syncDetailCards,30);
    setTimeout(refreshPlanner,60);
  });

  window.__studielotsBuild={...(window.__studielotsBuild||{}),version:'v566',
    canonicalDetailPlannerSync:true,
    plannerRowReconciliation:true};
})();

/* v570 — locked five-item navigation */
(function(){
  function lockNav(){
    const nav=document.querySelector('.lotsen-bottomnav');
    if(!nav)return;
    const wanted=[
      ['start','Hem'],['degrees','Möjligheter'],['plannerClean','Planeraren'],['programMatch','Program']
    ];
    const buttons=[...nav.querySelectorAll(':scope > button')];
    buttons.forEach(b=>{
      const label=(b.querySelector('b')?.textContent||'').trim();
      if(label==='Studier') b.remove();
    });
    const planner=[...nav.querySelectorAll(':scope > button')].find(b=>(b.querySelector('b')?.textContent||'').trim()==='Planeraren');
    const program=[...nav.querySelectorAll(':scope > button')].find(b=>(b.querySelector('b')?.textContent||'').trim()==='Program');
    if(planner&&program&&planner.nextElementSibling!==program)nav.insertBefore(planner,program);
    [...nav.querySelectorAll(':scope > button')].forEach(b=>{
      const label=(b.querySelector('b')?.textContent||'').trim();
      if(label==='Planeraren'){
        b.dataset.screen='plannerClean'; b.dataset.navTarget='plannerClean';
        b.onclick=()=>window.openStudyPlanner?window.openStudyPlanner():(window.go&&window.go('plannerClean'));
      }
    });
  }
  lockNav();
  document.addEventListener('studielots:screen-rendered',()=>setTimeout(lockNav,0));
  window.__studielotsBuild={...(window.__studielotsBuild||{}),version:'v570',lockedBottomNav:['Hem','Möjligheter','Planeraren','Program','Mer']};
})();

/* v572 — approved Planner redesign */
(function(){
  const A=v=>Array.isArray(v)?v:(v?[v]:[]);
  const N=v=>Number(String(v??0).replace(',','.'))||0;
  const F=v=>N(v).toLocaleString('sv-SE',{maximumFractionDigits:1});
  const Q=s=>String(s||'').toLocaleLowerCase('sv-SE').normalize('NFD')
    .replace(/[\u0300-\u036f]/g,'').replace(/[^a-z0-9åäö]+/g,' ').trim();
  const E=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));

  function snap(){
    try{return JSON.parse(sessionStorage.getItem('studielots_planner_snapshot')||'null')}catch(e){return null}
  }

  function normalize(s){
    const matches=A(s?.matches);
    const q=x=>Q(x);
    const matchFor=r=>matches.find(m=>
      (q(r.code)&&q(m.targetCode||m.code)===q(r.code)) ||
      (q(r.name)&&q(m.targetName||m.name)===q(r.name))
    );
    const rows=A(s?.rows).map((r,i)=>{
      const hp=N(r.hp), m=matchFor(r);
      let matched=N(r.matchedHp||r.creditedHp||m?.matchedHp||m?.creditedHp||m?.hpMatched);
      if(!matched && m){
        const explicitPartial=m.partial===true||m.matchType==='partial'||m.type==='partial';
        const sourceHp=N(m.sourceHp||m.sourceCredits||m.source?.hp);
        if(explicitPartial && sourceHp) matched=Math.min(hp,sourceHp);
        else if(!explicitPartial) matched=hp;
      }
      matched=Math.max(0,Math.min(hp,matched));
      const status=matched>=hp-.01?'credited':matched>0?'partial':(r.status==='credited'?'credited':r.status==='partial'?'partial':'remaining');
      return {...r,hp,matchedHp:status==='credited'?hp:matched,
        term:N(r.term)||Math.max(1,Math.floor(i/4)+1),status};
    });
    const total=N(s?.totalHp)||N(s?.creditedHp)+N(s?.remainingHp)||180;
    const credited=Math.max(0,Math.min(total,N(s?.creditedHp)));
    return {...s,rows,totalHp:total,creditedHp:credited,remainingHp:Math.max(0,total-credited)};
  }

  function groups(s){
    const m=new Map();
    s.rows.forEach(r=>{if(!m.has(r.term))m.set(r.term,[]);m.get(r.term).push(r)});
    return [...m.entries()].sort((a,b)=>a[0]-b[0]).map(([term,rows])=>{
      const hp=rows.reduce((a,r)=>a+r.hp,0);
      const credited=rows.reduce((a,r)=>a+(r.status==='credited'?r.hp:N(r.matchedHp)),0);
      return {term,rows,hp,credited,left:Math.max(0,hp-credited)};
    });
  }

  function semesterLabel(t,s){
    const row=A(s.rows).find(r=>r.term===t);
    return row?.termLabel||row?.semesterLabel||row?.semester||row?.period||`Termin ${t}`;
  }

  function fastAlternatives(s){
    const out=[];
    A(s.fasterAlternatives||s.alternatives||s.fasterRoute).forEach(x=>out.push({
      name:x.name||x.title||x.courseName||'Snabbare väg',
      hp:N(x.hp||x.credits),
      term:N(x.term||x.targetTerm)||null,
      save:N(x.savesTerms||x.termSavings||x.savedTerms),
      reason:x.reason||x.description||''
    }));
    s.rows.forEach(r=>{
      const x=r.fasterAlternative||r.alternative;
      if(x)out.push({
        name:x.name||x.title||x.courseName||'Snabbare väg',
        hp:N(x.hp||x.credits),
        term:N(x.term||r.term)||null,
        save:N(x.savesTerms||x.termSavings||x.savedTerms),
        reason:x.reason||x.description||''
      });
    });
    return out.sort((a,b)=>b.save-a.save);
  }

  function courseRow(r){
    const credited=r.status==='credited', partial=r.status==='partial';
    const state=credited?'credited':partial?'partial':'remaining';
    return `<div class="v572-course" data-status="${state}">
      <span class="v572-status ${state}">${credited?'✓':partial?'◐':'○'}</span>
      <div class="v572-course-copy">
        <strong>${E(r.name||'Kurs')}</strong>
        <small class="${credited?'credited':partial?'partial':''}">${credited?'Kan räknas in':partial?`${F(r.matchedHp)} av ${F(r.hp)} hp kan räknas in`:'Kvar att läsa'}</small>
      </div>
      <b>${F(r.hp)} hp</b>
      <button type="button" class="v572-more" aria-label="Mer">⋮</button>
    </div>`;
  }

  function render(){
    if(document.querySelector('.screen.active')?.id!=='plannerClean')return;
    const root=document.getElementById('plannerClean');
    let s=snap();
    if(!root||!s)return;
    s=normalize(s);
    const ts=groups(s);
    const pct=s.totalHp?Math.round(s.creditedHp/s.totalHp*100):0;
    const subject=s.selection?.subject||s.program?.name||'Vald studieväg';
    const university=s.program?.university||s.selection?.university||'';
    const best=fastAlternatives(s)[0];

    root.innerHTML=`
      <div class="v572-shell">
        <main class="v572-main">
          <div class="v572-eyebrow">PLANERAREN</div>
          <h1>Din studieplan</h1>
          <p class="v572-lead">En konkret väg utifrån vad du redan har läst och vad som återstår.</p>

          <section class="v572-choice">
            <span class="v572-grad">🎓</span>
            <div><strong>${E(subject)}</strong><small>${E(university)}</small></div>
            <button type="button" id="v572Change">Ändra</button>
          </section>

          <section class="v572-summary">
            <button type="button" data-filter-jump="credited"><strong>${F(s.creditedHp)} hp</strong><span>kan räknas in i examen ⓘ</span></button>
            <button type="button" data-filter-jump="remaining"><strong>${F(s.remainingHp)} hp</strong><span>kvar att läsa ⓘ</span></button>
          </section>

          <section class="v572-calendar">
            <div class="v572-calendar-head"><h2>Din studiekalender</h2><button type="button" data-yearview="1">▣ Årsvy</button></div>
            <div class="v572-term-strip">
              ${ts.map(t=>{
                const done=t.left<=.01,part=t.credited>0&&!done;
                return `<button type="button" class="v572-term ${done?'done':part?'part':''}" data-term="${t.term}">
                  <b>T${t.term}</b><small>${E(semesterLabel(t.term,s))}</small>
                  <i>${done?'✓':part?'◐':''}</i>
                  <strong>${F(t.hp)} hp</strong>
                  <em>${done?'Kan räknas in':part?'Delvis kvar att läsa':'Återstår'}</em>
                </button>`;
              }).join('')}
            </div>
            <div class="v572-calendar-key"><span><i class="g"></i>Kan räknas in</span><span><i class="y"></i>Delvis</span><span><i></i>Återstår</span></div>
            <div class="v572-progress-label"><span>${F(s.creditedHp)} av ${F(s.totalHp)} hp planerade</span><b>${pct}%</b></div>
            <div class="v572-progress"><i style="width:${pct}%"></i></div>
          </section>

          <section class="v572-fast-inline ${best?'':'quiet'}">
            <span>⚡</span>
            <div><div><b>SNABBARE VÄG TILL EXAMEN</b>${best?.save?`<em>-${best.save} termin${best.save===1?'':'er'}</em>`:''}</div>
            <p>${best?(best.save?`Den rekommenderade vägen kan göra dig klar ${best.save} termin${best.save===1?'':'er'} tidigare.`:'Ett snabbare alternativ har hittats.'):'Ingen verifierbar genväg hittad ännu.'}</p></div>
            ${best?'<button type="button" data-v572-fast="1">Visa snabbare väg →</button>':''}
          </section>

          <section class="v572-studyplan">
            <div class="v572-studyplan-head"><h2>Studieplan</h2><button type="button" class="v572-sort">☷ Sortera</button></div>
            <div class="v572-filters">
              <button class="active" data-filter="all">Alla</button>
              <button data-filter="credited">Kan räknas in</button>
              <button data-filter="remaining">Kvar att läsa</button>
            </div>
            <div class="v572-accordion">
              ${ts.map((t,idx)=>`<section class="v572-term-section ${idx===0?'open':''}" data-term-section="${t.term}">
                <button type="button" class="v572-term-head">
                  <span>Termin ${t.term}${semesterLabel(t.term,s)!==`Termin ${t.term}`?` – ${E(semesterLabel(t.term,s))}`:''}</span>
                  <b>${F(t.hp)} hp</b><i>${idx===0?'⌃':'⌄'}</i>
                </button>
                <div class="v572-term-body">${t.rows.map(courseRow).join('')}</div>
              </section>`).join('')}
            </div>
          </section>
        </main>
      </div>`;

    root.querySelector('#v572Change').onclick=()=>window.__v549NewPlan?.();

    root.querySelectorAll('.v572-term-head').forEach(btn=>{
      btn.onclick=()=>{
        const sec=btn.closest('.v572-term-section');
        sec.classList.toggle('open');
        btn.querySelector('i').textContent=sec.classList.contains('open')?'⌃':'⌄';
      };
    });

    root.querySelectorAll('[data-term]').forEach(btn=>{
      btn.onclick=()=>{
        const term=btn.dataset.term;
        const sec=root.querySelector(`[data-term-section="${term}"]`);
        if(sec){
          sec.classList.add('open');
          sec.querySelector('.v572-term-head i').textContent='⌃';
          sec.scrollIntoView({behavior:'smooth',block:'start'});
        }
      };
    });

    root.querySelectorAll('[data-filter]').forEach(btn=>{
      btn.onclick=()=>{
        root.querySelectorAll('[data-filter]').forEach(x=>x.classList.remove('active'));
        btn.classList.add('active');
        const f=btn.dataset.filter;
        root.querySelectorAll('.v572-course').forEach(r=>{
          r.style.display=(f==='all'||r.dataset.status===f)?'grid':'none';
        });
      };
    });

    root.querySelectorAll('[data-filter-jump]').forEach(btn=>{
      btn.onclick=()=>{
        const f=btn.dataset.filterJump;
        const filter=root.querySelector(`[data-filter="${f}"]`);
        filter?.click();
        root.querySelector('.v572-studyplan')?.scrollIntoView({behavior:'smooth',block:'start'});
      };
    });

    root.querySelectorAll('[data-v572-fast]').forEach(btn=>{
      btn.onclick=()=>{
        root.querySelector('#sl-pace-picker')?.scrollIntoView({behavior:'smooth',block:'start'});
      };
    });
  }

  document.addEventListener('studielots:screen-rendered',e=>{
    if(e?.detail?.screen==='plannerClean')setTimeout(render,50);
  });
  setTimeout(render,250);
  window.__studielotsRenderPlannerV572=render;
  window.__studielotsBuild={...(window.__studielotsBuild||{}),version:'v572',plannerApprovedDesign:true};
})();

