/* v575 — remove duplicate legacy Planner renderers */
(function(){
  function cleanPlanner(){
    const root=document.getElementById('plannerClean');
    if(!root)return;

    const shell=root.querySelector('.v572-shell');
    if(!shell)return;

    // Keep exactly one approved Planner shell.
    [...root.children].forEach(ch=>{
      if(ch!==shell) ch.remove();
    });

    // Remove legacy enhancement blocks that older renderers may append.
    root.querySelectorAll(
      '.v565-calendar,.v565-plan,.v557-plan,.v558-plan,'+
      '.v549-planner-page,#plannerCleanContent,.v565-term-block'
    ).forEach(el=>{
      if(!el.closest('.v572-shell')) el.remove();
    });

    // Inside the new shell, remove any accidental legacy blocks.
    shell.querySelectorAll('.v565-calendar,.v565-plan,.v557-plan,.v558-plan').forEach(el=>el.remove());

    // Prevent accidental duplicate approved shells.
    const shells=[...root.querySelectorAll(':scope > .v572-shell')];
    shells.slice(1).forEach(el=>el.remove());
  }

  // Run after all old delayed renderers.
  document.addEventListener('studielots:screen-rendered',e=>{
    if(e?.detail?.screen==='plannerClean'){
      [20,80,180,400,800].forEach(ms=>setTimeout(cleanPlanner,ms));
    }
  });

  setTimeout(cleanPlanner,300);

  window.__studielotsBuild={
    ...(window.__studielotsBuild||{}),
    version:'v575',
    plannerSingleRenderer:true,
    legacyPlannerDuplicatesRemoved:true
  };
})();

/* v578 — term cards open visible detail sheet */
(function(){
  const N=v=>Number(String(v??0).replace(',','.'))||0;
  const F=v=>N(v).toLocaleString('sv-SE',{maximumFractionDigits:1});
  const E=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));

  function getSnap(){
    try{return JSON.parse(sessionStorage.getItem('studielots_planner_snapshot')||'null')}catch(e){return null}
  }

  function rowsForTerm(s,term){
    return (Array.isArray(s?.rows)?s.rows:[]).filter((r,i)=>{
      const t=N(r.term)||Math.max(1,Math.floor(i/4)+1);
      return t===N(term);
    });
  }

  function termSheet(term){
    const s=getSnap();
    if(!s)return;
    const rows=rowsForTerm(s,term);
    const total=rows.reduce((a,r)=>a+N(r.hp),0);
    const credited=rows.filter(r=>r.status==='credited').reduce((a,r)=>a+N(r.hp),0);
    const remaining=Math.max(0,total-credited);

    document.getElementById('v578TermSheet')?.remove();

    const courses=rows.length?rows.map(r=>{
      const credited=r.status==='credited';
      return `<div class="v578-course">
        <span class="v578-course-status ${credited?'done':'left'}">${credited?'✓':'◐'}</span>
        <div>
          <strong>${E(r.name||'Kurs')}</strong>
          <small>${credited?'Kan räknas in':'Kvar att läsa'}</small>
          ${r.sourceName?`<em>${E(r.sourceName)}${r.sourceUniversity?` · ${E(r.sourceUniversity)}`:''}</em>`:''}
        </div>
        <b>${F(r.hp)} hp</b>
      </div>`;
    }).join(''):'<p class="v578-empty">Inga kursdetaljer finns för den här terminen ännu.</p>';

    const el=document.createElement('div');
    el.id='v578TermSheet';
    el.innerHTML=`
      <div class="v578-backdrop"></div>
      <section class="v578-sheet">
        <div class="v578-sheet-handle"></div>
        <header>
          <div>
            <small>TERMIN ${term}</small>
            <h2>Termin ${term}</h2>
          </div>
          <button type="button" aria-label="Stäng">×</button>
        </header>
        <div class="v578-term-summary">
          <div><strong>${F(credited)} hp</strong><span>kan räknas in</span></div>
          <div><strong>${F(remaining)} hp</strong><span>kvar att läsa</span></div>
        </div>
        <div class="v578-course-list">${courses}</div>
      </section>`;
    document.body.appendChild(el);

    const close=()=>el.remove();
    el.querySelector('header button').onclick=close;
    el.querySelector('.v578-backdrop').onclick=close;
  }

  function bind(){
    if(document.querySelector('.screen.active')?.id!=='plannerClean')return;
    const root=document.getElementById('plannerClean');
    if(!root)return;

    // Calendar cards open a real detail sheet.
    root.querySelectorAll('.v572-term[data-term]').forEach(btn=>{
      if(!btn.querySelector('.v576-open-cue')){
        const cue=document.createElement('span');
        cue.className='v576-open-cue';
        cue.textContent='Visa';
        btn.appendChild(cue);
      }
      btn.onclick=e=>{
        e.preventDefault();
        e.stopPropagation();
        termSheet(btn.dataset.term);
      };
    });

    // Accordion headers still work as an inline alternative.
    root.querySelectorAll('.v572-term-head').forEach(btn=>{
      btn.onclick=e=>{
        e.preventDefault();
        const sec=btn.closest('.v572-term-section');
        if(!sec)return;
        const wasOpen=sec.classList.contains('open');
        root.querySelectorAll('.v572-term-section').forEach(x=>{
          x.classList.remove('open');
          const i=x.querySelector('.v572-term-head i');
          if(i)i.textContent='⌄';
        });
        if(!wasOpen){
          sec.classList.add('open');
          const i=sec.querySelector('.v572-term-head i');
          if(i)i.textContent='⌃';
        }
      };
    });
  }

  document.addEventListener('studielots:screen-rendered',e=>{
    if(e?.detail?.screen==='plannerClean'){
      [50,160,400].forEach(ms=>setTimeout(bind,ms));
    }
  });
  setTimeout(bind,300);

  window.__studielotsOpenTermDetails=termSheet;
  window.__studielotsBuild={
    ...(window.__studielotsBuild||{}),
    version:'v578',
    termCardsOpenDetailSheet:true
  };
})();

/* v617 — one authoritative programme search */
(function(){
  const ACTIVE_PROGRAM_UNIVERSITIES = new Set([
    'chalmers tekniska högskola',
    'göteborgs universitet',
    'lunds universitet',
    'luleå tekniska universitet'
  ]);

  const norm=v=>String(v||'').trim().toLocaleLowerCase('sv-SE');

  function activeProgram(p){
    return ACTIVE_PROGRAM_UNIVERSITIES.has(norm(p?.university));
  }

  function catalogue(){
    if(typeof programCatalog!=='undefined'&&Array.isArray(programCatalog))return programCatalog;
    return Array.isArray(window.programCatalog)?window.programCatalog:[];
  }

  function uniquePrograms(rows){
    const out=[],seen=new Set();
    (Array.isArray(rows)?rows:[]).forEach(p=>{
      const key=[norm(p?.university),norm(p?.name)].join('|');
      if(!seen.has(key)){seen.add(key);out.push(p)}
    });
    return out;
  }

  function searchScore(p,q){
    if(!q)return 1;
    const hay=norm(`${p?.name||''} ${p?.university||''} ${p?.code||''} ${p?.officialCode||''}`);
    if(hay===q)return 1000;
    if(hay.startsWith(q))return 500;
    if(hay.includes(q))return 250;
    const words=q.split(/\s+/).filter(Boolean);
    return words.reduce((s,w)=>s+(hay.includes(w)?25:0),0);
  }

  window.renderProgramSearch=function(){
    const host=document.getElementById('programSearchResults');
    if(!host)return;

    const input=document.getElementById('programSearchInput');
    const q=norm(input?.value||'');

    let rows=uniquePrograms(catalogue().filter(activeProgram));

    if(q){
      rows=rows.map(p=>({p,score:searchScore(p,q)}))
        .filter(x=>x.score>0)
        .sort((a,b)=>b.score-a.score || String(a.p.name||'').localeCompare(String(b.p.name||''),'sv'))
        .map(x=>x.p);
    }else{
      rows.sort((a,b)=>String(a.name||'').localeCompare(String(b.name||''),'sv'));
    }

    rows=rows.slice(0,30);

    host.innerHTML=rows.length?rows.map(p=>{
      const id=encodeURIComponent(String(p.id||p.code||p.name||''));
      const meta=[
        p.university||'',
        p.officialCode||p.code||'',
        Number(p.hp||0)?`${Number(p.hp)} hp`:'',
        p.level||''
      ].filter(Boolean).join(' · ');
      let logo='';
      try{ logo=typeof universityLogoHtml==='function'?universityLogoHtml(p.university,'sm'):'' }catch(e){}
      return `<button type="button" class="program-search-row program-search-row-clickable" data-v579-program="${id}">
        <div class="uni-name-with-logo">${logo}<div><strong>${typeof escapeHtml==='function'?escapeHtml(p.name||'Program'):String(p.name||'Program')}</strong><span>${typeof escapeHtml==='function'?escapeHtml(meta):meta}</span></div></div>
        <span>›</span>
      </button>`;
    }).join(''):'<div class="muted small program-empty">Inget program hittades.</div>';

    host.querySelectorAll('[data-v579-program]').forEach(btn=>{
      btn.onclick=e=>{
        e.preventDefault();
        e.stopPropagation();
        const key=decodeURIComponent(btn.dataset.v579Program||'');
        const p=catalogue().find(x=>
          String(x?.id||x?.code||x?.name||'')===key
        );
        if(!p)return;

        try{sessionStorage.setItem('lotsen_selected_program',String(p.id||p.code||p.name||''))}catch(e){}

        // Prefer the newest direct opener if available, otherwise use the canonical selector.
        try{
          if(typeof window.v390OpenProgram==='function')return window.v390OpenProgram(p.id||p.code||p.name);
        }catch(e){}
        try{
          if(typeof window.v379ActivateProgram==='function')return window.v379ActivateProgram(p.id||p.code||p.name);
        }catch(e){}
        try{
          if(typeof window.selectProgramForMatch==='function')return window.selectProgramForMatch(p.id||p.code||p.name);
        }catch(e){
          console.error('v579 program open fallback',e);
        }
      };
    });
  };

  function safeRender(){
    try{
      window.renderProgramSearch();
    }catch(e){
      console.error('v579 renderProgramSearch',e);
      const host=document.getElementById('programSearchResults');
      if(host)host.innerHTML='<div class="card empty"><strong>Kunde inte visa programmen.</strong><div class="small muted">Ladda om sidan och försök igen.</div></div>';
    }
  }

  const oldInput=document.getElementById('programSearchInput');
  if(oldInput){
    const input=oldInput.cloneNode(true);
    input.removeAttribute('oninput');
    input.dataset.programSearchRuntime='617';
    oldInput.replaceWith(input);
    input.addEventListener('input',safeRender);
  }

  document.addEventListener('studielots:screen-rendered',e=>{
    if(e?.detail?.screen==='programMatch')setTimeout(safeRender,20);
  });

  // If user is already on Program when this build loads.
  if(document.querySelector('.screen.active')?.id==='programMatch')setTimeout(safeRender,50);

  window.__studielotsBuild={
    ...(window.__studielotsBuild||{}),
    version:'v617',
    programSearchTdzFixed:true,
    programSearchOwnUniversityGate:true
  };
})();

(function(){
 try{sessionStorage.removeItem('sl_waiting_for_ladok_pdf');sessionStorage.removeItem('studielots_waiting_ladok_pdf')}catch(e){}
 try{if('serviceWorker' in navigator){navigator.serviceWorker.getRegistrations().then(function(rs){rs.forEach(function(r){var u=String((r.active&&r.active.scriptURL)||(r.waiting&&r.waiting.scriptURL)||(r.installing&&r.installing.scriptURL)||'');if(/studielots-sw\\.js/i.test(u))r.unregister()})}).catch(function(){})}}catch(e){}
 window.__studielotsBuild=Object.assign({},window.__studielotsBuild||{},{version:'v584',legacyMeritImport:true,ladokGuidedFlow:false,pwaShareTargetPrepared:false});
})();

/* v585 — engine/planner QA guard */
(function(){
 const A=v=>Array.isArray(v)?v:(v?[v]:[]);
 const N=v=>Number(String(v??0).replace(',','.'))||0;
 const Q=s=>String(s||'').toLocaleLowerCase('sv-SE').normalize('NFD').replace(/[\u0300-\u036f]/g,'').replace(/[^a-z0-9åäö]+/g,' ').trim();

 function sanitizeSnapshot(s){
   if(!s)return s;
   const total=N(s.totalHp)||180;
   const credited=Math.max(0,Math.min(total,N(s.creditedHp)));
   const matches=A(s.matches);
   const rows=A(s.rows).map(r=>{
     const hp=N(r.hp);
     const m=matches.find(x=>
       (Q(r.code)&&Q(x.targetCode||x.code)===Q(r.code))||
       (Q(r.name)&&Q(x.targetName||x.name)===Q(r.name))
     );
     let matched=N(r.matchedHp||r.creditedHp||m?.matchedHp||m?.creditedHp||m?.hpMatched);
     if(!matched&&m){
       const partial=m.partial===true||Q(m.matchType)==='partial'||Q(m.type)==='partial';
       const sourceHp=N(m.sourceHp||m.sourceCredits||m.source?.hp);
       matched=partial?(sourceHp?Math.min(hp,sourceHp):0):hp;
     }
     matched=Math.max(0,Math.min(hp,matched));
     const status=matched>=hp-.01?'credited':matched>0?'partial':(r.status==='credited'?'credited':r.status==='partial'?'partial':'remaining');
     return {...r,hp,matchedHp:status==='credited'?hp:matched,status};
   });
   return {...s,rows,totalHp:total,creditedHp:credited,remainingHp:Math.max(0,total-credited),
     qa:{...(s.qa||{}),v585:true,hpInvariant:Math.abs((credited+Math.max(0,total-credited))-total)<.01}};
 }

 function resave(){
   try{
     const raw=JSON.parse(sessionStorage.getItem('studielots_planner_snapshot')||'null');
     if(!raw)return;
     const clean=sanitizeSnapshot(raw);
     sessionStorage.setItem('studielots_planner_snapshot',JSON.stringify(clean));
     sessionStorage.setItem('studielots_visible_degree_totals',JSON.stringify({
       creditedHp:clean.creditedHp,remainingHp:clean.remainingHp,totalHp:clean.totalHp
     }));
   }catch(e){}
 }

 document.addEventListener('click',e=>{
   const el=e.target.closest('button,a'); if(!el)return;
   const t=Q(el.textContent);
   if(t.includes('skapa plan')||t.includes('planeraren')){
     setTimeout(()=>{resave();window.__studielotsRenderPlannerV572?.()},0);
   }
 },true);

 window.__studielotsRunQA=function(){
   let s=null; try{s=JSON.parse(sessionStorage.getItem('studielots_planner_snapshot')||'null')}catch(e){}
   const c=sanitizeSnapshot(s);
   if(!c)return {ok:false,reason:'Ingen sparad planner-snapshot'};
   const rowHp=A(c.rows).reduce((a,r)=>a+N(r.hp),0);
   const partial=A(c.rows).filter(r=>r.status==='partial').length;
   return {
     ok:Math.abs(c.creditedHp+c.remainingHp-c.totalHp)<.01,
     totalHp:c.totalHp,creditedHp:c.creditedHp,remainingHp:c.remainingHp,
     rowHp,rows:A(c.rows).length,partialRows:partial,
     sourceOfTruth:c.sourceOfTruth||'',verifiedRule:!!c.verifiedRule
   };
 };
 window.__studielotsBuild={...(window.__studielotsBuild||{}),version:'v585',plannerPartialMatches:true,qaGuard:true};
})();

/* v586 — degree-rule QA guardrails
   Prevents false 100% candidate matches when subject/progression/thesis evidence is missing.
   Local verified university rules remain authoritative when explicitly present. */
(function(){
 const A=v=>Array.isArray(v)?v:(v?[v]:[]);
 const N=v=>Number(String(v??0).replace(',','.'))||0;
 const Q=v=>String(v||'').toLocaleLowerCase('sv-SE').normalize('NFD').replace(/[\u0300-\u036f]/g,'').replace(/[^a-z0-9åäö]+/g,' ').trim();
 const isAdvanced=r=>/^(a1n|a1f|a1e|a2e|a2f)\b/i.test(String(r?.level||r?.progression||''));
 const isThesis=r=>/(examensarbete|kandidatuppsats|kandidatarbete|självständigt arbete|degree project|bachelor.?s thesis)/i.test(String(r?.name||''));
 const subj=(r)=>Q(r?.subject||r?.mainField||r?.huvudomrade||'');

 function candidateAudit(result){
   if(!result || result.kind!=='degree') return {applicable:false,ok:true};
   const total=N(result.totalHp)||180;
   if(total!==180) return {applicable:false,ok:true};

   const rows=A(result.rows);
   const matches=A(result.matches);
   const target=Q(result.subject);
   const creditedRows=rows.filter(r=>r.status==='credited'||N(r.matchedHp)>0);
   const credited=N(result.creditedHp);

   // Evidence metrics. These are guardrails, not a replacement for a university's verified local rule.
   const mainHp=creditedRows.filter(r=>target && subj(r)===target).reduce((a,r)=>a+Math.min(N(r.hp),N(r.matchedHp)||N(r.hp)),0);
   const thesisHp=creditedRows.filter(r=>isThesis(r) && (!target||!subj(r)||subj(r)===target))
      .reduce((a,r)=>a+Math.min(N(r.hp),N(r.matchedHp)||N(r.hp)),0);
   const advancedHp=creditedRows.filter(isAdvanced).reduce((a,r)=>a+Math.min(N(r.hp),N(r.matchedHp)||N(r.hp)),0);

   // Generic candidate route must never be called 100% complete without evidence
   // for 90 hp main field + 15 hp thesis. Verified local rules may provide explicit evidence.
   const hasExplicitRuleEvidence=Boolean(result.verifiedRule && (result.ruleId||result.ruleEvidence));
   const falseComplete=credited>=total-.01 && !hasExplicitRuleEvidence && (mainHp<90 || thesisHp<15);

   return {
     applicable:true,ok:!falseComplete,falseComplete,
     totalHp:total,creditedHp:credited,mainFieldHp:mainHp,thesisHp,advancedHp,
     targetSubject:result.subject||'',verifiedRule:!!result.verifiedRule
   };
 }

 function auditIssuedDegree(result){
   const issued=A(window.__studielotsUnifiedMerits?.issuedDegrees||window.__studielotsImportedDegrees||[]);
   const target=Q(result?.subject);
   const same=issued.some(d=>{
     const n=Q(d.name||d.degree||d.title), ds=Q(d.subject||d.mainField||'');
     return /(kandidat|bachelor)/.test(n) && (!target||!ds||ds===target);
   });
   return {sameCandidateAlreadyIssued:same};
 }

 const previous=window.__studielotsRunQA;
 window.__studielotsRunQA=function(){
   const base=typeof previous==='function'?previous():{};
   let result=null;
   try{ result=window.__studielotsUnifiedResult?.currentResult?.()||null }catch(e){}
   const degree=candidateAudit(result);
   const issued=auditIssuedDegree(result);
   return {...base,degreeRules:degree,issuedDegree:issued,
     ok:Boolean(base?.ok!==false && degree.ok!==false)};
 };

 // Before a planner snapshot is accepted, annotate suspicious generic "100%" results.
 const oldSave=window.__studielotsSaveUnifiedSnapshot;
 if(typeof oldSave==='function'){
   window.__studielotsSaveUnifiedSnapshot=function(){
     const snap=oldSave();
     try{
       const r=window.__studielotsUnifiedResult?.currentResult?.();
       const qa=candidateAudit(r);
       if(snap && qa.falseComplete){
         snap.qa={...(snap.qa||{}),candidateRuleWarning:true,candidateAudit:qa};
         snap.verifiedRule=false;
         snap.wording={...(snap.wording||{}),
           warning:'Examenskraven behöver verifieras: huvudområde och examensarbete kan inte styrkas fullt ut.'};
         sessionStorage.setItem('studielots_planner_snapshot',JSON.stringify(snap));
       }
     }catch(e){}
     return snap;
   };
 }

 window.__studielotsDegreeRuleQA={version:'v586',candidateAudit,auditIssuedDegree};
 window.__studielotsBuild={...(window.__studielotsBuild||{}),version:'v586',degreeRuleQA:true};
})();

/* v587 — progression + no-double-count QA
   Audits G1N/G1F/G1E/G2F/G2E/A1N/A1F/A1E/A2E and prevents the same merit
   from silently satisfying multiple target requirements inside one snapshot. */
(function(){
 const A=v=>Array.isArray(v)?v:(v?[v]:[]);
 const N=v=>Number(String(v??0).replace(',','.'))||0;
 const Q=v=>String(v||'').toLocaleLowerCase('sv-SE').normalize('NFD').replace(/[\u0300-\u036f]/g,'').replace(/[^a-z0-9åäö]+/g,' ').trim();
 const LEVELS={g1n:10,g1f:20,g1e:25,g2f:30,g2e:40,a1n:50,a1f:60,a1e:65,a2e:70};
 const level=r=>Q(r?.level||r?.progression||r?.progressionCode||'').replace(/\s/g,'');
 const isAdv=r=>/^a[12]/.test(level(r));
 const thesis=r=>/(examensarbete|kandidatuppsats|kandidatarbete|självständigt arbete|degree project|bachelor.?s thesis)/i.test(String(r?.name||''));

 function sourceKey(m){
   return Q(m?.sourceId||m?.sourceCode||m?.sourceCourseCode||m?.sourceName||
            m?.source?.id||m?.source?.code||m?.source?.name||'');
 }
 function targetKey(m){
   return Q(m?.targetId||m?.targetCode||m?.targetName||m?.code||m?.name||'');
 }

 function audit(snapshot){
   const rows=A(snapshot?.rows), matches=A(snapshot?.matches);
   const sourceUse=new Map(), duplicateUses=[];
   matches.forEach(m=>{
     const sk=sourceKey(m), tk=targetKey(m);
     if(!sk||!tk)return;
     if(!sourceUse.has(sk))sourceUse.set(sk,new Set());
     sourceUse.get(sk).add(tk);
   });
   sourceUse.forEach((targets,source)=>{
     if(targets.size>1)duplicateUses.push({source,targets:[...targets]});
   });

   const progression={g1n:0,g1f:0,g1e:0,g2f:0,g2e:0,a1n:0,a1f:0,a1e:0,a2e:0,unknown:0};
   rows.forEach(r=>{
     const hp=Math.min(N(r.hp),N(r.matchedHp)||(r.status==='credited'?N(r.hp):0));
     if(!hp)return;
     const l=level(r);
     if(Object.prototype.hasOwnProperty.call(progression,l))progression[l]+=hp;
     else progression.unknown+=hp;
   });

   const advancedHp=rows.filter(isAdv).reduce((a,r)=>a+Math.min(N(r.hp),N(r.matchedHp)||(r.status==='credited'?N(r.hp):0)),0);
   const thesisRows=rows.filter(r=>thesis(r)&&(r.status==='credited'||N(r.matchedHp)>0));
   const thesisSources=new Map();
   thesisRows.forEach(r=>{
     const k=Q(r.sourceCode||r.sourceName||r.code||r.name);
     if(k)thesisSources.set(k,(thesisSources.get(k)||0)+1);
   });

   return {
     ok:duplicateUses.length===0,
     duplicateMeritUses:duplicateUses,
     progression,
     advancedHp,
     thesisRows:thesisRows.length,
     progressionKnownHp:Object.entries(progression).filter(([k])=>k!=='unknown').reduce((a,[,v])=>a+v,0),
     unknownProgressionHp:progression.unknown
   };
 }

 function deDuplicate(snapshot){
   if(!snapshot)return snapshot;
   const used=new Set();
   const matches=A(snapshot.matches).map(m=>{
     const sk=sourceKey(m);
     if(!sk)return m;
     if(used.has(sk)){
       return {...m,duplicateBlocked:true,matchedHp:0,creditedHp:0,hpMatched:0,
         partial:false,matchType:'blocked-duplicate',
         qaWarning:'Samma merit används redan för ett annat krav.'};
     }
     used.add(sk); return m;
   });
   return {...snapshot,matches,qa:{...(snapshot.qa||{}),v587:true}};
 }

 function fixStored(){
   try{
     const raw=JSON.parse(sessionStorage.getItem('studielots_planner_snapshot')||'null');
     if(!raw)return null;
     const fixed=deDuplicate(raw);
     sessionStorage.setItem('studielots_planner_snapshot',JSON.stringify(fixed));
     return fixed;
   }catch(e){return null}
 }

 const prev=window.__studielotsRunQA;
 window.__studielotsRunQA=function(){
   const base=typeof prev==='function'?prev():{};
   let snap=null;try{snap=JSON.parse(sessionStorage.getItem('studielots_planner_snapshot')||'null')}catch(e){}
   const p=audit(snap);
   return {...base,progressionAndReuse:p,ok:Boolean(base?.ok!==false&&p.ok)};
 };

 document.addEventListener('click',e=>{
   const el=e.target.closest('button,a');if(!el)return;
   const t=Q(el.textContent);
   if(t.includes('skapa plan')||t.includes('planeraren')){
     setTimeout(()=>{fixStored();window.__studielotsRenderPlannerV572?.()},1);
   }
 },true);

 window.__studielotsProgressionQA={version:'v587',LEVELS,audit,deDuplicate};
 window.__studielotsBuild={...(window.__studielotsBuild||{}),version:'v587',progressionQA:true,doubleCountGuard:true};
})();

/* v588 — advanced-degree QA: candidate prerequisite + magister/master scope */
(function(){
 const A=v=>Array.isArray(v)?v:(v?[v]:[]);
 const N=v=>Number(String(v??0).replace(',','.'))||0;
 const Q=v=>String(v||'').toLocaleLowerCase('sv-SE').normalize('NFD').replace(/[\u0300-\u036f]/g,'').replace(/[^a-z0-9åäö]+/g,' ').trim();
 const L=r=>Q(r?.level||r?.progression||r?.progressionCode||'').replace(/\s/g,'');
 const ADV=r=>/^a[12]/.test(L(r));
 const THESIS=r=>/(examensarbete|magisteruppsats|masteruppsats|självständigt arbete|degree project|master.?s thesis)/i.test(String(r?.name||''));

 function issuedDegrees(){
   return A(window.__studielotsUnifiedMerits?.issuedDegrees||window.__studielotsImportedDegrees||[]);
 }
 function hasPriorDegree(){
   return issuedDegrees().some(d=>{
     const x=Q(d.name||d.degree||d.title);
     const hp=N(d.hp||d.credits);
     return /(kandidat|bachelor|yrkesexamen|professional degree)/.test(x) && (!hp||hp>=180);
   });
 }
 function audit(result){
   if(!result||result.kind!=='degree')return {applicable:false,ok:true};
   const title=Q(result.programName||result.degreeName||result.name||result.level||'');
   const total=N(result.totalHp);
   const magister=/magister/.test(title)||(total===60 && /avancer/.test(Q(result.cycle||'')));
   const master=/master/.test(title)||(total===120 && /avancer/.test(Q(result.cycle||'')));
   if(!magister&&!master)return {applicable:false,ok:true};

   const rows=A(result.rows);
   const creditedRows=rows.filter(r=>r.status==='credited'||N(r.matchedHp)>0);
   const hpOf=r=>Math.min(N(r.hp),N(r.matchedHp)||(r.status==='credited'?N(r.hp):0));
   const advancedHp=creditedRows.filter(ADV).reduce((a,r)=>a+hpOf(r),0);
   const target=Q(result.subject);
   const mainAdvancedHp=creditedRows.filter(r=>ADV(r)&&(!target||Q(r.subject||r.mainField||r.huvudomrade)===target)).reduce((a,r)=>a+hpOf(r),0);
   const thesisHp=creditedRows.filter(r=>ADV(r)&&THESIS(r)&&(!target||!Q(r.subject||r.mainField||r.huvudomrade)||Q(r.subject||r.mainField||r.huvudomrade)===target)).reduce((a,r)=>a+hpOf(r),0);

   const prior=hasPriorDegree() || Boolean(result.prerequisiteDegreeVerified);
   const reqTotal=magister?60:120, reqMain=magister?30:60, reqThesis=magister?15:15;
   // For master, 30 hp thesis is the normal target; 15 hp can be sufficient only
   // when a qualifying previous advanced-level independent project exists.
   const masterThesisException=master && Boolean(result.previousAdvancedThesis15Verified);
   const effectiveThesisReq=master?(masterThesisException?15:30):15;

   const falseComplete=N(result.creditedHp)>=reqTotal-.01 &&
      (!prior || advancedHp<reqTotal || mainAdvancedHp<reqMain || thesisHp<effectiveThesisReq);

   return {
     applicable:true,ok:!falseComplete,falseComplete,type:magister?'magister':'master',
     prerequisiteDegreeVerified:prior,
     requiredHp:reqTotal,advancedHp,
     requiredMainFieldAdvancedHp:reqMain,mainFieldAdvancedHp:mainAdvancedHp,
     requiredThesisHp:effectiveThesisReq,thesisHp,
     masterThesisException
   };
 }

 const prev=window.__studielotsRunQA;
 window.__studielotsRunQA=function(){
   const base=typeof prev==='function'?prev():{};
   let r=null;try{r=window.__studielotsUnifiedResult?.currentResult?.()||null}catch(e){}
   const a=audit(r);
   return {...base,advancedDegree:a,ok:Boolean(base?.ok!==false&&a.ok!==false)};
 };

 const oldSave=window.__studielotsSaveUnifiedSnapshot;
 if(typeof oldSave==='function'){
   window.__studielotsSaveUnifiedSnapshot=function(){
     const snap=oldSave();
     try{
       const r=window.__studielotsUnifiedResult?.currentResult?.();
       const a=audit(r);
       if(snap&&a.falseComplete){
         snap.qa={...(snap.qa||{}),advancedDegreeWarning:true,advancedDegreeAudit:a};
         snap.verifiedRule=false;
         snap.wording={...(snap.wording||{}),
           warning:'Kraven för examen på avancerad nivå behöver verifieras innan planen kan visas som komplett.'};
         sessionStorage.setItem('studielots_planner_snapshot',JSON.stringify(snap));
       }
     }catch(e){}
     return snap;
   };
 }

 window.__studielotsAdvancedDegreeQA={version:'v588',audit,hasPriorDegree};
 window.__studielotsBuild={...(window.__studielotsBuild||{}),version:'v588',advancedDegreeQA:true};
})();
